window.SUKHMANI_PAYLOAD = {"metadata":{"title":"Sukhmani Sahib","totalPages":82,"totalLines":2027,"source":"SearchGurbani","audioUrl":"https://backend.searchgurbani.com/storage/audio/baanis/sukhmani_sahib.mp3","generatedAt":"2026-04-18T18:22:16.283Z"},"pages":[{"index":1,"ang":262,"lines":[{"punjabi":"ਗਉੜੀ ਸੁਖਮਨੀ ਮਃ ੫ ॥","lareedar":"ਗਉੜੀਸੁਖਮਨੀਮਃ੫ ॥","translit":"Gourree Sukhamanee Ma 5 ||","english":"Gauree Sukhmani, Fifth Mehl,"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ੴ ਸਤਿਗੁਰ ਪ੍ਰਸਾਦਿ ॥","lareedar":"ੴਸਤਿਗੁਰਪ੍ਰਸਾਦਿ ॥","translit":"Ik Oankaar Sathigur Prasaadh ||","english":"One Universal Creator God. By The Grace Of The True Guru:"},{"punjabi":"ਆਦਿ ਗੁਰਏ ਨਮਹ ॥","lareedar":"ਆਦਿਗੁਰਏਨਮਹ ॥","translit":"Aadh Gureae Nameh ||","english":"I bow to the Primal Guru."},{"punjabi":"ਜੁਗਾਦਿ ਗੁਰਏ ਨਮਹ ॥","lareedar":"ਜੁਗਾਦਿਗੁਰਏਨਮਹ ॥","translit":"Jugaadh Gureae Nameh ||","english":"I bow to the Guru of the ages."},{"punjabi":"ਸਤਿਗੁਰਏ ਨਮਹ ॥","lareedar":"ਸਤਿਗੁਰਏਨਮਹ ॥","translit":"Sathigureae Nameh ||","english":"I bow to the True Guru."},{"punjabi":"ਸ੍ਰੀ ਗੁਰਦੇਵਏ ਨਮਹ ॥੧॥","lareedar":"ਸ੍ਰੀਗੁਰਦੇਵਏਨਮਹ ॥੧ ॥","translit":"Sree Guradhaeveae Nameh ||1||","english":"I bow to the Great, Divine Guru. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਸਿਮਰਉ ਸਿਮਰਿ ਸਿਮਰਿ ਸੁਖੁ ਪਾਵਉ ॥","lareedar":"ਸਿਮਰਉਸਿਮਰਿਸਿਮਰਿਸੁਖੁਪਾਵਉ ॥","translit":"Simaro Simar Simar Sukh Paavo ||","english":"Meditate, meditate, meditate in remembrance of Him, and find peace."},{"punjabi":"ਕਲਿ ਕਲੇਸ ਤਨ ਮਾਹਿ ਮਿਟਾਵਉ ॥","lareedar":"ਕਲਿਕਲੇਸਤਨਮਾਹਿਮਿਟਾਵਉ ॥","translit":"Kal Kalaes Than Maahi Mittaavo ||","english":"Worry and anguish shall be dispelled from your body."},{"punjabi":"ਸਿਮਰਉ ਜਾਸੁ ਬਿਸੁੰਭਰ ਏਕੈ ॥","lareedar":"ਸਿਮਰਉਜਾਸੁਬਿਸੁੰਭਰਏਕੈ ॥","translit":"Simaro Jaas Bisunbhar Eaekai ||","english":"Remember in praise the One who pervades the whole Universe."},{"punjabi":"ਨਾਮੁ ਜਪਤ ਅਗਨਤ ਅਨੇਕੈ ॥","lareedar":"ਨਾਮੁਜਪਤਅਗਨਤਅਨੇਕੈ ॥","translit":"Naam Japath Aganath Anaekai ||","english":"His Name is chanted by countless people, in so many ways."},{"punjabi":"ਬੇਦ ਪੁਰਾਨ ਸਿੰਮ੍ਰਿਤਿ ਸੁਧਾਖ੍ਯ੍ਯਰ ॥","lareedar":"ਬੇਦਪੁਰਾਨਸਿੰਮ੍ਰਿਤਿਸੁਧਾਖ੍ਯ੍ਯਰ ॥","translit":"Baedh Puraan Sinmrith Sudhhaakhyar ||","english":"The Vedas, the Puraanas and the Simritees, the purest of utterances,"},{"punjabi":"ਕੀਨੇ ਰਾਮ ਨਾਮ ਇਕ ਆਖ੍ਯ੍ਯਰ ॥","lareedar":"ਕੀਨੇਰਾਮਨਾਮਇਕਆਖ੍ਯ੍ਯਰ ॥","translit":"Keenae Raam Naam Eik Aakhyar ||","english":"Were created from the One Word of the Name of the Lord."},{"punjabi":"ਕਿਨਕਾ ਏਕ ਜਿਸੁ ਜੀਅ ਬਸਾਵੈ ॥","lareedar":"ਕਿਨਕਾਏਕਜਿਸੁਜੀਅਬਸਾਵੈ ॥","translit":"Kinakaa Eaek Jis Jeea Basaavai ||","english":"That one, in whose soul the One Lord dwells"},{"punjabi":"ਤਾ ਕੀ ਮਹਿਮਾ ਗਨੀ ਨ ਆਵੈ ॥","lareedar":"ਤਾਕੀਮਹਿਮਾਗਨੀਨਆਵੈ ॥","translit":"Thaa Kee Mehimaa Ganee N Aavai ||","english":"The praises of his glory cannot be recounted."},{"punjabi":"ਕਾਂਖੀ ਏਕੈ ਦਰਸ ਤੁਹਾਰੋ ॥","lareedar":"ਕਾਂਖੀਏਕੈਦਰਸਤੁਹਾਰੋ ॥","translit":"Kaankhee Eaekai Dharas Thuhaaro ||","english":"Those who yearn only for the blessing of Your Darshan"},{"punjabi":"ਨਾਨਕ ਉਨ ਸੰਗਿ ਮੋਹਿ ਉਧਾਰੋ ॥੧॥","lareedar":"ਨਾਨਕਉਨਸੰਗਿਮੋਹਿਉਧਾਰੋ ॥੧ ॥","translit":"Naanak Oun Sang Mohi Oudhhaaro ||1||","english":"- Nanak: save me along with them! ||1||"},{"punjabi":"ਸੁਖਮਨੀ ਸੁਖ ਅੰਮ੍ਰਿਤ ਪ੍ਰਭ ਨਾਮੁ ॥","lareedar":"ਸੁਖਮਨੀਸੁਖਅੰਮ੍ਰਿਤਪ੍ਰਭਨਾਮੁ ॥","translit":"Sukhamanee Sukh Anmrith Prabh Naam ||","english":"Sukhmani: Peace of Mind, the Nectar of the Name of God."},{"punjabi":"ਭਗਤ ਜਨਾ ਕੈ ਮਨਿ ਬਿਸ੍ਰਾਮ ॥ ਰਹਾਉ ॥","lareedar":"ਭਗਤਜਨਾਕੈਮਨਿਬਿਸ੍ਰਾਮ ॥ਰਹਾਉ ॥","translit":"Bhagath Janaa Kai Man Bisraam || Rehaao ||","english":"The minds of the devotees abide in a joyful peace. ||Pause||"},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਗਰਭਿ ਨ ਬਸੈ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਗਰਭਿਨਬਸੈ ॥","translit":"Prabh Kai Simaran Garabh N Basai ||","english":"Remembering God, one does not have to enter into the womb again."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਦੂਖੁ ਜਮੁ ਨਸੈ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਦੂਖੁਜਮੁਨਸੈ ॥","translit":"Prabh Kai Simaran Dhookh Jam Nasai ||","english":"Remembering God, the pain of death is dispelled."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਕਾਲੁ ਪਰਹਰੈ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਕਾਲੁਪਰਹਰੈ ॥","translit":"Prabh Kai Simaran Kaal Pareharai ||","english":"Remembering God, death is eliminated."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਦੁਸਮਨੁ ਟਰੈ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਦੁਸਮਨੁਟਰੈ ॥","translit":"Prabh Kai Simaran Dhusaman Ttarai ||","english":"Remembering God, one's enemies are repelled."},{"punjabi":"ਪ੍ਰਭ ਸਿਮਰਤ ਕਛੁ ਬਿਘਨੁ ਨ ਲਾਗੈ ॥","lareedar":"ਪ੍ਰਭਸਿਮਰਤਕਛੁਬਿਘਨੁਨਲਾਗੈ ॥","translit":"Prabh Simarath Kashh Bighan N Laagai ||","english":"Remembering God, no obstacles are met."}]},{"index":2,"ang":262,"lines":[{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਅਨਦਿਨੁ ਜਾਗੈ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਅਨਦਿਨੁਜਾਗੈ ॥","translit":"Prabh Kai Simaran Anadhin Jaagai ||","english":"Remembering God, one remains awake and aware, night and day."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਭਉ ਨ ਬਿਆਪੈ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਭਉਨਬਿਆਪੈ ॥","translit":"Prabh Kai Simaran Bho N Biaapai ||","english":"Remembering God, one is not touched by fear."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਦੁਖੁ ਨ ਸੰਤਾਪੈ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਦੁਖੁਨਸੰਤਾਪੈ ॥","translit":"Prabh Kai Simaran Dhukh N Santhaapai ||","english":"Remembering God, one does not suffer sorrow."},{"punjabi":"ਪ੍ਰਭ ਕਾ ਸਿਮਰਨੁ ਸਾਧ ਕੈ ਸੰਗਿ ॥","lareedar":"ਪ੍ਰਭਕਾਸਿਮਰਨੁਸਾਧਕੈਸੰਗਿ ॥","translit":"Prabh Kaa Simaran Saadhh Kai Sang ||","english":"The meditative remembrance of God is in the Company of the Holy."},{"punjabi":"ਸਰਬ ਨਿਧਾਨ ਨਾਨਕ ਹਰਿ ਰੰਗਿ ॥੨॥","lareedar":"ਸਰਬਨਿਧਾਨਨਾਨਕਹਰਿਰੰਗਿ ॥੨ ॥","translit":"Sarab Nidhhaan Naanak Har Rang ||2||","english":"All treasures, O Nanak, are in the Love of the Lord. ||2||"},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਰਿਧਿ ਸਿਧਿ ਨਉ ਨਿਧਿ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਰਿਧਿਸਿਧਿਨਉਨਿਧਿ ॥","translit":"Prabh Kai Simaran Ridhh Sidhh No Nidhh ||","english":"In the remembrance of God are wealth, miraculous spiritual powers and the nine treasures."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਗਿਆਨੁ ਧਿਆਨੁ ਤਤੁ ਬੁਧਿ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਗਿਆਨੁਧਿਆਨੁਤਤੁਬੁਧਿ ॥","translit":"Prabh Kai Simaran Giaan Dhhiaan Thath Budhh ||","english":"In the remembrance of God are knowledge, meditation and the essence of wisdom."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਜਪ ਤਪ ਪੂਜਾ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਜਪਤਪਪੂਜਾ ॥","translit":"Prabh Kai Simaran Jap Thap Poojaa ||","english":"In the remembrance of God are chanting, intense meditation and devotional worship."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਬਿਨਸੈ ਦੂਜਾ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਬਿਨਸੈਦੂਜਾ ॥","translit":"Prabh Kai Simaran Binasai Dhoojaa ||","english":"In the remembrance of God, duality is removed."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਤੀਰਥ ਇਸਨਾਨੀ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਤੀਰਥਇਸਨਾਨੀ ॥","translit":"Prabh Kai Simaran Theerathh Eisanaanee ||","english":"In the remembrance of God are purifying baths at sacred shrines of pilgrimage."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਦਰਗਹ ਮਾਨੀ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਦਰਗਹਮਾਨੀ ॥","translit":"Prabh Kai Simaran Dharageh Maanee ||","english":"In the remembrance of God, one attains honor in the Court of the Lord."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਹੋਇ ਸੁ ਭਲਾ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਹੋਇਸੁਭਲਾ ॥","translit":"Prabh Kai Simaran Hoe S Bhalaa ||","english":"In the remembrance of God, one becomes good."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਸੁਫਲ ਫਲਾ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਸੁਫਲਫਲਾ ॥","translit":"Prabh Kai Simaran Sufal Falaa ||","english":"In the remembrance of God, one flowers in fruition."},{"punjabi":"ਸੇ ਸਿਮਰਹਿ ਜਿਨ ਆਪਿ ਸਿਮਰਾਏ ॥","lareedar":"ਸੇਸਿਮਰਹਿਜਿਨਆਪਿਸਿਮਰਾਏ ॥","translit":"Sae Simarehi Jin Aap Simaraaeae ||","english":"They alone remember Him in meditation, whom He inspires to meditate."},{"punjabi":"ਨਾਨਕ ਤਾ ਕੈ ਲਾਗਉ ਪਾਏ ॥੩॥","lareedar":"ਨਾਨਕਤਾਕੈਲਾਗਉਪਾਏ ॥੩ ॥","translit":"Naanak Thaa Kai Laago Paaeae ||3||","english":"Nanak grasps the feet of those humble beings. ||3||"},{"punjabi":"ਪ੍ਰਭ ਕਾ ਸਿਮਰਨੁ ਸਭ ਤੇ ਊਚਾ ॥","lareedar":"ਪ੍ਰਭਕਾਸਿਮਰਨੁਸਭਤੇਊਚਾ ॥","translit":"Prabh Kaa Simaran Sabh Thae Oochaa ||","english":"The remembrance of God is the highest and most exalted of all."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਉਧਰੇ ਮੂਚਾ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਉਧਰੇਮੂਚਾ ॥","translit":"Prabh Kai Simaran Oudhharae Moochaa ||","english":"In the remembrance of God, many are saved."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਤ੍ਰਿਸਨਾ ਬੁਝੈ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਤ੍ਰਿਸਨਾਬੁਝੈ ॥","translit":"Prabh Kai Simaran Thrisanaa Bujhai ||","english":"In the remembrance of God, thirst is quenched."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਸਭੁ ਕਿਛੁ ਸੁਝੈ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਸਭੁਕਿਛੁਸੁਝੈ ॥","translit":"Prabh Kai Simaran Sabh Kishh Sujhai ||","english":"In the remembrance of God, all things are known."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਨਾਹੀ ਜਮ ਤ੍ਰਾਸਾ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਨਾਹੀਜਮਤ੍ਰਾਸਾ ॥","translit":"Prabh Kai Simaran Naahee Jam Thraasaa ||","english":"In the remembrance of God, there is no fear of death."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਪੂਰਨ ਆਸਾ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਪੂਰਨਆਸਾ ॥","translit":"Prabh Kai Simaran Pooran Aasaa ||","english":"In the remembrance of God, hopes are fulfilled."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਮਨ ਕੀ ਮਲੁ ਜਾਇ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਮਨਕੀਮਲੁਜਾਇ ॥","translit":"Prabh Kai Simaran Man Kee Mal Jaae ||","english":"In the remembrance of God, the filth of the mind is removed."},{"punjabi":"ਅੰਮ੍ਰਿਤ ਨਾਮੁ ਰਿਦ ਮਾਹਿ ਸਮਾਇ ॥","lareedar":"ਅੰਮ੍ਰਿਤਨਾਮੁਰਿਦਮਾਹਿਸਮਾਇ ॥","translit":"Anmrith Naam Ridh Maahi Samaae ||","english":"The Ambrosial Naam, the Name of the Lord, is absorbed into the heart."},{"punjabi":"ਪ੍ਰਭ ਜੀ ਬਸਹਿ ਸਾਧ ਕੀ ਰਸਨਾ ॥","lareedar":"ਪ੍ਰਭਜੀਬਸਹਿਸਾਧਕੀਰਸਨਾ ॥","translit":"Prabh Jee Basehi Saadhh Kee Rasanaa ||","english":"God abides upon the tongues of His Saints."},{"punjabi":"ਨਾਨਕ ਜਨ ਕਾ ਦਾਸਨਿ ਦਸਨਾ ॥੪॥","lareedar":"ਨਾਨਕਜਨਕਾਦਾਸਨਿਦਸਨਾ ॥੪ ॥","translit":"Naanak Jan Kaa Dhaasan Dhasanaa ||4||","english":"Nanak is the servant of the slave of His slaves. ||4||"}]},{"index":3,"ang":263,"lines":[{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਸੇ ਧਨਵੰਤੇ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਸੇਧਨਵੰਤੇ ॥","translit":"Prabh Ko Simarehi Sae Dhhanavanthae ||","english":"Those who remember God are wealthy."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਸੇ ਪਤਿਵੰਤੇ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਸੇਪਤਿਵੰਤੇ ॥","translit":"Prabh Ko Simarehi Sae Pathivanthae ||","english":"Those who remember God are honorable."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਸੇ ਜਨ ਪਰਵਾਨ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਸੇਜਨਪਰਵਾਨ ॥","translit":"Prabh Ko Simarehi Sae Jan Paravaan ||","english":"Those who remember God are approved."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਸੇ ਪੁਰਖ ਪ੍ਰਧਾਨ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਸੇਪੁਰਖਪ੍ਰਧਾਨ ॥","translit":"Prabh Ko Simarehi Sae Purakh Pradhhaan ||","english":"Those who remember God are the most distinguished persons."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਸਿ ਬੇਮੁਹਤਾਜੇ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਸਿਬੇਮੁਹਤਾਜੇ ॥","translit":"Prabh Ko Simarehi S Baemuhathaajae ||","english":"Those who remember God are not lacking."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਸਿ ਸਰਬ ਕੇ ਰਾਜੇ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਸਿਸਰਬਕੇਰਾਜੇ ॥","translit":"Prabh Ko Simarehi S Sarab Kae Raajae ||","english":"Those who remember God are the rulers of all."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਸੇ ਸੁਖਵਾਸੀ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਸੇਸੁਖਵਾਸੀ ॥","translit":"Prabh Ko Simarehi Sae Sukhavaasee ||","english":"Those who remember God dwell in peace."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਸਦਾ ਅਬਿਨਾਸੀ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਸਦਾਅਬਿਨਾਸੀ ॥","translit":"Prabh Ko Simarehi Sadhaa Abinaasee ||","english":"Those who remember God are immortal and eternal."},{"punjabi":"ਸਿਮਰਨ ਤੇ ਲਾਗੇ ਜਿਨ ਆਪਿ ਦਇਆਲਾ ॥","lareedar":"ਸਿਮਰਨਤੇਲਾਗੇਜਿਨਆਪਿਦਇਆਲਾ ॥","translit":"Simaran Thae Laagae Jin Aap Dhaeiaalaa ||","english":"They alone hold to the remembrance of Him, unto whom He Himself shows His Mercy."},{"punjabi":"ਨਾਨਕ ਜਨ ਕੀ ਮੰਗੈ ਰਵਾਲਾ ॥੫॥","lareedar":"ਨਾਨਕਜਨਕੀਮੰਗੈਰਵਾਲਾ ॥੫ ॥","translit":"Naanak Jan Kee Mangai Ravaalaa ||5||","english":"Nanak begs for the dust of their feet. ||5||"},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਸੇ ਪਰਉਪਕਾਰੀ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਸੇਪਰਉਪਕਾਰੀ ॥","translit":"Prabh Ko Simarehi Sae Paroupakaaree ||","english":"Those who remember God generously help others."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਤਿਨ ਸਦ ਬਲਿਹਾਰੀ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਤਿਨਸਦਬਲਿਹਾਰੀ ॥","translit":"Prabh Ko Simarehi Thin Sadh Balihaaree ||","english":"Those who remember God - to them, I am forever a sacrifice."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਸੇ ਮੁਖ ਸੁਹਾਵੇ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਸੇਮੁਖਸੁਹਾਵੇ ॥","translit":"Prabh Ko Simarehi Sae Mukh Suhaavae ||","english":"Those who remember God - their faces are beautiful."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਤਿਨ ਸੂਖਿ ਬਿਹਾਵੈ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਤਿਨਸੂਖਿਬਿਹਾਵੈ ॥","translit":"Prabh Ko Simarehi Thin Sookh Bihaavai ||","english":"Those who remember God abide in peace."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਤਿਨ ਆਤਮੁ ਜੀਤਾ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਤਿਨਆਤਮੁਜੀਤਾ ॥","translit":"Prabh Ko Simarehi Thin Aatham Jeethaa ||","english":"Those who remember God conquer their souls."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਤਿਨ ਨਿਰਮਲ ਰੀਤਾ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਤਿਨਨਿਰਮਲਰੀਤਾ ॥","translit":"Prabh Ko Simarehi Thin Niramal Reethaa ||","english":"Those who remember God have a pure and spotless lifestyle."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਤਿਨ ਅਨਦ ਘਨੇਰੇ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਤਿਨਅਨਦਘਨੇਰੇ ॥","translit":"Prabh Ko Simarehi Thin Anadh Ghanaerae ||","english":"Those who remember God experience all sorts of joys."},{"punjabi":"ਪ੍ਰਭ ਕਉ ਸਿਮਰਹਿ ਬਸਹਿ ਹਰਿ ਨੇਰੇ ॥","lareedar":"ਪ੍ਰਭਕਉਸਿਮਰਹਿਬਸਹਿਹਰਿਨੇਰੇ ॥","translit":"Prabh Ko Simarehi Basehi Har Naerae ||","english":"Those who remember God abide near the Lord."},{"punjabi":"ਸੰਤ ਕ੍ਰਿਪਾ ਤੇ ਅਨਦਿਨੁ ਜਾਗਿ ॥","lareedar":"ਸੰਤਕ੍ਰਿਪਾਤੇਅਨਦਿਨੁਜਾਗਿ ॥","translit":"Santh Kirapaa Thae Anadhin Jaag ||","english":"By the Grace of the Saints, one remains awake and aware, night and day."},{"punjabi":"ਨਾਨਕ ਸਿਮਰਨੁ ਪੂਰੈ ਭਾਗਿ ॥੬॥","lareedar":"ਨਾਨਕਸਿਮਰਨੁਪੂਰੈਭਾਗਿ ॥੬ ॥","translit":"Naanak Simaran Poorai Bhaag ||6||","english":"O Nanak, this meditative remembrance comes only by perfect destiny. ||6||"},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਕਾਰਜ ਪੂਰੇ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਕਾਰਜਪੂਰੇ ॥","translit":"Prabh Kai Simaran Kaaraj Poorae ||","english":"Remembering God, one's works are accomplished."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਕਬਹੁ ਨ ਝੂਰੇ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਕਬਹੁਨਝੂਰੇ ॥","translit":"Prabh Kai Simaran Kabahu N Jhoorae ||","english":"Remembering God, one never grieves."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਹਰਿ ਗੁਨ ਬਾਨੀ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਹਰਿਗੁਨਬਾਨੀ ॥","translit":"Prabh Kai Simaran Har Gun Baanee ||","english":"Remembering God, one speaks the Glorious Praises of the Lord."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਸਹਜਿ ਸਮਾਨੀ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਸਹਜਿਸਮਾਨੀ ॥","translit":"Prabh Kai Simaran Sehaj Samaanee ||","english":"Remembering God, one is absorbed into the state of intuitive ease."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਨਿਹਚਲ ਆਸਨੁ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਨਿਹਚਲਆਸਨੁ ॥","translit":"Prabh Kai Simaran Nihachal Aasan ||","english":"Remembering God, one attains the unchanging position."}]},{"index":4,"ang":263,"lines":[{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਕਮਲ ਬਿਗਾਸਨੁ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਕਮਲਬਿਗਾਸਨੁ ॥","translit":"Prabh Kai Simaran Kamal Bigaasan ||","english":"Remembering God, the heart-lotus blossoms forth."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਅਨਹਦ ਝੁਨਕਾਰ ॥","lareedar":"ਪ੍ਰਭਕੈਸਿਮਰਨਿਅਨਹਦਝੁਨਕਾਰ ॥","translit":"Prabh Kai Simaran Anehadh Jhunakaar ||","english":"Remembering God, the unstruck melody vibrates."},{"punjabi":"ਸੁਖੁ ਪ੍ਰਭ ਸਿਮਰਨ ਕਾ ਅੰਤੁ ਨ ਪਾਰ ॥","lareedar":"ਸੁਖੁਪ੍ਰਭਸਿਮਰਨਕਾਅੰਤੁਨਪਾਰ ॥","translit":"Sukh Prabh Simaran Kaa Anth N Paar ||","english":"The peace of the meditative remembrance of God has no end or limitation."},{"punjabi":"ਸਿਮਰਹਿ ਸੇ ਜਨ ਜਿਨ ਕਉ ਪ੍ਰਭ ਮਇਆ ॥","lareedar":"ਸਿਮਰਹਿਸੇਜਨਜਿਨਕਉਪ੍ਰਭਮਇਆ ॥","translit":"Simarehi Sae Jan Jin Ko Prabh Maeiaa ||","english":"They alone remember Him, upon whom God bestows His Grace."},{"punjabi":"ਨਾਨਕ ਤਿਨ ਜਨ ਸਰਨੀ ਪਇਆ ॥੭॥","lareedar":"ਨਾਨਕਤਿਨਜਨਸਰਨੀਪਇਆ ॥੭ ॥","translit":"Naanak Thin Jan Saranee Paeiaa ||7||","english":"Nanak seeks the Sanctuary of those humble beings. ||7||"},{"punjabi":"ਹਰਿ ਸਿਮਰਨੁ ਕਰਿ ਭਗਤ ਪ੍ਰਗਟਾਏ ॥","lareedar":"ਹਰਿਸਿਮਰਨੁਕਰਿਭਗਤਪ੍ਰਗਟਾਏ ॥","translit":"Har Simaran Kar Bhagath Pragattaaeae ||","english":"Remembering the Lord, His devotees are famous and radiant."},{"punjabi":"ਹਰਿ ਸਿਮਰਨਿ ਲਗਿ ਬੇਦ ਉਪਾਏ ॥","lareedar":"ਹਰਿਸਿਮਰਨਿਲਗਿਬੇਦਉਪਾਏ ॥","translit":"Har Simaran Lag Baedh Oupaaeae ||","english":"Remembering the Lord, the Vedas were composed."},{"punjabi":"ਹਰਿ ਸਿਮਰਨਿ ਭਏ ਸਿਧ ਜਤੀ ਦਾਤੇ ॥","lareedar":"ਹਰਿਸਿਮਰਨਿਭਏਸਿਧਜਤੀਦਾਤੇ ॥","translit":"Har Simaran Bheae Sidhh Jathee Dhaathae ||","english":"Remembering the Lord, we become Siddhas, celibates and givers."},{"punjabi":"ਹਰਿ ਸਿਮਰਨਿ ਨੀਚ ਚਹੁ ਕੁੰਟ ਜਾਤੇ ॥","lareedar":"ਹਰਿਸਿਮਰਨਿਨੀਚਚਹੁਕੁੰਟਜਾਤੇ ॥","translit":"Har Simaran Neech Chahu Kuntt Jaathae ||","english":"Remembering the Lord, the lowly become known in all four directions."},{"punjabi":"ਹਰਿ ਸਿਮਰਨਿ ਧਾਰੀ ਸਭ ਧਰਨਾ ॥","lareedar":"ਹਰਿਸਿਮਰਨਿਧਾਰੀਸਭਧਰਨਾ ॥","translit":"Har Simaran Dhhaaree Sabh Dhharanaa ||","english":"For the remembrance of the Lord, the whole world was established."},{"punjabi":"ਸਿਮਰਿ ਸਿਮਰਿ ਹਰਿ ਕਾਰਨ ਕਰਨਾ ॥","lareedar":"ਸਿਮਰਿਸਿਮਰਿਹਰਿਕਾਰਨਕਰਨਾ ॥","translit":"Simar Simar Har Kaaran Karanaa ||","english":"Remember, remember in meditation the Lord, the Creator, the Cause of causes."},{"punjabi":"ਹਰਿ ਸਿਮਰਨਿ ਕੀਓ ਸਗਲ ਅਕਾਰਾ ॥","lareedar":"ਹਰਿਸਿਮਰਨਿਕੀਓਸਗਲਅਕਾਰਾ ॥","translit":"Har Simaran Keeou Sagal Akaaraa ||","english":"For the remembrance of the Lord, He created the whole creation."},{"punjabi":"ਹਰਿ ਸਿਮਰਨ ਮਹਿ ਆਪਿ ਨਿਰੰਕਾਰਾ ॥","lareedar":"ਹਰਿਸਿਮਰਨਮਹਿਆਪਿਨਿਰੰਕਾਰਾ ॥","translit":"Har Simaran Mehi Aap Nirankaaraa ||","english":"In the remembrance of the Lord, He Himself is Formless."},{"punjabi":"ਕਰਿ ਕਿਰਪਾ ਜਿਸੁ ਆਪਿ ਬੁਝਾਇਆ ॥","lareedar":"ਕਰਿਕਿਰਪਾਜਿਸੁਆਪਿਬੁਝਾਇਆ ॥","translit":"Kar Kirapaa Jis Aap Bujhaaeiaa ||","english":"By His Grace, He Himself bestows understanding."},{"punjabi":"ਨਾਨਕ ਗੁਰਮੁਖਿ ਹਰਿ ਸਿਮਰਨੁ ਤਿਨਿ ਪਾਇਆ ॥੮॥੧॥","lareedar":"ਨਾਨਕਗੁਰਮੁਖਿਹਰਿਸਿਮਰਨੁਤਿਨਿਪਾਇਆ ॥੮ ॥੧ ॥","translit":"Naanak Guramukh Har Simaran Thin Paaeiaa ||8||1||","english":"O Nanak, the Gurmukh attains the remembrance of the Lord. ||8||1||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਦੀਨ ਦਰਦ ਦੁਖ ਭੰਜਨਾ ਘਟਿ ਘਟਿ ਨਾਥ ਅਨਾਥ ॥","lareedar":"ਦੀਨਦਰਦਦੁਖਭੰਜਨਾਘਟਿਘਟਿਨਾਥਅਨਾਥ ॥","translit":"Dheen Dharadh Dhukh Bhanjanaa Ghatt Ghatt Naathh Anaathh ||","english":"O Destroyer of the pains and the suffering of the poor, O Master of each and every heart, O Masterless One:"},{"punjabi":"ਸਰਣਿ ਤੁਮ੍ਹ੍ਹਾਰੀ ਆਇਓ ਨਾਨਕ ਕੇ ਪ੍ਰਭ ਸਾਥ ॥੧॥","lareedar":"ਸਰਣਿਤੁਮ੍ਹ੍ਹਾਰੀਆਇਓਨਾਨਕਕੇਪ੍ਰਭਸਾਥ ॥੧ ॥","translit":"Saran Thumhaaree Aaeiou Naanak Kae Prabh Saathh ||1||","english":"I have come seeking Your Sanctuary. O God, please be with Nanak! ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਜਹ ਮਾਤ ਪਿਤਾ ਸੁਤ ਮੀਤ ਨ ਭਾਈ ॥","lareedar":"ਜਹਮਾਤਪਿਤਾਸੁਤਮੀਤਨਭਾਈ ॥","translit":"Jeh Maath Pithaa Suth Meeth N Bhaaee ||","english":"Where there is no mother, father, children, friends or siblings"},{"punjabi":"ਮਨ ਊਹਾ ਨਾਮੁ ਤੇਰੈ ਸੰਗਿ ਸਹਾਈ ॥","lareedar":"ਮਨਊਹਾਨਾਮੁਤੇਰੈਸੰਗਿਸਹਾਈ ॥","translit":"Man Oohaa Naam Thaerai Sang Sehaaee ||","english":"O my mind, there, only the Naam, the Name of the Lord, shall be with you as your help and support."},{"punjabi":"ਜਹ ਮਹਾ ਭਇਆਨ ਦੂਤ ਜਮ ਦਲੈ ॥","lareedar":"ਜਹਮਹਾਭਇਆਨਦੂਤਜਮਦਲੈ ॥","translit":"Jeh Mehaa Bhaeiaan Dhooth Jam Dhalai ||","english":"Where the great and terrible Messenger of Death shall try to crush you,"},{"punjabi":"ਤਹ ਕੇਵਲ ਨਾਮੁ ਸੰਗਿ ਤੇਰੈ ਚਲੈ ॥","lareedar":"ਤਹਕੇਵਲਨਾਮੁਸੰਗਿਤੇਰੈਚਲੈ ॥","translit":"Theh Kaeval Naam Sang Thaerai Chalai ||","english":"There, only the Naam shall go along with you."},{"punjabi":"ਜਹ ਮੁਸਕਲ ਹੋਵੈ ਅਤਿ ਭਾਰੀ ॥","lareedar":"ਜਹਮੁਸਕਲਹੋਵੈਅਤਿਭਾਰੀ ॥","translit":"Jeh Musakal Hovai Ath Bhaaree ||","english":"Where the obstacles are so very heavy,"},{"punjabi":"ਹਰਿ ਕੋ ਨਾਮੁ ਖਿਨ ਮਾਹਿ ਉਧਾਰੀ ॥","lareedar":"ਹਰਿਕੋਨਾਮੁਖਿਨਮਾਹਿਉਧਾਰੀ ॥","translit":"Har Ko Naam Khin Maahi Oudhhaaree ||","english":"The Name of the Lord shall rescue you in an instant."}]},{"index":5,"ang":264,"lines":[{"punjabi":"ਅਨਿਕ ਪੁਨਹਚਰਨ ਕਰਤ ਨਹੀ ਤਰੈ ॥","lareedar":"ਅਨਿਕਪੁਨਹਚਰਨਕਰਤਨਹੀਤਰੈ ॥","translit":"Anik Punehacharan Karath Nehee Tharai ||","english":"By performing countless religious rituals, you shall not be saved."},{"punjabi":"ਹਰਿ ਕੋ ਨਾਮੁ ਕੋਟਿ ਪਾਪ ਪਰਹਰੈ ॥","lareedar":"ਹਰਿਕੋਨਾਮੁਕੋਟਿਪਾਪਪਰਹਰੈ ॥","translit":"Har Ko Naam Kott Paap Pareharai ||","english":"The Name of the Lord washes off millions of sins."},{"punjabi":"ਗੁਰਮੁਖਿ ਨਾਮੁ ਜਪਹੁ ਮਨ ਮੇਰੇ ॥","lareedar":"ਗੁਰਮੁਖਿਨਾਮੁਜਪਹੁਮਨਮੇਰੇ ॥","translit":"Guramukh Naam Japahu Man Maerae ||","english":"As Gurmukh, chant the Naam, O my mind."},{"punjabi":"ਨਾਨਕ ਪਾਵਹੁ ਸੂਖ ਘਨੇਰੇ ॥੧॥","lareedar":"ਨਾਨਕਪਾਵਹੁਸੂਖਘਨੇਰੇ ॥੧ ॥","translit":"Naanak Paavahu Sookh Ghanaerae ||1||","english":"O Nanak, you shall obtain countless joys. ||1||"},{"punjabi":"ਸਗਲ ਸ੍ਰਿਸਟਿ ਕੋ ਰਾਜਾ ਦੁਖੀਆ ॥","lareedar":"ਸਗਲਸ੍ਰਿਸਟਿਕੋਰਾਜਾਦੁਖੀਆ ॥","translit":"Sagal Srisatt Ko Raajaa Dhukheeaa ||","english":"The rulers of the all the world are unhappy;"},{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਜਪਤ ਹੋਇ ਸੁਖੀਆ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਜਪਤਹੋਇਸੁਖੀਆ ॥","translit":"Har Kaa Naam Japath Hoe Sukheeaa ||","english":"One who chants the Name of the Lord becomes happy."},{"punjabi":"ਲਾਖ ਕਰੋਰੀ ਬੰਧੁ ਨ ਪਰੈ ॥","lareedar":"ਲਾਖਕਰੋਰੀਬੰਧੁਨਪਰੈ ॥","translit":"Laakh Karoree Bandhh N Parai ||","english":"Acquiring hundreds of thousands and millions, your desires shall not be contained."},{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਜਪਤ ਨਿਸਤਰੈ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਜਪਤਨਿਸਤਰੈ ॥","translit":"Har Kaa Naam Japath Nisatharai ||","english":"Chanting the Name of the Lord, you shall find release."},{"punjabi":"ਅਨਿਕ ਮਾਇਆ ਰੰਗ ਤਿਖ ਨ ਬੁਝਾਵੈ ॥","lareedar":"ਅਨਿਕਮਾਇਆਰੰਗਤਿਖਨਬੁਝਾਵੈ ॥","translit":"Anik Maaeiaa Rang Thikh N Bujhaavai ||","english":"By the countless pleasures of Maya, your thirst shall not be quenched."},{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਜਪਤ ਆਘਾਵੈ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਜਪਤਆਘਾਵੈ ॥","translit":"Har Kaa Naam Japath Aaghaavai ||","english":"Chanting the Name of the Lord, you shall be satisfied."},{"punjabi":"ਜਿਹ ਮਾਰਗਿ ਇਹੁ ਜਾਤ ਇਕੇਲਾ ॥","lareedar":"ਜਿਹਮਾਰਗਿਇਹੁਜਾਤਇਕੇਲਾ ॥","translit":"Jih Maarag Eihu Jaath Eikaelaa ||","english":"Upon that path where you must go all alone,"},{"punjabi":"ਤਹ ਹਰਿ ਨਾਮੁ ਸੰਗਿ ਹੋਤ ਸੁਹੇਲਾ ॥","lareedar":"ਤਹਹਰਿਨਾਮੁਸੰਗਿਹੋਤਸੁਹੇਲਾ ॥","translit":"Theh Har Naam Sang Hoth Suhaelaa ||","english":"There, only the Lord's Name shall go with you to sustain you."},{"punjabi":"ਐਸਾ ਨਾਮੁ ਮਨ ਸਦਾ ਧਿਆਈਐ ॥","lareedar":"ਐਸਾਨਾਮੁਮਨਸਦਾਧਿਆਈਐ ॥","translit":"Aisaa Naam Man Sadhaa Dhhiaaeeai ||","english":"On such a Name, O my mind, meditate forever."},{"punjabi":"ਨਾਨਕ ਗੁਰਮੁਖਿ ਪਰਮ ਗਤਿ ਪਾਈਐ ॥੨॥","lareedar":"ਨਾਨਕਗੁਰਮੁਖਿਪਰਮਗਤਿਪਾਈਐ ॥੨ ॥","translit":"Naanak Guramukh Param Gath Paaeeai ||2||","english":"O Nanak, as Gurmukh, you shall obtain the state of supreme dignity. ||2||"},{"punjabi":"ਛੂਟਤ ਨਹੀ ਕੋਟਿ ਲਖ ਬਾਹੀ ॥","lareedar":"ਛੂਟਤਨਹੀਕੋਟਿਲਖਬਾਹੀ ॥","translit":"Shhoottath Nehee Kott Lakh Baahee ||","english":"You shall not be saved by hundreds of thousands and millions of helping hands."},{"punjabi":"ਨਾਮੁ ਜਪਤ ਤਹ ਪਾਰਿ ਪਰਾਹੀ ॥","lareedar":"ਨਾਮੁਜਪਤਤਹਪਾਰਿਪਰਾਹੀ ॥","translit":"Naam Japath Theh Paar Paraahee ||","english":"Chanting the Naam, you shall be lifted up and carried across."},{"punjabi":"ਅਨਿਕ ਬਿਘਨ ਜਹ ਆਇ ਸੰਘਾਰੈ ॥","lareedar":"ਅਨਿਕਬਿਘਨਜਹਆਇਸੰਘਾਰੈ ॥","translit":"Anik Bighan Jeh Aae Sanghaarai ||","english":"Where countless misfortunes threaten to destroy you,"},{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਤਤਕਾਲ ਉਧਾਰੈ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਤਤਕਾਲਉਧਾਰੈ ॥","translit":"Har Kaa Naam Thathakaal Oudhhaarai ||","english":"The Name of the Lord shall rescue you in an instant."},{"punjabi":"ਅਨਿਕ ਜੋਨਿ ਜਨਮੈ ਮਰਿ ਜਾਮ ॥","lareedar":"ਅਨਿਕਜੋਨਿਜਨਮੈਮਰਿਜਾਮ ॥","translit":"Anik Jon Janamai Mar Jaam ||","english":"Through countless incarnations, people are born and die."},{"punjabi":"ਨਾਮੁ ਜਪਤ ਪਾਵੈ ਬਿਸ੍ਰਾਮ ॥","lareedar":"ਨਾਮੁਜਪਤਪਾਵੈਬਿਸ੍ਰਾਮ ॥","translit":"Naam Japath Paavai Bisraam ||","english":"Chanting the Name of the Lord, you shall come to rest in peace."},{"punjabi":"ਹਉ ਮੈਲਾ ਮਲੁ ਕਬਹੁ ਨ ਧੋਵੈ ॥","lareedar":"ਹਉਮੈਲਾਮਲੁਕਬਹੁਨਧੋਵੈ ॥","translit":"Ho Mailaa Mal Kabahu N Dhhovai ||","english":"The ego is polluted by a filth which can never be washed off."},{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਕੋਟਿ ਪਾਪ ਖੋਵੈ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਕੋਟਿਪਾਪਖੋਵੈ ॥","translit":"Har Kaa Naam Kott Paap Khovai ||","english":"The Name of the Lord erases millions of sins."},{"punjabi":"ਐਸਾ ਨਾਮੁ ਜਪਹੁ ਮਨ ਰੰਗਿ ॥","lareedar":"ਐਸਾਨਾਮੁਜਪਹੁਮਨਰੰਗਿ ॥","translit":"Aisaa Naam Japahu Man Rang ||","english":"Chant such a Name with love, O my mind."},{"punjabi":"ਨਾਨਕ ਪਾਈਐ ਸਾਧ ਕੈ ਸੰਗਿ ॥੩॥","lareedar":"ਨਾਨਕਪਾਈਐਸਾਧਕੈਸੰਗਿ ॥੩ ॥","translit":"Naanak Paaeeai Saadhh Kai Sang ||3||","english":"O Nanak, it is obtained in the Company of the Holy. ||3||"},{"punjabi":"ਜਿਹ ਮਾਰਗ ਕੇ ਗਨੇ ਜਾਹਿ ਨ ਕੋਸਾ ॥","lareedar":"ਜਿਹਮਾਰਗਕੇਗਨੇਜਾਹਿਨਕੋਸਾ ॥","translit":"Jih Maarag Kae Ganae Jaahi N Kosaa ||","english":"On that path where the miles cannot be counted,"}]},{"index":6,"ang":264,"lines":[{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਊਹਾ ਸੰਗਿ ਤੋਸਾ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਊਹਾਸੰਗਿਤੋਸਾ ॥","translit":"Har Kaa Naam Oohaa Sang Thosaa ||","english":"There, the Name of the Lord shall be your sustenance."},{"punjabi":"ਜਿਹ ਪੈਡੈ ਮਹਾ ਅੰਧ ਗੁਬਾਰਾ ॥","lareedar":"ਜਿਹਪੈਡੈਮਹਾਅੰਧਗੁਬਾਰਾ ॥","translit":"Jih Paiddai Mehaa Andhh Gubaaraa ||","english":"On that journey of total, pitch-black darkness,"},{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਸੰਗਿ ਉਜੀਆਰਾ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਸੰਗਿਉਜੀਆਰਾ ॥","translit":"Har Kaa Naam Sang Oujeeaaraa ||","english":"The Name of the Lord shall be the Light with you."},{"punjabi":"ਜਹਾ ਪੰਥਿ ਤੇਰਾ ਕੋ ਨ ਸਿਞਾਨੂ ॥","lareedar":"ਜਹਾਪੰਥਿਤੇਰਾਕੋਨਸਿਞਾਨੂ ॥","translit":"Jehaa Panthh Thaeraa Ko N Sinjaanoo ||","english":"On that journey where no one knows you,"},{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਤਹ ਨਾਲਿ ਪਛਾਨੂ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਤਹਨਾਲਿਪਛਾਨੂ ॥","translit":"Har Kaa Naam Theh Naal Pashhaanoo ||","english":"With the Name of the Lord, you shall be recognized."},{"punjabi":"ਜਹ ਮਹਾ ਭਇਆਨ ਤਪਤਿ ਬਹੁ ਘਾਮ ॥","lareedar":"ਜਹਮਹਾਭਇਆਨਤਪਤਿਬਹੁਘਾਮ ॥","translit":"Jeh Mehaa Bhaeiaan Thapath Bahu Ghaam ||","english":"Where there is awesome and terrible heat and blazing sunshine,"},{"punjabi":"ਤਹ ਹਰਿ ਕੇ ਨਾਮ ਕੀ ਤੁਮ ਊਪਰਿ ਛਾਮ ॥","lareedar":"ਤਹਹਰਿਕੇਨਾਮਕੀਤੁਮਊਪਰਿਛਾਮ ॥","translit":"Theh Har Kae Naam Kee Thum Oopar Shhaam ||","english":"There, the Name of the Lord will give you shade."},{"punjabi":"ਜਹਾ ਤ੍ਰਿਖਾ ਮਨ ਤੁਝੁ ਆਕਰਖੈ ॥","lareedar":"ਜਹਾਤ੍ਰਿਖਾਮਨਤੁਝੁਆਕਰਖੈ ॥","translit":"Jehaa Thrikhaa Man Thujh Aakarakhai ||","english":"Where thirst, O my mind, torments you to cry out,"},{"punjabi":"ਤਹ ਨਾਨਕ ਹਰਿ ਹਰਿ ਅੰਮ੍ਰਿਤੁ ਬਰਖੈ ॥੪॥","lareedar":"ਤਹਨਾਨਕਹਰਿਹਰਿਅੰਮ੍ਰਿਤੁਬਰਖੈ ॥੪ ॥","translit":"Theh Naanak Har Har Anmrith Barakhai ||4||","english":"There, O Nanak, the Ambrosial Name, Har, Har, shall rain down upon you. ||4||"},{"punjabi":"ਭਗਤ ਜਨਾ ਕੀ ਬਰਤਨਿ ਨਾਮੁ ॥","lareedar":"ਭਗਤਜਨਾਕੀਬਰਤਨਿਨਾਮੁ ॥","translit":"Bhagath Janaa Kee Barathan Naam ||","english":"Unto the devotee, the Naam is an article of daily use."},{"punjabi":"ਸੰਤ ਜਨਾ ਕੈ ਮਨਿ ਬਿਸ੍ਰਾਮੁ ॥","lareedar":"ਸੰਤਜਨਾਕੈਮਨਿਬਿਸ੍ਰਾਮੁ ॥","translit":"Santh Janaa Kai Man Bisraam ||","english":"The minds of the humble Saints are at peace."},{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਦਾਸ ਕੀ ਓਟ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਦਾਸਕੀਓਟ ॥","translit":"Har Kaa Naam Dhaas Kee Outt ||","english":"The Name of the Lord is the Support of His servants."},{"punjabi":"ਹਰਿ ਕੈ ਨਾਮਿ ਉਧਰੇ ਜਨ ਕੋਟਿ ॥","lareedar":"ਹਰਿਕੈਨਾਮਿਉਧਰੇਜਨਕੋਟਿ ॥","translit":"Har Kai Naam Oudhharae Jan Kott ||","english":"By the Name of the Lord, millions have been saved."},{"punjabi":"ਹਰਿ ਜਸੁ ਕਰਤ ਸੰਤ ਦਿਨੁ ਰਾਤਿ ॥","lareedar":"ਹਰਿਜਸੁਕਰਤਸੰਤਦਿਨੁਰਾਤਿ ॥","translit":"Har Jas Karath Santh Dhin Raath ||","english":"The Saints chant the Praises of the Lord, day and night."},{"punjabi":"ਹਰਿ ਹਰਿ ਅਉਖਧੁ ਸਾਧ ਕਮਾਤਿ ॥","lareedar":"ਹਰਿਹਰਿਅਉਖਧੁਸਾਧਕਮਾਤਿ ॥","translit":"Har Har Aoukhadhh Saadhh Kamaath ||","english":"Har, Har - the Lord's Name - the Holy use it as their healing medicine."},{"punjabi":"ਹਰਿ ਜਨ ਕੈ ਹਰਿ ਨਾਮੁ ਨਿਧਾਨੁ ॥","lareedar":"ਹਰਿਜਨਕੈਹਰਿਨਾਮੁਨਿਧਾਨੁ ॥","translit":"Har Jan Kai Har Naam Nidhhaan ||","english":"The Lord's Name is the treasure of the Lord's servant."},{"punjabi":"ਪਾਰਬ੍ਰਹਮਿ ਜਨ ਕੀਨੋ ਦਾਨ ॥","lareedar":"ਪਾਰਬ੍ਰਹਮਿਜਨਕੀਨੋਦਾਨ ॥","translit":"Paarabreham Jan Keeno Dhaan ||","english":"The Supreme Lord God has blessed His humble servant with this gift."},{"punjabi":"ਮਨ ਤਨ ਰੰਗਿ ਰਤੇ ਰੰਗ ਏਕੈ ॥","lareedar":"ਮਨਤਨਰੰਗਿਰਤੇਰੰਗਏਕੈ ॥","translit":"Man Than Rang Rathae Rang Eaekai ||","english":"Mind and body are imbued with ecstasy in the Love of the One Lord."},{"punjabi":"ਨਾਨਕ ਜਨ ਕੈ ਬਿਰਤਿ ਬਿਬੇਕੈ ॥੫॥","lareedar":"ਨਾਨਕਜਨਕੈਬਿਰਤਿਬਿਬੇਕੈ ॥੫ ॥","translit":"Naanak Jan Kai Birath Bibaekai ||5||","english":"O Nanak, careful and discerning understanding is the way of the Lord's humble servant. ||5||"},{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਜਨ ਕਉ ਮੁਕਤਿ ਜੁਗਤਿ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਜਨਕਉਮੁਕਤਿਜੁਗਤਿ ॥","translit":"Har Kaa Naam Jan Ko Mukath Jugath ||","english":"The Name of the Lord is the path of liberation for His humble servants."},{"punjabi":"ਹਰਿ ਕੈ ਨਾਮਿ ਜਨ ਕਉ ਤ੍ਰਿਪਤਿ ਭੁਗਤਿ ॥","lareedar":"ਹਰਿਕੈਨਾਮਿਜਨਕਉਤ੍ਰਿਪਤਿਭੁਗਤਿ ॥","translit":"Har Kai Naam Jan Ko Thripath Bhugath ||","english":"With the food of the Name of the Lord, His servants are satisfied."},{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਜਨ ਕਾ ਰੂਪ ਰੰਗੁ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਜਨਕਾਰੂਪਰੰਗੁ ॥","translit":"Har Kaa Naam Jan Kaa Roop Rang ||","english":"The Name of the Lord is the beauty and delight of His servants."},{"punjabi":"ਹਰਿ ਨਾਮੁ ਜਪਤ ਕਬ ਪਰੈ ਨ ਭੰਗੁ ॥","lareedar":"ਹਰਿਨਾਮੁਜਪਤਕਬਪਰੈਨਭੰਗੁ ॥","translit":"Har Naam Japath Kab Parai N Bhang ||","english":"Chanting the Lord's Name, one is never blocked by obstacles."},{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਜਨ ਕੀ ਵਡਿਆਈ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਜਨਕੀਵਡਿਆਈ ॥","translit":"Har Kaa Naam Jan Kee Vaddiaaee ||","english":"The Name of the Lord is the glorious greatness of His servants."},{"punjabi":"ਹਰਿ ਕੈ ਨਾਮਿ ਜਨ ਸੋਭਾ ਪਾਈ ॥","lareedar":"ਹਰਿਕੈਨਾਮਿਜਨਸੋਭਾਪਾਈ ॥","translit":"Har Kai Naam Jan Sobhaa Paaee ||","english":"Through the Name of the Lord, His servants obtain honor."}]},{"index":7,"ang":265,"lines":[{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਜਨ ਕਉ ਭੋਗ ਜੋਗ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਜਨਕਉਭੋਗਜੋਗ ॥","translit":"Har Kaa Naam Jan Ko Bhog Jog ||","english":"The Name of the Lord is the enjoyment and Yoga of His servants."},{"punjabi":"ਹਰਿ ਨਾਮੁ ਜਪਤ ਕਛੁ ਨਾਹਿ ਬਿਓਗੁ ॥","lareedar":"ਹਰਿਨਾਮੁਜਪਤਕਛੁਨਾਹਿਬਿਓਗੁ ॥","translit":"Har Naam Japath Kashh Naahi Bioug ||","english":"Chanting the Lord's Name, there is no separation from Him."},{"punjabi":"ਜਨੁ ਰਾਤਾ ਹਰਿ ਨਾਮ ਕੀ ਸੇਵਾ ॥","lareedar":"ਜਨੁਰਾਤਾਹਰਿਨਾਮਕੀਸੇਵਾ ॥","translit":"Jan Raathaa Har Naam Kee Saevaa ||","english":"His servants are imbued with the service of the Lord's Name."},{"punjabi":"ਨਾਨਕ ਪੂਜੈ ਹਰਿ ਹਰਿ ਦੇਵਾ ॥੬॥","lareedar":"ਨਾਨਕਪੂਜੈਹਰਿਹਰਿਦੇਵਾ ॥੬ ॥","translit":"Naanak Poojai Har Har Dhaevaa ||6||","english":"O Nanak, worship the Lord, the Lord Divine, Har, Har. ||6||"},{"punjabi":"ਹਰਿ ਹਰਿ ਜਨ ਕੈ ਮਾਲੁ ਖਜੀਨਾ ॥","lareedar":"ਹਰਿਹਰਿਜਨਕੈਮਾਲੁਖਜੀਨਾ ॥","translit":"Har Har Jan Kai Maal Khajeenaa ||","english":"The Lord's Name, Har, Har, is the treasure of wealth of His servants."},{"punjabi":"ਹਰਿ ਧਨੁ ਜਨ ਕਉ ਆਪਿ ਪ੍ਰਭਿ ਦੀਨਾ ॥","lareedar":"ਹਰਿਧਨੁਜਨਕਉਆਪਿਪ੍ਰਭਿਦੀਨਾ ॥","translit":"Har Dhhan Jan Ko Aap Prabh Dheenaa ||","english":"The treasure of the Lord has been bestowed on His servants by God Himself."},{"punjabi":"ਹਰਿ ਹਰਿ ਜਨ ਕੈ ਓਟ ਸਤਾਣੀ ॥","lareedar":"ਹਰਿਹਰਿਜਨਕੈਓਟਸਤਾਣੀ ॥","translit":"Har Har Jan Kai Outt Sathaanee ||","english":"The Lord, Har, Har is the All-powerful Protection of His servants."},{"punjabi":"ਹਰਿ ਪ੍ਰਤਾਪਿ ਜਨ ਅਵਰ ਨ ਜਾਣੀ ॥","lareedar":"ਹਰਿਪ੍ਰਤਾਪਿਜਨਅਵਰਨਜਾਣੀ ॥","translit":"Har Prathaap Jan Avar N Jaanee ||","english":"His servants know no other than the Lord's Magnificence."},{"punjabi":"ਓਤਿ ਪੋਤਿ ਜਨ ਹਰਿ ਰਸਿ ਰਾਤੇ ॥","lareedar":"ਓਤਿਪੋਤਿਜਨਹਰਿਰਸਿਰਾਤੇ ॥","translit":"Outh Poth Jan Har Ras Raathae ||","english":"Through and through, His servants are imbued with the Lord's Love."},{"punjabi":"ਸੁੰਨ ਸਮਾਧਿ ਨਾਮ ਰਸ ਮਾਤੇ ॥","lareedar":"ਸੁੰਨਸਮਾਧਿਨਾਮਰਸਮਾਤੇ ॥","translit":"Sunn Samaadhh Naam Ras Maathae ||","english":"In deepest Samaadhi, they are intoxicated with the essence of the Naam."},{"punjabi":"ਆਠ ਪਹਰ ਜਨੁ ਹਰਿ ਹਰਿ ਜਪੈ ॥","lareedar":"ਆਠਪਹਰਜਨੁਹਰਿਹਰਿਜਪੈ ॥","translit":"Aath Pehar Jan Har Har Japai ||","english":"Twenty-four hours a day, His servants chant Har, Har."},{"punjabi":"ਹਰਿ ਕਾ ਭਗਤੁ ਪ੍ਰਗਟ ਨਹੀ ਛਪੈ ॥","lareedar":"ਹਰਿਕਾਭਗਤੁਪ੍ਰਗਟਨਹੀਛਪੈ ॥","translit":"Har Kaa Bhagath Pragatt Nehee Shhapai ||","english":"The devotees of the Lord are known and respected; they do not hide in secrecy."},{"punjabi":"ਹਰਿ ਕੀ ਭਗਤਿ ਮੁਕਤਿ ਬਹੁ ਕਰੇ ॥","lareedar":"ਹਰਿਕੀਭਗਤਿਮੁਕਤਿਬਹੁਕਰੇ ॥","translit":"Har Kee Bhagath Mukath Bahu Karae ||","english":"Through devotion to the Lord, many have been liberated."},{"punjabi":"ਨਾਨਕ ਜਨ ਸੰਗਿ ਕੇਤੇ ਤਰੇ ॥੭॥","lareedar":"ਨਾਨਕਜਨਸੰਗਿਕੇਤੇਤਰੇ ॥੭ ॥","translit":"Naanak Jan Sang Kaethae Tharae ||7||","english":"O Nanak, along with His servants, many others are saved. ||7||"},{"punjabi":"ਪਾਰਜਾਤੁ ਇਹੁ ਹਰਿ ਕੋ ਨਾਮ ॥","lareedar":"ਪਾਰਜਾਤੁਇਹੁਹਰਿਕੋਨਾਮ ॥","translit":"Paarajaath Eihu Har Ko Naam ||","english":"This Elysian Tree of miraculous powers is the Name of the Lord."},{"punjabi":"ਕਾਮਧੇਨ ਹਰਿ ਹਰਿ ਗੁਣ ਗਾਮ ॥","lareedar":"ਕਾਮਧੇਨਹਰਿਹਰਿਗੁਣਗਾਮ ॥","translit":"Kaamadhhaen Har Har Gun Gaam ||","english":"The Khaamadhayn, the cow of miraculous powers, is the singing of the Glory of the Lord's Name, Har, Har."},{"punjabi":"ਸਭ ਤੇ ਊਤਮ ਹਰਿ ਕੀ ਕਥਾ ॥","lareedar":"ਸਭਤੇਊਤਮਹਰਿਕੀਕਥਾ ॥","translit":"Sabh Thae Ootham Har Kee Kathhaa ||","english":"Highest of all is the Lord's Speech."},{"punjabi":"ਨਾਮੁ ਸੁਨਤ ਦਰਦ ਦੁਖ ਲਥਾ ॥","lareedar":"ਨਾਮੁਸੁਨਤਦਰਦਦੁਖਲਥਾ ॥","translit":"Naam Sunath Dharadh Dhukh Lathhaa ||","english":"Hearing the Naam, pain and sorrow are removed."},{"punjabi":"ਨਾਮ ਕੀ ਮਹਿਮਾ ਸੰਤ ਰਿਦ ਵਸੈ ॥","lareedar":"ਨਾਮਕੀਮਹਿਮਾਸੰਤਰਿਦਵਸੈ ॥","translit":"Naam Kee Mehimaa Santh Ridh Vasai ||","english":"The Glory of the Naam abides in the hearts of His Saints."},{"punjabi":"ਸੰਤ ਪ੍ਰਤਾਪਿ ਦੁਰਤੁ ਸਭੁ ਨਸੈ ॥","lareedar":"ਸੰਤਪ੍ਰਤਾਪਿਦੁਰਤੁਸਭੁਨਸੈ ॥","translit":"Santh Prathaap Dhurath Sabh Nasai ||","english":"By the Saint's kind intervention, all guilt is dispelled."},{"punjabi":"ਸੰਤ ਕਾ ਸੰਗੁ ਵਡਭਾਗੀ ਪਾਈਐ ॥","lareedar":"ਸੰਤਕਾਸੰਗੁਵਡਭਾਗੀਪਾਈਐ ॥","translit":"Santh Kaa Sang Vaddabhaagee Paaeeai ||","english":"The Society of the Saints is obtained by great good fortune."},{"punjabi":"ਸੰਤ ਕੀ ਸੇਵਾ ਨਾਮੁ ਧਿਆਈਐ ॥","lareedar":"ਸੰਤਕੀਸੇਵਾਨਾਮੁਧਿਆਈਐ ॥","translit":"Santh Kee Saevaa Naam Dhhiaaeeai ||","english":"Serving the Saint, one meditates on the Naam."},{"punjabi":"ਨਾਮ ਤੁਲਿ ਕਛੁ ਅਵਰੁ ਨ ਹੋਇ ॥","lareedar":"ਨਾਮਤੁਲਿਕਛੁਅਵਰੁਨਹੋਇ ॥","translit":"Naam Thul Kashh Avar N Hoe ||","english":"There is nothing equal to the Naam."},{"punjabi":"ਨਾਨਕ ਗੁਰਮੁਖਿ ਨਾਮੁ ਪਾਵੈ ਜਨੁ ਕੋਇ ॥੮॥੨॥","lareedar":"ਨਾਨਕਗੁਰਮੁਖਿਨਾਮੁਪਾਵੈਜਨੁਕੋਇ ॥੮ ॥੨ ॥","translit":"Naanak Guramukh Naam Paavai Jan Koe ||8||2||","english":"O Nanak, rare are those, who, as Gurmukh, obtain the Naam. ||8||2||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"}]},{"index":8,"ang":265,"lines":[{"punjabi":"ਬਹੁ ਸਾਸਤ੍ਰ ਬਹੁ ਸਿਮ੍ਰਿਤੀ ਪੇਖੇ ਸਰਬ ਢਢੋਲਿ ॥","lareedar":"ਬਹੁਸਾਸਤ੍ਰਬਹੁਸਿਮ੍ਰਿਤੀਪੇਖੇਸਰਬਢਢੋਲਿ ॥","translit":"Bahu Saasathr Bahu Simrithee Paekhae Sarab Dtadtol ||","english":"The many Shaastras and the many Simritees - I have seen and searched through them all."},{"punjabi":"ਪੂਜਸਿ ਨਾਹੀ ਹਰਿ ਹਰੇ ਨਾਨਕ ਨਾਮ ਅਮੋਲ ॥੧॥","lareedar":"ਪੂਜਸਿਨਾਹੀਹਰਿਹਰੇਨਾਨਕਨਾਮਅਮੋਲ ॥੧ ॥","translit":"Poojas Naahee Har Harae Naanak Naam Amol ||1||","english":"They are not equal to Har, Haray - O Nanak, the Lord's Invaluable Name. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਜਾਪ ਤਾਪ ਗਿਆਨ ਸਭਿ ਧਿਆਨ ॥","lareedar":"ਜਾਪਤਾਪਗਿਆਨਸਭਿਧਿਆਨ ॥","translit":"Jaap Thaap Giaan Sabh Dhhiaan ||","english":"Chanting, intense meditation, spiritual wisdom and all meditations;"},{"punjabi":"ਖਟ ਸਾਸਤ੍ਰ ਸਿਮ੍ਰਿਤਿ ਵਖਿਆਨ ॥","lareedar":"ਖਟਸਾਸਤ੍ਰਸਿਮ੍ਰਿਤਿਵਖਿਆਨ ॥","translit":"Khatt Saasathr Simrith Vakhiaan ||","english":"The six schools of philosophy and sermons on the scriptures;"},{"punjabi":"ਜੋਗ ਅਭਿਆਸ ਕਰਮ ਧ੍ਰਮ ਕਿਰਿਆ ॥","lareedar":"ਜੋਗਅਭਿਆਸਕਰਮਧ੍ਰਮਕਿਰਿਆ ॥","translit":"Jog Abhiaas Karam Dhhram Kiriaa ||","english":"The practice of Yoga and righteous conduct;"},{"punjabi":"ਸਗਲ ਤਿਆਗਿ ਬਨ ਮਧੇ ਫਿਰਿਆ ॥","lareedar":"ਸਗਲਤਿਆਗਿਬਨਮਧੇਫਿਰਿਆ ॥","translit":"Sagal Thiaag Ban Madhhae Firiaa ||","english":"The renunciation of everything and wandering around in the wilderness;"},{"punjabi":"ਅਨਿਕ ਪ੍ਰਕਾਰ ਕੀਏ ਬਹੁ ਜਤਨਾ ॥","lareedar":"ਅਨਿਕਪ੍ਰਕਾਰਕੀਏਬਹੁਜਤਨਾ ॥","translit":"Anik Prakaar Keeeae Bahu Jathanaa ||","english":"The performance of all sorts of works;"},{"punjabi":"ਪੁੰਨ ਦਾਨ ਹੋਮੇ ਬਹੁ ਰਤਨਾ ॥","lareedar":"ਪੁੰਨਦਾਨਹੋਮੇਬਹੁਰਤਨਾ ॥","translit":"Punn Dhaan Homae Bahu Rathanaa ||","english":"Donations to charities and offerings of jewels to fire;"},{"punjabi":"ਸਰੀਰੁ ਕਟਾਇ ਹੋਮੈ ਕਰਿ ਰਾਤੀ ॥","lareedar":"ਸਰੀਰੁਕਟਾਇਹੋਮੈਕਰਿਰਾਤੀ ॥","translit":"Sareer Kattaae Homai Kar Raathee ||","english":"Cutting the body apart and making the pieces into ceremonial fire offerings;"},{"punjabi":"ਵਰਤ ਨੇਮ ਕਰੈ ਬਹੁ ਭਾਤੀ ॥","lareedar":"ਵਰਤਨੇਮਕਰੈਬਹੁਭਾਤੀ ॥","translit":"Varath Naem Karai Bahu Bhaathee ||","english":"Keeping fasts and making vows of all sorts"},{"punjabi":"ਨਹੀ ਤੁਲਿ ਰਾਮ ਨਾਮ ਬੀਚਾਰ ॥","lareedar":"ਨਹੀਤੁਲਿਰਾਮਨਾਮਬੀਚਾਰ ॥","translit":"Nehee Thul Raam Naam Beechaar ||","english":"- none of these are equal to the contemplation of the Name of the Lord,"},{"punjabi":"ਨਾਨਕ ਗੁਰਮੁਖਿ ਨਾਮੁ ਜਪੀਐ ਇਕ ਬਾਰ ॥੧॥","lareedar":"ਨਾਨਕਗੁਰਮੁਖਿਨਾਮੁਜਪੀਐਇਕਬਾਰ ॥੧ ॥","translit":"Naanak Guramukh Naam Japeeai Eik Baar ||1||","english":"O Nanak, if, as Gurmukh, one chants the Naam, even once. ||1||"},{"punjabi":"ਨਉ ਖੰਡ ਪ੍ਰਿਥਮੀ ਫਿਰੈ ਚਿਰੁ ਜੀਵੈ ॥","lareedar":"ਨਉਖੰਡਪ੍ਰਿਥਮੀਫਿਰੈਚਿਰੁਜੀਵੈ ॥","translit":"No Khandd Prithhamee Firai Chir Jeevai ||","english":"You may roam over the nine continents of the world and live a very long life;"},{"punjabi":"ਮਹਾ ਉਦਾਸੁ ਤਪੀਸਰੁ ਥੀਵੈ ॥","lareedar":"ਮਹਾਉਦਾਸੁਤਪੀਸਰੁਥੀਵੈ ॥","translit":"Mehaa Oudhaas Thapeesar Thheevai ||","english":"You may become a great ascetic and a master of disciplined meditation"},{"punjabi":"ਅਗਨਿ ਮਾਹਿ ਹੋਮਤ ਪਰਾਨ ॥","lareedar":"ਅਗਨਿਮਾਹਿਹੋਮਤਪਰਾਨ ॥","translit":"Agan Maahi Homath Paraan ||","english":"And burn yourself in fire;"},{"punjabi":"ਕਨਿਕ ਅਸ੍ਵ ਹੈਵਰ ਭੂਮਿ ਦਾਨ ॥","lareedar":"ਕਨਿਕਅਸ੍ਵਹੈਵਰਭੂਮਿਦਾਨ ॥","translit":"Kanik Asv Haivar Bhoom Dhaan ||","english":"You may give away gold, horses, elephants and land;"},{"punjabi":"ਨਿਉਲੀ ਕਰਮ ਕਰੈ ਬਹੁ ਆਸਨ ॥","lareedar":"ਨਿਉਲੀਕਰਮਕਰੈਬਹੁਆਸਨ ॥","translit":"Nioulee Karam Karai Bahu Aasan ||","english":"You may practice techniques of inner cleansing and all sorts of Yogic postures;"},{"punjabi":"ਜੈਨ ਮਾਰਗ ਸੰਜਮ ਅਤਿ ਸਾਧਨ ॥","lareedar":"ਜੈਨਮਾਰਗਸੰਜਮਅਤਿਸਾਧਨ ॥","translit":"Jain Maarag Sanjam Ath Saadhhan ||","english":"You may adopt the self-mortifying ways of the Jains and great spiritual disciplines;"},{"punjabi":"ਨਿਮਖ ਨਿਮਖ ਕਰਿ ਸਰੀਰੁ ਕਟਾਵੈ ॥","lareedar":"ਨਿਮਖਨਿਮਖਕਰਿਸਰੀਰੁਕਟਾਵੈ ॥","translit":"Nimakh Nimakh Kar Sareer Kattaavai ||","english":"Piece by piece, you may cut your body apart;"},{"punjabi":"ਤਉ ਭੀ ਹਉਮੈ ਮੈਲੁ ਨ ਜਾਵੈ ॥","lareedar":"ਤਉਭੀਹਉਮੈਮੈਲੁਨਜਾਵੈ ॥","translit":"Tho Bhee Houmai Mail N Jaavai ||","english":"But even so, the filth of your ego shall not depart."},{"punjabi":"ਹਰਿ ਕੇ ਨਾਮ ਸਮਸਰਿ ਕਛੁ ਨਾਹਿ ॥","lareedar":"ਹਰਿਕੇਨਾਮਸਮਸਰਿਕਛੁਨਾਹਿ ॥","translit":"Har Kae Naam Samasar Kashh Naahi ||","english":"There is nothing equal to the Name of the Lord."},{"punjabi":"ਨਾਨਕ ਗੁਰਮੁਖਿ ਨਾਮੁ ਜਪਤ ਗਤਿ ਪਾਹਿ ॥੨॥","lareedar":"ਨਾਨਕਗੁਰਮੁਖਿਨਾਮੁਜਪਤਗਤਿਪਾਹਿ ॥੨ ॥","translit":"Naanak Guramukh Naam Japath Gath Paahi ||2||","english":"O Nanak, as Gurmukh, chant the Naam, and obtain salvation. ||2||"},{"punjabi":"ਮਨ ਕਾਮਨਾ ਤੀਰਥ ਦੇਹ ਛੁਟੈ ॥","lareedar":"ਮਨਕਾਮਨਾਤੀਰਥਦੇਹਛੁਟੈ ॥","translit":"Man Kaamanaa Theerathh Dhaeh Shhuttai ||","english":"With your mind filled with desire, you may give up your body at a sacred shrine of pilgrimage;"},{"punjabi":"ਗਰਬੁ ਗੁਮਾਨੁ ਨ ਮਨ ਤੇ ਹੁਟੈ ॥","lareedar":"ਗਰਬੁਗੁਮਾਨੁਨਮਨਤੇਹੁਟੈ ॥","translit":"Garab Gumaan N Man Thae Huttai ||","english":"But even so, egotistical pride shall not be removed from your mind."}]},{"index":9,"ang":265,"lines":[{"punjabi":"ਸੋਚ ਕਰੈ ਦਿਨਸੁ ਅਰੁ ਰਾਤਿ ॥","lareedar":"ਸੋਚਕਰੈਦਿਨਸੁਅਰੁਰਾਤਿ ॥","translit":"Soch Karai Dhinas Ar Raath ||","english":"You may practice cleansing day and night,"},{"punjabi":"ਮਨ ਕੀ ਮੈਲੁ ਨ ਤਨ ਤੇ ਜਾਤਿ ॥","lareedar":"ਮਨਕੀਮੈਲੁਨਤਨਤੇਜਾਤਿ ॥","translit":"Man Kee Mail N Than Thae Jaath ||","english":"But the filth of your mind shall not leave your body."},{"punjabi":"ਇਸੁ ਦੇਹੀ ਕਉ ਬਹੁ ਸਾਧਨਾ ਕਰੈ ॥","lareedar":"ਇਸੁਦੇਹੀਕਉਬਹੁਸਾਧਨਾਕਰੈ ॥","translit":"Eis Dhaehee Ko Bahu Saadhhanaa Karai ||","english":"You may subject your body to all sorts of disciplines,"},{"punjabi":"ਮਨ ਤੇ ਕਬਹੂ ਨ ਬਿਖਿਆ ਟਰੈ ॥","lareedar":"ਮਨਤੇਕਬਹੂਨਬਿਖਿਆਟਰੈ ॥","translit":"Man Thae Kabehoo N Bikhiaa Ttarai ||","english":"But your mind will never be rid of its corruption."},{"punjabi":"ਜਲਿ ਧੋਵੈ ਬਹੁ ਦੇਹ ਅਨੀਤਿ ॥","lareedar":"ਜਲਿਧੋਵੈਬਹੁਦੇਹਅਨੀਤਿ ॥","translit":"Jal Dhhovai Bahu Dhaeh Aneeth ||","english":"You may wash this transitory body with loads of water,"},{"punjabi":"ਸੁਧ ਕਹਾ ਹੋਇ ਕਾਚੀ ਭੀਤਿ ॥","lareedar":"ਸੁਧਕਹਾਹੋਇਕਾਚੀਭੀਤਿ ॥","translit":"Sudhh Kehaa Hoe Kaachee Bheeth ||","english":"But how can a wall of mud be washed clean?"},{"punjabi":"ਮਨ ਹਰਿ ਕੇ ਨਾਮ ਕੀ ਮਹਿਮਾ ਊਚ ॥","lareedar":"ਮਨਹਰਿਕੇਨਾਮਕੀਮਹਿਮਾਊਚ ॥","translit":"Man Har Kae Naam Kee Mehimaa Ooch ||","english":"O my mind, the Glorious Praise of the Name of the Lord is the highest;"},{"punjabi":"ਨਾਨਕ ਨਾਮਿ ਉਧਰੇ ਪਤਿਤ ਬਹੁ ਮੂਚ ॥੩॥","lareedar":"ਨਾਨਕਨਾਮਿਉਧਰੇਪਤਿਤਬਹੁਮੂਚ ॥੩ ॥","translit":"Naanak Naam Oudhharae Pathith Bahu Mooch ||3||","english":"O Nanak, the Naam has saved so many of the worst sinners. ||3||"},{"punjabi":"ਬਹੁਤੁ ਸਿਆਣਪ ਜਮ ਕਾ ਭਉ ਬਿਆਪੈ ॥","lareedar":"ਬਹੁਤੁਸਿਆਣਪਜਮਕਾਭਉਬਿਆਪੈ ॥","translit":"Bahuth Siaanap Jam Kaa Bho Biaapai ||","english":"Even with great cleverness, the fear of death clings to you."},{"punjabi":"ਅਨਿਕ ਜਤਨ ਕਰਿ ਤ੍ਰਿਸਨ ਨਾ ਧ੍ਰਾਪੈ ॥","lareedar":"ਅਨਿਕਜਤਨਕਰਿਤ੍ਰਿਸਨਨਾਧ੍ਰਾਪੈ ॥","translit":"Anik Jathan Kar Thrisan Naa Dhhraapai ||","english":"You try all sorts of things, but your thirst is still not satisfied."},{"punjabi":"ਭੇਖ ਅਨੇਕ ਅਗਨਿ ਨਹੀ ਬੁਝੈ ॥","lareedar":"ਭੇਖਅਨੇਕਅਗਨਿਨਹੀਬੁਝੈ ॥","translit":"Bhaekh Anaek Agan Nehee Bujhai ||","english":"Wearing various religious robes, the fire is not extinguished."},{"punjabi":"ਕੋਟਿ ਉਪਾਵ ਦਰਗਹ ਨਹੀ ਸਿਝੈ ॥","lareedar":"ਕੋਟਿਉਪਾਵਦਰਗਹਨਹੀਸਿਝੈ ॥","translit":"Kott Oupaav Dharageh Nehee Sijhai ||","english":"Even making millions of efforts, you shall not be accepted in the Court of the Lord."},{"punjabi":"ਛੂਟਸਿ ਨਾਹੀ ਊਭ ਪਇਆਲਿ ॥","lareedar":"ਛੂਟਸਿਨਾਹੀਊਭਪਇਆਲਿ ॥","translit":"Shhoottas Naahee Oobh Paeiaal ||","english":"You cannot escape to the heavens, or to the nether regions,"},{"punjabi":"ਮੋਹਿ ਬਿਆਪਹਿ ਮਾਇਆ ਜਾਲਿ ॥","lareedar":"ਮੋਹਿਬਿਆਪਹਿਮਾਇਆਜਾਲਿ ॥","translit":"Mohi Biaapehi Maaeiaa Jaal ||","english":"If you are entangled in emotional attachment and the net of Maya."},{"punjabi":"ਅਵਰ ਕਰਤੂਤਿ ਸਗਲੀ ਜਮੁ ਡਾਨੈ ॥","lareedar":"ਅਵਰਕਰਤੂਤਿਸਗਲੀਜਮੁਡਾਨੈ ॥","translit":"Avar Karathooth Sagalee Jam Ddaanai ||","english":"All other efforts are punished by the Messenger of Death,"},{"punjabi":"ਗੋਵਿੰਦ ਭਜਨ ਬਿਨੁ ਤਿਲੁ ਨਹੀ ਮਾਨੈ ॥","lareedar":"ਗੋਵਿੰਦਭਜਨਬਿਨੁਤਿਲੁਨਹੀਮਾਨੈ ॥","translit":"Govindh Bhajan Bin Thil Nehee Maanai ||","english":"Which accepts nothing at all, except meditation on the Lord of the Universe."},{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਜਪਤ ਦੁਖੁ ਜਾਇ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਜਪਤਦੁਖੁਜਾਇ ॥","translit":"Har Kaa Naam Japath Dhukh Jaae ||","english":"Chanting the Name of the Lord, sorrow is dispelled."},{"punjabi":"ਨਾਨਕ ਬੋਲੈ ਸਹਜਿ ਸੁਭਾਇ ॥੪॥","lareedar":"ਨਾਨਕਬੋਲੈਸਹਜਿਸੁਭਾਇ ॥੪ ॥","translit":"Naanak Bolai Sehaj Subhaae ||4||","english":"O Nanak, chant it with intuitive ease. ||4||"},{"punjabi":"ਚਾਰਿ ਪਦਾਰਥ ਜੇ ਕੋ ਮਾਗੈ ॥","lareedar":"ਚਾਰਿਪਦਾਰਥਜੇਕੋਮਾਗੈ ॥","translit":"Chaar Padhaarathh Jae Ko Maagai ||","english":"One who prays for the four cardinal blessings"},{"punjabi":"ਸਾਧ ਜਨਾ ਕੀ ਸੇਵਾ ਲਾਗੈ ॥","lareedar":"ਸਾਧਜਨਾਕੀਸੇਵਾਲਾਗੈ ॥","translit":"Saadhh Janaa Kee Saevaa Laagai ||","english":"Should commit himself to the service of the Saints."},{"punjabi":"ਜੇ ਕੋ ਆਪੁਨਾ ਦੂਖੁ ਮਿਟਾਵੈ ॥","lareedar":"ਜੇਕੋਆਪੁਨਾਦੂਖੁਮਿਟਾਵੈ ॥","translit":"Jae Ko Aapunaa Dhookh Mittaavai ||","english":"If you wish to erase your sorrows,"},{"punjabi":"ਹਰਿ ਹਰਿ ਨਾਮੁ ਰਿਦੈ ਸਦ ਗਾਵੈ ॥","lareedar":"ਹਰਿਹਰਿਨਾਮੁਰਿਦੈਸਦਗਾਵੈ ॥","translit":"Har Har Naam Ridhai Sadh Gaavai ||","english":"Sing the Name of the Lord, Har, Har, within your heart."},{"punjabi":"ਜੇ ਕੋ ਅਪੁਨੀ ਸੋਭਾ ਲੋਰੈ ॥","lareedar":"ਜੇਕੋਅਪੁਨੀਸੋਭਾਲੋਰੈ ॥","translit":"Jae Ko Apunee Sobhaa Lorai ||","english":"If you long for honor for yourself,"},{"punjabi":"ਸਾਧਸੰਗਿ ਇਹ ਹਉਮੈ ਛੋਰੈ ॥","lareedar":"ਸਾਧਸੰਗਿਇਹਹਉਮੈਛੋਰੈ ॥","translit":"Saadhhasang Eih Houmai Shhorai ||","english":"Then renounce your ego in the Saadh Sangat, the Company of the Holy."},{"punjabi":"ਜੇ ਕੋ ਜਨਮ ਮਰਣ ਤੇ ਡਰੈ ॥","lareedar":"ਜੇਕੋਜਨਮਮਰਣਤੇਡਰੈ ॥","translit":"Jae Ko Janam Maran Thae Ddarai ||","english":"If you fear the cycle of birth and death,"}]},{"index":10,"ang":266,"lines":[{"punjabi":"ਸਾਧ ਜਨਾ ਕੀ ਸਰਨੀ ਪਰੈ ॥","lareedar":"ਸਾਧਜਨਾਕੀਸਰਨੀਪਰੈ ॥","translit":"Saadhh Janaa Kee Saranee Parai ||","english":"Then seek the Sanctuary of the Holy."},{"punjabi":"ਜਿਸੁ ਜਨ ਕਉ ਪ੍ਰਭ ਦਰਸ ਪਿਆਸਾ ॥","lareedar":"ਜਿਸੁਜਨਕਉਪ੍ਰਭਦਰਸਪਿਆਸਾ ॥","translit":"Jis Jan Ko Prabh Dharas Piaasaa ||","english":"Those who thirst for the Blessed Vision of God's Darshan"},{"punjabi":"ਨਾਨਕ ਤਾ ਕੈ ਬਲਿ ਬਲਿ ਜਾਸਾ ॥੫॥","lareedar":"ਨਾਨਕਤਾਕੈਬਲਿਬਲਿਜਾਸਾ ॥੫ ॥","translit":"Naanak Thaa Kai Bal Bal Jaasaa ||5||","english":"- Nanak is a sacrifice, a sacrifice to them. ||5||"},{"punjabi":"ਸਗਲ ਪੁਰਖ ਮਹਿ ਪੁਰਖੁ ਪ੍ਰਧਾਨੁ ॥","lareedar":"ਸਗਲਪੁਰਖਮਹਿਪੁਰਖੁਪ੍ਰਧਾਨੁ ॥","translit":"Sagal Purakh Mehi Purakh Pradhhaan ||","english":"Among all persons, the supreme person is the one"},{"punjabi":"ਸਾਧਸੰਗਿ ਜਾ ਕਾ ਮਿਟੈ ਅਭਿਮਾਨੁ ॥","lareedar":"ਸਾਧਸੰਗਿਜਾਕਾਮਿਟੈਅਭਿਮਾਨੁ ॥","translit":"Saadhhasang Jaa Kaa Mittai Abhimaan ||","english":"Who gives up his egotistical pride in the Company of the Holy."},{"punjabi":"ਆਪਸ ਕਉ ਜੋ ਜਾਣੈ ਨੀਚਾ ॥","lareedar":"ਆਪਸਕਉਜੋਜਾਣੈਨੀਚਾ ॥","translit":"Aapas Ko Jo Jaanai Neechaa ||","english":"One who sees himself as lowly,"},{"punjabi":"ਸੋਊ ਗਨੀਐ ਸਭ ਤੇ ਊਚਾ ॥","lareedar":"ਸੋਊਗਨੀਐਸਭਤੇਊਚਾ ॥","translit":"Sooo Ganeeai Sabh Thae Oochaa ||","english":"Shall be accounted as the highest of all."},{"punjabi":"ਜਾ ਕਾ ਮਨੁ ਹੋਇ ਸਗਲ ਕੀ ਰੀਨਾ ॥","lareedar":"ਜਾਕਾਮਨੁਹੋਇਸਗਲਕੀਰੀਨਾ ॥","translit":"Jaa Kaa Man Hoe Sagal Kee Reenaa ||","english":"One whose mind is the dust of all,"},{"punjabi":"ਹਰਿ ਹਰਿ ਨਾਮੁ ਤਿਨਿ ਘਟਿ ਘਟਿ ਚੀਨਾ ॥","lareedar":"ਹਰਿਹਰਿਨਾਮੁਤਿਨਿਘਟਿਘਟਿਚੀਨਾ ॥","translit":"Har Har Naam Thin Ghatt Ghatt Cheenaa ||","english":"Recognizes the Name of the Lord, Har, Har, in each and every heart."},{"punjabi":"ਮਨ ਅਪੁਨੇ ਤੇ ਬੁਰਾ ਮਿਟਾਨਾ ॥","lareedar":"ਮਨਅਪੁਨੇਤੇਬੁਰਾਮਿਟਾਨਾ ॥","translit":"Man Apunae Thae Buraa Mittaanaa ||","english":"One who eradicates cruelty from within his own mind,"},{"punjabi":"ਪੇਖੈ ਸਗਲ ਸ੍ਰਿਸਟਿ ਸਾਜਨਾ ॥","lareedar":"ਪੇਖੈਸਗਲਸ੍ਰਿਸਟਿਸਾਜਨਾ ॥","translit":"Paekhai Sagal Srisatt Saajanaa ||","english":"Looks upon all the world as his friend."},{"punjabi":"ਸੂਖ ਦੂਖ ਜਨ ਸਮ ਦ੍ਰਿਸਟੇਤਾ ॥","lareedar":"ਸੂਖਦੂਖਜਨਸਮਦ੍ਰਿਸਟੇਤਾ ॥","translit":"Sookh Dhookh Jan Sam Dhrisattaethaa ||","english":"One who looks upon pleasure and pain as one and the same,"},{"punjabi":"ਨਾਨਕ ਪਾਪ ਪੁੰਨ ਨਹੀ ਲੇਪਾ ॥੬॥","lareedar":"ਨਾਨਕਪਾਪਪੁੰਨਨਹੀਲੇਪਾ ॥੬ ॥","translit":"Naanak Paap Punn Nehee Laepaa ||6||","english":"O Nanak, is not affected by sin or virtue. ||6||"},{"punjabi":"ਨਿਰਧਨ ਕਉ ਧਨੁ ਤੇਰੋ ਨਾਉ ॥","lareedar":"ਨਿਰਧਨਕਉਧਨੁਤੇਰੋਨਾਉ ॥","translit":"Niradhhan Ko Dhhan Thaero Naao ||","english":"To the poor, Your Name is wealth."},{"punjabi":"ਨਿਥਾਵੇ ਕਉ ਨਾਉ ਤੇਰਾ ਥਾਉ ॥","lareedar":"ਨਿਥਾਵੇਕਉਨਾਉਤੇਰਾਥਾਉ ॥","translit":"Nithhaavae Ko Naao Thaeraa Thhaao ||","english":"To the homeless, Your Name is home."},{"punjabi":"ਨਿਮਾਨੇ ਕਉ ਪ੍ਰਭ ਤੇਰੋ ਮਾਨੁ ॥","lareedar":"ਨਿਮਾਨੇਕਉਪ੍ਰਭਤੇਰੋਮਾਨੁ ॥","translit":"Nimaanae Ko Prabh Thaero Maan ||","english":"To the dishonored, You, O God, are honor."},{"punjabi":"ਸਗਲ ਘਟਾ ਕਉ ਦੇਵਹੁ ਦਾਨੁ ॥","lareedar":"ਸਗਲਘਟਾਕਉਦੇਵਹੁਦਾਨੁ ॥","translit":"Sagal Ghattaa Ko Dhaevahu Dhaan ||","english":"To all, You are the Giver of gifts."},{"punjabi":"ਕਰਨ ਕਰਾਵਨਹਾਰ ਸੁਆਮੀ ॥","lareedar":"ਕਰਨਕਰਾਵਨਹਾਰਸੁਆਮੀ ॥","translit":"Karan Karaavanehaar Suaamee ||","english":"O Creator Lord, Cause of causes, O Lord and Master,"},{"punjabi":"ਸਗਲ ਘਟਾ ਕੇ ਅੰਤਰਜਾਮੀ ॥","lareedar":"ਸਗਲਘਟਾਕੇਅੰਤਰਜਾਮੀ ॥","translit":"Sagal Ghattaa Kae Antharajaamee ||","english":"Inner-knower, Searcher of all hearts:"},{"punjabi":"ਅਪਨੀ ਗਤਿ ਮਿਤਿ ਜਾਨਹੁ ਆਪੇ ॥","lareedar":"ਅਪਨੀਗਤਿਮਿਤਿਜਾਨਹੁਆਪੇ ॥","translit":"Apanee Gath Mith Jaanahu Aapae ||","english":"You alone know Your own condition and state."},{"punjabi":"ਆਪਨ ਸੰਗਿ ਆਪਿ ਪ੍ਰਭ ਰਾਤੇ ॥","lareedar":"ਆਪਨਸੰਗਿਆਪਿਪ੍ਰਭਰਾਤੇ ॥","translit":"Aapan Sang Aap Prabh Raathae ||","english":"You Yourself, God, are imbued with Yourself."},{"punjabi":"ਤੁਮ੍ਹ੍ਹਰੀ ਉਸਤਤਿ ਤੁਮ ਤੇ ਹੋਇ ॥","lareedar":"ਤੁਮ੍ਹ੍ਹਰੀਉਸਤਤਿਤੁਮਤੇਹੋਇ ॥","translit":"Thumharee Ousathath Thum Thae Hoe ||","english":"You alone can celebrate Your Praises."},{"punjabi":"ਨਾਨਕ ਅਵਰੁ ਨ ਜਾਨਸਿ ਕੋਇ ॥੭॥","lareedar":"ਨਾਨਕਅਵਰੁਨਜਾਨਸਿਕੋਇ ॥੭ ॥","translit":"Naanak Avar N Jaanas Koe ||7||","english":"O Nanak, no one else knows. ||7||"},{"punjabi":"ਸਰਬ ਧਰਮ ਮਹਿ ਸ੍ਰੇਸਟ ਧਰਮੁ ॥","lareedar":"ਸਰਬਧਰਮਮਹਿਸ੍ਰੇਸਟਧਰਮੁ ॥","translit":"Sarab Dhharam Mehi Sraesatt Dhharam ||","english":"Of all religions, the best religion"},{"punjabi":"ਹਰਿ ਕੋ ਨਾਮੁ ਜਪਿ ਨਿਰਮਲ ਕਰਮੁ ॥","lareedar":"ਹਰਿਕੋਨਾਮੁਜਪਿਨਿਰਮਲਕਰਮੁ ॥","translit":"Har Ko Naam Jap Niramal Karam ||","english":"Is to chant the Name of the Lord and maintain pure conduct."}]},{"index":11,"ang":266,"lines":[{"punjabi":"ਸਗਲ ਕ੍ਰਿਆ ਮਹਿ ਊਤਮ ਕਿਰਿਆ ॥","lareedar":"ਸਗਲਕ੍ਰਿਆਮਹਿਊਤਮਕਿਰਿਆ ॥","translit":"Sagal Kiraaa Mehi Ootham Kiriaa ||","english":"Of all religious rituals, the most sublime ritual"},{"punjabi":"ਸਾਧਸੰਗਿ ਦੁਰਮਤਿ ਮਲੁ ਹਿਰਿਆ ॥","lareedar":"ਸਾਧਸੰਗਿਦੁਰਮਤਿਮਲੁਹਿਰਿਆ ॥","translit":"Saadhhasang Dhuramath Mal Hiriaa ||","english":"Is to erase the filth of the dirty mind in the Company of the Holy."},{"punjabi":"ਸਗਲ ਉਦਮ ਮਹਿ ਉਦਮੁ ਭਲਾ ॥","lareedar":"ਸਗਲਉਦਮਮਹਿਉਦਮੁਭਲਾ ॥","translit":"Sagal Oudham Mehi Oudham Bhalaa ||","english":"Of all efforts, the best effort"},{"punjabi":"ਹਰਿ ਕਾ ਨਾਮੁ ਜਪਹੁ ਜੀਅ ਸਦਾ ॥","lareedar":"ਹਰਿਕਾਨਾਮੁਜਪਹੁਜੀਅਸਦਾ ॥","translit":"Har Kaa Naam Japahu Jeea Sadhaa ||","english":"Is to chant the Name of the Lord in the heart, forever."},{"punjabi":"ਸਗਲ ਬਾਨੀ ਮਹਿ ਅੰਮ੍ਰਿਤ ਬਾਨੀ ॥","lareedar":"ਸਗਲਬਾਨੀਮਹਿਅੰਮ੍ਰਿਤਬਾਨੀ ॥","translit":"Sagal Baanee Mehi Anmrith Baanee ||","english":"Of all speech, the most ambrosial speech"},{"punjabi":"ਹਰਿ ਕੋ ਜਸੁ ਸੁਨਿ ਰਸਨ ਬਖਾਨੀ ॥","lareedar":"ਹਰਿਕੋਜਸੁਸੁਨਿਰਸਨਬਖਾਨੀ ॥","translit":"Har Ko Jas Sun Rasan Bakhaanee ||","english":"Is to hear the Lord's Praise and chant it with the tongue."},{"punjabi":"ਸਗਲ ਥਾਨ ਤੇ ਓਹੁ ਊਤਮ ਥਾਨੁ ॥","lareedar":"ਸਗਲਥਾਨਤੇਓਹੁਊਤਮਥਾਨੁ ॥","translit":"Sagal Thhaan Thae Ouhu Ootham Thhaan ||","english":"Of all places, the most sublime place,"},{"punjabi":"ਨਾਨਕ ਜਿਹ ਘਟਿ ਵਸੈ ਹਰਿ ਨਾਮੁ ॥੮॥੩॥","lareedar":"ਨਾਨਕਜਿਹਘਟਿਵਸੈਹਰਿਨਾਮੁ ॥੮ ॥੩ ॥","translit":"Naanak Jih Ghatt Vasai Har Naam ||8||3||","english":"O Nanak, is that heart in which the Name of the Lord abides. ||8||3||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਨਿਰਗੁਨੀਆਰ ਇਆਨਿਆ ਸੋ ਪ੍ਰਭੁ ਸਦਾ ਸਮਾਲਿ ॥","lareedar":"ਨਿਰਗੁਨੀਆਰਇਆਨਿਆਸੋਪ੍ਰਭੁਸਦਾਸਮਾਲਿ ॥","translit":"Niraguneeaar Eiaaniaa So Prabh Sadhaa Samaal ||","english":"You worthless, ignorant fool - dwell upon God forever."},{"punjabi":"ਜਿਨਿ ਕੀਆ ਤਿਸੁ ਚੀਤਿ ਰਖੁ ਨਾਨਕ ਨਿਬਹੀ ਨਾਲਿ ॥੧॥","lareedar":"ਜਿਨਿਕੀਆਤਿਸੁਚੀਤਿਰਖੁਨਾਨਕਨਿਬਹੀਨਾਲਿ ॥੧ ॥","translit":"Jin Keeaa This Cheeth Rakh Naanak Nibehee Naal ||1||","english":"Cherish in your consciousness the One who created you; O Nanak, He alone shall go along with you. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਰਮਈਆ ਕੇ ਗੁਨ ਚੇਤਿ ਪਰਾਨੀ ॥","lareedar":"ਰਮਈਆਕੇਗੁਨਚੇਤਿਪਰਾਨੀ ॥","translit":"Rameeaa Kae Gun Chaeth Paraanee ||","english":"Think of the Glory of the All-pervading Lord, O mortal;"},{"punjabi":"ਕਵਨ ਮੂਲ ਤੇ ਕਵਨ ਦ੍ਰਿਸਟਾਨੀ ॥","lareedar":"ਕਵਨਮੂਲਤੇਕਵਨਦ੍ਰਿਸਟਾਨੀ ॥","translit":"Kavan Mool Thae Kavan Dhrisattaanee ||","english":"What is your origin, and what is your appearance?"},{"punjabi":"ਜਿਨਿ ਤੂੰ ਸਾਜਿ ਸਵਾਰਿ ਸੀਗਾਰਿਆ ॥","lareedar":"ਜਿਨਿਤੂੰਸਾਜਿਸਵਾਰਿਸੀਗਾਰਿਆ ॥","translit":"Jin Thoon Saaj Savaar Seegaariaa ||","english":"He who fashioned, adorned and decorated you"},{"punjabi":"ਗਰਭ ਅਗਨਿ ਮਹਿ ਜਿਨਹਿ ਉਬਾਰਿਆ ॥","lareedar":"ਗਰਭਅਗਨਿਮਹਿਜਿਨਹਿਉਬਾਰਿਆ ॥","translit":"Garabh Agan Mehi Jinehi Oubaariaa ||","english":"In the fire of the womb, He preserved you."},{"punjabi":"ਬਾਰ ਬਿਵਸਥਾ ਤੁਝਹਿ ਪਿਆਰੈ ਦੂਧ ॥","lareedar":"ਬਾਰਬਿਵਸਥਾਤੁਝਹਿਪਿਆਰੈਦੂਧ ॥","translit":"Baar Bivasathhaa Thujhehi Piaarai Dhoodhh ||","english":"In your infancy, He gave you milk to drink."},{"punjabi":"ਭਰਿ ਜੋਬਨ ਭੋਜਨ ਸੁਖ ਸੂਧ ॥","lareedar":"ਭਰਿਜੋਬਨਭੋਜਨਸੁਖਸੂਧ ॥","translit":"Bhar Joban Bhojan Sukh Soodhh ||","english":"In the flower of your youth, He gave you food, pleasure and understanding."},{"punjabi":"ਬਿਰਧਿ ਭਇਆ ਊਪਰਿ ਸਾਕ ਸੈਨ ॥","lareedar":"ਬਿਰਧਿਭਇਆਊਪਰਿਸਾਕਸੈਨ ॥","translit":"Biradhh Bhaeiaa Oopar Saak Sain ||","english":"As you grow old, family and friends"},{"punjabi":"ਮੁਖਿ ਅਪਿਆਉ ਬੈਠ ਕਉ ਦੈਨ ॥","lareedar":"ਮੁਖਿਅਪਿਆਉਬੈਠਕਉਦੈਨ ॥","translit":"Mukh Apiaao Baith Ko Dhain ||","english":"Are there to feed you as you rest."},{"punjabi":"ਇਹੁ ਨਿਰਗੁਨੁ ਗੁਨੁ ਕਛੂ ਨ ਬੂਝੈ ॥","lareedar":"ਇਹੁਨਿਰਗੁਨੁਗੁਨੁਕਛੂਨਬੂਝੈ ॥","translit":"Eihu Niragun Gun Kashhoo N Boojhai ||","english":"This worthless person has not appreciated in the least, all the good deeds done for him."},{"punjabi":"ਬਖਸਿ ਲੇਹੁ ਤਉ ਨਾਨਕ ਸੀਝੈ ॥੧॥","lareedar":"ਬਖਸਿਲੇਹੁਤਉਨਾਨਕਸੀਝੈ ॥੧ ॥","translit":"Bakhas Laehu Tho Naanak Seejhai ||1||","english":"If you bless him with forgiveness, O Nanak, only then will he be saved. ||1||"},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਧਰ ਊਪਰਿ ਸੁਖਿ ਬਸਹਿ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਧਰਊਪਰਿਸੁਖਿਬਸਹਿ ॥","translit":"Jih Prasaadh Dhhar Oopar Sukh Basehi ||","english":"By His Grace, you abide in comfort upon the earth."},{"punjabi":"ਸੁਤ ਭ੍ਰਾਤ ਮੀਤ ਬਨਿਤਾ ਸੰਗਿ ਹਸਹਿ ॥","lareedar":"ਸੁਤਭ੍ਰਾਤਮੀਤਬਨਿਤਾਸੰਗਿਹਸਹਿ ॥","translit":"Suth Bhraath Meeth Banithaa Sang Hasehi ||","english":"With your children, siblings, friends and spouse, you laugh."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਪੀਵਹਿ ਸੀਤਲ ਜਲਾ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਪੀਵਹਿਸੀਤਲਜਲਾ ॥","translit":"Jih Prasaadh Peevehi Seethal Jalaa ||","english":"By His Grace, you drink in cool water."}]},{"index":12,"ang":267,"lines":[{"punjabi":"ਸੁਖਦਾਈ ਪਵਨੁ ਪਾਵਕੁ ਅਮੁਲਾ ॥","lareedar":"ਸੁਖਦਾਈਪਵਨੁਪਾਵਕੁਅਮੁਲਾ ॥","translit":"Sukhadhaaee Pavan Paavak Amulaa ||","english":"You have peaceful breezes and priceless fire."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਭੋਗਹਿ ਸਭਿ ਰਸਾ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਭੋਗਹਿਸਭਿਰਸਾ ॥","translit":"Jih Prasaadh Bhogehi Sabh Rasaa ||","english":"By His Grace, you enjoy all sorts of pleasures."},{"punjabi":"ਸਗਲ ਸਮਗ੍ਰੀ ਸੰਗਿ ਸਾਥਿ ਬਸਾ ॥","lareedar":"ਸਗਲਸਮਗ੍ਰੀਸੰਗਿਸਾਥਿਬਸਾ ॥","translit":"Sagal Samagree Sang Saathh Basaa ||","english":"You are provided with all the necessities of life."},{"punjabi":"ਦੀਨੇ ਹਸਤ ਪਾਵ ਕਰਨ ਨੇਤ੍ਰ ਰਸਨਾ ॥","lareedar":"ਦੀਨੇਹਸਤਪਾਵਕਰਨਨੇਤ੍ਰਰਸਨਾ ॥","translit":"Dheenae Hasath Paav Karan Naethr Rasanaa ||","english":"He gave you hands, feet, ears, eyes and tongue,"},{"punjabi":"ਤਿਸਹਿ ਤਿਆਗਿ ਅਵਰ ਸੰਗਿ ਰਚਨਾ ॥","lareedar":"ਤਿਸਹਿਤਿਆਗਿਅਵਰਸੰਗਿਰਚਨਾ ॥","translit":"Thisehi Thiaag Avar Sang Rachanaa ||","english":"And yet, you forsake Him and attach yourself to others."},{"punjabi":"ਐਸੇ ਦੋਖ ਮੂੜ ਅੰਧ ਬਿਆਪੇ ॥","lareedar":"ਐਸੇਦੋਖਮੂੜਅੰਧਬਿਆਪੇ ॥","translit":"Aisae Dhokh Moorr Andhh Biaapae ||","english":"Such sinful mistakes cling to the blind fools;"},{"punjabi":"ਨਾਨਕ ਕਾਢਿ ਲੇਹੁ ਪ੍ਰਭ ਆਪੇ ॥੨॥","lareedar":"ਨਾਨਕਕਾਢਿਲੇਹੁਪ੍ਰਭਆਪੇ ॥੨ ॥","translit":"Naanak Kaadt Laehu Prabh Aapae ||2||","english":"Nanak: uplift and save them, God! ||2||"},{"punjabi":"ਆਦਿ ਅੰਤਿ ਜੋ ਰਾਖਨਹਾਰੁ ॥","lareedar":"ਆਦਿਅੰਤਿਜੋਰਾਖਨਹਾਰੁ ॥","translit":"Aadh Anth Jo Raakhanehaar ||","english":"From beginning to end, He is our Protector,"},{"punjabi":"ਤਿਸ ਸਿਉ ਪ੍ਰੀਤਿ ਨ ਕਰੈ ਗਵਾਰੁ ॥","lareedar":"ਤਿਸਸਿਉਪ੍ਰੀਤਿਨਕਰੈਗਵਾਰੁ ॥","translit":"This Sio Preeth N Karai Gavaar ||","english":"And yet, the ignorant do not give their love to Him."},{"punjabi":"ਜਾ ਕੀ ਸੇਵਾ ਨਵ ਨਿਧਿ ਪਾਵੈ ॥","lareedar":"ਜਾਕੀਸੇਵਾਨਵਨਿਧਿਪਾਵੈ ॥","translit":"Jaa Kee Saevaa Nav Nidhh Paavai ||","english":"Serving Him, the nine treasures are obtained,"},{"punjabi":"ਤਾ ਸਿਉ ਮੂੜਾ ਮਨੁ ਨਹੀ ਲਾਵੈ ॥","lareedar":"ਤਾਸਿਉਮੂੜਾਮਨੁਨਹੀਲਾਵੈ ॥","translit":"Thaa Sio Moorraa Man Nehee Laavai ||","english":"And yet, the foolish do not link their minds with Him."},{"punjabi":"ਜੋ ਠਾਕੁਰੁ ਸਦ ਸਦਾ ਹਜੂਰੇ ॥","lareedar":"ਜੋਠਾਕੁਰੁਸਦਸਦਾਹਜੂਰੇ ॥","translit":"Jo Thaakur Sadh Sadhaa Hajoorae ||","english":"Our Lord and Master is Ever-present, forever and ever,"},{"punjabi":"ਤਾ ਕਉ ਅੰਧਾ ਜਾਨਤ ਦੂਰੇ ॥","lareedar":"ਤਾਕਉਅੰਧਾਜਾਨਤਦੂਰੇ ॥","translit":"Thaa Ko Andhhaa Jaanath Dhoorae ||","english":"And yet, the spiritually blind believe that He is far away."},{"punjabi":"ਜਾ ਕੀ ਟਹਲ ਪਾਵੈ ਦਰਗਹ ਮਾਨੁ ॥","lareedar":"ਜਾਕੀਟਹਲਪਾਵੈਦਰਗਹਮਾਨੁ ॥","translit":"Jaa Kee Ttehal Paavai Dharageh Maan ||","english":"In His service, one obtains honor in the Court of the Lord,"},{"punjabi":"ਤਿਸਹਿ ਬਿਸਾਰੈ ਮੁਗਧੁ ਅਜਾਨੁ ॥","lareedar":"ਤਿਸਹਿਬਿਸਾਰੈਮੁਗਧੁਅਜਾਨੁ ॥","translit":"Thisehi Bisaarai Mugadhh Ajaan ||","english":"And yet, the ignorant fool forgets Him."},{"punjabi":"ਸਦਾ ਸਦਾ ਇਹੁ ਭੂਲਨਹਾਰੁ ॥","lareedar":"ਸਦਾਸਦਾਇਹੁਭੂਲਨਹਾਰੁ ॥","translit":"Sadhaa Sadhaa Eihu Bhoolanehaar ||","english":"Forever and ever, this person makes mistakes;"},{"punjabi":"ਨਾਨਕ ਰਾਖਨਹਾਰੁ ਅਪਾਰੁ ॥੩॥","lareedar":"ਨਾਨਕਰਾਖਨਹਾਰੁਅਪਾਰੁ ॥੩ ॥","translit":"Naanak Raakhanehaar Apaar ||3||","english":"O Nanak, the Infinite Lord is our Saving Grace. ||3||"},{"punjabi":"ਰਤਨੁ ਤਿਆਗਿ ਕਉਡੀ ਸੰਗਿ ਰਚੈ ॥","lareedar":"ਰਤਨੁਤਿਆਗਿਕਉਡੀਸੰਗਿਰਚੈ ॥","translit":"Rathan Thiaag Kouddee Sang Rachai ||","english":"Forsaking the jewel, they are engrossed with a shell."},{"punjabi":"ਸਾਚੁ ਛੋਡਿ ਝੂਠ ਸੰਗਿ ਮਚੈ ॥","lareedar":"ਸਾਚੁਛੋਡਿਝੂਠਸੰਗਿਮਚੈ ॥","translit":"Saach Shhodd Jhooth Sang Machai ||","english":"They renounce Truth and embrace falsehood."},{"punjabi":"ਜੋ ਛਡਨਾ ਸੁ ਅਸਥਿਰੁ ਕਰਿ ਮਾਨੈ ॥","lareedar":"ਜੋਛਡਨਾਸੁਅਸਥਿਰੁਕਰਿਮਾਨੈ ॥","translit":"Jo Shhaddanaa S Asathhir Kar Maanai ||","english":"That which passes away, they believe to be permanent."},{"punjabi":"ਜੋ ਹੋਵਨੁ ਸੋ ਦੂਰਿ ਪਰਾਨੈ ॥","lareedar":"ਜੋਹੋਵਨੁਸੋਦੂਰਿਪਰਾਨੈ ॥","translit":"Jo Hovan So Dhoor Paraanai ||","english":"That which is immanent, they believe to be far off."},{"punjabi":"ਛੋਡਿ ਜਾਇ ਤਿਸ ਕਾ ਸ੍ਰਮੁ ਕਰੈ ॥","lareedar":"ਛੋਡਿਜਾਇਤਿਸਕਾਸ੍ਰਮੁਕਰੈ ॥","translit":"Shhodd Jaae This Kaa Sram Karai ||","english":"They struggle for what they must eventually leave."},{"punjabi":"ਸੰਗਿ ਸਹਾਈ ਤਿਸੁ ਪਰਹਰੈ ॥","lareedar":"ਸੰਗਿਸਹਾਈਤਿਸੁਪਰਹਰੈ ॥","translit":"Sang Sehaaee This Pareharai ||","english":"They turn away from the Lord, their Help and Support, who is always with them."},{"punjabi":"ਚੰਦਨ ਲੇਪੁ ਉਤਾਰੈ ਧੋਇ ॥","lareedar":"ਚੰਦਨਲੇਪੁਉਤਾਰੈਧੋਇ ॥","translit":"Chandhan Laep Outhaarai Dhhoe ||","english":"They wash off the sandalwood paste;"},{"punjabi":"ਗਰਧਬ ਪ੍ਰੀਤਿ ਭਸਮ ਸੰਗਿ ਹੋਇ ॥","lareedar":"ਗਰਧਬਪ੍ਰੀਤਿਭਸਮਸੰਗਿਹੋਇ ॥","translit":"Garadhhab Preeth Bhasam Sang Hoe ||","english":"Like donkeys, they are in love with the mud."}]},{"index":13,"ang":267,"lines":[{"punjabi":"ਅੰਧ ਕੂਪ ਮਹਿ ਪਤਿਤ ਬਿਕਰਾਲ ॥","lareedar":"ਅੰਧਕੂਪਮਹਿਪਤਿਤਬਿਕਰਾਲ ॥","translit":"Andhh Koop Mehi Pathith Bikaraal ||","english":"They have fallen into the deep, dark pit."},{"punjabi":"ਨਾਨਕ ਕਾਢਿ ਲੇਹੁ ਪ੍ਰਭ ਦਇਆਲ ॥੪॥","lareedar":"ਨਾਨਕਕਾਢਿਲੇਹੁਪ੍ਰਭਦਇਆਲ ॥੪ ॥","translit":"Naanak Kaadt Laehu Prabh Dhaeiaal ||4||","english":"Nanak: lift them up and save them, O Merciful Lord God! ||4||"},{"punjabi":"ਕਰਤੂਤਿ ਪਸੂ ਕੀ ਮਾਨਸ ਜਾਤਿ ॥","lareedar":"ਕਰਤੂਤਿਪਸੂਕੀਮਾਨਸਜਾਤਿ ॥","translit":"Karathooth Pasoo Kee Maanas Jaath ||","english":"They belong to the human species, but they act like animals."},{"punjabi":"ਲੋਕ ਪਚਾਰਾ ਕਰੈ ਦਿਨੁ ਰਾਤਿ ॥","lareedar":"ਲੋਕਪਚਾਰਾਕਰੈਦਿਨੁਰਾਤਿ ॥","translit":"Lok Pachaaraa Karai Dhin Raath ||","english":"They curse others day and night."},{"punjabi":"ਬਾਹਰਿ ਭੇਖ ਅੰਤਰਿ ਮਲੁ ਮਾਇਆ ॥","lareedar":"ਬਾਹਰਿਭੇਖਅੰਤਰਿਮਲੁਮਾਇਆ ॥","translit":"Baahar Bhaekh Anthar Mal Maaeiaa ||","english":"Outwardly, they wear religious robes, but within is the filth of Maya."},{"punjabi":"ਛਪਸਿ ਨਾਹਿ ਕਛੁ ਕਰੈ ਛਪਾਇਆ ॥","lareedar":"ਛਪਸਿਨਾਹਿਕਛੁਕਰੈਛਪਾਇਆ ॥","translit":"Shhapas Naahi Kashh Karai Shhapaaeiaa ||","english":"They cannot conceal this, no matter how hard they try."},{"punjabi":"ਬਾਹਰਿ ਗਿਆਨ ਧਿਆਨ ਇਸਨਾਨ ॥","lareedar":"ਬਾਹਰਿਗਿਆਨਧਿਆਨਇਸਨਾਨ ॥","translit":"Baahar Giaan Dhhiaan Eisanaan ||","english":"Outwardly, they display knowledge, meditation and purification,"},{"punjabi":"ਅੰਤਰਿ ਬਿਆਪੈ ਲੋਭੁ ਸੁਆਨੁ ॥","lareedar":"ਅੰਤਰਿਬਿਆਪੈਲੋਭੁਸੁਆਨੁ ॥","translit":"Anthar Biaapai Lobh Suaan ||","english":"But within clings the dog of greed."},{"punjabi":"ਅੰਤਰਿ ਅਗਨਿ ਬਾਹਰਿ ਤਨੁ ਸੁਆਹ ॥","lareedar":"ਅੰਤਰਿਅਗਨਿਬਾਹਰਿਤਨੁਸੁਆਹ ॥","translit":"Anthar Agan Baahar Than Suaah ||","english":"The fire of desire rages within; outwardly they apply ashes to their bodies."},{"punjabi":"ਗਲਿ ਪਾਥਰ ਕੈਸੇ ਤਰੈ ਅਥਾਹ ॥","lareedar":"ਗਲਿਪਾਥਰਕੈਸੇਤਰੈਅਥਾਹ ॥","translit":"Gal Paathhar Kaisae Tharai Athhaah ||","english":"There is a stone around their neck - how can they cross the unfathomable ocean?"},{"punjabi":"ਜਾ ਕੈ ਅੰਤਰਿ ਬਸੈ ਪ੍ਰਭੁ ਆਪਿ ॥","lareedar":"ਜਾਕੈਅੰਤਰਿਬਸੈਪ੍ਰਭੁਆਪਿ ॥","translit":"Jaa Kai Anthar Basai Prabh Aap ||","english":"Those, within whom God Himself abides"},{"punjabi":"ਨਾਨਕ ਤੇ ਜਨ ਸਹਜਿ ਸਮਾਤਿ ॥੫॥","lareedar":"ਨਾਨਕਤੇਜਨਸਹਜਿਸਮਾਤਿ ॥੫ ॥","translit":"Naanak Thae Jan Sehaj Samaath ||5||","english":"- O Nanak, those humble beings are intuitively absorbed in the Lord. ||5||"},{"punjabi":"ਸੁਨਿ ਅੰਧਾ ਕੈਸੇ ਮਾਰਗੁ ਪਾਵੈ ॥","lareedar":"ਸੁਨਿਅੰਧਾਕੈਸੇਮਾਰਗੁਪਾਵੈ ॥","translit":"Sun Andhhaa Kaisae Maarag Paavai ||","english":"By listening, how can the blind find the path?"},{"punjabi":"ਕਰੁ ਗਹਿ ਲੇਹੁ ਓੜਿ ਨਿਬਹਾਵੈ ॥","lareedar":"ਕਰੁਗਹਿਲੇਹੁਓੜਿਨਿਬਹਾਵੈ ॥","translit":"Kar Gehi Laehu Ourr Nibehaavai ||","english":"Take hold of his hand, and then he can reach his destination."},{"punjabi":"ਕਹਾ ਬੁਝਾਰਤਿ ਬੂਝੈ ਡੋਰਾ ॥","lareedar":"ਕਹਾਬੁਝਾਰਤਿਬੂਝੈਡੋਰਾ ॥","translit":"Kehaa Bujhaarath Boojhai Ddoraa ||","english":"How can a riddle be understood by the deaf?"},{"punjabi":"ਨਿਸਿ ਕਹੀਐ ਤਉ ਸਮਝੈ ਭੋਰਾ ॥","lareedar":"ਨਿਸਿਕਹੀਐਤਉਸਮਝੈਭੋਰਾ ॥","translit":"Nis Keheeai Tho Samajhai Bhoraa ||","english":"Say 'night', and he thinks you said 'day'."},{"punjabi":"ਕਹਾ ਬਿਸਨਪਦ ਗਾਵੈ ਗੁੰਗ ॥","lareedar":"ਕਹਾਬਿਸਨਪਦਗਾਵੈਗੁੰਗ ॥","translit":"Kehaa Bisanapadh Gaavai Gung ||","english":"How can the mute sing the Songs of the Lord?"},{"punjabi":"ਜਤਨ ਕਰੈ ਤਉ ਭੀ ਸੁਰ ਭੰਗ ॥","lareedar":"ਜਤਨਕਰੈਤਉਭੀਸੁਰਭੰਗ ॥","translit":"Jathan Karai Tho Bhee Sur Bhang ||","english":"He may try, but his voice will fail him."},{"punjabi":"ਕਹ ਪਿੰਗੁਲ ਪਰਬਤ ਪਰ ਭਵਨ ॥","lareedar":"ਕਹਪਿੰਗੁਲਪਰਬਤਪਰਭਵਨ ॥","translit":"Keh Pingul Parabath Par Bhavan ||","english":"How can the cripple climb up the mountain?"},{"punjabi":"ਨਹੀ ਹੋਤ ਊਹਾ ਉਸੁ ਗਵਨ ॥","lareedar":"ਨਹੀਹੋਤਊਹਾਉਸੁਗਵਨ ॥","translit":"Nehee Hoth Oohaa Ous Gavan ||","english":"He simply cannot go there."},{"punjabi":"ਕਰਤਾਰ ਕਰੁਣਾ ਮੈ ਦੀਨੁ ਬੇਨਤੀ ਕਰੈ ॥","lareedar":"ਕਰਤਾਰਕਰੁਣਾਮੈਦੀਨੁਬੇਨਤੀਕਰੈ ॥","translit":"Karathaar Karunaa Mai Dheen Baenathee Karai ||","english":"O Creator, Lord of Mercy - Your humble servant prays;"},{"punjabi":"ਨਾਨਕ ਤੁਮਰੀ ਕਿਰਪਾ ਤਰੈ ॥੬॥","lareedar":"ਨਾਨਕਤੁਮਰੀਕਿਰਪਾਤਰੈ ॥੬ ॥","translit":"Naanak Thumaree Kirapaa Tharai ||6||","english":"Nanak: by Your Grace, please save me. ||6||"},{"punjabi":"ਸੰਗਿ ਸਹਾਈ ਸੁ ਆਵੈ ਨ ਚੀਤਿ ॥","lareedar":"ਸੰਗਿਸਹਾਈਸੁਆਵੈਨਚੀਤਿ ॥","translit":"Sang Sehaaee S Aavai N Cheeth ||","english":"The Lord, our Help and Support, is always with us, but the mortal does not remember Him."},{"punjabi":"ਜੋ ਬੈਰਾਈ ਤਾ ਸਿਉ ਪ੍ਰੀਤਿ ॥","lareedar":"ਜੋਬੈਰਾਈਤਾਸਿਉਪ੍ਰੀਤਿ ॥","translit":"Jo Bairaaee Thaa Sio Preeth ||","english":"He shows love to his enemies."},{"punjabi":"ਬਲੂਆ ਕੇ ਗ੍ਰਿਹ ਭੀਤਰਿ ਬਸੈ ॥","lareedar":"ਬਲੂਆਕੇਗ੍ਰਿਹਭੀਤਰਿਬਸੈ ॥","translit":"Balooaa Kae Grih Bheethar Basai ||","english":"He lives in a castle of sand."}]},{"index":14,"ang":267,"lines":[{"punjabi":"ਅਨਦ ਕੇਲ ਮਾਇਆ ਰੰਗਿ ਰਸੈ ॥","lareedar":"ਅਨਦਕੇਲਮਾਇਆਰੰਗਿਰਸੈ ॥","translit":"Anadh Kael Maaeiaa Rang Rasai ||","english":"He enjoys the games of pleasure and the tastes of Maya."},{"punjabi":"ਦ੍ਰਿੜੁ ਕਰਿ ਮਾਨੈ ਮਨਹਿ ਪ੍ਰਤੀਤਿ ॥","lareedar":"ਦ੍ਰਿੜੁਕਰਿਮਾਨੈਮਨਹਿਪ੍ਰਤੀਤਿ ॥","translit":"Dhrirr Kar Maanai Manehi Pratheeth ||","english":"He believes them to be permanent - this is the belief of his mind."},{"punjabi":"ਕਾਲੁ ਨ ਆਵੈ ਮੂੜੇ ਚੀਤਿ ॥","lareedar":"ਕਾਲੁਨਆਵੈਮੂੜੇਚੀਤਿ ॥","translit":"Kaal N Aavai Moorrae Cheeth ||","english":"Death does not even come to mind for the fool."},{"punjabi":"ਬੈਰ ਬਿਰੋਧ ਕਾਮ ਕ੍ਰੋਧ ਮੋਹ ॥","lareedar":"ਬੈਰਬਿਰੋਧਕਾਮਕ੍ਰੋਧਮੋਹ ॥","translit":"Bair Birodhh Kaam Krodhh Moh ||","english":"Hate, conflict, sexual desire, anger, emotional attachment,"},{"punjabi":"ਝੂਠ ਬਿਕਾਰ ਮਹਾ ਲੋਭ ਧ੍ਰੋਹ ॥","lareedar":"ਝੂਠਬਿਕਾਰਮਹਾਲੋਭਧ੍ਰੋਹ ॥","translit":"Jhooth Bikaar Mehaa Lobh Dhhroh ||","english":"Falsehood, corruption, immense greed and deceit:"},{"punjabi":"ਇਆਹੂ ਜੁਗਤਿ ਬਿਹਾਨੇ ਕਈ ਜਨਮ ॥","lareedar":"ਇਆਹੂਜੁਗਤਿਬਿਹਾਨੇਕਈਜਨਮ ॥","translit":"Eiaahoo Jugath Bihaanae Kee Janam ||","english":"So many lifetimes are wasted in these ways."},{"punjabi":"ਨਾਨਕ ਰਾਖਿ ਲੇਹੁ ਆਪਨ ਕਰਿ ਕਰਮ ॥੭॥","lareedar":"ਨਾਨਕਰਾਖਿਲੇਹੁਆਪਨਕਰਿਕਰਮ ॥੭ ॥","translit":"Naanak Raakh Laehu Aapan Kar Karam ||7||","english":"Nanak: uplift them, and redeem them, O Lord - show Your Mercy! ||7||"},{"punjabi":"ਤੂ ਠਾਕੁਰੁ ਤੁਮ ਪਹਿ ਅਰਦਾਸਿ ॥","lareedar":"ਤੂਠਾਕੁਰੁਤੁਮਪਹਿਅਰਦਾਸਿ ॥","translit":"Thoo Thaakur Thum Pehi Aradhaas ||","english":"You are our Lord and Master; to You, I offer this prayer."},{"punjabi":"ਜੀਉ ਪਿੰਡੁ ਸਭੁ ਤੇਰੀ ਰਾਸਿ ॥","lareedar":"ਜੀਉਪਿੰਡੁਸਭੁਤੇਰੀਰਾਸਿ ॥","translit":"Jeeo Pindd Sabh Thaeree Raas ||","english":"This body and soul are all Your property."},{"punjabi":"ਤੁਮ ਮਾਤ ਪਿਤਾ ਹਮ ਬਾਰਿਕ ਤੇਰੇ ॥","lareedar":"ਤੁਮਮਾਤਪਿਤਾਹਮਬਾਰਿਕਤੇਰੇ ॥","translit":"Thum Maath Pithaa Ham Baarik Thaerae ||","english":"You are our mother and father; we are Your children."},{"punjabi":"ਤੁਮਰੀ ਕ੍ਰਿਪਾ ਮਹਿ ਸੂਖ ਘਨੇਰੇ ॥","lareedar":"ਤੁਮਰੀਕ੍ਰਿਪਾਮਹਿਸੂਖਘਨੇਰੇ ॥","translit":"Thumaree Kirapaa Mehi Sookh Ghanaerae ||","english":"In Your Grace, there are so many joys!"},{"punjabi":"ਕੋਇ ਨ ਜਾਨੈ ਤੁਮਰਾ ਅੰਤੁ ॥","lareedar":"ਕੋਇਨਜਾਨੈਤੁਮਰਾਅੰਤੁ ॥","translit":"Koe N Jaanai Thumaraa Anth ||","english":"No one knows Your limits."},{"punjabi":"ਊਚੇ ਤੇ ਊਚਾ ਭਗਵੰਤ ॥","lareedar":"ਊਚੇਤੇਊਚਾਭਗਵੰਤ ॥","translit":"Oochae Thae Oochaa Bhagavanth ||","english":"O Highest of the High, Most Generous God,"},{"punjabi":"ਸਗਲ ਸਮਗ੍ਰੀ ਤੁਮਰੈ ਸੂਤ੍ਰਿ ਧਾਰੀ ॥","lareedar":"ਸਗਲਸਮਗ੍ਰੀਤੁਮਰੈਸੂਤ੍ਰਿਧਾਰੀ ॥","translit":"Sagal Samagree Thumarai Soothr Dhhaaree ||","english":"The whole creation is strung on Your thread."},{"punjabi":"ਤੁਮ ਤੇ ਹੋਇ ਸੁ ਆਗਿਆਕਾਰੀ ॥","lareedar":"ਤੁਮਤੇਹੋਇਸੁਆਗਿਆਕਾਰੀ ॥","translit":"Thum Thae Hoe S Aagiaakaaree ||","english":"That which has come from You is under Your Command."},{"punjabi":"ਤੁਮਰੀ ਗਤਿ ਮਿਤਿ ਤੁਮ ਹੀ ਜਾਨੀ ॥","lareedar":"ਤੁਮਰੀਗਤਿਮਿਤਿਤੁਮਹੀਜਾਨੀ ॥","translit":"Thumaree Gath Mith Thum Hee Jaanee ||","english":"You alone know Your state and extent."},{"punjabi":"ਨਾਨਕ ਦਾਸ ਸਦਾ ਕੁਰਬਾਨੀ ॥੮॥੪॥","lareedar":"ਨਾਨਕਦਾਸਸਦਾਕੁਰਬਾਨੀ ॥੮ ॥੪ ॥","translit":"Naanak Dhaas Sadhaa Kurabaanee ||8||4||","english":"Nanak, Your slave, is forever a sacrifice. ||8||4||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਦੇਨਹਾਰੁ ਪ੍ਰਭ ਛੋਡਿ ਕੈ ਲਾਗਹਿ ਆਨ ਸੁਆਇ ॥","lareedar":"ਦੇਨਹਾਰੁਪ੍ਰਭਛੋਡਿਕੈਲਾਗਹਿਆਨਸੁਆਇ ॥","translit":"Dhaenehaar Prabh Shhodd Kai Laagehi Aan Suaae ||","english":"One who renounces God the Giver, and attaches himself to other affairs"},{"punjabi":"ਨਾਨਕ ਕਹੂ ਨ ਸੀਝਈ ਬਿਨੁ ਨਾਵੈ ਪਤਿ ਜਾਇ ॥੧॥","lareedar":"ਨਾਨਕਕਹੂਨਸੀਝਈਬਿਨੁਨਾਵੈਪਤਿਜਾਇ ॥੧ ॥","translit":"Naanak Kehoo N Seejhee Bin Naavai Path Jaae ||1||","english":"- O Nanak, he shall never succeed. Without the Name, he shall lose his honor. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਦਸ ਬਸਤੂ ਲੇ ਪਾਛੈ ਪਾਵੈ ॥","lareedar":"ਦਸਬਸਤੂਲੇਪਾਛੈਪਾਵੈ ॥","translit":"Dhas Basathoo Lae Paashhai Paavai ||","english":"He obtains ten things, and puts them behind him;"},{"punjabi":"ਏਕ ਬਸਤੁ ਕਾਰਨਿ ਬਿਖੋਟਿ ਗਵਾਵੈ ॥","lareedar":"ਏਕਬਸਤੁਕਾਰਨਿਬਿਖੋਟਿਗਵਾਵੈ ॥","translit":"Eaek Basath Kaaran Bikhott Gavaavai ||","english":"For the sake of one thing withheld, he forfeits his faith."},{"punjabi":"ਏਕ ਭੀ ਨ ਦੇਇ ਦਸ ਭੀ ਹਿਰਿ ਲੇਇ ॥","lareedar":"ਏਕਭੀਨਦੇਇਦਸਭੀਹਿਰਿਲੇਇ ॥","translit":"Eaek Bhee N Dhaee Dhas Bhee Hir Laee ||","english":"But what if that one thing were not given, and the ten were taken away?"},{"punjabi":"ਤਉ ਮੂੜਾ ਕਹੁ ਕਹਾ ਕਰੇਇ ॥","lareedar":"ਤਉਮੂੜਾਕਹੁਕਹਾਕਰੇਇ ॥","translit":"Tho Moorraa Kahu Kehaa Karaee ||","english":"Then, what could the fool say or do?"}]},{"index":15,"ang":268,"lines":[{"punjabi":"ਜਿਸੁ ਠਾਕੁਰ ਸਿਉ ਨਾਹੀ ਚਾਰਾ ॥","lareedar":"ਜਿਸੁਠਾਕੁਰਸਿਉਨਾਹੀਚਾਰਾ ॥","translit":"Jis Thaakur Sio Naahee Chaaraa ||","english":"Our Lord and Master cannot be moved by force."},{"punjabi":"ਤਾ ਕਉ ਕੀਜੈ ਸਦ ਨਮਸਕਾਰਾ ॥","lareedar":"ਤਾਕਉਕੀਜੈਸਦਨਮਸਕਾਰਾ ॥","translit":"Thaa Ko Keejai Sadh Namasakaaraa ||","english":"Unto Him, bow forever in adoration."},{"punjabi":"ਜਾ ਕੈ ਮਨਿ ਲਾਗਾ ਪ੍ਰਭੁ ਮੀਠਾ ॥","lareedar":"ਜਾਕੈਮਨਿਲਾਗਾਪ੍ਰਭੁਮੀਠਾ ॥","translit":"Jaa Kai Man Laagaa Prabh Meethaa ||","english":"That one, unto whose mind God seems sweet"},{"punjabi":"ਸਰਬ ਸੂਖ ਤਾਹੂ ਮਨਿ ਵੂਠਾ ॥","lareedar":"ਸਰਬਸੂਖਤਾਹੂਮਨਿਵੂਠਾ ॥","translit":"Sarab Sookh Thaahoo Man Voothaa ||","english":"All pleasures come to abide in his mind."},{"punjabi":"ਜਿਸੁ ਜਨ ਅਪਨਾ ਹੁਕਮੁ ਮਨਾਇਆ ॥","lareedar":"ਜਿਸੁਜਨਅਪਨਾਹੁਕਮੁਮਨਾਇਆ ॥","translit":"Jis Jan Apanaa Hukam Manaaeiaa ||","english":"One who abides by the Lord's Will,"},{"punjabi":"ਸਰਬ ਥੋਕ ਨਾਨਕ ਤਿਨਿ ਪਾਇਆ ॥੧॥","lareedar":"ਸਰਬਥੋਕਨਾਨਕਤਿਨਿਪਾਇਆ ॥੧ ॥","translit":"Sarab Thhok Naanak Thin Paaeiaa ||1||","english":"O Nanak, obtains all things. ||1||"},{"punjabi":"ਅਗਨਤ ਸਾਹੁ ਅਪਨੀ ਦੇ ਰਾਸਿ ॥","lareedar":"ਅਗਨਤਸਾਹੁਅਪਨੀਦੇਰਾਸਿ ॥","translit":"Aganath Saahu Apanee Dhae Raas ||","english":"God the Banker gives endless capital to the mortal,"},{"punjabi":"ਖਾਤ ਪੀਤ ਬਰਤੈ ਅਨਦ ਉਲਾਸਿ ॥","lareedar":"ਖਾਤਪੀਤਬਰਤੈਅਨਦਉਲਾਸਿ ॥","translit":"Khaath Peeth Barathai Anadh Oulaas ||","english":"Who eats, drinks and expends it with pleasure and joy."},{"punjabi":"ਅਪੁਨੀ ਅਮਾਨ ਕਛੁ ਬਹੁਰਿ ਸਾਹੁ ਲੇਇ ॥","lareedar":"ਅਪੁਨੀਅਮਾਨਕਛੁਬਹੁਰਿਸਾਹੁਲੇਇ ॥","translit":"Apunee Amaan Kashh Bahur Saahu Laee ||","english":"If some of this capital is later taken back by the Banker,"},{"punjabi":"ਅਗਿਆਨੀ ਮਨਿ ਰੋਸੁ ਕਰੇਇ ॥","lareedar":"ਅਗਿਆਨੀਮਨਿਰੋਸੁਕਰੇਇ ॥","translit":"Agiaanee Man Ros Karaee ||","english":"The ignorant person shows his anger."},{"punjabi":"ਅਪਨੀ ਪਰਤੀਤਿ ਆਪ ਹੀ ਖੋਵੈ ॥","lareedar":"ਅਪਨੀਪਰਤੀਤਿਆਪਹੀਖੋਵੈ ॥","translit":"Apanee Paratheeth Aap Hee Khovai ||","english":"He himself destroys his own credibility,"},{"punjabi":"ਬਹੁਰਿ ਉਸ ਕਾ ਬਿਸ੍ਵਾਸੁ ਨ ਹੋਵੈ ॥","lareedar":"ਬਹੁਰਿਉਸਕਾਬਿਸ੍ਵਾਸੁਨਹੋਵੈ ॥","translit":"Bahur Ous Kaa Bisvaas N Hovai ||","english":"And he shall not again be trusted."},{"punjabi":"ਜਿਸ ਕੀ ਬਸਤੁ ਤਿਸੁ ਆਗੈ ਰਾਖੈ ॥","lareedar":"ਜਿਸਕੀਬਸਤੁਤਿਸੁਆਗੈਰਾਖੈ ॥","translit":"Jis Kee Basath This Aagai Raakhai ||","english":"When one offers to the Lord, that which belongs to the Lord,"},{"punjabi":"ਪ੍ਰਭ ਕੀ ਆਗਿਆ ਮਾਨੈ ਮਾਥੈ ॥","lareedar":"ਪ੍ਰਭਕੀਆਗਿਆਮਾਨੈਮਾਥੈ ॥","translit":"Prabh Kee Aagiaa Maanai Maathhai ||","english":"And willingly abides by the Will of God's Order,"},{"punjabi":"ਉਸ ਤੇ ਚਉਗੁਨ ਕਰੈ ਨਿਹਾਲੁ ॥","lareedar":"ਉਸਤੇਚਉਗੁਨਕਰੈਨਿਹਾਲੁ ॥","translit":"Ous Thae Chougun Karai Nihaal ||","english":"The Lord will make him happy four times over."},{"punjabi":"ਨਾਨਕ ਸਾਹਿਬੁ ਸਦਾ ਦਇਆਲੁ ॥੨॥","lareedar":"ਨਾਨਕਸਾਹਿਬੁਸਦਾਦਇਆਲੁ ॥੨ ॥","translit":"Naanak Saahib Sadhaa Dhaeiaal ||2||","english":"O Nanak, our Lord and Master is merciful forever. ||2||"},{"punjabi":"ਅਨਿਕ ਭਾਤਿ ਮਾਇਆ ਕੇ ਹੇਤ ॥","lareedar":"ਅਨਿਕਭਾਤਿਮਾਇਆਕੇਹੇਤ ॥","translit":"Anik Bhaath Maaeiaa Kae Haeth ||","english":"The many forms of attachment to Maya shall surely pass away -"},{"punjabi":"ਸਰਪਰ ਹੋਵਤ ਜਾਨੁ ਅਨੇਤ ॥","lareedar":"ਸਰਪਰਹੋਵਤਜਾਨੁਅਨੇਤ ॥","translit":"Sarapar Hovath Jaan Anaeth ||","english":"Know that they are transitory."},{"punjabi":"ਬਿਰਖ ਕੀ ਛਾਇਆ ਸਿਉ ਰੰਗੁ ਲਾਵੈ ॥","lareedar":"ਬਿਰਖਕੀਛਾਇਆਸਿਉਰੰਗੁਲਾਵੈ ॥","translit":"Birakh Kee Shhaaeiaa Sio Rang Laavai ||","english":"People fall in love with the shade of the tree,"},{"punjabi":"ਓਹ ਬਿਨਸੈ ਉਹੁ ਮਨਿ ਪਛੁਤਾਵੈ ॥","lareedar":"ਓਹਬਿਨਸੈਉਹੁਮਨਿਪਛੁਤਾਵੈ ॥","translit":"Ouh Binasai Ouhu Man Pashhuthaavai ||","english":"And when it passes away, they feel regret in their minds."},{"punjabi":"ਜੋ ਦੀਸੈ ਸੋ ਚਾਲਨਹਾਰੁ ॥","lareedar":"ਜੋਦੀਸੈਸੋਚਾਲਨਹਾਰੁ ॥","translit":"Jo Dheesai So Chaalanehaar ||","english":"Whatever is seen, shall pass away;"},{"punjabi":"ਲਪਟਿ ਰਹਿਓ ਤਹ ਅੰਧ ਅੰਧਾਰੁ ॥","lareedar":"ਲਪਟਿਰਹਿਓਤਹਅੰਧਅੰਧਾਰੁ ॥","translit":"Lapatt Rehiou Theh Andhh Andhhaar ||","english":"And yet, the blindest of the blind cling to it."},{"punjabi":"ਬਟਾਊ ਸਿਉ ਜੋ ਲਾਵੈ ਨੇਹ ॥","lareedar":"ਬਟਾਊਸਿਉਜੋਲਾਵੈਨੇਹ ॥","translit":"Battaaoo Sio Jo Laavai Naeh ||","english":"One who gives her love to a passing traveler"},{"punjabi":"ਤਾ ਕਉ ਹਾਥਿ ਨ ਆਵੈ ਕੇਹ ॥","lareedar":"ਤਾਕਉਹਾਥਿਨਆਵੈਕੇਹ ॥","translit":"Thaa Ko Haathh N Aavai Kaeh ||","english":"Nothing shall come into her hands in this way."},{"punjabi":"ਮਨ ਹਰਿ ਕੇ ਨਾਮ ਕੀ ਪ੍ਰੀਤਿ ਸੁਖਦਾਈ ॥","lareedar":"ਮਨਹਰਿਕੇਨਾਮਕੀਪ੍ਰੀਤਿਸੁਖਦਾਈ ॥","translit":"Man Har Kae Naam Kee Preeth Sukhadhaaee ||","english":"O mind, the love of the Name of the Lord bestows peace."}]},{"index":16,"ang":268,"lines":[{"punjabi":"ਕਰਿ ਕਿਰਪਾ ਨਾਨਕ ਆਪਿ ਲਏ ਲਾਈ ॥੩॥","lareedar":"ਕਰਿਕਿਰਪਾਨਾਨਕਆਪਿਲਏਲਾਈ ॥੩ ॥","translit":"Kar Kirapaa Naanak Aap Leae Laaee ||3||","english":"O Nanak, the Lord, in His Mercy, unites us with Himself. ||3||"},{"punjabi":"ਮਿਥਿਆ ਤਨੁ ਧਨੁ ਕੁਟੰਬੁ ਸਬਾਇਆ ॥","lareedar":"ਮਿਥਿਆਤਨੁਧਨੁਕੁਟੰਬੁਸਬਾਇਆ ॥","translit":"Mithhiaa Than Dhhan Kuttanb Sabaaeiaa ||","english":"False are body, wealth, and all relations."},{"punjabi":"ਮਿਥਿਆ ਹਉਮੈ ਮਮਤਾ ਮਾਇਆ ॥","lareedar":"ਮਿਥਿਆਹਉਮੈਮਮਤਾਮਾਇਆ ॥","translit":"Mithhiaa Houmai Mamathaa Maaeiaa ||","english":"False are ego, possessiveness and Maya."},{"punjabi":"ਮਿਥਿਆ ਰਾਜ ਜੋਬਨ ਧਨ ਮਾਲ ॥","lareedar":"ਮਿਥਿਆਰਾਜਜੋਬਨਧਨਮਾਲ ॥","translit":"Mithhiaa Raaj Joban Dhhan Maal ||","english":"False are power, youth, wealth and property."},{"punjabi":"ਮਿਥਿਆ ਕਾਮ ਕ੍ਰੋਧ ਬਿਕਰਾਲ ॥","lareedar":"ਮਿਥਿਆਕਾਮਕ੍ਰੋਧਬਿਕਰਾਲ ॥","translit":"Mithhiaa Kaam Krodhh Bikaraal ||","english":"False are sexual desire and wild anger."},{"punjabi":"ਮਿਥਿਆ ਰਥ ਹਸਤੀ ਅਸ੍ਵ ਬਸਤ੍ਰਾ ॥","lareedar":"ਮਿਥਿਆਰਥਹਸਤੀਅਸ੍ਵਬਸਤ੍ਰਾ ॥","translit":"Mithhiaa Rathh Hasathee Asv Basathraa ||","english":"False are chariots, elephants, horses and expensive clothes."},{"punjabi":"ਮਿਥਿਆ ਰੰਗ ਸੰਗਿ ਮਾਇਆ ਪੇਖਿ ਹਸਤਾ ॥","lareedar":"ਮਿਥਿਆਰੰਗਸੰਗਿਮਾਇਆਪੇਖਿਹਸਤਾ ॥","translit":"Mithhiaa Rang Sang Maaeiaa Paekh Hasathaa ||","english":"False is the love of gathering wealth, and reveling in the sight of it."},{"punjabi":"ਮਿਥਿਆ ਧ੍ਰੋਹ ਮੋਹ ਅਭਿਮਾਨੁ ॥","lareedar":"ਮਿਥਿਆਧ੍ਰੋਹਮੋਹਅਭਿਮਾਨੁ ॥","translit":"Mithhiaa Dhhroh Moh Abhimaan ||","english":"False are deception, emotional attachment and egotistical pride."},{"punjabi":"ਮਿਥਿਆ ਆਪਸ ਊਪਰਿ ਕਰਤ ਗੁਮਾਨੁ ॥","lareedar":"ਮਿਥਿਆਆਪਸਊਪਰਿਕਰਤਗੁਮਾਨੁ ॥","translit":"Mithhiaa Aapas Oopar Karath Gumaan ||","english":"False are pride and self-conceit."},{"punjabi":"ਅਸਥਿਰੁ ਭਗਤਿ ਸਾਧ ਕੀ ਸਰਨ ॥","lareedar":"ਅਸਥਿਰੁਭਗਤਿਸਾਧਕੀਸਰਨ ॥","translit":"Asathhir Bhagath Saadhh Kee Saran ||","english":"Only devotional worship is permanent, and the Sanctuary of the Holy."},{"punjabi":"ਨਾਨਕ ਜਪਿ ਜਪਿ ਜੀਵੈ ਹਰਿ ਕੇ ਚਰਨ ॥੪॥","lareedar":"ਨਾਨਕਜਪਿਜਪਿਜੀਵੈਹਰਿਕੇਚਰਨ ॥੪ ॥","translit":"Naanak Jap Jap Jeevai Har Kae Charan ||4||","english":"Nanak lives by meditating, meditating on the Lotus Feet of the Lord. ||4||"},{"punjabi":"ਮਿਥਿਆ ਸ੍ਰਵਨ ਪਰ ਨਿੰਦਾ ਸੁਨਹਿ ॥","lareedar":"ਮਿਥਿਆਸ੍ਰਵਨਪਰਨਿੰਦਾਸੁਨਹਿ ॥","translit":"Mithhiaa Sravan Par Nindhaa Sunehi ||","english":"False are the ears which listen to the slander of others."},{"punjabi":"ਮਿਥਿਆ ਹਸਤ ਪਰ ਦਰਬ ਕਉ ਹਿਰਹਿ ॥","lareedar":"ਮਿਥਿਆਹਸਤਪਰਦਰਬਕਉਹਿਰਹਿ ॥","translit":"Mithhiaa Hasath Par Dharab Ko Hirehi ||","english":"False are the hands which steal the wealth of others."},{"punjabi":"ਮਿਥਿਆ ਨੇਤ੍ਰ ਪੇਖਤ ਪਰ ਤ੍ਰਿਅ ਰੂਪਾਦ ॥","lareedar":"ਮਿਥਿਆਨੇਤ੍ਰਪੇਖਤਪਰਤ੍ਰਿਅਰੂਪਾਦ ॥","translit":"Mithhiaa Naethr Paekhath Par Thria Roopaadh ||","english":"False are the eyes which gaze upon the beauty of another's wife."},{"punjabi":"ਮਿਥਿਆ ਰਸਨਾ ਭੋਜਨ ਅਨ ਸ੍ਵਾਦ ॥","lareedar":"ਮਿਥਿਆਰਸਨਾਭੋਜਨਅਨਸ੍ਵਾਦ ॥","translit":"Mithhiaa Rasanaa Bhojan An Svaadh ||","english":"False is the tongue which enjoys delicacies and external tastes."},{"punjabi":"ਮਿਥਿਆ ਚਰਨ ਪਰ ਬਿਕਾਰ ਕਉ ਧਾਵਹਿ ॥","lareedar":"ਮਿਥਿਆਚਰਨਪਰਬਿਕਾਰਕਉਧਾਵਹਿ ॥","translit":"Mithhiaa Charan Par Bikaar Ko Dhhaavehi ||","english":"False are the feet which run to do evil to others."},{"punjabi":"ਮਿਥਿਆ ਮਨ ਪਰ ਲੋਭ ਲੁਭਾਵਹਿ ॥","lareedar":"ਮਿਥਿਆਮਨਪਰਲੋਭਲੁਭਾਵਹਿ ॥","translit":"Mithhiaa Man Par Lobh Lubhaavehi ||","english":"False is the mind which covets the wealth of others."},{"punjabi":"ਮਿਥਿਆ ਤਨ ਨਹੀ ਪਰਉਪਕਾਰਾ ॥","lareedar":"ਮਿਥਿਆਤਨਨਹੀਪਰਉਪਕਾਰਾ ॥","translit":"Mithhiaa Than Nehee Paroupakaaraa ||","english":"False is the body which does not do good to others."},{"punjabi":"ਮਿਥਿਆ ਬਾਸੁ ਲੇਤ ਬਿਕਾਰਾ ॥","lareedar":"ਮਿਥਿਆਬਾਸੁਲੇਤਬਿਕਾਰਾ ॥","translit":"Mithhiaa Baas Laeth Bikaaraa ||","english":"False is the nose which inhales corruption."},{"punjabi":"ਬਿਨੁ ਬੂਝੇ ਮਿਥਿਆ ਸਭ ਭਏ ॥","lareedar":"ਬਿਨੁਬੂਝੇਮਿਥਿਆਸਭਭਏ ॥","translit":"Bin Boojhae Mithhiaa Sabh Bheae ||","english":"Without understanding, everything is false."},{"punjabi":"ਸਫਲ ਦੇਹ ਨਾਨਕ ਹਰਿ ਹਰਿ ਨਾਮ ਲਏ ॥੫॥","lareedar":"ਸਫਲਦੇਹਨਾਨਕਹਰਿਹਰਿਨਾਮਲਏ ॥੫ ॥","translit":"Safal Dhaeh Naanak Har Har Naam Leae ||5||","english":"Fruitful is the body, O Nanak, which takes to the Lord's Name. ||5||"},{"punjabi":"ਬਿਰਥੀ ਸਾਕਤ ਕੀ ਆਰਜਾ ॥","lareedar":"ਬਿਰਥੀਸਾਕਤਕੀਆਰਜਾ ॥","translit":"Birathhee Saakath Kee Aarajaa ||","english":"The life of the faithless cynic is totally useless."},{"punjabi":"ਸਾਚ ਬਿਨਾ ਕਹ ਹੋਵਤ ਸੂਚਾ ॥","lareedar":"ਸਾਚਬਿਨਾਕਹਹੋਵਤਸੂਚਾ ॥","translit":"Saach Binaa Keh Hovath Soochaa ||","english":"Without the Truth, how can anyone be pure?"},{"punjabi":"ਬਿਰਥਾ ਨਾਮ ਬਿਨਾ ਤਨੁ ਅੰਧ ॥","lareedar":"ਬਿਰਥਾਨਾਮਬਿਨਾਤਨੁਅੰਧ ॥","translit":"Birathhaa Naam Binaa Than Andhh ||","english":"Useless is the body of the spiritually blind, without the Name of the Lord."},{"punjabi":"ਮੁਖਿ ਆਵਤ ਤਾ ਕੈ ਦੁਰਗੰਧ ॥","lareedar":"ਮੁਖਿਆਵਤਤਾਕੈਦੁਰਗੰਧ ॥","translit":"Mukh Aavath Thaa Kai Dhuragandhh ||","english":"From his mouth, a foul smell issues forth."}]},{"index":17,"ang":269,"lines":[{"punjabi":"ਬਿਨੁ ਸਿਮਰਨ ਦਿਨੁ ਰੈਨਿ ਬ੍ਰਿਥਾ ਬਿਹਾਇ ॥","lareedar":"ਬਿਨੁਸਿਮਰਨਦਿਨੁਰੈਨਿਬ੍ਰਿਥਾਬਿਹਾਇ ॥","translit":"Bin Simaran Dhin Rain Brithhaa Bihaae ||","english":"Without the remembrance of the Lord, day and night pass in vain,"},{"punjabi":"ਮੇਘ ਬਿਨਾ ਜਿਉ ਖੇਤੀ ਜਾਇ ॥","lareedar":"ਮੇਘਬਿਨਾਜਿਉਖੇਤੀਜਾਇ ॥","translit":"Maegh Binaa Jio Khaethee Jaae ||","english":"Like the crop which withers without rain."},{"punjabi":"ਗੋਬਿਦ ਭਜਨ ਬਿਨੁ ਬ੍ਰਿਥੇ ਸਭ ਕਾਮ ॥","lareedar":"ਗੋਬਿਦਭਜਨਬਿਨੁਬ੍ਰਿਥੇਸਭਕਾਮ ॥","translit":"Gobidh Bhajan Bin Brithhae Sabh Kaam ||","english":"Without meditation on the Lord of the Universe, all works are in vain,"},{"punjabi":"ਜਿਉ ਕਿਰਪਨ ਕੇ ਨਿਰਾਰਥ ਦਾਮ ॥","lareedar":"ਜਿਉਕਿਰਪਨਕੇਨਿਰਾਰਥਦਾਮ ॥","translit":"Jio Kirapan Kae Niraarathh Dhaam ||","english":"Like the wealth of a miser, which lies useless."},{"punjabi":"ਧੰਨਿ ਧੰਨਿ ਤੇ ਜਨ ਜਿਹ ਘਟਿ ਬਸਿਓ ਹਰਿ ਨਾਉ ॥","lareedar":"ਧੰਨਿਧੰਨਿਤੇਜਨਜਿਹਘਟਿਬਸਿਓਹਰਿਨਾਉ ॥","translit":"Dhhann Dhhann Thae Jan Jih Ghatt Basiou Har Naao ||","english":"Blessed, blessed are those, whose hearts are filled with the Name of the Lord."},{"punjabi":"ਨਾਨਕ ਤਾ ਕੈ ਬਲਿ ਬਲਿ ਜਾਉ ॥੬॥","lareedar":"ਨਾਨਕਤਾਕੈਬਲਿਬਲਿਜਾਉ ॥੬ ॥","translit":"Naanak Thaa Kai Bal Bal Jaao ||6||","english":"Nanak is a sacrifice, a sacrifice to them. ||6||"},{"punjabi":"ਰਹਤ ਅਵਰ ਕਛੁ ਅਵਰ ਕਮਾਵਤ ॥","lareedar":"ਰਹਤਅਵਰਕਛੁਅਵਰਕਮਾਵਤ ॥","translit":"Rehath Avar Kashh Avar Kamaavath ||","english":"He says one thing, and does something else."},{"punjabi":"ਮਨਿ ਨਹੀ ਪ੍ਰੀਤਿ ਮੁਖਹੁ ਗੰਢ ਲਾਵਤ ॥","lareedar":"ਮਨਿਨਹੀਪ੍ਰੀਤਿਮੁਖਹੁਗੰਢਲਾਵਤ ॥","translit":"Man Nehee Preeth Mukhahu Gandt Laavath ||","english":"There is no love in his heart, and yet with his mouth he talks tall."},{"punjabi":"ਜਾਨਨਹਾਰ ਪ੍ਰਭੂ ਪਰਬੀਨ ॥","lareedar":"ਜਾਨਨਹਾਰਪ੍ਰਭੂਪਰਬੀਨ ॥","translit":"Jaananehaar Prabhoo Parabeen ||","english":"The Omniscient Lord God is the Knower of all."},{"punjabi":"ਬਾਹਰਿ ਭੇਖ ਨ ਕਾਹੂ ਭੀਨ ॥","lareedar":"ਬਾਹਰਿਭੇਖਨਕਾਹੂਭੀਨ ॥","translit":"Baahar Bhaekh N Kaahoo Bheen ||","english":"He is not impressed by outward display."},{"punjabi":"ਅਵਰ ਉਪਦੇਸੈ ਆਪਿ ਨ ਕਰੈ ॥","lareedar":"ਅਵਰਉਪਦੇਸੈਆਪਿਨਕਰੈ ॥","translit":"Avar Oupadhaesai Aap N Karai ||","english":"One who does not practice what he preaches to others,"},{"punjabi":"ਆਵਤ ਜਾਵਤ ਜਨਮੈ ਮਰੈ ॥","lareedar":"ਆਵਤਜਾਵਤਜਨਮੈਮਰੈ ॥","translit":"Aavath Jaavath Janamai Marai ||","english":"Shall come and go in reincarnation, through birth and death."},{"punjabi":"ਜਿਸ ਕੈ ਅੰਤਰਿ ਬਸੈ ਨਿਰੰਕਾਰੁ ॥","lareedar":"ਜਿਸਕੈਅੰਤਰਿਬਸੈਨਿਰੰਕਾਰੁ ॥","translit":"Jis Kai Anthar Basai Nirankaar ||","english":"One whose inner being is filled with the Formless Lord"},{"punjabi":"ਤਿਸ ਕੀ ਸੀਖ ਤਰੈ ਸੰਸਾਰੁ ॥","lareedar":"ਤਿਸਕੀਸੀਖਤਰੈਸੰਸਾਰੁ ॥","translit":"This Kee Seekh Tharai Sansaar ||","english":"By his teachings, the world is saved."},{"punjabi":"ਜੋ ਤੁਮ ਭਾਨੇ ਤਿਨ ਪ੍ਰਭੁ ਜਾਤਾ ॥","lareedar":"ਜੋਤੁਮਭਾਨੇਤਿਨਪ੍ਰਭੁਜਾਤਾ ॥","translit":"Jo Thum Bhaanae Thin Prabh Jaathaa ||","english":"Those who are pleasing to You, God, know You."},{"punjabi":"ਨਾਨਕ ਉਨ ਜਨ ਚਰਨ ਪਰਾਤਾ ॥੭॥","lareedar":"ਨਾਨਕਉਨਜਨਚਰਨਪਰਾਤਾ ॥੭ ॥","translit":"Naanak Oun Jan Charan Paraathaa ||7||","english":"Nanak falls at their feet. ||7||"},{"punjabi":"ਕਰਉ ਬੇਨਤੀ ਪਾਰਬ੍ਰਹਮੁ ਸਭੁ ਜਾਨੈ ॥","lareedar":"ਕਰਉਬੇਨਤੀਪਾਰਬ੍ਰਹਮੁਸਭੁਜਾਨੈ ॥","translit":"Karo Baenathee Paarabreham Sabh Jaanai ||","english":"Offer your prayers to the Supreme Lord God, who knows everything."},{"punjabi":"ਅਪਨਾ ਕੀਆ ਆਪਹਿ ਮਾਨੈ ॥","lareedar":"ਅਪਨਾਕੀਆਆਪਹਿਮਾਨੈ ॥","translit":"Apanaa Keeaa Aapehi Maanai ||","english":"He Himself values His own creatures."},{"punjabi":"ਆਪਹਿ ਆਪ ਆਪਿ ਕਰਤ ਨਿਬੇਰਾ ॥","lareedar":"ਆਪਹਿਆਪਆਪਿਕਰਤਨਿਬੇਰਾ ॥","translit":"Aapehi Aap Aap Karath Nibaeraa ||","english":"He Himself, by Himself, makes the decisions."},{"punjabi":"ਕਿਸੈ ਦੂਰਿ ਜਨਾਵਤ ਕਿਸੈ ਬੁਝਾਵਤ ਨੇਰਾ ॥","lareedar":"ਕਿਸੈਦੂਰਿਜਨਾਵਤਕਿਸੈਬੁਝਾਵਤਨੇਰਾ ॥","translit":"Kisai Dhoor Janaavath Kisai Bujhaavath Naeraa ||","english":"To some, He appears far away, while others perceive Him near at hand."},{"punjabi":"ਉਪਾਵ ਸਿਆਨਪ ਸਗਲ ਤੇ ਰਹਤ ॥","lareedar":"ਉਪਾਵਸਿਆਨਪਸਗਲਤੇਰਹਤ ॥","translit":"Oupaav Siaanap Sagal Thae Rehath ||","english":"He is beyond all efforts and clever tricks."},{"punjabi":"ਸਭੁ ਕਛੁ ਜਾਨੈ ਆਤਮ ਕੀ ਰਹਤ ॥","lareedar":"ਸਭੁਕਛੁਜਾਨੈਆਤਮਕੀਰਹਤ ॥","translit":"Sabh Kashh Jaanai Aatham Kee Rehath ||","english":"He knows all the ways and means of the soul."},{"punjabi":"ਜਿਸੁ ਭਾਵੈ ਤਿਸੁ ਲਏ ਲੜਿ ਲਾਇ ॥","lareedar":"ਜਿਸੁਭਾਵੈਤਿਸੁਲਏਲੜਿਲਾਇ ॥","translit":"Jis Bhaavai This Leae Larr Laae ||","english":"Those with whom He is pleased are attached to the hem of His robe."},{"punjabi":"ਥਾਨ ਥਨੰਤਰਿ ਰਹਿਆ ਸਮਾਇ ॥","lareedar":"ਥਾਨਥਨੰਤਰਿਰਹਿਆਸਮਾਇ ॥","translit":"Thhaan Thhananthar Rehiaa Samaae ||","english":"He is pervading all places and interspaces."},{"punjabi":"ਸੋ ਸੇਵਕੁ ਜਿਸੁ ਕਿਰਪਾ ਕਰੀ ॥","lareedar":"ਸੋਸੇਵਕੁਜਿਸੁਕਿਰਪਾਕਰੀ ॥","translit":"So Saevak Jis Kirapaa Karee ||","english":"Those upon whom He bestows His favor, become His servants."}]},{"index":18,"ang":269,"lines":[{"punjabi":"ਨਿਮਖ ਨਿਮਖ ਜਪਿ ਨਾਨਕ ਹਰੀ ॥੮॥੫॥","lareedar":"ਨਿਮਖਨਿਮਖਜਪਿਨਾਨਕਹਰੀ ॥੮ ॥੫ ॥","translit":"Nimakh Nimakh Jap Naanak Haree ||8||5||","english":"Each and every moment, O Nanak, meditate on the Lord. ||8||5||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਕਾਮ ਕ੍ਰੋਧ ਅਰੁ ਲੋਭ ਮੋਹ ਬਿਨਸਿ ਜਾਇ ਅਹੰਮੇਵ ॥","lareedar":"ਕਾਮਕ੍ਰੋਧਅਰੁਲੋਭਮੋਹਬਿਨਸਿਜਾਇਅਹੰਮੇਵ ॥","translit":"Kaam Krodhh Ar Lobh Moh Binas Jaae Ahanmaev ||","english":"Sexual desire, anger, greed and emotional attachment - may these be gone, and egotism as well."},{"punjabi":"ਨਾਨਕ ਪ੍ਰਭ ਸਰਣਾਗਤੀ ਕਰਿ ਪ੍ਰਸਾਦੁ ਗੁਰਦੇਵ ॥੧॥","lareedar":"ਨਾਨਕਪ੍ਰਭਸਰਣਾਗਤੀਕਰਿਪ੍ਰਸਾਦੁਗੁਰਦੇਵ ॥੧ ॥","translit":"Naanak Prabh Saranaagathee Kar Prasaadh Guradhaev ||1||","english":"Nanak seeks the Sanctuary of God; please bless me with Your Grace, O Divine Guru. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਛਤੀਹ ਅੰਮ੍ਰਿਤ ਖਾਹਿ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਛਤੀਹਅੰਮ੍ਰਿਤਖਾਹਿ ॥","translit":"Jih Prasaadh Shhatheeh Anmrith Khaahi ||","english":"By His Grace, you partake of the thirty-six delicacies;"},{"punjabi":"ਤਿਸੁ ਠਾਕੁਰ ਕਉ ਰਖੁ ਮਨ ਮਾਹਿ ॥","lareedar":"ਤਿਸੁਠਾਕੁਰਕਉਰਖੁਮਨਮਾਹਿ ॥","translit":"This Thaakur Ko Rakh Man Maahi ||","english":"Enshrine that Lord and Master within your mind."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਸੁਗੰਧਤ ਤਨਿ ਲਾਵਹਿ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਸੁਗੰਧਤਤਨਿਲਾਵਹਿ ॥","translit":"Jih Prasaadh Sugandhhath Than Laavehi ||","english":"By His Grace, you apply scented oils to your body;"},{"punjabi":"ਤਿਸ ਕਉ ਸਿਮਰਤ ਪਰਮ ਗਤਿ ਪਾਵਹਿ ॥","lareedar":"ਤਿਸਕਉਸਿਮਰਤਪਰਮਗਤਿਪਾਵਹਿ ॥","translit":"This Ko Simarath Param Gath Paavehi ||","english":"Remembering Him, the supreme status is obtained."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਬਸਹਿ ਸੁਖ ਮੰਦਰਿ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਬਸਹਿਸੁਖਮੰਦਰਿ ॥","translit":"Jih Prasaadh Basehi Sukh Mandhar ||","english":"By His Grace, you dwell in the palace of peace;"},{"punjabi":"ਤਿਸਹਿ ਧਿਆਇ ਸਦਾ ਮਨ ਅੰਦਰਿ ॥","lareedar":"ਤਿਸਹਿਧਿਆਇਸਦਾਮਨਅੰਦਰਿ ॥","translit":"Thisehi Dhhiaae Sadhaa Man Andhar ||","english":"Meditate forever on Him within your mind."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਗ੍ਰਿਹ ਸੰਗਿ ਸੁਖ ਬਸਨਾ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਗ੍ਰਿਹਸੰਗਿਸੁਖਬਸਨਾ ॥","translit":"Jih Prasaadh Grih Sang Sukh Basanaa ||","english":"By His Grace, you abide with your family in peace;"},{"punjabi":"ਆਠ ਪਹਰ ਸਿਮਰਹੁ ਤਿਸੁ ਰਸਨਾ ॥","lareedar":"ਆਠਪਹਰਸਿਮਰਹੁਤਿਸੁਰਸਨਾ ॥","translit":"Aath Pehar Simarahu This Rasanaa ||","english":"Keep His remembrance upon your tongue, twenty-four hours a day."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਰੰਗ ਰਸ ਭੋਗ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਰੰਗਰਸਭੋਗ ॥","translit":"Jih Prasaadh Rang Ras Bhog ||","english":"By His Grace, you enjoy tastes and pleasures;"},{"punjabi":"ਨਾਨਕ ਸਦਾ ਧਿਆਈਐ ਧਿਆਵਨ ਜੋਗ ॥੧॥","lareedar":"ਨਾਨਕਸਦਾਧਿਆਈਐਧਿਆਵਨਜੋਗ ॥੧ ॥","translit":"Naanak Sadhaa Dhhiaaeeai Dhhiaavan Jog ||1||","english":"O Nanak, meditate forever on the One, who is worthy of meditation. ||1||"},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਪਾਟ ਪਟੰਬਰ ਹਢਾਵਹਿ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਪਾਟਪਟੰਬਰਹਢਾਵਹਿ ॥","translit":"Jih Prasaadh Paatt Pattanbar Hadtaavehi ||","english":"By His Grace, you wear silks and satins;"},{"punjabi":"ਤਿਸਹਿ ਤਿਆਗਿ ਕਤ ਅਵਰ ਲੁਭਾਵਹਿ ॥","lareedar":"ਤਿਸਹਿਤਿਆਗਿਕਤਅਵਰਲੁਭਾਵਹਿ ॥","translit":"Thisehi Thiaag Kath Avar Lubhaavehi ||","english":"Why abandon Him, to attach yourself to another?"},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਸੁਖਿ ਸੇਜ ਸੋਈਜੈ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਸੁਖਿਸੇਜਸੋਈਜੈ ॥","translit":"Jih Prasaadh Sukh Saej Soeejai ||","english":"By His Grace, you sleep in a cozy bed;"},{"punjabi":"ਮਨ ਆਠ ਪਹਰ ਤਾ ਕਾ ਜਸੁ ਗਾਵੀਜੈ ॥","lareedar":"ਮਨਆਠਪਹਰਤਾਕਾਜਸੁਗਾਵੀਜੈ ॥","translit":"Man Aath Pehar Thaa Kaa Jas Gaaveejai ||","english":"O my mind, sing His Praises, twenty-four hours a day."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਤੁਝੁ ਸਭੁ ਕੋਊ ਮਾਨੈ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਤੁਝੁਸਭੁਕੋਊਮਾਨੈ ॥","translit":"Jih Prasaadh Thujh Sabh Kooo Maanai ||","english":"By His Grace, you are honored by everyone;"},{"punjabi":"ਮੁਖਿ ਤਾ ਕੋ ਜਸੁ ਰਸਨ ਬਖਾਨੈ ॥","lareedar":"ਮੁਖਿਤਾਕੋਜਸੁਰਸਨਬਖਾਨੈ ॥","translit":"Mukh Thaa Ko Jas Rasan Bakhaanai ||","english":"With your mouth and with your tongue, chant His Praises."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਤੇਰੋ ਰਹਤਾ ਧਰਮੁ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਤੇਰੋਰਹਤਾਧਰਮੁ ॥","translit":"Jih Prasaadh Thaero Rehathaa Dhharam ||","english":"By His Grace, you remain in the Dharma;"},{"punjabi":"ਮਨ ਸਦਾ ਧਿਆਇ ਕੇਵਲ ਪਾਰਬ੍ਰਹਮੁ ॥","lareedar":"ਮਨਸਦਾਧਿਆਇਕੇਵਲਪਾਰਬ੍ਰਹਮੁ ॥","translit":"Man Sadhaa Dhhiaae Kaeval Paarabreham ||","english":"O mind, meditate continually on the Supreme Lord God."},{"punjabi":"ਪ੍ਰਭ ਜੀ ਜਪਤ ਦਰਗਹ ਮਾਨੁ ਪਾਵਹਿ ॥","lareedar":"ਪ੍ਰਭਜੀਜਪਤਦਰਗਹਮਾਨੁਪਾਵਹਿ ॥","translit":"Prabh Jee Japath Dharageh Maan Paavehi ||","english":"Meditating on God, you shall be honored in His Court;"},{"punjabi":"ਨਾਨਕ ਪਤਿ ਸੇਤੀ ਘਰਿ ਜਾਵਹਿ ॥੨॥","lareedar":"ਨਾਨਕਪਤਿਸੇਤੀਘਰਿਜਾਵਹਿ ॥੨ ॥","translit":"Naanak Path Saethee Ghar Jaavehi ||2||","english":"O Nanak, you shall return to your true home with honor. ||2||"}]},{"index":19,"ang":270,"lines":[{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਆਰੋਗ ਕੰਚਨ ਦੇਹੀ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਆਰੋਗਕੰਚਨਦੇਹੀ ॥","translit":"Jih Prasaadh Aarog Kanchan Dhaehee ||","english":"By His Grace, you have a healthy, golden body;"},{"punjabi":"ਲਿਵ ਲਾਵਹੁ ਤਿਸੁ ਰਾਮ ਸਨੇਹੀ ॥","lareedar":"ਲਿਵਲਾਵਹੁਤਿਸੁਰਾਮਸਨੇਹੀ ॥","translit":"Liv Laavahu This Raam Sanaehee ||","english":"Attune yourself to that Loving Lord."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਤੇਰਾ ਓਲਾ ਰਹਤ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਤੇਰਾਓਲਾਰਹਤ ॥","translit":"Jih Prasaadh Thaeraa Oulaa Rehath ||","english":"By His Grace, your honor is preserved;"},{"punjabi":"ਮਨ ਸੁਖੁ ਪਾਵਹਿ ਹਰਿ ਹਰਿ ਜਸੁ ਕਹਤ ॥","lareedar":"ਮਨਸੁਖੁਪਾਵਹਿਹਰਿਹਰਿਜਸੁਕਹਤ ॥","translit":"Man Sukh Paavehi Har Har Jas Kehath ||","english":"O mind, chant the Praises of the Lord, Har, Har, and find peace."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਤੇਰੇ ਸਗਲ ਛਿਦ੍ਰ ਢਾਕੇ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਤੇਰੇਸਗਲਛਿਦ੍ਰਢਾਕੇ ॥","translit":"Jih Prasaadh Thaerae Sagal Shhidhr Dtaakae ||","english":"By His Grace, all your deficits are covered;"},{"punjabi":"ਮਨ ਸਰਨੀ ਪਰੁ ਠਾਕੁਰ ਪ੍ਰਭ ਤਾ ਕੈ ॥","lareedar":"ਮਨਸਰਨੀਪਰੁਠਾਕੁਰਪ੍ਰਭਤਾਕੈ ॥","translit":"Man Saranee Par Thaakur Prabh Thaa Kai ||","english":"O mind, seek the Sanctuary of God, our Lord and Master."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਤੁਝੁ ਕੋ ਨ ਪਹੂਚੈ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਤੁਝੁਕੋਨਪਹੂਚੈ ॥","translit":"Jih Prasaadh Thujh Ko N Pehoochai ||","english":"By His Grace, no one can rival you;"},{"punjabi":"ਮਨ ਸਾਸਿ ਸਾਸਿ ਸਿਮਰਹੁ ਪ੍ਰਭ ਊਚੇ ॥","lareedar":"ਮਨਸਾਸਿਸਾਸਿਸਿਮਰਹੁਪ੍ਰਭਊਚੇ ॥","translit":"Man Saas Saas Simarahu Prabh Oochae ||","english":"O mind, with each and every breath, remember God on High."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਪਾਈ ਦ੍ਰੁਲਭ ਦੇਹ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਪਾਈਦ੍ਰੁਲਭਦੇਹ ॥","translit":"Jih Prasaadh Paaee Dhraalabh Dhaeh ||","english":"By His Grace, you obtained this precious human body;"},{"punjabi":"ਨਾਨਕ ਤਾ ਕੀ ਭਗਤਿ ਕਰੇਹ ॥੩॥","lareedar":"ਨਾਨਕਤਾਕੀਭਗਤਿਕਰੇਹ ॥੩ ॥","translit":"Naanak Thaa Kee Bhagath Karaeh ||3||","english":"O Nanak, worship Him with devotion. ||3||"},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਆਭੂਖਨ ਪਹਿਰੀਜੈ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਆਭੂਖਨਪਹਿਰੀਜੈ ॥","translit":"Jih Prasaadh Aabhookhan Pehireejai ||","english":"By His Grace, you wear decorations;"},{"punjabi":"ਮਨ ਤਿਸੁ ਸਿਮਰਤ ਕਿਉ ਆਲਸੁ ਕੀਜੈ ॥","lareedar":"ਮਨਤਿਸੁਸਿਮਰਤਕਿਉਆਲਸੁਕੀਜੈ ॥","translit":"Man This Simarath Kio Aalas Keejai ||","english":"O mind, why are you so lazy? Why don't you remember Him in meditation?"},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਅਸ੍ਵ ਹਸਤਿ ਅਸਵਾਰੀ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਅਸ੍ਵਹਸਤਿਅਸਵਾਰੀ ॥","translit":"Jih Prasaadh Asv Hasath Asavaaree ||","english":"By His Grace, you have horses and elephants to ride;"},{"punjabi":"ਮਨ ਤਿਸੁ ਪ੍ਰਭ ਕਉ ਕਬਹੂ ਨ ਬਿਸਾਰੀ ॥","lareedar":"ਮਨਤਿਸੁਪ੍ਰਭਕਉਕਬਹੂਨਬਿਸਾਰੀ ॥","translit":"Man This Prabh Ko Kabehoo N Bisaaree ||","english":"O mind, never forget that God."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਬਾਗ ਮਿਲਖ ਧਨਾ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਬਾਗਮਿਲਖਧਨਾ ॥","translit":"Jih Prasaadh Baag Milakh Dhhanaa ||","english":"By His Grace, you have land, gardens and wealth;"},{"punjabi":"ਰਾਖੁ ਪਰੋਇ ਪ੍ਰਭੁ ਅਪੁਨੇ ਮਨਾ ॥","lareedar":"ਰਾਖੁਪਰੋਇਪ੍ਰਭੁਅਪੁਨੇਮਨਾ ॥","translit":"Raakh Paroe Prabh Apunae Manaa ||","english":"Keep God enshrined in your heart."},{"punjabi":"ਜਿਨਿ ਤੇਰੀ ਮਨ ਬਨਤ ਬਨਾਈ ॥","lareedar":"ਜਿਨਿਤੇਰੀਮਨਬਨਤਬਨਾਈ ॥","translit":"Jin Thaeree Man Banath Banaaee ||","english":"O mind, the One who formed your form"},{"punjabi":"ਊਠਤ ਬੈਠਤ ਸਦ ਤਿਸਹਿ ਧਿਆਈ ॥","lareedar":"ਊਠਤਬੈਠਤਸਦਤਿਸਹਿਧਿਆਈ ॥","translit":"Oothath Baithath Sadh Thisehi Dhhiaaee ||","english":"Standing up and sitting down, meditate always on Him."},{"punjabi":"ਤਿਸਹਿ ਧਿਆਇ ਜੋ ਏਕ ਅਲਖੈ ॥","lareedar":"ਤਿਸਹਿਧਿਆਇਜੋਏਕਅਲਖੈ ॥","translit":"Thisehi Dhhiaae Jo Eaek Alakhai ||","english":"Meditate on Him - the One Invisible Lord;"},{"punjabi":"ਈਹਾ ਊਹਾ ਨਾਨਕ ਤੇਰੀ ਰਖੈ ॥੪॥","lareedar":"ਈਹਾਊਹਾਨਾਨਕਤੇਰੀਰਖੈ ॥੪ ॥","translit":"Eehaa Oohaa Naanak Thaeree Rakhai ||4||","english":"Here and hereafter, O Nanak, He shall save you. ||4||"},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਕਰਹਿ ਪੁੰਨ ਬਹੁ ਦਾਨ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਕਰਹਿਪੁੰਨਬਹੁਦਾਨ ॥","translit":"Jih Prasaadh Karehi Punn Bahu Dhaan ||","english":"By His Grace, you give donations in abundance to charities;"},{"punjabi":"ਮਨ ਆਠ ਪਹਰ ਕਰਿ ਤਿਸ ਕਾ ਧਿਆਨ ॥","lareedar":"ਮਨਆਠਪਹਰਕਰਿਤਿਸਕਾਧਿਆਨ ॥","translit":"Man Aath Pehar Kar This Kaa Dhhiaan ||","english":"O mind, meditate on Him, twenty-four hours a day."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਤੂ ਆਚਾਰ ਬਿਉਹਾਰੀ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਤੂਆਚਾਰਬਿਉਹਾਰੀ ॥","translit":"Jih Prasaadh Thoo Aachaar Biouhaaree ||","english":"By His Grace, you perform religious rituals and worldly duties;"},{"punjabi":"ਤਿਸੁ ਪ੍ਰਭ ਕਉ ਸਾਸਿ ਸਾਸਿ ਚਿਤਾਰੀ ॥","lareedar":"ਤਿਸੁਪ੍ਰਭਕਉਸਾਸਿਸਾਸਿਚਿਤਾਰੀ ॥","translit":"This Prabh Ko Saas Saas Chithaaree ||","english":"Think of God with each and every breath."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਤੇਰਾ ਸੁੰਦਰ ਰੂਪੁ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਤੇਰਾਸੁੰਦਰਰੂਪੁ ॥","translit":"Jih Prasaadh Thaeraa Sundhar Roop ||","english":"By His Grace, your form is so beautiful;"}]},{"index":20,"ang":270,"lines":[{"punjabi":"ਸੋ ਪ੍ਰਭੁ ਸਿਮਰਹੁ ਸਦਾ ਅਨੂਪੁ ॥","lareedar":"ਸੋਪ੍ਰਭੁਸਿਮਰਹੁਸਦਾਅਨੂਪੁ ॥","translit":"So Prabh Simarahu Sadhaa Anoop ||","english":"Constantly remember God, the Incomparably Beautiful One."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਤੇਰੀ ਨੀਕੀ ਜਾਤਿ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਤੇਰੀਨੀਕੀਜਾਤਿ ॥","translit":"Jih Prasaadh Thaeree Neekee Jaath ||","english":"By His Grace, you have such high social status;"},{"punjabi":"ਸੋ ਪ੍ਰਭੁ ਸਿਮਰਿ ਸਦਾ ਦਿਨ ਰਾਤਿ ॥","lareedar":"ਸੋਪ੍ਰਭੁਸਿਮਰਿਸਦਾਦਿਨਰਾਤਿ ॥","translit":"So Prabh Simar Sadhaa Dhin Raath ||","english":"Remember God always, day and night."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਤੇਰੀ ਪਤਿ ਰਹੈ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਤੇਰੀਪਤਿਰਹੈ ॥","translit":"Jih Prasaadh Thaeree Path Rehai ||","english":"By His Grace, your honor is preserved;"},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਨਾਨਕ ਜਸੁ ਕਹੈ ॥੫॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਨਾਨਕਜਸੁਕਹੈ ॥੫ ॥","translit":"Gur Prasaadh Naanak Jas Kehai ||5||","english":"By Guru's Grace, O Nanak, chant His Praises. ||5||"},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਸੁਨਹਿ ਕਰਨ ਨਾਦ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਸੁਨਹਿਕਰਨਨਾਦ ॥","translit":"Jih Prasaadh Sunehi Karan Naadh ||","english":"By His Grace, you listen to the sound current of the Naad."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਪੇਖਹਿ ਬਿਸਮਾਦ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਪੇਖਹਿਬਿਸਮਾਦ ॥","translit":"Jih Prasaadh Paekhehi Bisamaadh ||","english":"By His Grace, you behold amazing wonders."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਬੋਲਹਿ ਅੰਮ੍ਰਿਤ ਰਸਨਾ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਬੋਲਹਿਅੰਮ੍ਰਿਤਰਸਨਾ ॥","translit":"Jih Prasaadh Bolehi Anmrith Rasanaa ||","english":"By His Grace, you speak ambrosial words with your tongue."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਸੁਖਿ ਸਹਜੇ ਬਸਨਾ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਸੁਖਿਸਹਜੇਬਸਨਾ ॥","translit":"Jih Prasaadh Sukh Sehajae Basanaa ||","english":"By His Grace, you abide in peace and ease."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਹਸਤ ਕਰ ਚਲਹਿ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਹਸਤਕਰਚਲਹਿ ॥","translit":"Jih Prasaadh Hasath Kar Chalehi ||","english":"By His Grace, your hands move and work."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਸੰਪੂਰਨ ਫਲਹਿ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਸੰਪੂਰਨਫਲਹਿ ॥","translit":"Jih Prasaadh Sanpooran Falehi ||","english":"By His Grace, you are completely fulfilled."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਪਰਮ ਗਤਿ ਪਾਵਹਿ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਪਰਮਗਤਿਪਾਵਹਿ ॥","translit":"Jih Prasaadh Param Gath Paavehi ||","english":"By His Grace, you obtain the supreme status."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਸੁਖਿ ਸਹਜਿ ਸਮਾਵਹਿ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਸੁਖਿਸਹਜਿਸਮਾਵਹਿ ॥","translit":"Jih Prasaadh Sukh Sehaj Samaavehi ||","english":"By His Grace, you are absorbed into celestial peace."},{"punjabi":"ਐਸਾ ਪ੍ਰਭੁ ਤਿਆਗਿ ਅਵਰ ਕਤ ਲਾਗਹੁ ॥","lareedar":"ਐਸਾਪ੍ਰਭੁਤਿਆਗਿਅਵਰਕਤਲਾਗਹੁ ॥","translit":"Aisaa Prabh Thiaag Avar Kath Laagahu ||","english":"Why forsake God, and attach yourself to another?"},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਨਾਨਕ ਮਨਿ ਜਾਗਹੁ ॥੬॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਨਾਨਕਮਨਿਜਾਗਹੁ ॥੬ ॥","translit":"Gur Prasaadh Naanak Man Jaagahu ||6||","english":"By Guru's Grace, O Nanak, awaken your mind! ||6||"},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਤੂੰ ਪ੍ਰਗਟੁ ਸੰਸਾਰਿ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਤੂੰਪ੍ਰਗਟੁਸੰਸਾਰਿ ॥","translit":"Jih Prasaadh Thoon Pragatt Sansaar ||","english":"By His Grace, you are famous all over the world;"},{"punjabi":"ਤਿਸੁ ਪ੍ਰਭ ਕਉ ਮੂਲਿ ਨ ਮਨਹੁ ਬਿਸਾਰਿ ॥","lareedar":"ਤਿਸੁਪ੍ਰਭਕਉਮੂਲਿਨਮਨਹੁਬਿਸਾਰਿ ॥","translit":"This Prabh Ko Mool N Manahu Bisaar ||","english":"Never forget God from your mind."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਤੇਰਾ ਪਰਤਾਪੁ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਤੇਰਾਪਰਤਾਪੁ ॥","translit":"Jih Prasaadh Thaeraa Parathaap ||","english":"By His Grace, you have prestige;"},{"punjabi":"ਰੇ ਮਨ ਮੂੜ ਤੂ ਤਾ ਕਉ ਜਾਪੁ ॥","lareedar":"ਰੇਮਨਮੂੜਤੂਤਾਕਉਜਾਪੁ ॥","translit":"Rae Man Moorr Thoo Thaa Ko Jaap ||","english":"O foolish mind, meditate on Him!"},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਤੇਰੇ ਕਾਰਜ ਪੂਰੇ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਤੇਰੇਕਾਰਜਪੂਰੇ ॥","translit":"Jih Prasaadh Thaerae Kaaraj Poorae ||","english":"By His Grace, your works are completed;"},{"punjabi":"ਤਿਸਹਿ ਜਾਨੁ ਮਨ ਸਦਾ ਹਜੂਰੇ ॥","lareedar":"ਤਿਸਹਿਜਾਨੁਮਨਸਦਾਹਜੂਰੇ ॥","translit":"Thisehi Jaan Man Sadhaa Hajoorae ||","english":"O mind, know Him to be close at hand."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਤੂੰ ਪਾਵਹਿ ਸਾਚੁ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਤੂੰਪਾਵਹਿਸਾਚੁ ॥","translit":"Jih Prasaadh Thoon Paavehi Saach ||","english":"By His Grace, you find the Truth;"},{"punjabi":"ਰੇ ਮਨ ਮੇਰੇ ਤੂੰ ਤਾ ਸਿਉ ਰਾਚੁ ॥","lareedar":"ਰੇਮਨਮੇਰੇਤੂੰਤਾਸਿਉਰਾਚੁ ॥","translit":"Rae Man Maerae Thoon Thaa Sio Raach ||","english":"O my mind, merge yourself into Him."},{"punjabi":"ਜਿਹ ਪ੍ਰਸਾਦਿ ਸਭ ਕੀ ਗਤਿ ਹੋਇ ॥","lareedar":"ਜਿਹਪ੍ਰਸਾਦਿਸਭਕੀਗਤਿਹੋਇ ॥","translit":"Jih Prasaadh Sabh Kee Gath Hoe ||","english":"By His Grace, everyone is saved;"},{"punjabi":"ਨਾਨਕ ਜਾਪੁ ਜਪੈ ਜਪੁ ਸੋਇ ॥੭॥","lareedar":"ਨਾਨਕਜਾਪੁਜਪੈਜਪੁਸੋਇ ॥੭ ॥","translit":"Naanak Jaap Japai Jap Soe ||7||","english":"O Nanak, meditate, and chant His Chant. ||7||"}]},{"index":21,"ang":270,"lines":[{"punjabi":"ਆਪਿ ਜਪਾਏ ਜਪੈ ਸੋ ਨਾਉ ॥","lareedar":"ਆਪਿਜਪਾਏਜਪੈਸੋਨਾਉ ॥","translit":"Aap Japaaeae Japai So Naao ||","english":"Those, whom He inspires to chant, chant His Name."},{"punjabi":"ਆਪਿ ਗਾਵਾਏ ਸੁ ਹਰਿ ਗੁਨ ਗਾਉ ॥","lareedar":"ਆਪਿਗਾਵਾਏਸੁਹਰਿਗੁਨਗਾਉ ॥","translit":"Aap Gaavaaeae S Har Gun Gaao ||","english":"Those, whom He inspires to sing, sing the Glorious Praises of the Lord."},{"punjabi":"ਪ੍ਰਭ ਕਿਰਪਾ ਤੇ ਹੋਇ ਪ੍ਰਗਾਸੁ ॥","lareedar":"ਪ੍ਰਭਕਿਰਪਾਤੇਹੋਇਪ੍ਰਗਾਸੁ ॥","translit":"Prabh Kirapaa Thae Hoe Pragaas ||","english":"By God's Grace, enlightenment comes."},{"punjabi":"ਪ੍ਰਭੂ ਦਇਆ ਤੇ ਕਮਲ ਬਿਗਾਸੁ ॥","lareedar":"ਪ੍ਰਭੂਦਇਆਤੇਕਮਲਬਿਗਾਸੁ ॥","translit":"Prabhoo Dhaeiaa Thae Kamal Bigaas ||","english":"By God's Kind Mercy, the heart-lotus blossoms forth."},{"punjabi":"ਪ੍ਰਭ ਸੁਪ੍ਰਸੰਨ ਬਸੈ ਮਨਿ ਸੋਇ ॥","lareedar":"ਪ੍ਰਭਸੁਪ੍ਰਸੰਨਬਸੈਮਨਿਸੋਇ ॥","translit":"Prabh Suprasann Basai Man Soe ||","english":"When God is totally pleased, He comes to dwell in the mind."},{"punjabi":"ਪ੍ਰਭ ਦਇਆ ਤੇ ਮਤਿ ਊਤਮ ਹੋਇ ॥","lareedar":"ਪ੍ਰਭਦਇਆਤੇਮਤਿਊਤਮਹੋਇ ॥","translit":"Prabh Dhaeiaa Thae Math Ootham Hoe ||","english":"By God's Kind Mercy, the intellect is exalted."},{"punjabi":"ਸਰਬ ਨਿਧਾਨ ਪ੍ਰਭ ਤੇਰੀ ਮਇਆ ॥","lareedar":"ਸਰਬਨਿਧਾਨਪ੍ਰਭਤੇਰੀਮਇਆ ॥","translit":"Sarab Nidhhaan Prabh Thaeree Maeiaa ||","english":"All treasures, O Lord, come by Your Kind Mercy."},{"punjabi":"ਆਪਹੁ ਕਛੂ ਨ ਕਿਨਹੂ ਲਇਆ ॥","lareedar":"ਆਪਹੁਕਛੂਨਕਿਨਹੂਲਇਆ ॥","translit":"Aapahu Kashhoo N Kinehoo Laeiaa ||","english":"No one obtains anything by himself."},{"punjabi":"ਜਿਤੁ ਜਿਤੁ ਲਾਵਹੁ ਤਿਤੁ ਲਗਹਿ ਹਰਿ ਨਾਥ ॥","lareedar":"ਜਿਤੁਜਿਤੁਲਾਵਹੁਤਿਤੁਲਗਹਿਹਰਿਨਾਥ ॥","translit":"Jith Jith Laavahu Thith Lagehi Har Naathh ||","english":"As You have delegated, so do we apply ourselves, O Lord and Master."},{"punjabi":"ਨਾਨਕ ਇਨ ਕੈ ਕਛੂ ਨ ਹਾਥ ॥੮॥੬॥","lareedar":"ਨਾਨਕਇਨਕੈਕਛੂਨਹਾਥ ॥੮ ॥੬ ॥","translit":"Naanak Ein Kai Kashhoo N Haathh ||8||6||","english":"O Nanak, nothing is in our hands. ||8||6||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਅਗਮ ਅਗਾਧਿ ਪਾਰਬ੍ਰਹਮੁ ਸੋਇ ॥","lareedar":"ਅਗਮਅਗਾਧਿਪਾਰਬ੍ਰਹਮੁਸੋਇ ॥","translit":"Agam Agaadhh Paarabreham Soe ||","english":"Unapproachable and Unfathomable is the Supreme Lord God;"},{"punjabi":"ਜੋ ਜੋ ਕਹੈ ਸੁ ਮੁਕਤਾ ਹੋਇ ॥","lareedar":"ਜੋਜੋਕਹੈਸੁਮੁਕਤਾਹੋਇ ॥","translit":"Jo Jo Kehai S Mukathaa Hoe ||","english":"Whoever speaks of Him shall be liberated."},{"punjabi":"ਸੁਨਿ ਮੀਤਾ ਨਾਨਕੁ ਬਿਨਵੰਤਾ ॥","lareedar":"ਸੁਨਿਮੀਤਾਨਾਨਕੁਬਿਨਵੰਤਾ ॥","translit":"Sun Meethaa Naanak Binavanthaa ||","english":"Listen, O friends, Nanak prays,"},{"punjabi":"ਸਾਧ ਜਨਾ ਕੀ ਅਚਰਜ ਕਥਾ ॥੧॥","lareedar":"ਸਾਧਜਨਾਕੀਅਚਰਜਕਥਾ ॥੧ ॥","translit":"Saadhh Janaa Kee Acharaj Kathhaa ||1||","english":"To the wonderful story of the Holy. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਮੁਖ ਊਜਲ ਹੋਤ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਮੁਖਊਜਲਹੋਤ ॥","translit":"Saadhh Kai Sang Mukh Oojal Hoth ||","english":"In the Company of the Holy, one's face becomes radiant."},{"punjabi":"ਸਾਧਸੰਗਿ ਮਲੁ ਸਗਲੀ ਖੋਤ ॥","lareedar":"ਸਾਧਸੰਗਿਮਲੁਸਗਲੀਖੋਤ ॥","translit":"Saadhhasang Mal Sagalee Khoth ||","english":"In the Company of the Holy, all filth is removed."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਮਿਟੈ ਅਭਿਮਾਨੁ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਮਿਟੈਅਭਿਮਾਨੁ ॥","translit":"Saadhh Kai Sang Mittai Abhimaan ||","english":"In the Company of the Holy, egotism is eliminated."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਪ੍ਰਗਟੈ ਸੁਗਿਆਨੁ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਪ੍ਰਗਟੈਸੁਗਿਆਨੁ ॥","translit":"Saadhh Kai Sang Pragattai Sugiaan ||","english":"In the Company of the Holy, spiritual wisdom is revealed."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਬੁਝੈ ਪ੍ਰਭੁ ਨੇਰਾ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਬੁਝੈਪ੍ਰਭੁਨੇਰਾ ॥","translit":"Saadhh Kai Sang Bujhai Prabh Naeraa ||","english":"In the Company of the Holy, God is understood to be near at hand."},{"punjabi":"ਸਾਧਸੰਗਿ ਸਭੁ ਹੋਤ ਨਿਬੇਰਾ ॥","lareedar":"ਸਾਧਸੰਗਿਸਭੁਹੋਤਨਿਬੇਰਾ ॥","translit":"Saadhhasang Sabh Hoth Nibaeraa ||","english":"In the Company of the Holy, all conflicts are settled."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਪਾਏ ਨਾਮ ਰਤਨੁ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਪਾਏਨਾਮਰਤਨੁ ॥","translit":"Saadhh Kai Sang Paaeae Naam Rathan ||","english":"In the Company of the Holy, one obtains the jewel of the Naam."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਏਕ ਊਪਰਿ ਜਤਨੁ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਏਕਊਪਰਿਜਤਨੁ ॥","translit":"Saadhh Kai Sang Eaek Oopar Jathan ||","english":"In the Company of the Holy, one's efforts are directed toward the One Lord."},{"punjabi":"ਸਾਧ ਕੀ ਮਹਿਮਾ ਬਰਨੈ ਕਉਨੁ ਪ੍ਰਾਨੀ ॥","lareedar":"ਸਾਧਕੀਮਹਿਮਾਬਰਨੈਕਉਨੁਪ੍ਰਾਨੀ ॥","translit":"Saadhh Kee Mehimaa Baranai Koun Praanee ||","english":"What mortal can speak of the Glorious Praises of the Holy?"}]},{"index":22,"ang":271,"lines":[{"punjabi":"ਨਾਨਕ ਸਾਧ ਕੀ ਸੋਭਾ ਪ੍ਰਭ ਮਾਹਿ ਸਮਾਨੀ ॥੧॥","lareedar":"ਨਾਨਕਸਾਧਕੀਸੋਭਾਪ੍ਰਭਮਾਹਿਸਮਾਨੀ ॥੧ ॥","translit":"Naanak Saadhh Kee Sobhaa Prabh Maahi Samaanee ||1||","english":"O Nanak, the glory of the Holy people merges into God. ||1||"},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਅਗੋਚਰੁ ਮਿਲੈ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਅਗੋਚਰੁਮਿਲੈ ॥","translit":"Saadhh Kai Sang Agochar Milai ||","english":"In the Company of the Holy, one meets the Incomprehensible Lord."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਸਦਾ ਪਰਫੁਲੈ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਸਦਾਪਰਫੁਲੈ ॥","translit":"Saadhh Kai Sang Sadhaa Parafulai ||","english":"In the Company of the Holy, one flourishes forever."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਆਵਹਿ ਬਸਿ ਪੰਚਾ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਆਵਹਿਬਸਿਪੰਚਾ ॥","translit":"Saadhh Kai Sang Aavehi Bas Panchaa ||","english":"In the Company of the Holy, the five passions are brought to rest."},{"punjabi":"ਸਾਧਸੰਗਿ ਅੰਮ੍ਰਿਤ ਰਸੁ ਭੁੰਚਾ ॥","lareedar":"ਸਾਧਸੰਗਿਅੰਮ੍ਰਿਤਰਸੁਭੁੰਚਾ ॥","translit":"Saadhhasang Anmrith Ras Bhunchaa ||","english":"In the Company of the Holy, one enjoys the essence of ambrosia."},{"punjabi":"ਸਾਧਸੰਗਿ ਹੋਇ ਸਭ ਕੀ ਰੇਨ ॥","lareedar":"ਸਾਧਸੰਗਿਹੋਇਸਭਕੀਰੇਨ ॥","translit":"Saadhhasang Hoe Sabh Kee Raen ||","english":"In the Company of the Holy, one becomes the dust of all."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਮਨੋਹਰ ਬੈਨ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਮਨੋਹਰਬੈਨ ॥","translit":"Saadhh Kai Sang Manohar Bain ||","english":"In the Company of the Holy, one's speech is enticing."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਨ ਕਤਹੂੰ ਧਾਵੈ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਨਕਤਹੂੰਧਾਵੈ ॥","translit":"Saadhh Kai Sang N Kathehoon Dhhaavai ||","english":"In the Company of the Holy, the mind does not wander."},{"punjabi":"ਸਾਧਸੰਗਿ ਅਸਥਿਤਿ ਮਨੁ ਪਾਵੈ ॥","lareedar":"ਸਾਧਸੰਗਿਅਸਥਿਤਿਮਨੁਪਾਵੈ ॥","translit":"Saadhhasang Asathhith Man Paavai ||","english":"In the Company of the Holy, the mind becomes stable."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਮਾਇਆ ਤੇ ਭਿੰਨ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਮਾਇਆਤੇਭਿੰਨ ॥","translit":"Saadhh Kai Sang Maaeiaa Thae Bhinn ||","english":"In the Company of the Holy, one is rid of Maya."},{"punjabi":"ਸਾਧਸੰਗਿ ਨਾਨਕ ਪ੍ਰਭ ਸੁਪ੍ਰਸੰਨ ॥੨॥","lareedar":"ਸਾਧਸੰਗਿਨਾਨਕਪ੍ਰਭਸੁਪ੍ਰਸੰਨ ॥੨ ॥","translit":"Saadhhasang Naanak Prabh Suprasann ||2||","english":"In the Company of the Holy, O Nanak, God is totally pleased. ||2||"},{"punjabi":"ਸਾਧਸੰਗਿ ਦੁਸਮਨ ਸਭਿ ਮੀਤ ॥","lareedar":"ਸਾਧਸੰਗਿਦੁਸਮਨਸਭਿਮੀਤ ॥","translit":"Saadhhasang Dhusaman Sabh Meeth ||","english":"In the Company of the Holy, all one's enemies become friends."},{"punjabi":"ਸਾਧੂ ਕੈ ਸੰਗਿ ਮਹਾ ਪੁਨੀਤ ॥","lareedar":"ਸਾਧੂਕੈਸੰਗਿਮਹਾਪੁਨੀਤ ॥","translit":"Saadhhoo Kai Sang Mehaa Puneeth ||","english":"In the Company of the Holy, there is great purity."},{"punjabi":"ਸਾਧਸੰਗਿ ਕਿਸ ਸਿਉ ਨਹੀ ਬੈਰੁ ॥","lareedar":"ਸਾਧਸੰਗਿਕਿਸਸਿਉਨਹੀਬੈਰੁ ॥","translit":"Saadhhasang Kis Sio Nehee Bair ||","english":"In the Company of the Holy, no one is hated."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਨ ਬੀਗਾ ਪੈਰੁ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਨਬੀਗਾਪੈਰੁ ॥","translit":"Saadhh Kai Sang N Beegaa Pair ||","english":"In the Company of the Holy, one's feet do not wander."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਨਾਹੀ ਕੋ ਮੰਦਾ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਨਾਹੀਕੋਮੰਦਾ ॥","translit":"Saadhh Kai Sang Naahee Ko Mandhaa ||","english":"In the Company of the Holy, no one seems evil."},{"punjabi":"ਸਾਧਸੰਗਿ ਜਾਨੇ ਪਰਮਾਨੰਦਾ ॥","lareedar":"ਸਾਧਸੰਗਿਜਾਨੇਪਰਮਾਨੰਦਾ ॥","translit":"Saadhhasang Jaanae Paramaanandhaa ||","english":"In the Company of the Holy, supreme bliss is known."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਨਾਹੀ ਹਉ ਤਾਪੁ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਨਾਹੀਹਉਤਾਪੁ ॥","translit":"Saadhh Kai Sang Naahee Ho Thaap ||","english":"In the Company of the Holy, the fever of ego departs."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਤਜੈ ਸਭੁ ਆਪੁ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਤਜੈਸਭੁਆਪੁ ॥","translit":"Saadhh Kai Sang Thajai Sabh Aap ||","english":"In the Company of the Holy, one renounces all selfishness."},{"punjabi":"ਆਪੇ ਜਾਨੈ ਸਾਧ ਬਡਾਈ ॥","lareedar":"ਆਪੇਜਾਨੈਸਾਧਬਡਾਈ ॥","translit":"Aapae Jaanai Saadhh Baddaaee ||","english":"He Himself knows the greatness of the Holy."},{"punjabi":"ਨਾਨਕ ਸਾਧ ਪ੍ਰਭੂ ਬਨਿ ਆਈ ॥੩॥","lareedar":"ਨਾਨਕਸਾਧਪ੍ਰਭੂਬਨਿਆਈ ॥੩ ॥","translit":"Naanak Saadhh Prabhoo Ban Aaee ||3||","english":"O Nanak, the Holy are at one with God. ||3||"},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਨ ਕਬਹੂ ਧਾਵੈ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਨਕਬਹੂਧਾਵੈ ॥","translit":"Saadhh Kai Sang N Kabehoo Dhhaavai ||","english":"In the Company of the Holy, the mind never wanders."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਸਦਾ ਸੁਖੁ ਪਾਵੈ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਸਦਾਸੁਖੁਪਾਵੈ ॥","translit":"Saadhh Kai Sang Sadhaa Sukh Paavai ||","english":"In the Company of the Holy, one obtains everlasting peace."},{"punjabi":"ਸਾਧਸੰਗਿ ਬਸਤੁ ਅਗੋਚਰ ਲਹੈ ॥","lareedar":"ਸਾਧਸੰਗਿਬਸਤੁਅਗੋਚਰਲਹੈ ॥","translit":"Saadhhasang Basath Agochar Lehai ||","english":"In the Company of the Holy, one grasps the Incomprehensible."},{"punjabi":"ਸਾਧੂ ਕੈ ਸੰਗਿ ਅਜਰੁ ਸਹੈ ॥","lareedar":"ਸਾਧੂਕੈਸੰਗਿਅਜਰੁਸਹੈ ॥","translit":"Saadhhoo Kai Sang Ajar Sehai ||","english":"In the Company of the Holy, one can endure the unendurable."}]},{"index":23,"ang":271,"lines":[{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਬਸੈ ਥਾਨਿ ਊਚੈ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਬਸੈਥਾਨਿਊਚੈ ॥","translit":"Saadhh Kai Sang Basai Thhaan Oochai ||","english":"In the Company of the Holy, one abides in the loftiest place."},{"punjabi":"ਸਾਧੂ ਕੈ ਸੰਗਿ ਮਹਲਿ ਪਹੂਚੈ ॥","lareedar":"ਸਾਧੂਕੈਸੰਗਿਮਹਲਿਪਹੂਚੈ ॥","translit":"Saadhhoo Kai Sang Mehal Pehoochai ||","english":"In the Company of the Holy, one attains the Mansion of the Lord's Presence."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਦ੍ਰਿੜੈ ਸਭਿ ਧਰਮ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਦ੍ਰਿੜੈਸਭਿਧਰਮ ॥","translit":"Saadhh Kai Sang Dhrirrai Sabh Dhharam ||","english":"In the Company of the Holy, one's Dharmic faith is firmly established."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਕੇਵਲ ਪਾਰਬ੍ਰਹਮ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਕੇਵਲਪਾਰਬ੍ਰਹਮ ॥","translit":"Saadhh Kai Sang Kaeval Paarabreham ||","english":"In the Company of the Holy, one dwells with the Supreme Lord God."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਪਾਏ ਨਾਮ ਨਿਧਾਨ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਪਾਏਨਾਮਨਿਧਾਨ ॥","translit":"Saadhh Kai Sang Paaeae Naam Nidhhaan ||","english":"In the Company of the Holy, one obtains the treasure of the Naam."},{"punjabi":"ਨਾਨਕ ਸਾਧੂ ਕੈ ਕੁਰਬਾਨ ॥੪॥","lareedar":"ਨਾਨਕਸਾਧੂਕੈਕੁਰਬਾਨ ॥੪ ॥","translit":"Naanak Saadhhoo Kai Kurabaan ||4||","english":"O Nanak, I am a sacrifice to the Holy. ||4||"},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਸਭ ਕੁਲ ਉਧਾਰੈ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਸਭਕੁਲਉਧਾਰੈ ॥","translit":"Saadhh Kai Sang Sabh Kul Oudhhaarai ||","english":"In the Company of the Holy, all one's family is saved."},{"punjabi":"ਸਾਧਸੰਗਿ ਸਾਜਨ ਮੀਤ ਕੁਟੰਬ ਨਿਸਤਾਰੈ ॥","lareedar":"ਸਾਧਸੰਗਿਸਾਜਨਮੀਤਕੁਟੰਬਨਿਸਤਾਰੈ ॥","translit":"Saadhhasang Saajan Meeth Kuttanb Nisathaarai ||","english":"In the Company of the Holy, one's friends, acquaintances and relatives are redeemed."},{"punjabi":"ਸਾਧੂ ਕੈ ਸੰਗਿ ਸੋ ਧਨੁ ਪਾਵੈ ॥","lareedar":"ਸਾਧੂਕੈਸੰਗਿਸੋਧਨੁਪਾਵੈ ॥","translit":"Saadhhoo Kai Sang So Dhhan Paavai ||","english":"In the Company of the Holy, that wealth is obtained."},{"punjabi":"ਜਿਸੁ ਧਨ ਤੇ ਸਭੁ ਕੋ ਵਰਸਾਵੈ ॥","lareedar":"ਜਿਸੁਧਨਤੇਸਭੁਕੋਵਰਸਾਵੈ ॥","translit":"Jis Dhhan Thae Sabh Ko Varasaavai ||","english":"Everyone benefits from that wealth."},{"punjabi":"ਸਾਧਸੰਗਿ ਧਰਮ ਰਾਇ ਕਰੇ ਸੇਵਾ ॥","lareedar":"ਸਾਧਸੰਗਿਧਰਮਰਾਇਕਰੇਸੇਵਾ ॥","translit":"Saadhhasang Dhharam Raae Karae Saevaa ||","english":"In the Company of the Holy, the Lord of Dharma serves."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਸੋਭਾ ਸੁਰਦੇਵਾ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਸੋਭਾਸੁਰਦੇਵਾ ॥","translit":"Saadhh Kai Sang Sobhaa Suradhaevaa ||","english":"In the Company of the Holy, the divine, angelic beings sing God's Praises."},{"punjabi":"ਸਾਧੂ ਕੈ ਸੰਗਿ ਪਾਪ ਪਲਾਇਨ ॥","lareedar":"ਸਾਧੂਕੈਸੰਗਿਪਾਪਪਲਾਇਨ ॥","translit":"Saadhhoo Kai Sang Paap Palaaein ||","english":"In the Company of the Holy, one's sins fly away."},{"punjabi":"ਸਾਧਸੰਗਿ ਅੰਮ੍ਰਿਤ ਗੁਨ ਗਾਇਨ ॥","lareedar":"ਸਾਧਸੰਗਿਅੰਮ੍ਰਿਤਗੁਨਗਾਇਨ ॥","translit":"Saadhhasang Anmrith Gun Gaaein ||","english":"In the Company of the Holy, one sings the Ambrosial Glories."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਸ੍ਰਬ ਥਾਨ ਗੰਮਿ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਸ੍ਰਬਥਾਨਗੰਮਿ ॥","translit":"Saadhh Kai Sang Srab Thhaan Ganm ||","english":"In the Company of the Holy, all places are within reach."},{"punjabi":"ਨਾਨਕ ਸਾਧ ਕੈ ਸੰਗਿ ਸਫਲ ਜਨੰਮ ॥੫॥","lareedar":"ਨਾਨਕਸਾਧਕੈਸੰਗਿਸਫਲਜਨੰਮ ॥੫ ॥","translit":"Naanak Saadhh Kai Sang Safal Jananm ||5||","english":"O Nanak, in the Company of the Holy, one's life becomes fruitful. ||5||"},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਨਹੀ ਕਛੁ ਘਾਲ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਨਹੀਕਛੁਘਾਲ ॥","translit":"Saadhh Kai Sang Nehee Kashh Ghaal ||","english":"In the Company of the Holy, there is no suffering."},{"punjabi":"ਦਰਸਨੁ ਭੇਟਤ ਹੋਤ ਨਿਹਾਲ ॥","lareedar":"ਦਰਸਨੁਭੇਟਤਹੋਤਨਿਹਾਲ ॥","translit":"Dharasan Bhaettath Hoth Nihaal ||","english":"The Blessed Vision of their Darshan brings a sublime, happy peace."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਕਲੂਖਤ ਹਰੈ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਕਲੂਖਤਹਰੈ ॥","translit":"Saadhh Kai Sang Kalookhath Harai ||","english":"In the Company of the Holy, blemishes are removed."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਨਰਕ ਪਰਹਰੈ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਨਰਕਪਰਹਰੈ ॥","translit":"Saadhh Kai Sang Narak Pareharai ||","english":"In the Company of the Holy, hell is far away."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਈਹਾ ਊਹਾ ਸੁਹੇਲਾ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਈਹਾਊਹਾਸੁਹੇਲਾ ॥","translit":"Saadhh Kai Sang Eehaa Oohaa Suhaelaa ||","english":"In the Company of the Holy, one is happy here and hereafter."},{"punjabi":"ਸਾਧਸੰਗਿ ਬਿਛੁਰਤ ਹਰਿ ਮੇਲਾ ॥","lareedar":"ਸਾਧਸੰਗਿਬਿਛੁਰਤਹਰਿਮੇਲਾ ॥","translit":"Saadhhasang Bishhurath Har Maelaa ||","english":"In the Company of the Holy, the separated ones are reunited with the Lord."},{"punjabi":"ਜੋ ਇਛੈ ਸੋਈ ਫਲੁ ਪਾਵੈ ॥","lareedar":"ਜੋਇਛੈਸੋਈਫਲੁਪਾਵੈ ॥","translit":"Jo Eishhai Soee Fal Paavai ||","english":"The fruits of one's desires are obtained."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਨ ਬਿਰਥਾ ਜਾਵੈ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਨਬਿਰਥਾਜਾਵੈ ॥","translit":"Saadhh Kai Sang N Birathhaa Jaavai ||","english":"In the Company of the Holy, no one goes empty-handed."},{"punjabi":"ਪਾਰਬ੍ਰਹਮੁ ਸਾਧ ਰਿਦ ਬਸੈ ॥","lareedar":"ਪਾਰਬ੍ਰਹਮੁਸਾਧਰਿਦਬਸੈ ॥","translit":"Paarabreham Saadhh Ridh Basai ||","english":"The Supreme Lord God dwells in the hearts of the Holy."}]},{"index":24,"ang":272,"lines":[{"punjabi":"ਨਾਨਕ ਉਧਰੈ ਸਾਧ ਸੁਨਿ ਰਸੈ ॥੬॥","lareedar":"ਨਾਨਕਉਧਰੈਸਾਧਸੁਨਿਰਸੈ ॥੬ ॥","translit":"Naanak Oudhharai Saadhh Sun Rasai ||6||","english":"O Nanak, listening to the sweet words of the Holy, one is saved. ||6||"},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਸੁਨਉ ਹਰਿ ਨਾਉ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਸੁਨਉਹਰਿਨਾਉ ॥","translit":"Saadhh Kai Sang Suno Har Naao ||","english":"In the Company of the Holy, listen to the Name of the Lord."},{"punjabi":"ਸਾਧਸੰਗਿ ਹਰਿ ਕੇ ਗੁਨ ਗਾਉ ॥","lareedar":"ਸਾਧਸੰਗਿਹਰਿਕੇਗੁਨਗਾਉ ॥","translit":"Saadhhasang Har Kae Gun Gaao ||","english":"In the Company of the Holy, sing the Glorious Praises of the Lord."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਨ ਮਨ ਤੇ ਬਿਸਰੈ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਨਮਨਤੇਬਿਸਰੈ ॥","translit":"Saadhh Kai Sang N Man Thae Bisarai ||","english":"In the Company of the Holy, do not forget Him from your mind."},{"punjabi":"ਸਾਧਸੰਗਿ ਸਰਪਰ ਨਿਸਤਰੈ ॥","lareedar":"ਸਾਧਸੰਗਿਸਰਪਰਨਿਸਤਰੈ ॥","translit":"Saadhhasang Sarapar Nisatharai ||","english":"In the Company of the Holy, you shall surely be saved."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਲਗੈ ਪ੍ਰਭੁ ਮੀਠਾ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਲਗੈਪ੍ਰਭੁਮੀਠਾ ॥","translit":"Saadhh Kai Sang Lagai Prabh Meethaa ||","english":"In the Company of the Holy, God seems very sweet."},{"punjabi":"ਸਾਧੂ ਕੈ ਸੰਗਿ ਘਟਿ ਘਟਿ ਡੀਠਾ ॥","lareedar":"ਸਾਧੂਕੈਸੰਗਿਘਟਿਘਟਿਡੀਠਾ ॥","translit":"Saadhhoo Kai Sang Ghatt Ghatt Ddeethaa ||","english":"In the Company of the Holy, He is seen in each and every heart."},{"punjabi":"ਸਾਧਸੰਗਿ ਭਏ ਆਗਿਆਕਾਰੀ ॥","lareedar":"ਸਾਧਸੰਗਿਭਏਆਗਿਆਕਾਰੀ ॥","translit":"Saadhhasang Bheae Aagiaakaaree ||","english":"In the Company of the Holy, we become obedient to the Lord."},{"punjabi":"ਸਾਧਸੰਗਿ ਗਤਿ ਭਈ ਹਮਾਰੀ ॥","lareedar":"ਸਾਧਸੰਗਿਗਤਿਭਈਹਮਾਰੀ ॥","translit":"Saadhhasang Gath Bhee Hamaaree ||","english":"In the Company of the Holy, we obtain the state of salvation."},{"punjabi":"ਸਾਧ ਕੈ ਸੰਗਿ ਮਿਟੇ ਸਭਿ ਰੋਗ ॥","lareedar":"ਸਾਧਕੈਸੰਗਿਮਿਟੇਸਭਿਰੋਗ ॥","translit":"Saadhh Kai Sang Mittae Sabh Rog ||","english":"In the Company of the Holy, all diseases are cured."},{"punjabi":"ਨਾਨਕ ਸਾਧ ਭੇਟੇ ਸੰਜੋਗ ॥੭॥","lareedar":"ਨਾਨਕਸਾਧਭੇਟੇਸੰਜੋਗ ॥੭ ॥","translit":"Naanak Saadhh Bhaettae Sanjog ||7||","english":"O Nanak, one meets with the Holy, by highest destiny. ||7||"},{"punjabi":"ਸਾਧ ਕੀ ਮਹਿਮਾ ਬੇਦ ਨ ਜਾਨਹਿ ॥","lareedar":"ਸਾਧਕੀਮਹਿਮਾਬੇਦਨਜਾਨਹਿ ॥","translit":"Saadhh Kee Mehimaa Baedh N Jaanehi ||","english":"The glory of the Holy people is not known to the Vedas."},{"punjabi":"ਜੇਤਾ ਸੁਨਹਿ ਤੇਤਾ ਬਖਿਆਨਹਿ ॥","lareedar":"ਜੇਤਾਸੁਨਹਿਤੇਤਾਬਖਿਆਨਹਿ ॥","translit":"Jaethaa Sunehi Thaethaa Bakhiaanehi ||","english":"They can describe only what they have heard."},{"punjabi":"ਸਾਧ ਕੀ ਉਪਮਾ ਤਿਹੁ ਗੁਣ ਤੇ ਦੂਰਿ ॥","lareedar":"ਸਾਧਕੀਉਪਮਾਤਿਹੁਗੁਣਤੇਦੂਰਿ ॥","translit":"Saadhh Kee Oupamaa Thihu Gun Thae Dhoor ||","english":"The greatness of the Holy people is beyond the three qualities."},{"punjabi":"ਸਾਧ ਕੀ ਉਪਮਾ ਰਹੀ ਭਰਪੂਰਿ ॥","lareedar":"ਸਾਧਕੀਉਪਮਾਰਹੀਭਰਪੂਰਿ ॥","translit":"Saadhh Kee Oupamaa Rehee Bharapoor ||","english":"The greatness of the Holy people is all-pervading."},{"punjabi":"ਸਾਧ ਕੀ ਸੋਭਾ ਕਾ ਨਾਹੀ ਅੰਤ ॥","lareedar":"ਸਾਧਕੀਸੋਭਾਕਾਨਾਹੀਅੰਤ ॥","translit":"Saadhh Kee Sobhaa Kaa Naahee Anth ||","english":"The glory of the Holy people has no limit."},{"punjabi":"ਸਾਧ ਕੀ ਸੋਭਾ ਸਦਾ ਬੇਅੰਤ ॥","lareedar":"ਸਾਧਕੀਸੋਭਾਸਦਾਬੇਅੰਤ ॥","translit":"Saadhh Kee Sobhaa Sadhaa Baeanth ||","english":"The glory of the Holy people is infinite and eternal."},{"punjabi":"ਸਾਧ ਕੀ ਸੋਭਾ ਊਚ ਤੇ ਊਚੀ ॥","lareedar":"ਸਾਧਕੀਸੋਭਾਊਚਤੇਊਚੀ ॥","translit":"Saadhh Kee Sobhaa Ooch Thae Oochee ||","english":"The glory of the Holy people is the highest of the high."},{"punjabi":"ਸਾਧ ਕੀ ਸੋਭਾ ਮੂਚ ਤੇ ਮੂਚੀ ॥","lareedar":"ਸਾਧਕੀਸੋਭਾਮੂਚਤੇਮੂਚੀ ॥","translit":"Saadhh Kee Sobhaa Mooch Thae Moochee ||","english":"The glory of the Holy people is the greatest of the great."},{"punjabi":"ਸਾਧ ਕੀ ਸੋਭਾ ਸਾਧ ਬਨਿ ਆਈ ॥","lareedar":"ਸਾਧਕੀਸੋਭਾਸਾਧਬਨਿਆਈ ॥","translit":"Saadhh Kee Sobhaa Saadhh Ban Aaee ||","english":"The glory of the Holy people is theirs alone;"},{"punjabi":"ਨਾਨਕ ਸਾਧ ਪ੍ਰਭ ਭੇਦੁ ਨ ਭਾਈ ॥੮॥੭॥","lareedar":"ਨਾਨਕਸਾਧਪ੍ਰਭਭੇਦੁਨਭਾਈ ॥੮ ॥੭ ॥","translit":"Naanak Saadhh Prabh Bhaedh N Bhaaee ||8||7||","english":"O Nanak, there is no difference between the Holy people and God. ||8||7||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਮਨਿ ਸਾਚਾ ਮੁਖਿ ਸਾਚਾ ਸੋਇ ॥","lareedar":"ਮਨਿਸਾਚਾਮੁਖਿਸਾਚਾਸੋਇ ॥","translit":"Man Saachaa Mukh Saachaa Soe ||","english":"The True One is on his mind, and the True One is upon his lips."},{"punjabi":"ਅਵਰੁ ਨ ਪੇਖੈ ਏਕਸੁ ਬਿਨੁ ਕੋਇ ॥","lareedar":"ਅਵਰੁਨਪੇਖੈਏਕਸੁਬਿਨੁਕੋਇ ॥","translit":"Avar N Paekhai Eaekas Bin Koe ||","english":"He sees only the One."},{"punjabi":"ਨਾਨਕ ਇਹ ਲਛਣ ਬ੍ਰਹਮ ਗਿਆਨੀ ਹੋਇ ॥੧॥","lareedar":"ਨਾਨਕਇਹਲਛਣਬ੍ਰਹਮਗਿਆਨੀਹੋਇ ॥੧ ॥","translit":"Naanak Eih Lashhan Breham Giaanee Hoe ||1||","english":"O Nanak, these are the qualities of the God-conscious being. ||1||"}]},{"index":25,"ang":272,"lines":[{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਸਦਾ ਨਿਰਲੇਪ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਸਦਾਨਿਰਲੇਪ ॥","translit":"Breham Giaanee Sadhaa Niralaep ||","english":"The God-conscious being is always unattached,"},{"punjabi":"ਜੈਸੇ ਜਲ ਮਹਿ ਕਮਲ ਅਲੇਪ ॥","lareedar":"ਜੈਸੇਜਲਮਹਿਕਮਲਅਲੇਪ ॥","translit":"Jaisae Jal Mehi Kamal Alaep ||","english":"As the lotus in the water remains detached."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਸਦਾ ਨਿਰਦੋਖ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਸਦਾਨਿਰਦੋਖ ॥","translit":"Breham Giaanee Sadhaa Niradhokh ||","english":"The God-conscious being is always unstained,"},{"punjabi":"ਜੈਸੇ ਸੂਰੁ ਸਰਬ ਕਉ ਸੋਖ ॥","lareedar":"ਜੈਸੇਸੂਰੁਸਰਬਕਉਸੋਖ ॥","translit":"Jaisae Soor Sarab Ko Sokh ||","english":"Like the sun, which gives its comfort and warmth to all."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਦ੍ਰਿਸਟਿ ਸਮਾਨਿ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਦ੍ਰਿਸਟਿਸਮਾਨਿ ॥","translit":"Breham Giaanee Kai Dhrisatt Samaan ||","english":"The God-conscious being looks upon all alike,"},{"punjabi":"ਜੈਸੇ ਰਾਜ ਰੰਕ ਕਉ ਲਾਗੈ ਤੁਲਿ ਪਵਾਨ ॥","lareedar":"ਜੈਸੇਰਾਜਰੰਕਕਉਲਾਗੈਤੁਲਿਪਵਾਨ ॥","translit":"Jaisae Raaj Rank Ko Laagai Thul Pavaan ||","english":"Like the wind, which blows equally upon the king and the poor beggar."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਧੀਰਜੁ ਏਕ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਧੀਰਜੁਏਕ ॥","translit":"Breham Giaanee Kai Dhheeraj Eaek ||","english":"The God-conscious being has a steady patience,"},{"punjabi":"ਜਿਉ ਬਸੁਧਾ ਕੋਊ ਖੋਦੈ ਕੋਊ ਚੰਦਨ ਲੇਪ ॥","lareedar":"ਜਿਉਬਸੁਧਾਕੋਊਖੋਦੈਕੋਊਚੰਦਨਲੇਪ ॥","translit":"Jio Basudhhaa Kooo Khodhai Kooo Chandhan Laep ||","english":"Like the earth, which is dug up by one, and anointed with sandal paste by another."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਾ ਇਹੈ ਗੁਨਾਉ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਾਇਹੈਗੁਨਾਉ ॥","translit":"Breham Giaanee Kaa Eihai Gunaao ||","english":"This is the quality of the God-conscious being:"},{"punjabi":"ਨਾਨਕ ਜਿਉ ਪਾਵਕ ਕਾ ਸਹਜ ਸੁਭਾਉ ॥੧॥","lareedar":"ਨਾਨਕਜਿਉਪਾਵਕਕਾਸਹਜਸੁਭਾਉ ॥੧ ॥","translit":"Naanak Jio Paavak Kaa Sehaj Subhaao ||1||","english":"O Nanak, his inherent nature is like a warming fire. ||1||"},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਨਿਰਮਲ ਤੇ ਨਿਰਮਲਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਨਿਰਮਲਤੇਨਿਰਮਲਾ ॥","translit":"Breham Giaanee Niramal Thae Niramalaa ||","english":"The God-conscious being is the purest of the pure;"},{"punjabi":"ਜੈਸੇ ਮੈਲੁ ਨ ਲਾਗੈ ਜਲਾ ॥","lareedar":"ਜੈਸੇਮੈਲੁਨਲਾਗੈਜਲਾ ॥","translit":"Jaisae Mail N Laagai Jalaa ||","english":"Filth does not stick to water."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਮਨਿ ਹੋਇ ਪ੍ਰਗਾਸੁ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਮਨਿਹੋਇਪ੍ਰਗਾਸੁ ॥","translit":"Breham Giaanee Kai Man Hoe Pragaas ||","english":"The God-conscious being's mind is enlightened,"},{"punjabi":"ਜੈਸੇ ਧਰ ਊਪਰਿ ਆਕਾਸੁ ॥","lareedar":"ਜੈਸੇਧਰਊਪਰਿਆਕਾਸੁ ॥","translit":"Jaisae Dhhar Oopar Aakaas ||","english":"Like the sky above the earth."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਮਿਤ੍ਰ ਸਤ੍ਰੁ ਸਮਾਨਿ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਮਿਤ੍ਰਸਤ੍ਰੁਸਮਾਨਿ ॥","translit":"Breham Giaanee Kai Mithr Sathra Samaan ||","english":"To the God-conscious being, friend and foe are the same."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਨਾਹੀ ਅਭਿਮਾਨ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਨਾਹੀਅਭਿਮਾਨ ॥","translit":"Breham Giaanee Kai Naahee Abhimaan ||","english":"The God-conscious being has no egotistical pride."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਊਚ ਤੇ ਊਚਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਊਚਤੇਊਚਾ ॥","translit":"Breham Giaanee Ooch Thae Oochaa ||","english":"The God-conscious being is the highest of the high."},{"punjabi":"ਮਨਿ ਅਪਨੈ ਹੈ ਸਭ ਤੇ ਨੀਚਾ ॥","lareedar":"ਮਨਿਅਪਨੈਹੈਸਭਤੇਨੀਚਾ ॥","translit":"Man Apanai Hai Sabh Thae Neechaa ||","english":"Within his own mind, he is the most humble of all."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਸੇ ਜਨ ਭਏ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਸੇਜਨਭਏ ॥","translit":"Breham Giaanee Sae Jan Bheae ||","english":"They alone become God-conscious beings,"},{"punjabi":"ਨਾਨਕ ਜਿਨ ਪ੍ਰਭੁ ਆਪਿ ਕਰੇਇ ॥੨॥","lareedar":"ਨਾਨਕਜਿਨਪ੍ਰਭੁਆਪਿਕਰੇਇ ॥੨ ॥","translit":"Naanak Jin Prabh Aap Karaee ||2||","english":"O Nanak, whom God Himself makes so. ||2||"},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਸਗਲ ਕੀ ਰੀਨਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਸਗਲਕੀਰੀਨਾ ॥","translit":"Breham Giaanee Sagal Kee Reenaa ||","english":"The God-conscious being is the dust of all."},{"punjabi":"ਆਤਮ ਰਸੁ ਬ੍ਰਹਮ ਗਿਆਨੀ ਚੀਨਾ ॥","lareedar":"ਆਤਮਰਸੁਬ੍ਰਹਮਗਿਆਨੀਚੀਨਾ ॥","translit":"Aatham Ras Breham Giaanee Cheenaa ||","english":"The God-conscious being knows the nature of the soul."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੀ ਸਭ ਊਪਰਿ ਮਇਆ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੀਸਭਊਪਰਿਮਇਆ ॥","translit":"Breham Giaanee Kee Sabh Oopar Maeiaa ||","english":"The God-conscious being shows kindness to all."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਤੇ ਕਛੁ ਬੁਰਾ ਨ ਭਇਆ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਤੇਕਛੁਬੁਰਾਨਭਇਆ ॥","translit":"Breham Giaanee Thae Kashh Buraa N Bhaeiaa ||","english":"No evil comes from the God-conscious being."}]},{"index":26,"ang":272,"lines":[{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਸਦਾ ਸਮਦਰਸੀ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਸਦਾਸਮਦਰਸੀ ॥","translit":"Breham Giaanee Sadhaa Samadharasee ||","english":"The God-conscious being is always impartial."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੀ ਦ੍ਰਿਸਟਿ ਅੰਮ੍ਰਿਤੁ ਬਰਸੀ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੀਦ੍ਰਿਸਟਿਅੰਮ੍ਰਿਤੁਬਰਸੀ ॥","translit":"Breham Giaanee Kee Dhrisatt Anmrith Barasee ||","english":"Nectar rains down from the glance of the God-conscious being."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਬੰਧਨ ਤੇ ਮੁਕਤਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਬੰਧਨਤੇਮੁਕਤਾ ॥","translit":"Breham Giaanee Bandhhan Thae Mukathaa ||","english":"The God-conscious being is free from entanglements."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੀ ਨਿਰਮਲ ਜੁਗਤਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੀਨਿਰਮਲਜੁਗਤਾ ॥","translit":"Breham Giaanee Kee Niramal Jugathaa ||","english":"The lifestyle of the God-conscious being is spotlessly pure."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਾ ਭੋਜਨੁ ਗਿਆਨ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਾਭੋਜਨੁਗਿਆਨ ॥","translit":"Breham Giaanee Kaa Bhojan Giaan ||","english":"Spiritual wisdom is the food of the God-conscious being."},{"punjabi":"ਨਾਨਕ ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਾ ਬ੍ਰਹਮ ਧਿਆਨੁ ॥੩॥","lareedar":"ਨਾਨਕਬ੍ਰਹਮਗਿਆਨੀਕਾਬ੍ਰਹਮਧਿਆਨੁ ॥੩ ॥","translit":"Naanak Breham Giaanee Kaa Breham Dhhiaan ||3||","english":"O Nanak, the God-conscious being is absorbed in God's meditation. ||3||"},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਏਕ ਊਪਰਿ ਆਸ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਏਕਊਪਰਿਆਸ ॥","translit":"Breham Giaanee Eaek Oopar Aas ||","english":"The God-conscious being centers his hopes on the One alone."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਾ ਨਹੀ ਬਿਨਾਸ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਾਨਹੀਬਿਨਾਸ ॥","translit":"Breham Giaanee Kaa Nehee Binaas ||","english":"The God-conscious being shall never perish."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਗਰੀਬੀ ਸਮਾਹਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਗਰੀਬੀਸਮਾਹਾ ॥","translit":"Breham Giaanee Kai Gareebee Samaahaa ||","english":"The God-conscious being is steeped in humility."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਪਰਉਪਕਾਰ ਉਮਾਹਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਪਰਉਪਕਾਰਉਮਾਹਾ ॥","translit":"Breham Giaanee Paroupakaar Oumaahaa ||","english":"The God-conscious being delights in doing good to others."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਨਾਹੀ ਧੰਧਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਨਾਹੀਧੰਧਾ ॥","translit":"Breham Giaanee Kai Naahee Dhhandhhaa ||","english":"The God-conscious being has no worldly entanglements."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਲੇ ਧਾਵਤੁ ਬੰਧਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਲੇਧਾਵਤੁਬੰਧਾ ॥","translit":"Breham Giaanee Lae Dhhaavath Bandhhaa ||","english":"The God-conscious being holds his wandering mind under control."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਹੋਇ ਸੁ ਭਲਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਹੋਇਸੁਭਲਾ ॥","translit":"Breham Giaanee Kai Hoe S Bhalaa ||","english":"The God-conscious being acts in the common good."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਸੁਫਲ ਫਲਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਸੁਫਲਫਲਾ ॥","translit":"Breham Giaanee Sufal Falaa ||","english":"The God-conscious being blossoms in fruitfulness."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਸੰਗਿ ਸਗਲ ਉਧਾਰੁ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਸੰਗਿਸਗਲਉਧਾਰੁ ॥","translit":"Breham Giaanee Sang Sagal Oudhhaar ||","english":"In the Company of the God-conscious being, all are saved."},{"punjabi":"ਨਾਨਕ ਬ੍ਰਹਮ ਗਿਆਨੀ ਜਪੈ ਸਗਲ ਸੰਸਾਰੁ ॥੪॥","lareedar":"ਨਾਨਕਬ੍ਰਹਮਗਿਆਨੀਜਪੈਸਗਲਸੰਸਾਰੁ ॥੪ ॥","translit":"Naanak Breham Giaanee Japai Sagal Sansaar ||4||","english":"O Nanak, through the God-conscious being, the whole world meditates on God. ||4||"},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਏਕੈ ਰੰਗ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਏਕੈਰੰਗ ॥","translit":"Breham Giaanee Kai Eaekai Rang ||","english":"The God-conscious being loves the One Lord alone."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਬਸੈ ਪ੍ਰਭੁ ਸੰਗ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਬਸੈਪ੍ਰਭੁਸੰਗ ॥","translit":"Breham Giaanee Kai Basai Prabh Sang ||","english":"The God-conscious being dwells with God."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਨਾਮੁ ਆਧਾਰੁ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਨਾਮੁਆਧਾਰੁ ॥","translit":"Breham Giaanee Kai Naam Aadhhaar ||","english":"The God-conscious being takes the Naam as his Support."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਨਾਮੁ ਪਰਵਾਰੁ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਨਾਮੁਪਰਵਾਰੁ ॥","translit":"Breham Giaanee Kai Naam Paravaar ||","english":"The God-conscious being has the Naam as his Family."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਸਦਾ ਸਦ ਜਾਗਤ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਸਦਾਸਦਜਾਗਤ ॥","translit":"Breham Giaanee Sadhaa Sadh Jaagath ||","english":"The God-conscious being is awake and aware, forever and ever."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਅਹੰਬੁਧਿ ਤਿਆਗਤ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਅਹੰਬੁਧਿਤਿਆਗਤ ॥","translit":"Breham Giaanee Ahanbudhh Thiaagath ||","english":"The God-conscious being renounces his proud ego."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਮਨਿ ਪਰਮਾਨੰਦ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਮਨਿਪਰਮਾਨੰਦ ॥","translit":"Breham Giaanee Kai Man Paramaanandh ||","english":"In the mind of the God-conscious being, there is supreme bliss."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਘਰਿ ਸਦਾ ਅਨੰਦ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਘਰਿਸਦਾਅਨੰਦ ॥","translit":"Breham Giaanee Kai Ghar Sadhaa Anandh ||","english":"In the home of the God-conscious being, there is everlasting bliss."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਸੁਖ ਸਹਜ ਨਿਵਾਸ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਸੁਖਸਹਜਨਿਵਾਸ ॥","translit":"Breham Giaanee Sukh Sehaj Nivaas ||","english":"The God-conscious being dwells in peaceful ease."}]},{"index":27,"ang":273,"lines":[{"punjabi":"ਨਾਨਕ ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਾ ਨਹੀ ਬਿਨਾਸ ॥੫॥","lareedar":"ਨਾਨਕਬ੍ਰਹਮਗਿਆਨੀਕਾਨਹੀਬਿਨਾਸ ॥੫ ॥","translit":"Naanak Breham Giaanee Kaa Nehee Binaas ||5||","english":"O Nanak, the God-conscious being shall never perish. ||5||"},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਬ੍ਰਹਮ ਕਾ ਬੇਤਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਬ੍ਰਹਮਕਾਬੇਤਾ ॥","translit":"Breham Giaanee Breham Kaa Baethaa ||","english":"The God-conscious being knows God."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਏਕ ਸੰਗਿ ਹੇਤਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਏਕਸੰਗਿਹੇਤਾ ॥","translit":"Breham Giaanee Eaek Sang Haethaa ||","english":"The God-conscious being is in love with the One alone."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਹੋਇ ਅਚਿੰਤ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਹੋਇਅਚਿੰਤ ॥","translit":"Breham Giaanee Kai Hoe Achinth ||","english":"The God-conscious being is carefree."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਾ ਨਿਰਮਲ ਮੰਤ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਾਨਿਰਮਲਮੰਤ ॥","translit":"Breham Giaanee Kaa Niramal Manth ||","english":"Pure are the Teachings of the God-conscious being."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਜਿਸੁ ਕਰੈ ਪ੍ਰਭੁ ਆਪਿ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਜਿਸੁਕਰੈਪ੍ਰਭੁਆਪਿ ॥","translit":"Breham Giaanee Jis Karai Prabh Aap ||","english":"The God-conscious being is made so by God Himself."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਾ ਬਡ ਪਰਤਾਪ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਾਬਡਪਰਤਾਪ ॥","translit":"Breham Giaanee Kaa Badd Parathaap ||","english":"The God-conscious being is gloriously great."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਾ ਦਰਸੁ ਬਡਭਾਗੀ ਪਾਈਐ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਾਦਰਸੁਬਡਭਾਗੀਪਾਈਐ ॥","translit":"Breham Giaanee Kaa Dharas Baddabhaagee Paaeeai ||","english":"The Darshan, the Blessed Vision of the God-conscious being, is obtained by great good fortune."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਉ ਬਲਿ ਬਲਿ ਜਾਈਐ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਉਬਲਿਬਲਿਜਾਈਐ ॥","translit":"Breham Giaanee Ko Bal Bal Jaaeeai ||","english":"To the God-conscious being, I make my life a sacrifice."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਉ ਖੋਜਹਿ ਮਹੇਸੁਰ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਉਖੋਜਹਿਮਹੇਸੁਰ ॥","translit":"Breham Giaanee Ko Khojehi Mehaesur ||","english":"The God-conscious being is sought by the great god Shiva."},{"punjabi":"ਨਾਨਕ ਬ੍ਰਹਮ ਗਿਆਨੀ ਆਪਿ ਪਰਮੇਸੁਰ ॥੬॥","lareedar":"ਨਾਨਕਬ੍ਰਹਮਗਿਆਨੀਆਪਿਪਰਮੇਸੁਰ ॥੬ ॥","translit":"Naanak Breham Giaanee Aap Paramaesur ||6||","english":"O Nanak, the God-conscious being is Himself the Supreme Lord God. ||6||"},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੀ ਕੀਮਤਿ ਨਾਹਿ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੀਕੀਮਤਿਨਾਹਿ ॥","translit":"Breham Giaanee Kee Keemath Naahi ||","english":"The God-conscious being cannot be appraised."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੈ ਸਗਲ ਮਨ ਮਾਹਿ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੈਸਗਲਮਨਮਾਹਿ ॥","translit":"Breham Giaanee Kai Sagal Man Maahi ||","english":"The God-conscious being has all within his mind."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਾ ਕਉਨ ਜਾਨੈ ਭੇਦੁ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਾਕਉਨਜਾਨੈਭੇਦੁ ॥","translit":"Breham Giaanee Kaa Koun Jaanai Bhaedh ||","english":"Who can know the mystery of the God-conscious being?"},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਉ ਸਦਾ ਅਦੇਸੁ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਉਸਦਾਅਦੇਸੁ ॥","translit":"Breham Giaanee Ko Sadhaa Adhaes ||","english":"Forever bow to the God-conscious being."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਾ ਕਥਿਆ ਨ ਜਾਇ ਅਧਾਖ੍ਯ੍ਯਰੁ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਾਕਥਿਆਨਜਾਇਅਧਾਖ੍ਯ੍ਯਰੁ ॥","translit":"Breham Giaanee Kaa Kathhiaa N Jaae Adhhaakhyar ||","english":"The God-conscious being cannot be described in words."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਸਰਬ ਕਾ ਠਾਕੁਰੁ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਸਰਬਕਾਠਾਕੁਰੁ ॥","translit":"Breham Giaanee Sarab Kaa Thaakur ||","english":"The God-conscious being is the Lord and Master of all."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੀ ਮਿਤਿ ਕਉਨੁ ਬਖਾਨੈ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੀਮਿਤਿਕਉਨੁਬਖਾਨੈ ॥","translit":"Breham Giaanee Kee Mith Koun Bakhaanai ||","english":"Who can describe the limits of the God-conscious being?"},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੀ ਗਤਿ ਬ੍ਰਹਮ ਗਿਆਨੀ ਜਾਨੈ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੀਗਤਿਬ੍ਰਹਮਗਿਆਨੀਜਾਨੈ ॥","translit":"Breham Giaanee Kee Gath Breham Giaanee Jaanai ||","english":"Only the God-conscious being can know the state of the God-conscious being."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਾ ਅੰਤੁ ਨ ਪਾਰੁ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਾਅੰਤੁਨਪਾਰੁ ॥","translit":"Breham Giaanee Kaa Anth N Paar ||","english":"The God-conscious being has no end or limitation."},{"punjabi":"ਨਾਨਕ ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਉ ਸਦਾ ਨਮਸਕਾਰੁ ॥੭॥","lareedar":"ਨਾਨਕਬ੍ਰਹਮਗਿਆਨੀਕਉਸਦਾਨਮਸਕਾਰੁ ॥੭ ॥","translit":"Naanak Breham Giaanee Ko Sadhaa Namasakaar ||7||","english":"O Nanak, to the God-conscious being, bow forever in reverence. ||7||"},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਸਭ ਸ੍ਰਿਸਟਿ ਕਾ ਕਰਤਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਸਭਸ੍ਰਿਸਟਿਕਾਕਰਤਾ ॥","translit":"Breham Giaanee Sabh Srisatt Kaa Karathaa ||","english":"The God-conscious being is the Creator of all the world."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਸਦ ਜੀਵੈ ਨਹੀ ਮਰਤਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਸਦਜੀਵੈਨਹੀਮਰਤਾ ॥","translit":"Breham Giaanee Sadh Jeevai Nehee Marathaa ||","english":"The God-conscious being lives forever, and does not die."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਮੁਕਤਿ ਜੁਗਤਿ ਜੀਅ ਕਾ ਦਾਤਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਮੁਕਤਿਜੁਗਤਿਜੀਅਕਾਦਾਤਾ ॥","translit":"Breham Giaanee Mukath Jugath Jeea Kaa Dhaathaa ||","english":"The God-conscious being is the Giver of the way of liberation of the soul."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਪੂਰਨ ਪੁਰਖੁ ਬਿਧਾਤਾ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਪੂਰਨਪੁਰਖੁਬਿਧਾਤਾ ॥","translit":"Breham Giaanee Pooran Purakh Bidhhaathaa ||","english":"The God-conscious being is the Perfect Supreme Being, who orchestrates all."}]},{"index":28,"ang":273,"lines":[{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਅਨਾਥ ਕਾ ਨਾਥੁ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਅਨਾਥਕਾਨਾਥੁ ॥","translit":"Breham Giaanee Anaathh Kaa Naathh ||","english":"The God-conscious being is the helper of the helpless."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਾ ਸਭ ਊਪਰਿ ਹਾਥੁ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਾਸਭਊਪਰਿਹਾਥੁ ॥","translit":"Breham Giaanee Kaa Sabh Oopar Haathh ||","english":"The God-conscious being extends his hand to all."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕਾ ਸਗਲ ਅਕਾਰੁ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕਾਸਗਲਅਕਾਰੁ ॥","translit":"Breham Giaanee Kaa Sagal Akaar ||","english":"The God-conscious being owns the entire creation."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਆਪਿ ਨਿਰੰਕਾਰੁ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਆਪਿਨਿਰੰਕਾਰੁ ॥","translit":"Breham Giaanee Aap Nirankaar ||","english":"The God-conscious being is himself the Formless Lord."},{"punjabi":"ਬ੍ਰਹਮ ਗਿਆਨੀ ਕੀ ਸੋਭਾ ਬ੍ਰਹਮ ਗਿਆਨੀ ਬਨੀ ॥","lareedar":"ਬ੍ਰਹਮਗਿਆਨੀਕੀਸੋਭਾਬ੍ਰਹਮਗਿਆਨੀਬਨੀ ॥","translit":"Breham Giaanee Kee Sobhaa Breham Giaanee Banee ||","english":"The glory of the God-conscious being belongs to the God-conscious being alone."},{"punjabi":"ਨਾਨਕ ਬ੍ਰਹਮ ਗਿਆਨੀ ਸਰਬ ਕਾ ਧਨੀ ॥੮॥੮॥","lareedar":"ਨਾਨਕਬ੍ਰਹਮਗਿਆਨੀਸਰਬਕਾਧਨੀ ॥੮ ॥੮ ॥","translit":"Naanak Breham Giaanee Sarab Kaa Dhhanee ||8||8||","english":"O Nanak, the God-conscious being is the Lord of all. ||8||8||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਉਰਿ ਧਾਰੈ ਜੋ ਅੰਤਰਿ ਨਾਮੁ ॥","lareedar":"ਉਰਿਧਾਰੈਜੋਅੰਤਰਿਨਾਮੁ ॥","translit":"Our Dhhaarai Jo Anthar Naam ||","english":"One who enshrines the Naam within the heart,"},{"punjabi":"ਸਰਬ ਮੈ ਪੇਖੈ ਭਗਵਾਨੁ ॥","lareedar":"ਸਰਬਮੈਪੇਖੈਭਗਵਾਨੁ ॥","translit":"Sarab Mai Paekhai Bhagavaan ||","english":"Who sees the Lord God in all,"},{"punjabi":"ਨਿਮਖ ਨਿਮਖ ਠਾਕੁਰ ਨਮਸਕਾਰੈ ॥","lareedar":"ਨਿਮਖਨਿਮਖਠਾਕੁਰਨਮਸਕਾਰੈ ॥","translit":"Nimakh Nimakh Thaakur Namasakaarai ||","english":"Who, each and every moment, bows in reverence to the Lord Master"},{"punjabi":"ਨਾਨਕ ਓਹੁ ਅਪਰਸੁ ਸਗਲ ਨਿਸਤਾਰੈ ॥੧॥","lareedar":"ਨਾਨਕਓਹੁਅਪਰਸੁਸਗਲਨਿਸਤਾਰੈ ॥੧ ॥","translit":"Naanak Ouhu Aparas Sagal Nisathaarai ||1||","english":"- O Nanak, such a one is the true 'touch-nothing Saint', who emancipates everyone. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਮਿਥਿਆ ਨਾਹੀ ਰਸਨਾ ਪਰਸ ॥","lareedar":"ਮਿਥਿਆਨਾਹੀਰਸਨਾਪਰਸ ॥","translit":"Mithhiaa Naahee Rasanaa Paras ||","english":"One whose tongue does not touch falsehood;"},{"punjabi":"ਮਨ ਮਹਿ ਪ੍ਰੀਤਿ ਨਿਰੰਜਨ ਦਰਸ ॥","lareedar":"ਮਨਮਹਿਪ੍ਰੀਤਿਨਿਰੰਜਨਦਰਸ ॥","translit":"Man Mehi Preeth Niranjan Dharas ||","english":"Whose mind is filled with love for the Blessed Vision of the Pure Lord,"},{"punjabi":"ਪਰ ਤ੍ਰਿਅ ਰੂਪੁ ਨ ਪੇਖੈ ਨੇਤ੍ਰ ॥","lareedar":"ਪਰਤ੍ਰਿਅਰੂਪੁਨਪੇਖੈਨੇਤ੍ਰ ॥","translit":"Par Thria Roop N Paekhai Naethr ||","english":"Whose eyes do not gaze upon the beauty of others' wives,"},{"punjabi":"ਸਾਧ ਕੀ ਟਹਲ ਸੰਤਸੰਗਿ ਹੇਤ ॥","lareedar":"ਸਾਧਕੀਟਹਲਸੰਤਸੰਗਿਹੇਤ ॥","translit":"Saadhh Kee Ttehal Santhasang Haeth ||","english":"Who serves the Holy and loves the Saints' Congregation,"},{"punjabi":"ਕਰਨ ਨ ਸੁਨੈ ਕਾਹੂ ਕੀ ਨਿੰਦਾ ॥","lareedar":"ਕਰਨਨਸੁਨੈਕਾਹੂਕੀਨਿੰਦਾ ॥","translit":"Karan N Sunai Kaahoo Kee Nindhaa ||","english":"Whose ears do not listen to slander against anyone,"},{"punjabi":"ਸਭ ਤੇ ਜਾਨੈ ਆਪਸ ਕਉ ਮੰਦਾ ॥","lareedar":"ਸਭਤੇਜਾਨੈਆਪਸਕਉਮੰਦਾ ॥","translit":"Sabh Thae Jaanai Aapas Ko Mandhaa ||","english":"Who deems himself to be the worst of all,"},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਬਿਖਿਆ ਪਰਹਰੈ ॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਬਿਖਿਆਪਰਹਰੈ ॥","translit":"Gur Prasaadh Bikhiaa Pareharai ||","english":"Who, by Guru's Grace, renounces corruption,"},{"punjabi":"ਮਨ ਕੀ ਬਾਸਨਾ ਮਨ ਤੇ ਟਰੈ ॥","lareedar":"ਮਨਕੀਬਾਸਨਾਮਨਤੇਟਰੈ ॥","translit":"Man Kee Baasanaa Man Thae Ttarai ||","english":"Who banishes the mind's evil desires from his mind,"},{"punjabi":"ਇੰਦ੍ਰੀ ਜਿਤ ਪੰਚ ਦੋਖ ਤੇ ਰਹਤ ॥","lareedar":"ਇੰਦ੍ਰੀਜਿਤਪੰਚਦੋਖਤੇਰਹਤ ॥","translit":"Eindhree Jith Panch Dhokh Thae Rehath ||","english":"Who conquers his sexual instincts and is free of the five sinful passions"},{"punjabi":"ਨਾਨਕ ਕੋਟਿ ਮਧੇ ਕੋ ਐਸਾ ਅਪਰਸ ॥੧॥","lareedar":"ਨਾਨਕਕੋਟਿਮਧੇਕੋਐਸਾਅਪਰਸ ॥੧ ॥","translit":"Naanak Kott Madhhae Ko Aisaa Aparas ||1||","english":"- O Nanak, among millions, there is scarcely one such 'touch-nothing Saint'. ||1||"},{"punjabi":"ਬੈਸਨੋ ਸੋ ਜਿਸੁ ਊਪਰਿ ਸੁਪ੍ਰਸੰਨ ॥","lareedar":"ਬੈਸਨੋਸੋਜਿਸੁਊਪਰਿਸੁਪ੍ਰਸੰਨ ॥","translit":"Baisano So Jis Oopar Suprasann ||","english":"The true Vaishnaav, the devotee of Vishnu, is the one with whom God is thoroughly pleased."},{"punjabi":"ਬਿਸਨ ਕੀ ਮਾਇਆ ਤੇ ਹੋਇ ਭਿੰਨ ॥","lareedar":"ਬਿਸਨਕੀਮਾਇਆਤੇਹੋਇਭਿੰਨ ॥","translit":"Bisan Kee Maaeiaa Thae Hoe Bhinn ||","english":"He dwells apart from Maya."},{"punjabi":"ਕਰਮ ਕਰਤ ਹੋਵੈ ਨਿਹਕਰਮ ॥","lareedar":"ਕਰਮਕਰਤਹੋਵੈਨਿਹਕਰਮ ॥","translit":"Karam Karath Hovai Nihakaram ||","english":"Performing good deeds, he does not seek rewards."}]},{"index":29,"ang":274,"lines":[{"punjabi":"ਤਿਸੁ ਬੈਸਨੋ ਕਾ ਨਿਰਮਲ ਧਰਮ ॥","lareedar":"ਤਿਸੁਬੈਸਨੋਕਾਨਿਰਮਲਧਰਮ ॥","translit":"This Baisano Kaa Niramal Dhharam ||","english":"Spotlessly pure is the religion of such a Vaishnaav;"},{"punjabi":"ਕਾਹੂ ਫਲ ਕੀ ਇਛਾ ਨਹੀ ਬਾਛੈ ॥","lareedar":"ਕਾਹੂਫਲਕੀਇਛਾਨਹੀਬਾਛੈ ॥","translit":"Kaahoo Fal Kee Eishhaa Nehee Baashhai ||","english":"He has no desire for the fruits of his labors."},{"punjabi":"ਕੇਵਲ ਭਗਤਿ ਕੀਰਤਨ ਸੰਗਿ ਰਾਚੈ ॥","lareedar":"ਕੇਵਲਭਗਤਿਕੀਰਤਨਸੰਗਿਰਾਚੈ ॥","translit":"Kaeval Bhagath Keerathan Sang Raachai ||","english":"He is absorbed in devotional worship and the singing of Kirtan, the songs of the Lord's Glory."},{"punjabi":"ਮਨ ਤਨ ਅੰਤਰਿ ਸਿਮਰਨ ਗੋਪਾਲ ॥","lareedar":"ਮਨਤਨਅੰਤਰਿਸਿਮਰਨਗੋਪਾਲ ॥","translit":"Man Than Anthar Simaran Gopaal ||","english":"Within his mind and body, he meditates in remembrance on the Lord of the Universe."},{"punjabi":"ਸਭ ਊਪਰਿ ਹੋਵਤ ਕਿਰਪਾਲ ॥","lareedar":"ਸਭਊਪਰਿਹੋਵਤਕਿਰਪਾਲ ॥","translit":"Sabh Oopar Hovath Kirapaal ||","english":"He is kind to all creatures."},{"punjabi":"ਆਪਿ ਦ੍ਰਿੜੈ ਅਵਰਹ ਨਾਮੁ ਜਪਾਵੈ ॥","lareedar":"ਆਪਿਦ੍ਰਿੜੈਅਵਰਹਨਾਮੁਜਪਾਵੈ ॥","translit":"Aap Dhrirrai Avareh Naam Japaavai ||","english":"He holds fast to the Naam, and inspires others to chant it."},{"punjabi":"ਨਾਨਕ ਓਹੁ ਬੈਸਨੋ ਪਰਮ ਗਤਿ ਪਾਵੈ ॥੨॥","lareedar":"ਨਾਨਕਓਹੁਬੈਸਨੋਪਰਮਗਤਿਪਾਵੈ ॥੨ ॥","translit":"Naanak Ouhu Baisano Param Gath Paavai ||2||","english":"O Nanak, such a Vaishnaav obtains the supreme status. ||2||"},{"punjabi":"ਭਗਉਤੀ ਭਗਵੰਤ ਭਗਤਿ ਕਾ ਰੰਗੁ ॥","lareedar":"ਭਗਉਤੀਭਗਵੰਤਭਗਤਿਕਾਰੰਗੁ ॥","translit":"Bhagouthee Bhagavanth Bhagath Kaa Rang ||","english":"The true Bhagaautee, the devotee of Adi Shakti, loves the devotional worship of God."},{"punjabi":"ਸਗਲ ਤਿਆਗੈ ਦੁਸਟ ਕਾ ਸੰਗੁ ॥","lareedar":"ਸਗਲਤਿਆਗੈਦੁਸਟਕਾਸੰਗੁ ॥","translit":"Sagal Thiaagai Dhusatt Kaa Sang ||","english":"He forsakes the company of all wicked people."},{"punjabi":"ਮਨ ਤੇ ਬਿਨਸੈ ਸਗਲਾ ਭਰਮੁ ॥","lareedar":"ਮਨਤੇਬਿਨਸੈਸਗਲਾਭਰਮੁ ॥","translit":"Man Thae Binasai Sagalaa Bharam ||","english":"All doubts are removed from his mind."},{"punjabi":"ਕਰਿ ਪੂਜੈ ਸਗਲ ਪਾਰਬ੍ਰਹਮੁ ॥","lareedar":"ਕਰਿਪੂਜੈਸਗਲਪਾਰਬ੍ਰਹਮੁ ॥","translit":"Kar Poojai Sagal Paarabreham ||","english":"He performs devotional service to the Supreme Lord God in all."},{"punjabi":"ਸਾਧਸੰਗਿ ਪਾਪਾ ਮਲੁ ਖੋਵੈ ॥","lareedar":"ਸਾਧਸੰਗਿਪਾਪਾਮਲੁਖੋਵੈ ॥","translit":"Saadhhasang Paapaa Mal Khovai ||","english":"In the Company of the Holy, the filth of sin is washed away."},{"punjabi":"ਤਿਸੁ ਭਗਉਤੀ ਕੀ ਮਤਿ ਊਤਮ ਹੋਵੈ ॥","lareedar":"ਤਿਸੁਭਗਉਤੀਕੀਮਤਿਊਤਮਹੋਵੈ ॥","translit":"This Bhagouthee Kee Math Ootham Hovai ||","english":"The wisdom of such a Bhagaautee becomes supreme."},{"punjabi":"ਭਗਵੰਤ ਕੀ ਟਹਲ ਕਰੈ ਨਿਤ ਨੀਤਿ ॥","lareedar":"ਭਗਵੰਤਕੀਟਹਲਕਰੈਨਿਤਨੀਤਿ ॥","translit":"Bhagavanth Kee Ttehal Karai Nith Neeth ||","english":"He constantly performs the service of the Supreme Lord God."},{"punjabi":"ਮਨੁ ਤਨੁ ਅਰਪੈ ਬਿਸਨ ਪਰੀਤਿ ॥","lareedar":"ਮਨੁਤਨੁਅਰਪੈਬਿਸਨਪਰੀਤਿ ॥","translit":"Man Than Arapai Bisan Pareeth ||","english":"He dedicates his mind and body to the Love of God."},{"punjabi":"ਹਰਿ ਕੇ ਚਰਨ ਹਿਰਦੈ ਬਸਾਵੈ ॥","lareedar":"ਹਰਿਕੇਚਰਨਹਿਰਦੈਬਸਾਵੈ ॥","translit":"Har Kae Charan Hiradhai Basaavai ||","english":"The Lotus Feet of the Lord abide in his heart."},{"punjabi":"ਨਾਨਕ ਐਸਾ ਭਗਉਤੀ ਭਗਵੰਤ ਕਉ ਪਾਵੈ ॥੩॥","lareedar":"ਨਾਨਕਐਸਾਭਗਉਤੀਭਗਵੰਤਕਉਪਾਵੈ ॥੩ ॥","translit":"Naanak Aisaa Bhagouthee Bhagavanth Ko Paavai ||3||","english":"O Nanak, such a Bhagaautee attains the Lord God. ||3||"},{"punjabi":"ਸੋ ਪੰਡਿਤੁ ਜੋ ਮਨੁ ਪਰਬੋਧੈ ॥","lareedar":"ਸੋਪੰਡਿਤੁਜੋਮਨੁਪਰਬੋਧੈ ॥","translit":"So Panddith Jo Man Parabodhhai ||","english":"He is a true Pandit, a religious scholar, who instructs his own mind."},{"punjabi":"ਰਾਮ ਨਾਮੁ ਆਤਮ ਮਹਿ ਸੋਧੈ ॥","lareedar":"ਰਾਮਨਾਮੁਆਤਮਮਹਿਸੋਧੈ ॥","translit":"Raam Naam Aatham Mehi Sodhhai ||","english":"He searches for the Lord's Name within his own soul."},{"punjabi":"ਰਾਮ ਨਾਮ ਸਾਰੁ ਰਸੁ ਪੀਵੈ ॥","lareedar":"ਰਾਮਨਾਮਸਾਰੁਰਸੁਪੀਵੈ ॥","translit":"Raam Naam Saar Ras Peevai ||","english":"He drinks in the Exquisite Nectar of the Lord's Name."},{"punjabi":"ਉਸੁ ਪੰਡਿਤ ਕੈ ਉਪਦੇਸਿ ਜਗੁ ਜੀਵੈ ॥","lareedar":"ਉਸੁਪੰਡਿਤਕੈਉਪਦੇਸਿਜਗੁਜੀਵੈ ॥","translit":"Ous Panddith Kai Oupadhaes Jag Jeevai ||","english":"By that Pandit's teachings, the world lives."},{"punjabi":"ਹਰਿ ਕੀ ਕਥਾ ਹਿਰਦੈ ਬਸਾਵੈ ॥","lareedar":"ਹਰਿਕੀਕਥਾਹਿਰਦੈਬਸਾਵੈ ॥","translit":"Har Kee Kathhaa Hiradhai Basaavai ||","english":"He implants the Sermon of the Lord in his heart."},{"punjabi":"ਸੋ ਪੰਡਿਤੁ ਫਿਰਿ ਜੋਨਿ ਨ ਆਵੈ ॥","lareedar":"ਸੋਪੰਡਿਤੁਫਿਰਿਜੋਨਿਨਆਵੈ ॥","translit":"So Panddith Fir Jon N Aavai ||","english":"Such a Pandit is not cast into the womb of reincarnation again."},{"punjabi":"ਬੇਦ ਪੁਰਾਨ ਸਿਮ੍ਰਿਤਿ ਬੂਝੈ ਮੂਲ ॥","lareedar":"ਬੇਦਪੁਰਾਨਸਿਮ੍ਰਿਤਿਬੂਝੈਮੂਲ ॥","translit":"Baedh Puraan Simrith Boojhai Mool ||","english":"He understands the fundamental essence of the Vedas, the Puraanas and the Simritees."},{"punjabi":"ਸੂਖਮ ਮਹਿ ਜਾਨੈ ਅਸਥੂਲੁ ॥","lareedar":"ਸੂਖਮਮਹਿਜਾਨੈਅਸਥੂਲੁ ॥","translit":"Sookham Mehi Jaanai Asathhool ||","english":"In the unmanifest, he sees the manifest world to exist."}]},{"index":30,"ang":274,"lines":[{"punjabi":"ਚਹੁ ਵਰਨਾ ਕਉ ਦੇ ਉਪਦੇਸੁ ॥","lareedar":"ਚਹੁਵਰਨਾਕਉਦੇਉਪਦੇਸੁ ॥","translit":"Chahu Varanaa Ko Dhae Oupadhaes ||","english":"He gives instruction to people of all castes and social classes."},{"punjabi":"ਨਾਨਕ ਉਸੁ ਪੰਡਿਤ ਕਉ ਸਦਾ ਅਦੇਸੁ ॥੪॥","lareedar":"ਨਾਨਕਉਸੁਪੰਡਿਤਕਉਸਦਾਅਦੇਸੁ ॥੪ ॥","translit":"Naanak Ous Panddith Ko Sadhaa Adhaes ||4||","english":"O Nanak, to such a Pandit, I bow in salutation forever. ||4||"},{"punjabi":"ਬੀਜ ਮੰਤ੍ਰੁ ਸਰਬ ਕੋ ਗਿਆਨੁ ॥","lareedar":"ਬੀਜਮੰਤ੍ਰੁਸਰਬਕੋਗਿਆਨੁ ॥","translit":"Beej Manthra Sarab Ko Giaan ||","english":"The Beej Mantra, the Seed Mantra, is spiritual wisdom for everyone."},{"punjabi":"ਚਹੁ ਵਰਨਾ ਮਹਿ ਜਪੈ ਕੋਊ ਨਾਮੁ ॥","lareedar":"ਚਹੁਵਰਨਾਮਹਿਜਪੈਕੋਊਨਾਮੁ ॥","translit":"Chahu Varanaa Mehi Japai Kooo Naam ||","english":"Anyone, from any class, may chant the Naam."},{"punjabi":"ਜੋ ਜੋ ਜਪੈ ਤਿਸ ਕੀ ਗਤਿ ਹੋਇ ॥","lareedar":"ਜੋਜੋਜਪੈਤਿਸਕੀਗਤਿਹੋਇ ॥","translit":"Jo Jo Japai This Kee Gath Hoe ||","english":"Whoever chants it, is emancipated."},{"punjabi":"ਸਾਧਸੰਗਿ ਪਾਵੈ ਜਨੁ ਕੋਇ ॥","lareedar":"ਸਾਧਸੰਗਿਪਾਵੈਜਨੁਕੋਇ ॥","translit":"Saadhhasang Paavai Jan Koe ||","english":"And yet, rare are those who attain it, in the Company of the Holy."},{"punjabi":"ਕਰਿ ਕਿਰਪਾ ਅੰਤਰਿ ਉਰ ਧਾਰੈ ॥","lareedar":"ਕਰਿਕਿਰਪਾਅੰਤਰਿਉਰਧਾਰੈ ॥","translit":"Kar Kirapaa Anthar Our Dhhaarai ||","english":"By His Grace, He enshrines it within."},{"punjabi":"ਪਸੁ ਪ੍ਰੇਤ ਮੁਘਦ ਪਾਥਰ ਕਉ ਤਾਰੈ ॥","lareedar":"ਪਸੁਪ੍ਰੇਤਮੁਘਦਪਾਥਰਕਉਤਾਰੈ ॥","translit":"Pas Praeth Mughadh Paathhar Ko Thaarai ||","english":"Even beasts, ghosts and the stone-hearted are saved."},{"punjabi":"ਸਰਬ ਰੋਗ ਕਾ ਅਉਖਦੁ ਨਾਮੁ ॥","lareedar":"ਸਰਬਰੋਗਕਾਅਉਖਦੁਨਾਮੁ ॥","translit":"Sarab Rog Kaa Aoukhadh Naam ||","english":"The Naam is the panacea, the remedy to cure all ills."},{"punjabi":"ਕਲਿਆਣ ਰੂਪ ਮੰਗਲ ਗੁਣ ਗਾਮ ॥","lareedar":"ਕਲਿਆਣਰੂਪਮੰਗਲਗੁਣਗਾਮ ॥","translit":"Kaliaan Roop Mangal Gun Gaam ||","english":"Singing the Glory of God is the embodiment of bliss and emancipation."},{"punjabi":"ਕਾਹੂ ਜੁਗਤਿ ਕਿਤੈ ਨ ਪਾਈਐ ਧਰਮਿ ॥","lareedar":"ਕਾਹੂਜੁਗਤਿਕਿਤੈਨਪਾਈਐਧਰਮਿ ॥","translit":"Kaahoo Jugath Kithai N Paaeeai Dhharam ||","english":"It cannot be obtained by any religious rituals."},{"punjabi":"ਨਾਨਕ ਤਿਸੁ ਮਿਲੈ ਜਿਸੁ ਲਿਖਿਆ ਧੁਰਿ ਕਰਮਿ ॥੫॥","lareedar":"ਨਾਨਕਤਿਸੁਮਿਲੈਜਿਸੁਲਿਖਿਆਧੁਰਿਕਰਮਿ ॥੫ ॥","translit":"Naanak This Milai Jis Likhiaa Dhhur Karam ||5||","english":"O Nanak, he alone obtains it, whose karma is so pre-ordained. ||5||"},{"punjabi":"ਜਿਸ ਕੈ ਮਨਿ ਪਾਰਬ੍ਰਹਮ ਕਾ ਨਿਵਾਸੁ ॥","lareedar":"ਜਿਸਕੈਮਨਿਪਾਰਬ੍ਰਹਮਕਾਨਿਵਾਸੁ ॥","translit":"Jis Kai Man Paarabreham Kaa Nivaas ||","english":"One whose mind is a home for the Supreme Lord God"},{"punjabi":"ਤਿਸ ਕਾ ਨਾਮੁ ਸਤਿ ਰਾਮਦਾਸੁ ॥","lareedar":"ਤਿਸਕਾਨਾਮੁਸਤਿਰਾਮਦਾਸੁ ॥","translit":"This Kaa Naam Sath Raamadhaas ||","english":"- his name is truly Ram Das, the Lord's servant."},{"punjabi":"ਆਤਮ ਰਾਮੁ ਤਿਸੁ ਨਦਰੀ ਆਇਆ ॥","lareedar":"ਆਤਮਰਾਮੁਤਿਸੁਨਦਰੀਆਇਆ ॥","translit":"Aatham Raam This Nadharee Aaeiaa ||","english":"He comes to have the Vision of the Lord, the Supreme Soul."},{"punjabi":"ਦਾਸ ਦਸੰਤਣ ਭਾਇ ਤਿਨਿ ਪਾਇਆ ॥","lareedar":"ਦਾਸਦਸੰਤਣਭਾਇਤਿਨਿਪਾਇਆ ॥","translit":"Dhaas Dhasanthan Bhaae Thin Paaeiaa ||","english":"Deeming himself to be the slave of the Lord's slaves, he obtains it."},{"punjabi":"ਸਦਾ ਨਿਕਟਿ ਨਿਕਟਿ ਹਰਿ ਜਾਨੁ ॥","lareedar":"ਸਦਾਨਿਕਟਿਨਿਕਟਿਹਰਿਜਾਨੁ ॥","translit":"Sadhaa Nikatt Nikatt Har Jaan ||","english":"He knows the Lord to be Ever-present, close at hand."},{"punjabi":"ਸੋ ਦਾਸੁ ਦਰਗਹ ਪਰਵਾਨੁ ॥","lareedar":"ਸੋਦਾਸੁਦਰਗਹਪਰਵਾਨੁ ॥","translit":"So Dhaas Dharageh Paravaan ||","english":"Such a servant is honored in the Court of the Lord."},{"punjabi":"ਅਪੁਨੇ ਦਾਸ ਕਉ ਆਪਿ ਕਿਰਪਾ ਕਰੈ ॥","lareedar":"ਅਪੁਨੇਦਾਸਕਉਆਪਿਕਿਰਪਾਕਰੈ ॥","translit":"Apunae Dhaas Ko Aap Kirapaa Karai ||","english":"To His servant, He Himself shows His Mercy."},{"punjabi":"ਤਿਸੁ ਦਾਸ ਕਉ ਸਭ ਸੋਝੀ ਪਰੈ ॥","lareedar":"ਤਿਸੁਦਾਸਕਉਸਭਸੋਝੀਪਰੈ ॥","translit":"This Dhaas Ko Sabh Sojhee Parai ||","english":"Such a servant understands everything."},{"punjabi":"ਸਗਲ ਸੰਗਿ ਆਤਮ ਉਦਾਸੁ ॥","lareedar":"ਸਗਲਸੰਗਿਆਤਮਉਦਾਸੁ ॥","translit":"Sagal Sang Aatham Oudhaas ||","english":"Amidst all, his soul is unattached."},{"punjabi":"ਐਸੀ ਜੁਗਤਿ ਨਾਨਕ ਰਾਮਦਾਸੁ ॥੬॥","lareedar":"ਐਸੀਜੁਗਤਿਨਾਨਕਰਾਮਦਾਸੁ ॥੬ ॥","translit":"Aisee Jugath Naanak Raamadhaas ||6||","english":"Such is the way, O Nanak, of the Lord's servant. ||6||"},{"punjabi":"ਪ੍ਰਭ ਕੀ ਆਗਿਆ ਆਤਮ ਹਿਤਾਵੈ ॥","lareedar":"ਪ੍ਰਭਕੀਆਗਿਆਆਤਮਹਿਤਾਵੈ ॥","translit":"Prabh Kee Aagiaa Aatham Hithaavai ||","english":"One who, in his soul, loves the Will of God,"},{"punjabi":"ਜੀਵਨ ਮੁਕਤਿ ਸੋਊ ਕਹਾਵੈ ॥","lareedar":"ਜੀਵਨਮੁਕਤਿਸੋਊਕਹਾਵੈ ॥","translit":"Jeevan Mukath Sooo Kehaavai ||","english":"Is said to be Jivan Mukta - liberated while yet alive."},{"punjabi":"ਤੈਸਾ ਹਰਖੁ ਤੈਸਾ ਉਸੁ ਸੋਗੁ ॥","lareedar":"ਤੈਸਾਹਰਖੁਤੈਸਾਉਸੁਸੋਗੁ ॥","translit":"Thaisaa Harakh Thaisaa Ous Sog ||","english":"As is joy, so is sorrow to him."}]},{"index":31,"ang":275,"lines":[{"punjabi":"ਸਦਾ ਅਨੰਦੁ ਤਹ ਨਹੀ ਬਿਓਗੁ ॥","lareedar":"ਸਦਾਅਨੰਦੁਤਹਨਹੀਬਿਓਗੁ ॥","translit":"Sadhaa Anandh Theh Nehee Bioug ||","english":"He is in eternal bliss, and is not separated from God."},{"punjabi":"ਤੈਸਾ ਸੁਵਰਨੁ ਤੈਸੀ ਉਸੁ ਮਾਟੀ ॥","lareedar":"ਤੈਸਾਸੁਵਰਨੁਤੈਸੀਉਸੁਮਾਟੀ ॥","translit":"Thaisaa Suvaran Thaisee Ous Maattee ||","english":"As is gold, so is dust to him."},{"punjabi":"ਤੈਸਾ ਅੰਮ੍ਰਿਤੁ ਤੈਸੀ ਬਿਖੁ ਖਾਟੀ ॥","lareedar":"ਤੈਸਾਅੰਮ੍ਰਿਤੁਤੈਸੀਬਿਖੁਖਾਟੀ ॥","translit":"Thaisaa Anmrith Thaisee Bikh Khaattee ||","english":"As is ambrosial nectar, so is bitter poison to him."},{"punjabi":"ਤੈਸਾ ਮਾਨੁ ਤੈਸਾ ਅਭਿਮਾਨੁ ॥","lareedar":"ਤੈਸਾਮਾਨੁਤੈਸਾਅਭਿਮਾਨੁ ॥","translit":"Thaisaa Maan Thaisaa Abhimaan ||","english":"As is honor, so is dishonor."},{"punjabi":"ਤੈਸਾ ਰੰਕੁ ਤੈਸਾ ਰਾਜਾਨੁ ॥","lareedar":"ਤੈਸਾਰੰਕੁਤੈਸਾਰਾਜਾਨੁ ॥","translit":"Thaisaa Rank Thaisaa Raajaan ||","english":"As is the beggar, so is the king."},{"punjabi":"ਜੋ ਵਰਤਾਏ ਸਾਈ ਜੁਗਤਿ ॥","lareedar":"ਜੋਵਰਤਾਏਸਾਈਜੁਗਤਿ ॥","translit":"Jo Varathaaeae Saaee Jugath ||","english":"Whatever God ordains, that is his way."},{"punjabi":"ਨਾਨਕ ਓਹੁ ਪੁਰਖੁ ਕਹੀਐ ਜੀਵਨ ਮੁਕਤਿ ॥੭॥","lareedar":"ਨਾਨਕਓਹੁਪੁਰਖੁਕਹੀਐਜੀਵਨਮੁਕਤਿ ॥੭ ॥","translit":"Naanak Ouhu Purakh Keheeai Jeevan Mukath ||7||","english":"O Nanak, that being is known as Jivan Mukta. ||7||"},{"punjabi":"ਪਾਰਬ੍ਰਹਮ ਕੇ ਸਗਲੇ ਠਾਉ ॥","lareedar":"ਪਾਰਬ੍ਰਹਮਕੇਸਗਲੇਠਾਉ ॥","translit":"Paarabreham Kae Sagalae Thaao ||","english":"All places belong to the Supreme Lord God."},{"punjabi":"ਜਿਤੁ ਜਿਤੁ ਘਰਿ ਰਾਖੈ ਤੈਸਾ ਤਿਨ ਨਾਉ ॥","lareedar":"ਜਿਤੁਜਿਤੁਘਰਿਰਾਖੈਤੈਸਾਤਿਨਨਾਉ ॥","translit":"Jith Jith Ghar Raakhai Thaisaa Thin Naao ||","english":"According to the homes in which they are placed, so are His creatures named."},{"punjabi":"ਆਪੇ ਕਰਨ ਕਰਾਵਨ ਜੋਗੁ ॥","lareedar":"ਆਪੇਕਰਨਕਰਾਵਨਜੋਗੁ ॥","translit":"Aapae Karan Karaavan Jog ||","english":"He Himself is the Doer, the Cause of causes."},{"punjabi":"ਪ੍ਰਭ ਭਾਵੈ ਸੋਈ ਫੁਨਿ ਹੋਗੁ ॥","lareedar":"ਪ੍ਰਭਭਾਵੈਸੋਈਫੁਨਿਹੋਗੁ ॥","translit":"Prabh Bhaavai Soee Fun Hog ||","english":"Whatever pleases God, ultimately comes to pass."},{"punjabi":"ਪਸਰਿਓ ਆਪਿ ਹੋਇ ਅਨਤ ਤਰੰਗ ॥","lareedar":"ਪਸਰਿਓਆਪਿਹੋਇਅਨਤਤਰੰਗ ॥","translit":"Pasariou Aap Hoe Anath Tharang ||","english":"He Himself is All-pervading, in endless waves."},{"punjabi":"ਲਖੇ ਨ ਜਾਹਿ ਪਾਰਬ੍ਰਹਮ ਕੇ ਰੰਗ ॥","lareedar":"ਲਖੇਨਜਾਹਿਪਾਰਬ੍ਰਹਮਕੇਰੰਗ ॥","translit":"Lakhae N Jaahi Paarabreham Kae Rang ||","english":"The playful sport of the Supreme Lord God cannot be known."},{"punjabi":"ਜੈਸੀ ਮਤਿ ਦੇਇ ਤੈਸਾ ਪਰਗਾਸ ॥","lareedar":"ਜੈਸੀਮਤਿਦੇਇਤੈਸਾਪਰਗਾਸ ॥","translit":"Jaisee Math Dhaee Thaisaa Paragaas ||","english":"As the understanding is given, so is one enlightened."},{"punjabi":"ਪਾਰਬ੍ਰਹਮੁ ਕਰਤਾ ਅਬਿਨਾਸ ॥","lareedar":"ਪਾਰਬ੍ਰਹਮੁਕਰਤਾਅਬਿਨਾਸ ॥","translit":"Paarabreham Karathaa Abinaas ||","english":"The Supreme Lord God, the Creator, is eternal and everlasting."},{"punjabi":"ਸਦਾ ਸਦਾ ਸਦਾ ਦਇਆਲ ॥","lareedar":"ਸਦਾਸਦਾਸਦਾਦਇਆਲ ॥","translit":"Sadhaa Sadhaa Sadhaa Dhaeiaal ||","english":"Forever, forever and ever, He is merciful."},{"punjabi":"ਸਿਮਰਿ ਸਿਮਰਿ ਨਾਨਕ ਭਏ ਨਿਹਾਲ ॥੮॥੯॥","lareedar":"ਸਿਮਰਿਸਿਮਰਿਨਾਨਕਭਏਨਿਹਾਲ ॥੮ ॥੯ ॥","translit":"Simar Simar Naanak Bheae Nihaal ||8||9||","english":"Remembering Him, remembering Him in meditation, O Nanak, one is blessed with ecstasy. ||8||9||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਉਸਤਤਿ ਕਰਹਿ ਅਨੇਕ ਜਨ ਅੰਤੁ ਨ ਪਾਰਾਵਾਰ ॥","lareedar":"ਉਸਤਤਿਕਰਹਿਅਨੇਕਜਨਅੰਤੁਨਪਾਰਾਵਾਰ ॥","translit":"Ousathath Karehi Anaek Jan Anth N Paaraavaar ||","english":"Many people praise the Lord. He has no end or limitation."},{"punjabi":"ਨਾਨਕ ਰਚਨਾ ਪ੍ਰਭਿ ਰਚੀ ਬਹੁ ਬਿਧਿ ਅਨਿਕ ਪ੍ਰਕਾਰ ॥੧॥","lareedar":"ਨਾਨਕਰਚਨਾਪ੍ਰਭਿਰਚੀਬਹੁਬਿਧਿਅਨਿਕਪ੍ਰਕਾਰ ॥੧ ॥","translit":"Naanak Rachanaa Prabh Rachee Bahu Bidhh Anik Prakaar ||1||","english":"O Nanak, God created the creation, with its many ways and various species. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਕਈ ਕੋਟਿ ਹੋਏ ਪੂਜਾਰੀ ॥","lareedar":"ਕਈਕੋਟਿਹੋਏਪੂਜਾਰੀ ॥","translit":"Kee Kott Hoeae Poojaaree ||","english":"Many millions are His devotees."},{"punjabi":"ਕਈ ਕੋਟਿ ਆਚਾਰ ਬਿਉਹਾਰੀ ॥","lareedar":"ਕਈਕੋਟਿਆਚਾਰਬਿਉਹਾਰੀ ॥","translit":"Kee Kott Aachaar Biouhaaree ||","english":"Many millions perform religious rituals and worldly duties."},{"punjabi":"ਕਈ ਕੋਟਿ ਭਏ ਤੀਰਥ ਵਾਸੀ ॥","lareedar":"ਕਈਕੋਟਿਭਏਤੀਰਥਵਾਸੀ ॥","translit":"Kee Kott Bheae Theerathh Vaasee ||","english":"Many millions become dwellers at sacred shrines of pilgrimage."},{"punjabi":"ਕਈ ਕੋਟਿ ਬਨ ਭ੍ਰਮਹਿ ਉਦਾਸੀ ॥","lareedar":"ਕਈਕੋਟਿਬਨਭ੍ਰਮਹਿਉਦਾਸੀ ॥","translit":"Kee Kott Ban Bhramehi Oudhaasee ||","english":"Many millions wander as renunciates in the wilderness."}]},{"index":32,"ang":275,"lines":[{"punjabi":"ਕਈ ਕੋਟਿ ਬੇਦ ਕੇ ਸ੍ਰੋਤੇ ॥","lareedar":"ਕਈਕੋਟਿਬੇਦਕੇਸ੍ਰੋਤੇ ॥","translit":"Kee Kott Baedh Kae Srothae ||","english":"Many millions listen to the Vedas."},{"punjabi":"ਕਈ ਕੋਟਿ ਤਪੀਸੁਰ ਹੋਤੇ ॥","lareedar":"ਕਈਕੋਟਿਤਪੀਸੁਰਹੋਤੇ ॥","translit":"Kee Kott Thapeesur Hothae ||","english":"Many millions become austere penitents."},{"punjabi":"ਕਈ ਕੋਟਿ ਆਤਮ ਧਿਆਨੁ ਧਾਰਹਿ ॥","lareedar":"ਕਈਕੋਟਿਆਤਮਧਿਆਨੁਧਾਰਹਿ ॥","translit":"Kee Kott Aatham Dhhiaan Dhhaarehi ||","english":"Many millions enshrine meditation within their souls."},{"punjabi":"ਕਈ ਕੋਟਿ ਕਬਿ ਕਾਬਿ ਬੀਚਾਰਹਿ ॥","lareedar":"ਕਈਕੋਟਿਕਬਿਕਾਬਿਬੀਚਾਰਹਿ ॥","translit":"Kee Kott Kab Kaab Beechaarehi ||","english":"Many millions of poets contemplate Him through poetry."},{"punjabi":"ਕਈ ਕੋਟਿ ਨਵਤਨ ਨਾਮ ਧਿਆਵਹਿ ॥","lareedar":"ਕਈਕੋਟਿਨਵਤਨਨਾਮਧਿਆਵਹਿ ॥","translit":"Kee Kott Navathan Naam Dhhiaavehi ||","english":"Many millions meditate on His eternally new Naam."},{"punjabi":"ਨਾਨਕ ਕਰਤੇ ਕਾ ਅੰਤੁ ਨ ਪਾਵਹਿ ॥੧॥","lareedar":"ਨਾਨਕਕਰਤੇਕਾਅੰਤੁਨਪਾਵਹਿ ॥੧ ॥","translit":"Naanak Karathae Kaa Anth N Paavehi ||1||","english":"O Nanak, none can find the limits of the Creator. ||1||"},{"punjabi":"ਕਈ ਕੋਟਿ ਭਏ ਅਭਿਮਾਨੀ ॥","lareedar":"ਕਈਕੋਟਿਭਏਅਭਿਮਾਨੀ ॥","translit":"Kee Kott Bheae Abhimaanee ||","english":"Many millions become self-centered."},{"punjabi":"ਕਈ ਕੋਟਿ ਅੰਧ ਅਗਿਆਨੀ ॥","lareedar":"ਕਈਕੋਟਿਅੰਧਅਗਿਆਨੀ ॥","translit":"Kee Kott Andhh Agiaanee ||","english":"Many millions are blinded by ignorance."},{"punjabi":"ਕਈ ਕੋਟਿ ਕਿਰਪਨ ਕਠੋਰ ॥","lareedar":"ਕਈਕੋਟਿਕਿਰਪਨਕਠੋਰ ॥","translit":"Kee Kott Kirapan Kathor ||","english":"Many millions are stone-hearted misers."},{"punjabi":"ਕਈ ਕੋਟਿ ਅਭਿਗ ਆਤਮ ਨਿਕੋਰ ॥","lareedar":"ਕਈਕੋਟਿਅਭਿਗਆਤਮਨਿਕੋਰ ॥","translit":"Kee Kott Abhig Aatham Nikor ||","english":"Many millions are heartless, with dry, withered souls."},{"punjabi":"ਕਈ ਕੋਟਿ ਪਰ ਦਰਬ ਕਉ ਹਿਰਹਿ ॥","lareedar":"ਕਈਕੋਟਿਪਰਦਰਬਕਉਹਿਰਹਿ ॥","translit":"Kee Kott Par Dharab Ko Hirehi ||","english":"Many millions steal the wealth of others."},{"punjabi":"ਕਈ ਕੋਟਿ ਪਰ ਦੂਖਨਾ ਕਰਹਿ ॥","lareedar":"ਕਈਕੋਟਿਪਰਦੂਖਨਾਕਰਹਿ ॥","translit":"Kee Kott Par Dhookhanaa Karehi ||","english":"Many millions slander others."},{"punjabi":"ਕਈ ਕੋਟਿ ਮਾਇਆ ਸ੍ਰਮ ਮਾਹਿ ॥","lareedar":"ਕਈਕੋਟਿਮਾਇਆਸ੍ਰਮਮਾਹਿ ॥","translit":"Kee Kott Maaeiaa Sram Maahi ||","english":"Many millions struggle in Maya."},{"punjabi":"ਕਈ ਕੋਟਿ ਪਰਦੇਸ ਭ੍ਰਮਾਹਿ ॥","lareedar":"ਕਈਕੋਟਿਪਰਦੇਸਭ੍ਰਮਾਹਿ ॥","translit":"Kee Kott Paradhaes Bhramaahi ||","english":"Many millions wander in foreign lands."},{"punjabi":"ਜਿਤੁ ਜਿਤੁ ਲਾਵਹੁ ਤਿਤੁ ਤਿਤੁ ਲਗਨਾ ॥","lareedar":"ਜਿਤੁਜਿਤੁਲਾਵਹੁਤਿਤੁਤਿਤੁਲਗਨਾ ॥","translit":"Jith Jith Laavahu Thith Thith Laganaa ||","english":"Whatever God attaches them to - with that they are engaged."},{"punjabi":"ਨਾਨਕ ਕਰਤੇ ਕੀ ਜਾਨੈ ਕਰਤਾ ਰਚਨਾ ॥੨॥","lareedar":"ਨਾਨਕਕਰਤੇਕੀਜਾਨੈਕਰਤਾਰਚਨਾ ॥੨ ॥","translit":"Naanak Karathae Kee Jaanai Karathaa Rachanaa ||2||","english":"O Nanak, the Creator alone knows the workings of His creation. ||2||"},{"punjabi":"ਕਈ ਕੋਟਿ ਸਿਧ ਜਤੀ ਜੋਗੀ ॥","lareedar":"ਕਈਕੋਟਿਸਿਧਜਤੀਜੋਗੀ ॥","translit":"Kee Kott Sidhh Jathee Jogee ||","english":"Many millions are Siddhas, celibates and Yogis."},{"punjabi":"ਕਈ ਕੋਟਿ ਰਾਜੇ ਰਸ ਭੋਗੀ ॥","lareedar":"ਕਈਕੋਟਿਰਾਜੇਰਸਭੋਗੀ ॥","translit":"Kee Kott Raajae Ras Bhogee ||","english":"Many millions are kings, enjoying worldly pleasures."},{"punjabi":"ਕਈ ਕੋਟਿ ਪੰਖੀ ਸਰਪ ਉਪਾਏ ॥","lareedar":"ਕਈਕੋਟਿਪੰਖੀਸਰਪਉਪਾਏ ॥","translit":"Kee Kott Pankhee Sarap Oupaaeae ||","english":"Many millions of birds and snakes have been created."},{"punjabi":"ਕਈ ਕੋਟਿ ਪਾਥਰ ਬਿਰਖ ਨਿਪਜਾਏ ॥","lareedar":"ਕਈਕੋਟਿਪਾਥਰਬਿਰਖਨਿਪਜਾਏ ॥","translit":"Kee Kott Paathhar Birakh Nipajaaeae ||","english":"Many millions of stones and trees have been produced."},{"punjabi":"ਕਈ ਕੋਟਿ ਪਵਣ ਪਾਣੀ ਬੈਸੰਤਰ ॥","lareedar":"ਕਈਕੋਟਿਪਵਣਪਾਣੀਬੈਸੰਤਰ ॥","translit":"Kee Kott Pavan Paanee Baisanthar ||","english":"Many millions are the winds, waters and fires."},{"punjabi":"ਕਈ ਕੋਟਿ ਦੇਸ ਭੂ ਮੰਡਲ ॥","lareedar":"ਕਈਕੋਟਿਦੇਸਭੂਮੰਡਲ ॥","translit":"Kee Kott Dhaes Bhoo Manddal ||","english":"Many millions are the countries and realms of the world."},{"punjabi":"ਕਈ ਕੋਟਿ ਸਸੀਅਰ ਸੂਰ ਨਖ੍ਯ੍ਯਤ੍ਰ ॥","lareedar":"ਕਈਕੋਟਿਸਸੀਅਰਸੂਰਨਖ੍ਯ੍ਯਤ੍ਰ ॥","translit":"Kee Kott Saseear Soor Nakhyathr ||","english":"Many millions are the moons, suns and stars."},{"punjabi":"ਕਈ ਕੋਟਿ ਦੇਵ ਦਾਨਵ ਇੰਦ੍ਰ ਸਿਰਿ ਛਤ੍ਰ ॥","lareedar":"ਕਈਕੋਟਿਦੇਵਦਾਨਵਇੰਦ੍ਰਸਿਰਿਛਤ੍ਰ ॥","translit":"Kee Kott Dhaev Dhaanav Eindhr Sir Shhathr ||","english":"Many millions are the demi-gods, demons and Indras, under their regal canopies."},{"punjabi":"ਸਗਲ ਸਮਗ੍ਰੀ ਅਪਨੈ ਸੂਤਿ ਧਾਰੈ ॥","lareedar":"ਸਗਲਸਮਗ੍ਰੀਅਪਨੈਸੂਤਿਧਾਰੈ ॥","translit":"Sagal Samagree Apanai Sooth Dhhaarai ||","english":"He has strung the entire creation upon His thread."}]},{"index":33,"ang":276,"lines":[{"punjabi":"ਨਾਨਕ ਜਿਸੁ ਜਿਸੁ ਭਾਵੈ ਤਿਸੁ ਤਿਸੁ ਨਿਸਤਾਰੈ ॥੩॥","lareedar":"ਨਾਨਕਜਿਸੁਜਿਸੁਭਾਵੈਤਿਸੁਤਿਸੁਨਿਸਤਾਰੈ ॥੩ ॥","translit":"Naanak Jis Jis Bhaavai This This Nisathaarai ||3||","english":"O Nanak, He emancipates those with whom He is pleased. ||3||"},{"punjabi":"ਕਈ ਕੋਟਿ ਰਾਜਸ ਤਾਮਸ ਸਾਤਕ ॥","lareedar":"ਕਈਕੋਟਿਰਾਜਸਤਾਮਸਸਾਤਕ ॥","translit":"Kee Kott Raajas Thaamas Saathak ||","english":"Many millions abide in heated activity, slothful darkness and peaceful light."},{"punjabi":"ਕਈ ਕੋਟਿ ਬੇਦ ਪੁਰਾਨ ਸਿਮ੍ਰਿਤਿ ਅਰੁ ਸਾਸਤ ॥","lareedar":"ਕਈਕੋਟਿਬੇਦਪੁਰਾਨਸਿਮ੍ਰਿਤਿਅਰੁਸਾਸਤ ॥","translit":"Kee Kott Baedh Puraan Simrith Ar Saasath ||","english":"Many millions are the Vedas, Puraanas, Simritees and Shaastras."},{"punjabi":"ਕਈ ਕੋਟਿ ਕੀਏ ਰਤਨ ਸਮੁਦ ॥","lareedar":"ਕਈਕੋਟਿਕੀਏਰਤਨਸਮੁਦ ॥","translit":"Kee Kott Keeeae Rathan Samudh ||","english":"Many millions are the pearls of the oceans."},{"punjabi":"ਕਈ ਕੋਟਿ ਨਾਨਾ ਪ੍ਰਕਾਰ ਜੰਤ ॥","lareedar":"ਕਈਕੋਟਿਨਾਨਾਪ੍ਰਕਾਰਜੰਤ ॥","translit":"Kee Kott Naanaa Prakaar Janth ||","english":"Many millions are the beings of so many descriptions."},{"punjabi":"ਕਈ ਕੋਟਿ ਕੀਏ ਚਿਰ ਜੀਵੇ ॥","lareedar":"ਕਈਕੋਟਿਕੀਏਚਿਰਜੀਵੇ ॥","translit":"Kee Kott Keeeae Chir Jeevae ||","english":"Many millions are made long-lived."},{"punjabi":"ਕਈ ਕੋਟਿ ਗਿਰੀ ਮੇਰ ਸੁਵਰਨ ਥੀਵੇ ॥","lareedar":"ਕਈਕੋਟਿਗਿਰੀਮੇਰਸੁਵਰਨਥੀਵੇ ॥","translit":"Kee Kott Giree Maer Suvaran Thheevae ||","english":"Many millions of hills and mountains have been made of gold."},{"punjabi":"ਕਈ ਕੋਟਿ ਜਖ੍ਯ੍ਯ ਕਿੰਨਰ ਪਿਸਾਚ ॥","lareedar":"ਕਈਕੋਟਿਜਖ੍ਯ੍ਯਕਿੰਨਰਪਿਸਾਚ ॥","translit":"Kee Kott Jakhy Kinnar Pisaach ||","english":"Many millions are the Yakhshas - the servants of the god of wealth, the Kinnars - the gods of celestial music, and the evil spirits of the Pisaach."},{"punjabi":"ਕਈ ਕੋਟਿ ਭੂਤ ਪ੍ਰੇਤ ਸੂਕਰ ਮ੍ਰਿਗਾਚ ॥","lareedar":"ਕਈਕੋਟਿਭੂਤਪ੍ਰੇਤਸੂਕਰਮ੍ਰਿਗਾਚ ॥","translit":"Kee Kott Bhooth Praeth Sookar Mrigaach ||","english":"Many millions are the evil nature-spirits, ghosts, pigs and tigers."},{"punjabi":"ਸਭ ਤੇ ਨੇਰੈ ਸਭਹੂ ਤੇ ਦੂਰਿ ॥","lareedar":"ਸਭਤੇਨੇਰੈਸਭਹੂਤੇਦੂਰਿ ॥","translit":"Sabh Thae Naerai Sabhehoo Thae Dhoor ||","english":"He is near to all, and yet far from all;"},{"punjabi":"ਨਾਨਕ ਆਪਿ ਅਲਿਪਤੁ ਰਹਿਆ ਭਰਪੂਰਿ ॥੪॥","lareedar":"ਨਾਨਕਆਪਿਅਲਿਪਤੁਰਹਿਆਭਰਪੂਰਿ ॥੪ ॥","translit":"Naanak Aap Alipath Rehiaa Bharapoor ||4||","english":"O Nanak, He Himself remains distinct, while yet pervading all. ||4||"},{"punjabi":"ਕਈ ਕੋਟਿ ਪਾਤਾਲ ਕੇ ਵਾਸੀ ॥","lareedar":"ਕਈਕੋਟਿਪਾਤਾਲਕੇਵਾਸੀ ॥","translit":"Kee Kott Paathaal Kae Vaasee ||","english":"Many millions inhabit the nether regions."},{"punjabi":"ਕਈ ਕੋਟਿ ਨਰਕ ਸੁਰਗ ਨਿਵਾਸੀ ॥","lareedar":"ਕਈਕੋਟਿਨਰਕਸੁਰਗਨਿਵਾਸੀ ॥","translit":"Kee Kott Narak Surag Nivaasee ||","english":"Many millions dwell in heaven and hell."},{"punjabi":"ਕਈ ਕੋਟਿ ਜਨਮਹਿ ਜੀਵਹਿ ਮਰਹਿ ॥","lareedar":"ਕਈਕੋਟਿਜਨਮਹਿਜੀਵਹਿਮਰਹਿ ॥","translit":"Kee Kott Janamehi Jeevehi Marehi ||","english":"Many millions are born, live and die."},{"punjabi":"ਕਈ ਕੋਟਿ ਬਹੁ ਜੋਨੀ ਫਿਰਹਿ ॥","lareedar":"ਕਈਕੋਟਿਬਹੁਜੋਨੀਫਿਰਹਿ ॥","translit":"Kee Kott Bahu Jonee Firehi ||","english":"Many millions are reincarnated, over and over again."},{"punjabi":"ਕਈ ਕੋਟਿ ਬੈਠਤ ਹੀ ਖਾਹਿ ॥","lareedar":"ਕਈਕੋਟਿਬੈਠਤਹੀਖਾਹਿ ॥","translit":"Kee Kott Baithath Hee Khaahi ||","english":"Many millions eat while sitting at ease."},{"punjabi":"ਕਈ ਕੋਟਿ ਘਾਲਹਿ ਥਕਿ ਪਾਹਿ ॥","lareedar":"ਕਈਕੋਟਿਘਾਲਹਿਥਕਿਪਾਹਿ ॥","translit":"Kee Kott Ghaalehi Thhak Paahi ||","english":"Many millions are exhausted by their labors."},{"punjabi":"ਕਈ ਕੋਟਿ ਕੀਏ ਧਨਵੰਤ ॥","lareedar":"ਕਈਕੋਟਿਕੀਏਧਨਵੰਤ ॥","translit":"Kee Kott Keeeae Dhhanavanth ||","english":"Many millions are created wealthy."},{"punjabi":"ਕਈ ਕੋਟਿ ਮਾਇਆ ਮਹਿ ਚਿੰਤ ॥","lareedar":"ਕਈਕੋਟਿਮਾਇਆਮਹਿਚਿੰਤ ॥","translit":"Kee Kott Maaeiaa Mehi Chinth ||","english":"Many millions are anxiously involved in Maya."},{"punjabi":"ਜਹ ਜਹ ਭਾਣਾ ਤਹ ਤਹ ਰਾਖੇ ॥","lareedar":"ਜਹਜਹਭਾਣਾਤਹਤਹਰਾਖੇ ॥","translit":"Jeh Jeh Bhaanaa Theh Theh Raakhae ||","english":"Wherever He wills, there He keeps us."},{"punjabi":"ਨਾਨਕ ਸਭੁ ਕਿਛੁ ਪ੍ਰਭ ਕੈ ਹਾਥੇ ॥੫॥","lareedar":"ਨਾਨਕਸਭੁਕਿਛੁਪ੍ਰਭਕੈਹਾਥੇ ॥੫ ॥","translit":"Naanak Sabh Kishh Prabh Kai Haathhae ||5||","english":"O Nanak, everything is in the Hands of God. ||5||"},{"punjabi":"ਕਈ ਕੋਟਿ ਭਏ ਬੈਰਾਗੀ ॥","lareedar":"ਕਈਕੋਟਿਭਏਬੈਰਾਗੀ ॥","translit":"Kee Kott Bheae Bairaagee ||","english":"Many millions become Bairaagees, who renounce the world."},{"punjabi":"ਰਾਮ ਨਾਮ ਸੰਗਿ ਤਿਨਿ ਲਿਵ ਲਾਗੀ ॥","lareedar":"ਰਾਮਨਾਮਸੰਗਿਤਿਨਿਲਿਵਲਾਗੀ ॥","translit":"Raam Naam Sang Thin Liv Laagee ||","english":"They have attached themselves to the Lord's Name."},{"punjabi":"ਕਈ ਕੋਟਿ ਪ੍ਰਭ ਕਉ ਖੋਜੰਤੇ ॥","lareedar":"ਕਈਕੋਟਿਪ੍ਰਭਕਉਖੋਜੰਤੇ ॥","translit":"Kee Kott Prabh Ko Khojanthae ||","english":"Many millions are searching for God."},{"punjabi":"ਆਤਮ ਮਹਿ ਪਾਰਬ੍ਰਹਮੁ ਲਹੰਤੇ ॥","lareedar":"ਆਤਮਮਹਿਪਾਰਬ੍ਰਹਮੁਲਹੰਤੇ ॥","translit":"Aatham Mehi Paarabreham Lehanthae ||","english":"Within their souls, they find the Supreme Lord God."}]},{"index":34,"ang":276,"lines":[{"punjabi":"ਕਈ ਕੋਟਿ ਦਰਸਨ ਪ੍ਰਭ ਪਿਆਸ ॥","lareedar":"ਕਈਕੋਟਿਦਰਸਨਪ੍ਰਭਪਿਆਸ ॥","translit":"Kee Kott Dharasan Prabh Piaas ||","english":"Many millions thirst for the Blessing of God's Darshan."},{"punjabi":"ਤਿਨ ਕਉ ਮਿਲਿਓ ਪ੍ਰਭੁ ਅਬਿਨਾਸ ॥","lareedar":"ਤਿਨਕਉਮਿਲਿਓਪ੍ਰਭੁਅਬਿਨਾਸ ॥","translit":"Thin Ko Miliou Prabh Abinaas ||","english":"They meet with God, the Eternal."},{"punjabi":"ਕਈ ਕੋਟਿ ਮਾਗਹਿ ਸਤਸੰਗੁ ॥","lareedar":"ਕਈਕੋਟਿਮਾਗਹਿਸਤਸੰਗੁ ॥","translit":"Kee Kott Maagehi Sathasang ||","english":"Many millions pray for the Society of the Saints."},{"punjabi":"ਪਾਰਬ੍ਰਹਮ ਤਿਨ ਲਾਗਾ ਰੰਗੁ ॥","lareedar":"ਪਾਰਬ੍ਰਹਮਤਿਨਲਾਗਾਰੰਗੁ ॥","translit":"Paarabreham Thin Laagaa Rang ||","english":"They are imbued with the Love of the Supreme Lord God."},{"punjabi":"ਜਿਨ ਕਉ ਹੋਏ ਆਪਿ ਸੁਪ੍ਰਸੰਨ ॥","lareedar":"ਜਿਨਕਉਹੋਏਆਪਿਸੁਪ੍ਰਸੰਨ ॥","translit":"Jin Ko Hoeae Aap Suprasann ||","english":"Those with whom He Himself is pleased,"},{"punjabi":"ਨਾਨਕ ਤੇ ਜਨ ਸਦਾ ਧਨਿ ਧੰਨਿ ॥੬॥","lareedar":"ਨਾਨਕਤੇਜਨਸਦਾਧਨਿਧੰਨਿ ॥੬ ॥","translit":"Naanak Thae Jan Sadhaa Dhhan Dhhann ||6||","english":"O Nanak, are blessed, forever blessed. ||6||"},{"punjabi":"ਕਈ ਕੋਟਿ ਖਾਣੀ ਅਰੁ ਖੰਡ ॥","lareedar":"ਕਈਕੋਟਿਖਾਣੀਅਰੁਖੰਡ ॥","translit":"Kee Kott Khaanee Ar Khandd ||","english":"Many millions are the fields of creation and the galaxies."},{"punjabi":"ਕਈ ਕੋਟਿ ਅਕਾਸ ਬ੍ਰਹਮੰਡ ॥","lareedar":"ਕਈਕੋਟਿਅਕਾਸਬ੍ਰਹਮੰਡ ॥","translit":"Kee Kott Akaas Brehamandd ||","english":"Many millions are the etheric skies and the solar systems."},{"punjabi":"ਕਈ ਕੋਟਿ ਹੋਏ ਅਵਤਾਰ ॥","lareedar":"ਕਈਕੋਟਿਹੋਏਅਵਤਾਰ ॥","translit":"Kee Kott Hoeae Avathaar ||","english":"Many millions are the divine incarnations."},{"punjabi":"ਕਈ ਜੁਗਤਿ ਕੀਨੋ ਬਿਸਥਾਰ ॥","lareedar":"ਕਈਜੁਗਤਿਕੀਨੋਬਿਸਥਾਰ ॥","translit":"Kee Jugath Keeno Bisathhaar ||","english":"In so many ways, He has unfolded Himself."},{"punjabi":"ਕਈ ਬਾਰ ਪਸਰਿਓ ਪਾਸਾਰ ॥","lareedar":"ਕਈਬਾਰਪਸਰਿਓਪਾਸਾਰ ॥","translit":"Kee Baar Pasariou Paasaar ||","english":"So many times, He has expanded His expansion."},{"punjabi":"ਸਦਾ ਸਦਾ ਇਕੁ ਏਕੰਕਾਰ ॥","lareedar":"ਸਦਾਸਦਾਇਕੁਏਕੰਕਾਰ ॥","translit":"Sadhaa Sadhaa Eik Eaekankaar ||","english":"Forever and ever, He is the One, the One Universal Creator."},{"punjabi":"ਕਈ ਕੋਟਿ ਕੀਨੇ ਬਹੁ ਭਾਤਿ ॥","lareedar":"ਕਈਕੋਟਿਕੀਨੇਬਹੁਭਾਤਿ ॥","translit":"Kee Kott Keenae Bahu Bhaath ||","english":"Many millions are created in various forms."},{"punjabi":"ਪ੍ਰਭ ਤੇ ਹੋਏ ਪ੍ਰਭ ਮਾਹਿ ਸਮਾਤਿ ॥","lareedar":"ਪ੍ਰਭਤੇਹੋਏਪ੍ਰਭਮਾਹਿਸਮਾਤਿ ॥","translit":"Prabh Thae Hoeae Prabh Maahi Samaath ||","english":"From God they emanate, and into God they merge once again."},{"punjabi":"ਤਾ ਕਾ ਅੰਤੁ ਨ ਜਾਨੈ ਕੋਇ ॥","lareedar":"ਤਾਕਾਅੰਤੁਨਜਾਨੈਕੋਇ ॥","translit":"Thaa Kaa Anth N Jaanai Koe ||","english":"His limits are not known to anyone."},{"punjabi":"ਆਪੇ ਆਪਿ ਨਾਨਕ ਪ੍ਰਭੁ ਸੋਇ ॥੭॥","lareedar":"ਆਪੇਆਪਿਨਾਨਕਪ੍ਰਭੁਸੋਇ ॥੭ ॥","translit":"Aapae Aap Naanak Prabh Soe ||7||","english":"Of Himself, and by Himself, O Nanak, God exists. ||7||"},{"punjabi":"ਕਈ ਕੋਟਿ ਪਾਰਬ੍ਰਹਮ ਕੇ ਦਾਸ ॥","lareedar":"ਕਈਕੋਟਿਪਾਰਬ੍ਰਹਮਕੇਦਾਸ ॥","translit":"Kee Kott Paarabreham Kae Dhaas ||","english":"Many millions are the servants of the Supreme Lord God."},{"punjabi":"ਤਿਨ ਹੋਵਤ ਆਤਮ ਪਰਗਾਸ ॥","lareedar":"ਤਿਨਹੋਵਤਆਤਮਪਰਗਾਸ ॥","translit":"Thin Hovath Aatham Paragaas ||","english":"Their souls are enlightened."},{"punjabi":"ਕਈ ਕੋਟਿ ਤਤ ਕੇ ਬੇਤੇ ॥","lareedar":"ਕਈਕੋਟਿਤਤਕੇਬੇਤੇ ॥","translit":"Kee Kott Thath Kae Baethae ||","english":"Many millions know the essence of reality."},{"punjabi":"ਸਦਾ ਨਿਹਾਰਹਿ ਏਕੋ ਨੇਤ੍ਰੇ ॥","lareedar":"ਸਦਾਨਿਹਾਰਹਿਏਕੋਨੇਤ੍ਰੇ ॥","translit":"Sadhaa Nihaarehi Eaeko Naethrae ||","english":"Their eyes gaze forever on the One alone."},{"punjabi":"ਕਈ ਕੋਟਿ ਨਾਮ ਰਸੁ ਪੀਵਹਿ ॥","lareedar":"ਕਈਕੋਟਿਨਾਮਰਸੁਪੀਵਹਿ ॥","translit":"Kee Kott Naam Ras Peevehi ||","english":"Many millions drink in the essence of the Naam."},{"punjabi":"ਅਮਰ ਭਏ ਸਦ ਸਦ ਹੀ ਜੀਵਹਿ ॥","lareedar":"ਅਮਰਭਏਸਦਸਦਹੀਜੀਵਹਿ ॥","translit":"Amar Bheae Sadh Sadh Hee Jeevehi ||","english":"They become immortal; they live forever and ever."},{"punjabi":"ਕਈ ਕੋਟਿ ਨਾਮ ਗੁਨ ਗਾਵਹਿ ॥","lareedar":"ਕਈਕੋਟਿਨਾਮਗੁਨਗਾਵਹਿ ॥","translit":"Kee Kott Naam Gun Gaavehi ||","english":"Many millions sing the Glorious Praises of the Naam."},{"punjabi":"ਆਤਮ ਰਸਿ ਸੁਖਿ ਸਹਜਿ ਸਮਾਵਹਿ ॥","lareedar":"ਆਤਮਰਸਿਸੁਖਿਸਹਜਿਸਮਾਵਹਿ ॥","translit":"Aatham Ras Sukh Sehaj Samaavehi ||","english":"They are absorbed in intuitive peace and pleasure."},{"punjabi":"ਅਪੁਨੇ ਜਨ ਕਉ ਸਾਸਿ ਸਾਸਿ ਸਮਾਰੇ ॥","lareedar":"ਅਪੁਨੇਜਨਕਉਸਾਸਿਸਾਸਿਸਮਾਰੇ ॥","translit":"Apunae Jan Ko Saas Saas Samaarae ||","english":"He remembers His servants with each and every breath."}]},{"index":35,"ang":276,"lines":[{"punjabi":"ਨਾਨਕ ਓਇ ਪਰਮੇਸੁਰ ਕੇ ਪਿਆਰੇ ॥੮॥੧੦॥","lareedar":"ਨਾਨਕਓਇਪਰਮੇਸੁਰਕੇਪਿਆਰੇ ॥੮ ॥੧੦ ॥","translit":"Naanak Oue Paramaesur Kae Piaarae ||8||10||","english":"O Nanak, they are the beloveds of the Transcendent Lord God. ||8||10||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਕਰਣ ਕਾਰਣ ਪ੍ਰਭੁ ਏਕੁ ਹੈ ਦੂਸਰ ਨਾਹੀ ਕੋਇ ॥","lareedar":"ਕਰਣਕਾਰਣਪ੍ਰਭੁਏਕੁਹੈਦੂਸਰਨਾਹੀਕੋਇ ॥","translit":"Karan Kaaran Prabh Eaek Hai Dhoosar Naahee Koe ||","english":"God alone is the Doer of deeds - there is no other at all."},{"punjabi":"ਨਾਨਕ ਤਿਸੁ ਬਲਿਹਾਰਣੈ ਜਲਿ ਥਲਿ ਮਹੀਅਲਿ ਸੋਇ ॥੧॥","lareedar":"ਨਾਨਕਤਿਸੁਬਲਿਹਾਰਣੈਜਲਿਥਲਿਮਹੀਅਲਿਸੋਇ ॥੧ ॥","translit":"Naanak This Balihaaranai Jal Thhal Meheeal Soe ||1||","english":"O Nanak, I am a sacrifice to the One, who pervades the waters, the lands, the sky and all space. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਕਰਨ ਕਰਾਵਨ ਕਰਨੈ ਜੋਗੁ ॥","lareedar":"ਕਰਨਕਰਾਵਨਕਰਨੈਜੋਗੁ ॥","translit":"Karan Karaavan Karanai Jog ||","english":"The Doer, the Cause of causes, is potent to do anything."},{"punjabi":"ਜੋ ਤਿਸੁ ਭਾਵੈ ਸੋਈ ਹੋਗੁ ॥","lareedar":"ਜੋਤਿਸੁਭਾਵੈਸੋਈਹੋਗੁ ॥","translit":"Jo This Bhaavai Soee Hog ||","english":"That which pleases Him, comes to pass."},{"punjabi":"ਖਿਨ ਮਹਿ ਥਾਪਿ ਉਥਾਪਨਹਾਰਾ ॥","lareedar":"ਖਿਨਮਹਿਥਾਪਿਉਥਾਪਨਹਾਰਾ ॥","translit":"Khin Mehi Thhaap Outhhaapanehaaraa ||","english":"In an instant, He creates and destroys."},{"punjabi":"ਅੰਤੁ ਨਹੀ ਕਿਛੁ ਪਾਰਾਵਾਰਾ ॥","lareedar":"ਅੰਤੁਨਹੀਕਿਛੁਪਾਰਾਵਾਰਾ ॥","translit":"Anth Nehee Kishh Paaraavaaraa ||","english":"He has no end or limitation."},{"punjabi":"ਹੁਕਮੇ ਧਾਰਿ ਅਧਰ ਰਹਾਵੈ ॥","lareedar":"ਹੁਕਮੇਧਾਰਿਅਧਰਰਹਾਵੈ ॥","translit":"Hukamae Dhhaar Adhhar Rehaavai ||","english":"By His Order, He established the earth, and He maintains it unsupported."},{"punjabi":"ਹੁਕਮੇ ਉਪਜੈ ਹੁਕਮਿ ਸਮਾਵੈ ॥","lareedar":"ਹੁਕਮੇਉਪਜੈਹੁਕਮਿਸਮਾਵੈ ॥","translit":"Hukamae Oupajai Hukam Samaavai ||","english":"By His Order, the world was created; by His Order, it shall merge again into Him."},{"punjabi":"ਹੁਕਮੇ ਊਚ ਨੀਚ ਬਿਉਹਾਰ ॥","lareedar":"ਹੁਕਮੇਊਚਨੀਚਬਿਉਹਾਰ ॥","translit":"Hukamae Ooch Neech Biouhaar ||","english":"By His Order, one's occupation is high or low."},{"punjabi":"ਹੁਕਮੇ ਅਨਿਕ ਰੰਗ ਪਰਕਾਰ ॥","lareedar":"ਹੁਕਮੇਅਨਿਕਰੰਗਪਰਕਾਰ ॥","translit":"Hukamae Anik Rang Parakaar ||","english":"By His Order, there are so many colors and forms."},{"punjabi":"ਕਰਿ ਕਰਿ ਦੇਖੈ ਅਪਨੀ ਵਡਿਆਈ ॥","lareedar":"ਕਰਿਕਰਿਦੇਖੈਅਪਨੀਵਡਿਆਈ ॥","translit":"Kar Kar Dhaekhai Apanee Vaddiaaee ||","english":"Having created the Creation, He beholds His own greatness."},{"punjabi":"ਨਾਨਕ ਸਭ ਮਹਿ ਰਹਿਆ ਸਮਾਈ ॥੧॥","lareedar":"ਨਾਨਕਸਭਮਹਿਰਹਿਆਸਮਾਈ ॥੧ ॥","translit":"Naanak Sabh Mehi Rehiaa Samaaee ||1||","english":"O Nanak, He is pervading in all. ||1||"},{"punjabi":"ਪ੍ਰਭ ਭਾਵੈ ਮਾਨੁਖ ਗਤਿ ਪਾਵੈ ॥","lareedar":"ਪ੍ਰਭਭਾਵੈਮਾਨੁਖਗਤਿਪਾਵੈ ॥","translit":"Prabh Bhaavai Maanukh Gath Paavai ||","english":"If it pleases God, one attains salvation."},{"punjabi":"ਪ੍ਰਭ ਭਾਵੈ ਤਾ ਪਾਥਰ ਤਰਾਵੈ ॥","lareedar":"ਪ੍ਰਭਭਾਵੈਤਾਪਾਥਰਤਰਾਵੈ ॥","translit":"Prabh Bhaavai Thaa Paathhar Tharaavai ||","english":"If it pleases God, then even stones can swim."},{"punjabi":"ਪ੍ਰਭ ਭਾਵੈ ਬਿਨੁ ਸਾਸ ਤੇ ਰਾਖੈ ॥","lareedar":"ਪ੍ਰਭਭਾਵੈਬਿਨੁਸਾਸਤੇਰਾਖੈ ॥","translit":"Prabh Bhaavai Bin Saas Thae Raakhai ||","english":"If it pleases God, the body is preserved, even without the breath of life."},{"punjabi":"ਪ੍ਰਭ ਭਾਵੈ ਤਾ ਹਰਿ ਗੁਣ ਭਾਖੈ ॥","lareedar":"ਪ੍ਰਭਭਾਵੈਤਾਹਰਿਗੁਣਭਾਖੈ ॥","translit":"Prabh Bhaavai Thaa Har Gun Bhaakhai ||","english":"If it pleases God, then one chants the Lord's Glorious Praises."},{"punjabi":"ਪ੍ਰਭ ਭਾਵੈ ਤਾ ਪਤਿਤ ਉਧਾਰੈ ॥","lareedar":"ਪ੍ਰਭਭਾਵੈਤਾਪਤਿਤਉਧਾਰੈ ॥","translit":"Prabh Bhaavai Thaa Pathith Oudhhaarai ||","english":"If it pleases God, then even sinners are saved."},{"punjabi":"ਆਪਿ ਕਰੈ ਆਪਨ ਬੀਚਾਰੈ ॥","lareedar":"ਆਪਿਕਰੈਆਪਨਬੀਚਾਰੈ ॥","translit":"Aap Karai Aapan Beechaarai ||","english":"He Himself acts, and He Himself contemplates."},{"punjabi":"ਦੁਹਾ ਸਿਰਿਆ ਕਾ ਆਪਿ ਸੁਆਮੀ ॥","lareedar":"ਦੁਹਾਸਿਰਿਆਕਾਆਪਿਸੁਆਮੀ ॥","translit":"Dhuhaa Siriaa Kaa Aap Suaamee ||","english":"He Himself is the Master of both worlds."},{"punjabi":"ਖੇਲੈ ਬਿਗਸੈ ਅੰਤਰਜਾਮੀ ॥","lareedar":"ਖੇਲੈਬਿਗਸੈਅੰਤਰਜਾਮੀ ॥","translit":"Khaelai Bigasai Antharajaamee ||","english":"He plays and He enjoys; He is the Inner-knower, the Searcher of hearts."},{"punjabi":"ਜੋ ਭਾਵੈ ਸੋ ਕਾਰ ਕਰਾਵੈ ॥","lareedar":"ਜੋਭਾਵੈਸੋਕਾਰਕਰਾਵੈ ॥","translit":"Jo Bhaavai So Kaar Karaavai ||","english":"As He wills, He causes actions to be done."},{"punjabi":"ਨਾਨਕ ਦ੍ਰਿਸਟੀ ਅਵਰੁ ਨ ਆਵੈ ॥੨॥","lareedar":"ਨਾਨਕਦ੍ਰਿਸਟੀਅਵਰੁਨਆਵੈ ॥੨ ॥","translit":"Naanak Dhrisattee Avar N Aavai ||2||","english":"Nanak sees no other than Him. ||2||"}]},{"index":36,"ang":277,"lines":[{"punjabi":"ਕਹੁ ਮਾਨੁਖ ਤੇ ਕਿਆ ਹੋਇ ਆਵੈ ॥","lareedar":"ਕਹੁਮਾਨੁਖਤੇਕਿਆਹੋਇਆਵੈ ॥","translit":"Kahu Maanukh Thae Kiaa Hoe Aavai ||","english":"Tell me - what can a mere mortal do?"},{"punjabi":"ਜੋ ਤਿਸੁ ਭਾਵੈ ਸੋਈ ਕਰਾਵੈ ॥","lareedar":"ਜੋਤਿਸੁਭਾਵੈਸੋਈਕਰਾਵੈ ॥","translit":"Jo This Bhaavai Soee Karaavai ||","english":"Whatever pleases God is what He causes us to do."},{"punjabi":"ਇਸ ਕੈ ਹਾਥਿ ਹੋਇ ਤਾ ਸਭੁ ਕਿਛੁ ਲੇਇ ॥","lareedar":"ਇਸਕੈਹਾਥਿਹੋਇਤਾਸਭੁਕਿਛੁਲੇਇ ॥","translit":"Eis Kai Haathh Hoe Thaa Sabh Kishh Laee ||","english":"If it were in our hands, we would grab up everything."},{"punjabi":"ਜੋ ਤਿਸੁ ਭਾਵੈ ਸੋਈ ਕਰੇਇ ॥","lareedar":"ਜੋਤਿਸੁਭਾਵੈਸੋਈਕਰੇਇ ॥","translit":"Jo This Bhaavai Soee Karaee ||","english":"Whatever pleases God - that is what He does."},{"punjabi":"ਅਨਜਾਨਤ ਬਿਖਿਆ ਮਹਿ ਰਚੈ ॥","lareedar":"ਅਨਜਾਨਤਬਿਖਿਆਮਹਿਰਚੈ ॥","translit":"Anajaanath Bikhiaa Mehi Rachai ||","english":"Through ignorance, people are engrossed in corruption."},{"punjabi":"ਜੇ ਜਾਨਤ ਆਪਨ ਆਪ ਬਚੈ ॥","lareedar":"ਜੇਜਾਨਤਆਪਨਆਪਬਚੈ ॥","translit":"Jae Jaanath Aapan Aap Bachai ||","english":"If they knew better, they would save themselves."},{"punjabi":"ਭਰਮੇ ਭੂਲਾ ਦਹ ਦਿਸਿ ਧਾਵੈ ॥","lareedar":"ਭਰਮੇਭੂਲਾਦਹਦਿਸਿਧਾਵੈ ॥","translit":"Bharamae Bhoolaa Dheh Dhis Dhhaavai ||","english":"Deluded by doubt, they wander around in the ten directions."},{"punjabi":"ਨਿਮਖ ਮਾਹਿ ਚਾਰਿ ਕੁੰਟ ਫਿਰਿ ਆਵੈ ॥","lareedar":"ਨਿਮਖਮਾਹਿਚਾਰਿਕੁੰਟਫਿਰਿਆਵੈ ॥","translit":"Nimakh Maahi Chaar Kuntt Fir Aavai ||","english":"In an instant, their minds go around the four corners of the world and come back again."},{"punjabi":"ਕਰਿ ਕਿਰਪਾ ਜਿਸੁ ਅਪਨੀ ਭਗਤਿ ਦੇਇ ॥","lareedar":"ਕਰਿਕਿਰਪਾਜਿਸੁਅਪਨੀਭਗਤਿਦੇਇ ॥","translit":"Kar Kirapaa Jis Apanee Bhagath Dhaee ||","english":"Those whom the Lord mercifully blesses with His devotional worship"},{"punjabi":"ਨਾਨਕ ਤੇ ਜਨ ਨਾਮਿ ਮਿਲੇਇ ॥੩॥","lareedar":"ਨਾਨਕਤੇਜਨਨਾਮਿਮਿਲੇਇ ॥੩ ॥","translit":"Naanak Thae Jan Naam Milaee ||3||","english":"- O Nanak, they are absorbed into the Naam. ||3||"},{"punjabi":"ਖਿਨ ਮਹਿ ਨੀਚ ਕੀਟ ਕਉ ਰਾਜ ॥","lareedar":"ਖਿਨਮਹਿਨੀਚਕੀਟਕਉਰਾਜ ॥","translit":"Khin Mehi Neech Keett Ko Raaj ||","english":"In an instant, the lowly worm is transformed into a king."},{"punjabi":"ਪਾਰਬ੍ਰਹਮ ਗਰੀਬ ਨਿਵਾਜ ॥","lareedar":"ਪਾਰਬ੍ਰਹਮਗਰੀਬਨਿਵਾਜ ॥","translit":"Paarabreham Gareeb Nivaaj ||","english":"The Supreme Lord God is the Protector of the humble."},{"punjabi":"ਜਾ ਕਾ ਦ੍ਰਿਸਟਿ ਕਛੂ ਨ ਆਵੈ ॥","lareedar":"ਜਾਕਾਦ੍ਰਿਸਟਿਕਛੂਨਆਵੈ ॥","translit":"Jaa Kaa Dhrisatt Kashhoo N Aavai ||","english":"Even one who has never been seen at all,"},{"punjabi":"ਤਿਸੁ ਤਤਕਾਲ ਦਹ ਦਿਸ ਪ੍ਰਗਟਾਵੈ ॥","lareedar":"ਤਿਸੁਤਤਕਾਲਦਹਦਿਸਪ੍ਰਗਟਾਵੈ ॥","translit":"This Thathakaal Dheh Dhis Pragattaavai ||","english":"Becomes instantly famous in the ten directions."},{"punjabi":"ਜਾ ਕਉ ਅਪੁਨੀ ਕਰੈ ਬਖਸੀਸ ॥","lareedar":"ਜਾਕਉਅਪੁਨੀਕਰੈਬਖਸੀਸ ॥","translit":"Jaa Ko Apunee Karai Bakhasees ||","english":"And that one upon whom He bestows His blessings"},{"punjabi":"ਤਾ ਕਾ ਲੇਖਾ ਨ ਗਨੈ ਜਗਦੀਸ ॥","lareedar":"ਤਾਕਾਲੇਖਾਨਗਨੈਜਗਦੀਸ ॥","translit":"Thaa Kaa Laekhaa N Ganai Jagadhees ||","english":"The Lord of the world does not hold him to his account."},{"punjabi":"ਜੀਉ ਪਿੰਡੁ ਸਭ ਤਿਸ ਕੀ ਰਾਸਿ ॥","lareedar":"ਜੀਉਪਿੰਡੁਸਭਤਿਸਕੀਰਾਸਿ ॥","translit":"Jeeo Pindd Sabh This Kee Raas ||","english":"Soul and body are all His property."},{"punjabi":"ਘਟਿ ਘਟਿ ਪੂਰਨ ਬ੍ਰਹਮ ਪ੍ਰਗਾਸ ॥","lareedar":"ਘਟਿਘਟਿਪੂਰਨਬ੍ਰਹਮਪ੍ਰਗਾਸ ॥","translit":"Ghatt Ghatt Pooran Breham Pragaas ||","english":"Each and every heart is illuminated by the Perfect Lord God."},{"punjabi":"ਅਪਨੀ ਬਣਤ ਆਪਿ ਬਨਾਈ ॥","lareedar":"ਅਪਨੀਬਣਤਆਪਿਬਨਾਈ ॥","translit":"Apanee Banath Aap Banaaee ||","english":"He Himself fashioned His own handiwork."},{"punjabi":"ਨਾਨਕ ਜੀਵੈ ਦੇਖਿ ਬਡਾਈ ॥੪॥","lareedar":"ਨਾਨਕਜੀਵੈਦੇਖਿਬਡਾਈ ॥੪ ॥","translit":"Naanak Jeevai Dhaekh Baddaaee ||4||","english":"Nanak lives by beholding His greatness. ||4||"},{"punjabi":"ਇਸ ਕਾ ਬਲੁ ਨਾਹੀ ਇਸੁ ਹਾਥ ॥","lareedar":"ਇਸਕਾਬਲੁਨਾਹੀਇਸੁਹਾਥ ॥","translit":"Eis Kaa Bal Naahee Eis Haathh ||","english":"There is no power in the hands of mortal beings;"},{"punjabi":"ਕਰਨ ਕਰਾਵਨ ਸਰਬ ਕੋ ਨਾਥ ॥","lareedar":"ਕਰਨਕਰਾਵਨਸਰਬਕੋਨਾਥ ॥","translit":"Karan Karaavan Sarab Ko Naathh ||","english":"The Doer, the Cause of causes is the Lord of all."},{"punjabi":"ਆਗਿਆਕਾਰੀ ਬਪੁਰਾ ਜੀਉ ॥","lareedar":"ਆਗਿਆਕਾਰੀਬਪੁਰਾਜੀਉ ॥","translit":"Aagiaakaaree Bapuraa Jeeo ||","english":"The helpless beings are subject to His Command."},{"punjabi":"ਜੋ ਤਿਸੁ ਭਾਵੈ ਸੋਈ ਫੁਨਿ ਥੀਉ ॥","lareedar":"ਜੋਤਿਸੁਭਾਵੈਸੋਈਫੁਨਿਥੀਉ ॥","translit":"Jo This Bhaavai Soee Fun Thheeo ||","english":"That which pleases Him, ultimately comes to pass."},{"punjabi":"ਕਬਹੂ ਊਚ ਨੀਚ ਮਹਿ ਬਸੈ ॥","lareedar":"ਕਬਹੂਊਚਨੀਚਮਹਿਬਸੈ ॥","translit":"Kabehoo Ooch Neech Mehi Basai ||","english":"Sometimes, they abide in exaltation; sometimes, they are depressed."}]},{"index":37,"ang":277,"lines":[{"punjabi":"ਕਬਹੂ ਸੋਗ ਹਰਖ ਰੰਗਿ ਹਸੈ ॥","lareedar":"ਕਬਹੂਸੋਗਹਰਖਰੰਗਿਹਸੈ ॥","translit":"Kabehoo Sog Harakh Rang Hasai ||","english":"Sometimes, they are sad, and sometimes they laugh with joy and delight."},{"punjabi":"ਕਬਹੂ ਨਿੰਦ ਚਿੰਦ ਬਿਉਹਾਰ ॥","lareedar":"ਕਬਹੂਨਿੰਦਚਿੰਦਬਿਉਹਾਰ ॥","translit":"Kabehoo Nindh Chindh Biouhaar ||","english":"Sometimes, they are occupied with slander and anxiety."},{"punjabi":"ਕਬਹੂ ਊਭ ਅਕਾਸ ਪਇਆਲ ॥","lareedar":"ਕਬਹੂਊਭਅਕਾਸਪਇਆਲ ॥","translit":"Kabehoo Oobh Akaas Paeiaal ||","english":"Sometimes, they are high in the Akaashic Ethers, sometimes in the nether regions of the underworld."},{"punjabi":"ਕਬਹੂ ਬੇਤਾ ਬ੍ਰਹਮ ਬੀਚਾਰ ॥","lareedar":"ਕਬਹੂਬੇਤਾਬ੍ਰਹਮਬੀਚਾਰ ॥","translit":"Kabehoo Baethaa Breham Beechaar ||","english":"Sometimes, they know the contemplation of God."},{"punjabi":"ਨਾਨਕ ਆਪਿ ਮਿਲਾਵਣਹਾਰ ॥੫॥","lareedar":"ਨਾਨਕਆਪਿਮਿਲਾਵਣਹਾਰ ॥੫ ॥","translit":"Naanak Aap Milaavanehaar ||5||","english":"O Nanak, God Himself unites them with Himself. ||5||"},{"punjabi":"ਕਬਹੂ ਨਿਰਤਿ ਕਰੈ ਬਹੁ ਭਾਤਿ ॥","lareedar":"ਕਬਹੂਨਿਰਤਿਕਰੈਬਹੁਭਾਤਿ ॥","translit":"Kabehoo Nirath Karai Bahu Bhaath ||","english":"Sometimes, they dance in various ways."},{"punjabi":"ਕਬਹੂ ਸੋਇ ਰਹੈ ਦਿਨੁ ਰਾਤਿ ॥","lareedar":"ਕਬਹੂਸੋਇਰਹੈਦਿਨੁਰਾਤਿ ॥","translit":"Kabehoo Soe Rehai Dhin Raath ||","english":"Sometimes, they remain asleep day and night."},{"punjabi":"ਕਬਹੂ ਮਹਾ ਕ੍ਰੋਧ ਬਿਕਰਾਲ ॥","lareedar":"ਕਬਹੂਮਹਾਕ੍ਰੋਧਬਿਕਰਾਲ ॥","translit":"Kabehoo Mehaa Krodhh Bikaraal ||","english":"Sometimes, they are awesome, in terrible rage."},{"punjabi":"ਕਬਹੂੰ ਸਰਬ ਕੀ ਹੋਤ ਰਵਾਲ ॥","lareedar":"ਕਬਹੂੰਸਰਬਕੀਹੋਤਰਵਾਲ ॥","translit":"Kabehoon Sarab Kee Hoth Ravaal ||","english":"Sometimes, they are the dust of the feet of all."},{"punjabi":"ਕਬਹੂ ਹੋਇ ਬਹੈ ਬਡ ਰਾਜਾ ॥","lareedar":"ਕਬਹੂਹੋਇਬਹੈਬਡਰਾਜਾ ॥","translit":"Kabehoo Hoe Behai Badd Raajaa ||","english":"Sometimes, they sit as great kings."},{"punjabi":"ਕਬਹੁ ਭੇਖਾਰੀ ਨੀਚ ਕਾ ਸਾਜਾ ॥","lareedar":"ਕਬਹੁਭੇਖਾਰੀਨੀਚਕਾਸਾਜਾ ॥","translit":"Kabahu Bhaekhaaree Neech Kaa Saajaa ||","english":"Sometimes, they wear the coat of a lowly beggar."},{"punjabi":"ਕਬਹੂ ਅਪਕੀਰਤਿ ਮਹਿ ਆਵੈ ॥","lareedar":"ਕਬਹੂਅਪਕੀਰਤਿਮਹਿਆਵੈ ॥","translit":"Kabehoo Apakeerath Mehi Aavai ||","english":"Sometimes, they come to have evil reputations."},{"punjabi":"ਕਬਹੂ ਭਲਾ ਭਲਾ ਕਹਾਵੈ ॥","lareedar":"ਕਬਹੂਭਲਾਭਲਾਕਹਾਵੈ ॥","translit":"Kabehoo Bhalaa Bhalaa Kehaavai ||","english":"Sometimes, they are known as very, very good."},{"punjabi":"ਜਿਉ ਪ੍ਰਭੁ ਰਾਖੈ ਤਿਵ ਹੀ ਰਹੈ ॥","lareedar":"ਜਿਉਪ੍ਰਭੁਰਾਖੈਤਿਵਹੀਰਹੈ ॥","translit":"Jio Prabh Raakhai Thiv Hee Rehai ||","english":"As God keeps them, so they remain."},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਨਾਨਕ ਸਚੁ ਕਹੈ ॥੬॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਨਾਨਕਸਚੁਕਹੈ ॥੬ ॥","translit":"Gur Prasaadh Naanak Sach Kehai ||6||","english":"By Guru's Grace, O Nanak, the Truth is told. ||6||"},{"punjabi":"ਕਬਹੂ ਹੋਇ ਪੰਡਿਤੁ ਕਰੇ ਬਖ੍ਯ੍ਯਾਨੁ ॥","lareedar":"ਕਬਹੂਹੋਇਪੰਡਿਤੁਕਰੇਬਖ੍ਯ੍ਯਾਨੁ ॥","translit":"Kabehoo Hoe Panddith Karae Bakhyaan ||","english":"Sometimes, as scholars, they deliver lectures."},{"punjabi":"ਕਬਹੂ ਮੋਨਿਧਾਰੀ ਲਾਵੈ ਧਿਆਨੁ ॥","lareedar":"ਕਬਹੂਮੋਨਿਧਾਰੀਲਾਵੈਧਿਆਨੁ ॥","translit":"Kabehoo Monidhhaaree Laavai Dhhiaan ||","english":"Sometimes, they hold to silence in deep meditation."},{"punjabi":"ਕਬਹੂ ਤਟ ਤੀਰਥ ਇਸਨਾਨ ॥","lareedar":"ਕਬਹੂਤਟਤੀਰਥਇਸਨਾਨ ॥","translit":"Kabehoo Thatt Theerathh Eisanaan ||","english":"Sometimes, they take cleansing baths at places of pilgrimage."},{"punjabi":"ਕਬਹੂ ਸਿਧ ਸਾਧਿਕ ਮੁਖਿ ਗਿਆਨ ॥","lareedar":"ਕਬਹੂਸਿਧਸਾਧਿਕਮੁਖਿਗਿਆਨ ॥","translit":"Kabehoo Sidhh Saadhhik Mukh Giaan ||","english":"Sometimes, as Siddhas or seekers, they impart spiritual wisdom."},{"punjabi":"ਕਬਹੂ ਕੀਟ ਹਸਤਿ ਪਤੰਗ ਹੋਇ ਜੀਆ ॥","lareedar":"ਕਬਹੂਕੀਟਹਸਤਿਪਤੰਗਹੋਇਜੀਆ ॥","translit":"Kabehoo Keett Hasath Pathang Hoe Jeeaa ||","english":"Sometimes, they becomes worms, elephants, or moths."},{"punjabi":"ਅਨਿਕ ਜੋਨਿ ਭਰਮੈ ਭਰਮੀਆ ॥","lareedar":"ਅਨਿਕਜੋਨਿਭਰਮੈਭਰਮੀਆ ॥","translit":"Anik Jon Bharamai Bharameeaa ||","english":"They may wander and roam through countless incarnations."},{"punjabi":"ਨਾਨਾ ਰੂਪ ਜਿਉ ਸ੍ਵਾਗੀ ਦਿਖਾਵੈ ॥","lareedar":"ਨਾਨਾਰੂਪਜਿਉਸ੍ਵਾਗੀਦਿਖਾਵੈ ॥","translit":"Naanaa Roop Jio Svaagee Dhikhaavai ||","english":"In various costumes, like actors, they appear."},{"punjabi":"ਜਿਉ ਪ੍ਰਭ ਭਾਵੈ ਤਿਵੈ ਨਚਾਵੈ ॥","lareedar":"ਜਿਉਪ੍ਰਭਭਾਵੈਤਿਵੈਨਚਾਵੈ ॥","translit":"Jio Prabh Bhaavai Thivai Nachaavai ||","english":"As it pleases God, they dance."},{"punjabi":"ਜੋ ਤਿਸੁ ਭਾਵੈ ਸੋਈ ਹੋਇ ॥","lareedar":"ਜੋਤਿਸੁਭਾਵੈਸੋਈਹੋਇ ॥","translit":"Jo This Bhaavai Soee Hoe ||","english":"Whatever pleases Him, comes to pass."},{"punjabi":"ਨਾਨਕ ਦੂਜਾ ਅਵਰੁ ਨ ਕੋਇ ॥੭॥","lareedar":"ਨਾਨਕਦੂਜਾਅਵਰੁਨਕੋਇ ॥੭ ॥","translit":"Naanak Dhoojaa Avar N Koe ||7||","english":"O Nanak, there is no other at all. ||7||"}]},{"index":38,"ang":278,"lines":[{"punjabi":"ਕਬਹੂ ਸਾਧਸੰਗਤਿ ਇਹੁ ਪਾਵੈ ॥","lareedar":"ਕਬਹੂਸਾਧਸੰਗਤਿਇਹੁਪਾਵੈ ॥","translit":"Kabehoo Saadhhasangath Eihu Paavai ||","english":"Sometimes, this being attains the Company of the Holy."},{"punjabi":"ਉਸੁ ਅਸਥਾਨ ਤੇ ਬਹੁਰਿ ਨ ਆਵੈ ॥","lareedar":"ਉਸੁਅਸਥਾਨਤੇਬਹੁਰਿਨਆਵੈ ॥","translit":"Ous Asathhaan Thae Bahur N Aavai ||","english":"From that place, he does not have to come back again."},{"punjabi":"ਅੰਤਰਿ ਹੋਇ ਗਿਆਨ ਪਰਗਾਸੁ ॥","lareedar":"ਅੰਤਰਿਹੋਇਗਿਆਨਪਰਗਾਸੁ ॥","translit":"Anthar Hoe Giaan Paragaas ||","english":"The light of spiritual wisdom dawns within."},{"punjabi":"ਉਸੁ ਅਸਥਾਨ ਕਾ ਨਹੀ ਬਿਨਾਸੁ ॥","lareedar":"ਉਸੁਅਸਥਾਨਕਾਨਹੀਬਿਨਾਸੁ ॥","translit":"Ous Asathhaan Kaa Nehee Binaas ||","english":"That place does not perish."},{"punjabi":"ਮਨ ਤਨ ਨਾਮਿ ਰਤੇ ਇਕ ਰੰਗਿ ॥","lareedar":"ਮਨਤਨਨਾਮਿਰਤੇਇਕਰੰਗਿ ॥","translit":"Man Than Naam Rathae Eik Rang ||","english":"The mind and body are imbued with the Love of the Naam, the Name of the One Lord."},{"punjabi":"ਸਦਾ ਬਸਹਿ ਪਾਰਬ੍ਰਹਮ ਕੈ ਸੰਗਿ ॥","lareedar":"ਸਦਾਬਸਹਿਪਾਰਬ੍ਰਹਮਕੈਸੰਗਿ ॥","translit":"Sadhaa Basehi Paarabreham Kai Sang ||","english":"He dwells forever with the Supreme Lord God."},{"punjabi":"ਜਿਉ ਜਲ ਮਹਿ ਜਲੁ ਆਇ ਖਟਾਨਾ ॥","lareedar":"ਜਿਉਜਲਮਹਿਜਲੁਆਇਖਟਾਨਾ ॥","translit":"Jio Jal Mehi Jal Aae Khattaanaa ||","english":"As water comes to blend with water,"},{"punjabi":"ਤਿਉ ਜੋਤੀ ਸੰਗਿ ਜੋਤਿ ਸਮਾਨਾ ॥","lareedar":"ਤਿਉਜੋਤੀਸੰਗਿਜੋਤਿਸਮਾਨਾ ॥","translit":"Thio Jothee Sang Joth Samaanaa ||","english":"His light blends into the Light."},{"punjabi":"ਮਿਟਿ ਗਏ ਗਵਨ ਪਾਏ ਬਿਸ੍ਰਾਮ ॥","lareedar":"ਮਿਟਿਗਏਗਵਨਪਾਏਬਿਸ੍ਰਾਮ ॥","translit":"Mitt Geae Gavan Paaeae Bisraam ||","english":"Reincarnation is ended, and eternal peace is found."},{"punjabi":"ਨਾਨਕ ਪ੍ਰਭ ਕੈ ਸਦ ਕੁਰਬਾਨ ॥੮॥੧੧॥","lareedar":"ਨਾਨਕਪ੍ਰਭਕੈਸਦਕੁਰਬਾਨ ॥੮ ॥੧੧ ॥","translit":"Naanak Prabh Kai Sadh Kurabaan ||8||11||","english":"Nanak is forever a sacrifice to God. ||8||11||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਸੁਖੀ ਬਸੈ ਮਸਕੀਨੀਆ ਆਪੁ ਨਿਵਾਰਿ ਤਲੇ ॥","lareedar":"ਸੁਖੀਬਸੈਮਸਕੀਨੀਆਆਪੁਨਿਵਾਰਿਤਲੇ ॥","translit":"Sukhee Basai Masakeeneeaa Aap Nivaar Thalae ||","english":"The humble beings abide in peace; subduing egotism, they are meek."},{"punjabi":"ਬਡੇ ਬਡੇ ਅਹੰਕਾਰੀਆ ਨਾਨਕ ਗਰਬਿ ਗਲੇ ॥੧॥","lareedar":"ਬਡੇਬਡੇਅਹੰਕਾਰੀਆਨਾਨਕਗਰਬਿਗਲੇ ॥੧ ॥","translit":"Baddae Baddae Ahankaareeaa Naanak Garab Galae ||1||","english":"The very proud and arrogant persons, O Nanak, are consumed by their own pride. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਜਿਸ ਕੈ ਅੰਤਰਿ ਰਾਜ ਅਭਿਮਾਨੁ ॥","lareedar":"ਜਿਸਕੈਅੰਤਰਿਰਾਜਅਭਿਮਾਨੁ ॥","translit":"Jis Kai Anthar Raaj Abhimaan ||","english":"One who has the pride of power within,"},{"punjabi":"ਸੋ ਨਰਕਪਾਤੀ ਹੋਵਤ ਸੁਆਨੁ ॥","lareedar":"ਸੋਨਰਕਪਾਤੀਹੋਵਤਸੁਆਨੁ ॥","translit":"So Narakapaathee Hovath Suaan ||","english":"Shall dwell in hell, and become a dog."},{"punjabi":"ਜੋ ਜਾਨੈ ਮੈ ਜੋਬਨਵੰਤੁ ॥","lareedar":"ਜੋਜਾਨੈਮੈਜੋਬਨਵੰਤੁ ॥","translit":"Jo Jaanai Mai Jobanavanth ||","english":"One who deems himself to have the beauty of youth,"},{"punjabi":"ਸੋ ਹੋਵਤ ਬਿਸਟਾ ਕਾ ਜੰਤੁ ॥","lareedar":"ਸੋਹੋਵਤਬਿਸਟਾਕਾਜੰਤੁ ॥","translit":"So Hovath Bisattaa Kaa Janth ||","english":"Shall become a maggot in manure."},{"punjabi":"ਆਪਸ ਕਉ ਕਰਮਵੰਤੁ ਕਹਾਵੈ ॥","lareedar":"ਆਪਸਕਉਕਰਮਵੰਤੁਕਹਾਵੈ ॥","translit":"Aapas Ko Karamavanth Kehaavai ||","english":"One who claims to act virtuously,"},{"punjabi":"ਜਨਮਿ ਮਰੈ ਬਹੁ ਜੋਨਿ ਭ੍ਰਮਾਵੈ ॥","lareedar":"ਜਨਮਿਮਰੈਬਹੁਜੋਨਿਭ੍ਰਮਾਵੈ ॥","translit":"Janam Marai Bahu Jon Bhramaavai ||","english":"Shall live and die, wandering through countless reincarnations."},{"punjabi":"ਧਨ ਭੂਮਿ ਕਾ ਜੋ ਕਰੈ ਗੁਮਾਨੁ ॥","lareedar":"ਧਨਭੂਮਿਕਾਜੋਕਰੈਗੁਮਾਨੁ ॥","translit":"Dhhan Bhoom Kaa Jo Karai Gumaan ||","english":"One who takes pride in wealth and lands"},{"punjabi":"ਸੋ ਮੂਰਖੁ ਅੰਧਾ ਅਗਿਆਨੁ ॥","lareedar":"ਸੋਮੂਰਖੁਅੰਧਾਅਗਿਆਨੁ ॥","translit":"So Moorakh Andhhaa Agiaan ||","english":"Is a fool, blind and ignorant."},{"punjabi":"ਕਰਿ ਕਿਰਪਾ ਜਿਸ ਕੈ ਹਿਰਦੈ ਗਰੀਬੀ ਬਸਾਵੈ ॥","lareedar":"ਕਰਿਕਿਰਪਾਜਿਸਕੈਹਿਰਦੈਗਰੀਬੀਬਸਾਵੈ ॥","translit":"Kar Kirapaa Jis Kai Hiradhai Gareebee Basaavai ||","english":"One whose heart is mercifully blessed with abiding humility,"},{"punjabi":"ਨਾਨਕ ਈਹਾ ਮੁਕਤੁ ਆਗੈ ਸੁਖੁ ਪਾਵੈ ॥੧॥","lareedar":"ਨਾਨਕਈਹਾਮੁਕਤੁਆਗੈਸੁਖੁਪਾਵੈ ॥੧ ॥","translit":"Naanak Eehaa Mukath Aagai Sukh Paavai ||1||","english":"O Nanak, is liberated here, and obtains peace hereafter. ||1||"},{"punjabi":"ਧਨਵੰਤਾ ਹੋਇ ਕਰਿ ਗਰਬਾਵੈ ॥","lareedar":"ਧਨਵੰਤਾਹੋਇਕਰਿਗਰਬਾਵੈ ॥","translit":"Dhhanavanthaa Hoe Kar Garabaavai ||","english":"One who becomes wealthy and takes pride in it"}]},{"index":39,"ang":278,"lines":[{"punjabi":"ਤ੍ਰਿਣ ਸਮਾਨਿ ਕਛੁ ਸੰਗਿ ਨ ਜਾਵੈ ॥","lareedar":"ਤ੍ਰਿਣਸਮਾਨਿਕਛੁਸੰਗਿਨਜਾਵੈ ॥","translit":"Thrin Samaan Kashh Sang N Jaavai ||","english":"Not even a piece of straw shall go along with him."},{"punjabi":"ਬਹੁ ਲਸਕਰ ਮਾਨੁਖ ਊਪਰਿ ਕਰੇ ਆਸ ॥","lareedar":"ਬਹੁਲਸਕਰਮਾਨੁਖਊਪਰਿਕਰੇਆਸ ॥","translit":"Bahu Lasakar Maanukh Oopar Karae Aas ||","english":"He may place his hopes on a large army of men,"},{"punjabi":"ਪਲ ਭੀਤਰਿ ਤਾ ਕਾ ਹੋਇ ਬਿਨਾਸ ॥","lareedar":"ਪਲਭੀਤਰਿਤਾਕਾਹੋਇਬਿਨਾਸ ॥","translit":"Pal Bheethar Thaa Kaa Hoe Binaas ||","english":"But he shall vanish in an instant."},{"punjabi":"ਸਭ ਤੇ ਆਪ ਜਾਨੈ ਬਲਵੰਤੁ ॥","lareedar":"ਸਭਤੇਆਪਜਾਨੈਬਲਵੰਤੁ ॥","translit":"Sabh Thae Aap Jaanai Balavanth ||","english":"One who deems himself to be the strongest of all,"},{"punjabi":"ਖਿਨ ਮਹਿ ਹੋਇ ਜਾਇ ਭਸਮੰਤੁ ॥","lareedar":"ਖਿਨਮਹਿਹੋਇਜਾਇਭਸਮੰਤੁ ॥","translit":"Khin Mehi Hoe Jaae Bhasamanth ||","english":"In an instant, shall be reduced to ashes."},{"punjabi":"ਕਿਸੈ ਨ ਬਦੈ ਆਪਿ ਅਹੰਕਾਰੀ ॥","lareedar":"ਕਿਸੈਨਬਦੈਆਪਿਅਹੰਕਾਰੀ ॥","translit":"Kisai N Badhai Aap Ahankaaree ||","english":"One who thinks of no one else except his own prideful self"},{"punjabi":"ਧਰਮ ਰਾਇ ਤਿਸੁ ਕਰੇ ਖੁਆਰੀ ॥","lareedar":"ਧਰਮਰਾਇਤਿਸੁਕਰੇਖੁਆਰੀ ॥","translit":"Dhharam Raae This Karae Khuaaree ||","english":"The Righteous Judge of Dharma shall expose his disgrace."},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਜਾ ਕਾ ਮਿਟੈ ਅਭਿਮਾਨੁ ॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਜਾਕਾਮਿਟੈਅਭਿਮਾਨੁ ॥","translit":"Gur Prasaadh Jaa Kaa Mittai Abhimaan ||","english":"One who, by Guru's Grace, eliminates his ego,"},{"punjabi":"ਸੋ ਜਨੁ ਨਾਨਕ ਦਰਗਹ ਪਰਵਾਨੁ ॥੨॥","lareedar":"ਸੋਜਨੁਨਾਨਕਦਰਗਹਪਰਵਾਨੁ ॥੨ ॥","translit":"So Jan Naanak Dharageh Paravaan ||2||","english":"O Nanak, becomes acceptable in the Court of the Lord. ||2||"},{"punjabi":"ਕੋਟਿ ਕਰਮ ਕਰੈ ਹਉ ਧਾਰੇ ॥","lareedar":"ਕੋਟਿਕਰਮਕਰੈਹਉਧਾਰੇ ॥","translit":"Kott Karam Karai Ho Dhhaarae ||","english":"If someone does millions of good deeds, while acting in ego,"},{"punjabi":"ਸ੍ਰਮੁ ਪਾਵੈ ਸਗਲੇ ਬਿਰਥਾਰੇ ॥","lareedar":"ਸ੍ਰਮੁਪਾਵੈਸਗਲੇਬਿਰਥਾਰੇ ॥","translit":"Sram Paavai Sagalae Birathhaarae ||","english":"He shall incur only trouble; all this is in vain."},{"punjabi":"ਅਨਿਕ ਤਪਸਿਆ ਕਰੇ ਅਹੰਕਾਰ ॥","lareedar":"ਅਨਿਕਤਪਸਿਆਕਰੇਅਹੰਕਾਰ ॥","translit":"Anik Thapasiaa Karae Ahankaar ||","english":"If someone performs great penance, while acting in selfishness and conceit,"},{"punjabi":"ਨਰਕ ਸੁਰਗ ਫਿਰਿ ਫਿਰਿ ਅਵਤਾਰ ॥","lareedar":"ਨਰਕਸੁਰਗਫਿਰਿਫਿਰਿਅਵਤਾਰ ॥","translit":"Narak Surag Fir Fir Avathaar ||","english":"He shall be reincarnated into heaven and hell, over and over again."},{"punjabi":"ਅਨਿਕ ਜਤਨ ਕਰਿ ਆਤਮ ਨਹੀ ਦ੍ਰਵੈ ॥","lareedar":"ਅਨਿਕਜਤਨਕਰਿਆਤਮਨਹੀਦ੍ਰਵੈ ॥","translit":"Anik Jathan Kar Aatham Nehee Dhravai ||","english":"He makes all sorts of efforts, but his soul is still not softened"},{"punjabi":"ਹਰਿ ਦਰਗਹ ਕਹੁ ਕੈਸੇ ਗਵੈ ॥","lareedar":"ਹਰਿਦਰਗਹਕਹੁਕੈਸੇਗਵੈ ॥","translit":"Har Dharageh Kahu Kaisae Gavai ||","english":"How can he go to the Court of the Lord?"},{"punjabi":"ਆਪਸ ਕਉ ਜੋ ਭਲਾ ਕਹਾਵੈ ॥","lareedar":"ਆਪਸਕਉਜੋਭਲਾਕਹਾਵੈ ॥","translit":"Aapas Ko Jo Bhalaa Kehaavai ||","english":"One who calls himself good"},{"punjabi":"ਤਿਸਹਿ ਭਲਾਈ ਨਿਕਟਿ ਨ ਆਵੈ ॥","lareedar":"ਤਿਸਹਿਭਲਾਈਨਿਕਟਿਨਆਵੈ ॥","translit":"Thisehi Bhalaaee Nikatt N Aavai ||","english":"Goodness shall not draw near him."},{"punjabi":"ਸਰਬ ਕੀ ਰੇਨ ਜਾ ਕਾ ਮਨੁ ਹੋਇ ॥","lareedar":"ਸਰਬਕੀਰੇਨਜਾਕਾਮਨੁਹੋਇ ॥","translit":"Sarab Kee Raen Jaa Kaa Man Hoe ||","english":"One whose mind is the dust of all"},{"punjabi":"ਕਹੁ ਨਾਨਕ ਤਾ ਕੀ ਨਿਰਮਲ ਸੋਇ ॥੩॥","lareedar":"ਕਹੁਨਾਨਕਤਾਕੀਨਿਰਮਲਸੋਇ ॥੩ ॥","translit":"Kahu Naanak Thaa Kee Niramal Soe ||3||","english":"- says Nanak, his reputation is spotlessly pure. ||3||"},{"punjabi":"ਜਬ ਲਗੁ ਜਾਨੈ ਮੁਝ ਤੇ ਕਛੁ ਹੋਇ ॥","lareedar":"ਜਬਲਗੁਜਾਨੈਮੁਝਤੇਕਛੁਹੋਇ ॥","translit":"Jab Lag Jaanai Mujh Thae Kashh Hoe ||","english":"As long as someone thinks that he is the one who acts,"},{"punjabi":"ਤਬ ਇਸ ਕਉ ਸੁਖੁ ਨਾਹੀ ਕੋਇ ॥","lareedar":"ਤਬਇਸਕਉਸੁਖੁਨਾਹੀਕੋਇ ॥","translit":"Thab Eis Ko Sukh Naahee Koe ||","english":"He shall have no peace."},{"punjabi":"ਜਬ ਇਹ ਜਾਨੈ ਮੈ ਕਿਛੁ ਕਰਤਾ ॥","lareedar":"ਜਬਇਹਜਾਨੈਮੈਕਿਛੁਕਰਤਾ ॥","translit":"Jab Eih Jaanai Mai Kishh Karathaa ||","english":"As long as this mortal thinks that he is the one who does things,"},{"punjabi":"ਤਬ ਲਗੁ ਗਰਭ ਜੋਨਿ ਮਹਿ ਫਿਰਤਾ ॥","lareedar":"ਤਬਲਗੁਗਰਭਜੋਨਿਮਹਿਫਿਰਤਾ ॥","translit":"Thab Lag Garabh Jon Mehi Firathaa ||","english":"He shall wander in reincarnation through the womb."},{"punjabi":"ਜਬ ਧਾਰੈ ਕੋਊ ਬੈਰੀ ਮੀਤੁ ॥","lareedar":"ਜਬਧਾਰੈਕੋਊਬੈਰੀਮੀਤੁ ॥","translit":"Jab Dhhaarai Kooo Bairee Meeth ||","english":"As long as he considers one an enemy, and another a friend,"},{"punjabi":"ਤਬ ਲਗੁ ਨਿਹਚਲੁ ਨਾਹੀ ਚੀਤੁ ॥","lareedar":"ਤਬਲਗੁਨਿਹਚਲੁਨਾਹੀਚੀਤੁ ॥","translit":"Thab Lag Nihachal Naahee Cheeth ||","english":"His mind shall not come to rest."}]},{"index":40,"ang":278,"lines":[{"punjabi":"ਜਬ ਲਗੁ ਮੋਹ ਮਗਨ ਸੰਗਿ ਮਾਇ ॥","lareedar":"ਜਬਲਗੁਮੋਹਮਗਨਸੰਗਿਮਾਇ ॥","translit":"Jab Lag Moh Magan Sang Maae ||","english":"As long as he is intoxicated with attachment to Maya,"},{"punjabi":"ਤਬ ਲਗੁ ਧਰਮ ਰਾਇ ਦੇਇ ਸਜਾਇ ॥","lareedar":"ਤਬਲਗੁਧਰਮਰਾਇਦੇਇਸਜਾਇ ॥","translit":"Thab Lag Dhharam Raae Dhaee Sajaae ||","english":"The Righteous Judge shall punish him."},{"punjabi":"ਪ੍ਰਭ ਕਿਰਪਾ ਤੇ ਬੰਧਨ ਤੂਟੈ ॥","lareedar":"ਪ੍ਰਭਕਿਰਪਾਤੇਬੰਧਨਤੂਟੈ ॥","translit":"Prabh Kirapaa Thae Bandhhan Thoottai ||","english":"By God's Grace, his bonds are shattered;"},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਨਾਨਕ ਹਉ ਛੂਟੈ ॥੪॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਨਾਨਕਹਉਛੂਟੈ ॥੪ ॥","translit":"Gur Prasaadh Naanak Ho Shhoottai ||4||","english":"By Guru's Grace, O Nanak, his ego is eliminated. ||4||"},{"punjabi":"ਸਹਸ ਖਟੇ ਲਖ ਕਉ ਉਠਿ ਧਾਵੈ ॥","lareedar":"ਸਹਸਖਟੇਲਖਕਉਉਠਿਧਾਵੈ ॥","translit":"Sehas Khattae Lakh Ko Outh Dhhaavai ||","english":"Earning a thousand, he runs after a hundred thousand."},{"punjabi":"ਤ੍ਰਿਪਤਿ ਨ ਆਵੈ ਮਾਇਆ ਪਾਛੈ ਪਾਵੈ ॥","lareedar":"ਤ੍ਰਿਪਤਿਨਆਵੈਮਾਇਆਪਾਛੈਪਾਵੈ ॥","translit":"Thripath N Aavai Maaeiaa Paashhai Paavai ||","english":"Satisfaction is not obtained by chasing after Maya."},{"punjabi":"ਅਨਿਕ ਭੋਗ ਬਿਖਿਆ ਕੇ ਕਰੈ ॥","lareedar":"ਅਨਿਕਭੋਗਬਿਖਿਆਕੇਕਰੈ ॥","translit":"Anik Bhog Bikhiaa Kae Karai ||","english":"He may enjoy all sorts of corrupt pleasures,"},{"punjabi":"ਨਹ ਤ੍ਰਿਪਤਾਵੈ ਖਪਿ ਖਪਿ ਮਰੈ ॥","lareedar":"ਨਹਤ੍ਰਿਪਤਾਵੈਖਪਿਖਪਿਮਰੈ ॥","translit":"Neh Thripathaavai Khap Khap Marai ||","english":"But he is still not satisfied; he indulges again and again, wearing himself out, until he dies."},{"punjabi":"ਬਿਨਾ ਸੰਤੋਖ ਨਹੀ ਕੋਊ ਰਾਜੈ ॥","lareedar":"ਬਿਨਾਸੰਤੋਖਨਹੀਕੋਊਰਾਜੈ ॥","translit":"Binaa Santhokh Nehee Kooo Raajai ||","english":"Without contentment, no one is satisfied."},{"punjabi":"ਸੁਪਨ ਮਨੋਰਥ ਬ੍ਰਿਥੇ ਸਭ ਕਾਜੈ ॥","lareedar":"ਸੁਪਨਮਨੋਰਥਬ੍ਰਿਥੇਸਭਕਾਜੈ ॥","translit":"Supan Manorathh Brithhae Sabh Kaajai ||","english":"Like the objects in a dream, all his efforts are in vain."},{"punjabi":"ਨਾਮ ਰੰਗਿ ਸਰਬ ਸੁਖੁ ਹੋਇ ॥","lareedar":"ਨਾਮਰੰਗਿਸਰਬਸੁਖੁਹੋਇ ॥","translit":"Naam Rang Sarab Sukh Hoe ||","english":"Through the love of the Naam, all peace is obtained."},{"punjabi":"ਬਡਭਾਗੀ ਕਿਸੈ ਪਰਾਪਤਿ ਹੋਇ ॥","lareedar":"ਬਡਭਾਗੀਕਿਸੈਪਰਾਪਤਿਹੋਇ ॥","translit":"Baddabhaagee Kisai Paraapath Hoe ||","english":"Only a few obtain this, by great good fortune."},{"punjabi":"ਕਰਨ ਕਰਾਵਨ ਆਪੇ ਆਪਿ ॥","lareedar":"ਕਰਨਕਰਾਵਨਆਪੇਆਪਿ ॥","translit":"Karan Karaavan Aapae Aap ||","english":"He Himself is Himself the Cause of causes."},{"punjabi":"ਸਦਾ ਸਦਾ ਨਾਨਕ ਹਰਿ ਜਾਪਿ ॥੫॥","lareedar":"ਸਦਾਸਦਾਨਾਨਕਹਰਿਜਾਪਿ ॥੫ ॥","translit":"Sadhaa Sadhaa Naanak Har Jaap ||5||","english":"Forever and ever, O Nanak, chant the Lord's Name. ||5||"},{"punjabi":"ਕਰਨ ਕਰਾਵਨ ਕਰਨੈਹਾਰੁ ॥","lareedar":"ਕਰਨਕਰਾਵਨਕਰਨੈਹਾਰੁ ॥","translit":"Karan Karaavan Karanaihaar ||","english":"The Doer, the Cause of causes, is the Creator Lord."},{"punjabi":"ਇਸ ਕੈ ਹਾਥਿ ਕਹਾ ਬੀਚਾਰੁ ॥","lareedar":"ਇਸਕੈਹਾਥਿਕਹਾਬੀਚਾਰੁ ॥","translit":"Eis Kai Haathh Kehaa Beechaar ||","english":"What deliberations are in the hands of mortal beings?"},{"punjabi":"ਜੈਸੀ ਦ੍ਰਿਸਟਿ ਕਰੇ ਤੈਸਾ ਹੋਇ ॥","lareedar":"ਜੈਸੀਦ੍ਰਿਸਟਿਕਰੇਤੈਸਾਹੋਇ ॥","translit":"Jaisee Dhrisatt Karae Thaisaa Hoe ||","english":"As God casts His Glance of Grace, they come to be."},{"punjabi":"ਆਪੇ ਆਪਿ ਆਪਿ ਪ੍ਰਭੁ ਸੋਇ ॥","lareedar":"ਆਪੇਆਪਿਆਪਿਪ੍ਰਭੁਸੋਇ ॥","translit":"Aapae Aap Aap Prabh Soe ||","english":"God Himself, of Himself, is unto Himself."},{"punjabi":"ਜੋ ਕਿਛੁ ਕੀਨੋ ਸੁ ਅਪਨੈ ਰੰਗਿ ॥","lareedar":"ਜੋਕਿਛੁਕੀਨੋਸੁਅਪਨੈਰੰਗਿ ॥","translit":"Jo Kishh Keeno S Apanai Rang ||","english":"Whatever He created, was by His Own Pleasure."},{"punjabi":"ਸਭ ਤੇ ਦੂਰਿ ਸਭਹੂ ਕੈ ਸੰਗਿ ॥","lareedar":"ਸਭਤੇਦੂਰਿਸਭਹੂਕੈਸੰਗਿ ॥","translit":"Sabh Thae Dhoor Sabhehoo Kai Sang ||","english":"He is far from all, and yet with all."},{"punjabi":"ਬੂਝੈ ਦੇਖੈ ਕਰੈ ਬਿਬੇਕ ॥","lareedar":"ਬੂਝੈਦੇਖੈਕਰੈਬਿਬੇਕ ॥","translit":"Boojhai Dhaekhai Karai Bibaek ||","english":"He understands, He sees, and He passes judgment."},{"punjabi":"ਆਪਹਿ ਏਕ ਆਪਹਿ ਅਨੇਕ ॥","lareedar":"ਆਪਹਿਏਕਆਪਹਿਅਨੇਕ ॥","translit":"Aapehi Eaek Aapehi Anaek ||","english":"He Himself is the One, and He Himself is the many."},{"punjabi":"ਮਰੈ ਨ ਬਿਨਸੈ ਆਵੈ ਨ ਜਾਇ ॥","lareedar":"ਮਰੈਨਬਿਨਸੈਆਵੈਨਜਾਇ ॥","translit":"Marai N Binasai Aavai N Jaae ||","english":"He does not die or perish; He does not come or go."},{"punjabi":"ਨਾਨਕ ਸਦ ਹੀ ਰਹਿਆ ਸਮਾਇ ॥੬॥","lareedar":"ਨਾਨਕਸਦਹੀਰਹਿਆਸਮਾਇ ॥੬ ॥","translit":"Naanak Sadh Hee Rehiaa Samaae ||6||","english":"O Nanak, He remains forever All-pervading. ||6||"},{"punjabi":"ਆਪਿ ਉਪਦੇਸੈ ਸਮਝੈ ਆਪਿ ॥","lareedar":"ਆਪਿਉਪਦੇਸੈਸਮਝੈਆਪਿ ॥","translit":"Aap Oupadhaesai Samajhai Aap ||","english":"He Himself instructs, and He Himself learns."}]},{"index":41,"ang":279,"lines":[{"punjabi":"ਆਪੇ ਰਚਿਆ ਸਭ ਕੈ ਸਾਥਿ ॥","lareedar":"ਆਪੇਰਚਿਆਸਭਕੈਸਾਥਿ ॥","translit":"Aapae Rachiaa Sabh Kai Saathh ||","english":"He Himself mingles with all."},{"punjabi":"ਆਪਿ ਕੀਨੋ ਆਪਨ ਬਿਸਥਾਰੁ ॥","lareedar":"ਆਪਿਕੀਨੋਆਪਨਬਿਸਥਾਰੁ ॥","translit":"Aap Keeno Aapan Bisathhaar ||","english":"He Himself created His own expanse."},{"punjabi":"ਸਭੁ ਕਛੁ ਉਸ ਕਾ ਓਹੁ ਕਰਨੈਹਾਰੁ ॥","lareedar":"ਸਭੁਕਛੁਉਸਕਾਓਹੁਕਰਨੈਹਾਰੁ ॥","translit":"Sabh Kashh Ous Kaa Ouhu Karanaihaar ||","english":"All things are His; He is the Creator."},{"punjabi":"ਉਸ ਤੇ ਭਿੰਨ ਕਹਹੁ ਕਿਛੁ ਹੋਇ ॥","lareedar":"ਉਸਤੇਭਿੰਨਕਹਹੁਕਿਛੁਹੋਇ ॥","translit":"Ous Thae Bhinn Kehahu Kishh Hoe ||","english":"Without Him, what could be done?"},{"punjabi":"ਥਾਨ ਥਨੰਤਰਿ ਏਕੈ ਸੋਇ ॥","lareedar":"ਥਾਨਥਨੰਤਰਿਏਕੈਸੋਇ ॥","translit":"Thhaan Thhananthar Eaekai Soe ||","english":"In the spaces and interspaces, He is the One."},{"punjabi":"ਅਪੁਨੇ ਚਲਿਤ ਆਪਿ ਕਰਣੈਹਾਰ ॥","lareedar":"ਅਪੁਨੇਚਲਿਤਆਪਿਕਰਣੈਹਾਰ ॥","translit":"Apunae Chalith Aap Karanaihaar ||","english":"In His own play, He Himself is the Actor."},{"punjabi":"ਕਉਤਕ ਕਰੈ ਰੰਗ ਆਪਾਰ ॥","lareedar":"ਕਉਤਕਕਰੈਰੰਗਆਪਾਰ ॥","translit":"Kouthak Karai Rang Aapaar ||","english":"He produces His plays with infinite variety."},{"punjabi":"ਮਨ ਮਹਿ ਆਪਿ ਮਨ ਅਪੁਨੇ ਮਾਹਿ ॥","lareedar":"ਮਨਮਹਿਆਪਿਮਨਅਪੁਨੇਮਾਹਿ ॥","translit":"Man Mehi Aap Man Apunae Maahi ||","english":"He Himself is in the mind, and the mind is in Him."},{"punjabi":"ਨਾਨਕ ਕੀਮਤਿ ਕਹਨੁ ਨ ਜਾਇ ॥੭॥","lareedar":"ਨਾਨਕਕੀਮਤਿਕਹਨੁਨਜਾਇ ॥੭ ॥","translit":"Naanak Keemath Kehan N Jaae ||7||","english":"O Nanak, His worth cannot be estimated. ||7||"},{"punjabi":"ਸਤਿ ਸਤਿ ਸਤਿ ਪ੍ਰਭੁ ਸੁਆਮੀ ॥","lareedar":"ਸਤਿਸਤਿਸਤਿਪ੍ਰਭੁਸੁਆਮੀ ॥","translit":"Sath Sath Sath Prabh Suaamee ||","english":"True, True, True is God, our Lord and Master."},{"punjabi":"ਗੁਰ ਪਰਸਾਦਿ ਕਿਨੈ ਵਖਿਆਨੀ ॥","lareedar":"ਗੁਰਪਰਸਾਦਿਕਿਨੈਵਖਿਆਨੀ ॥","translit":"Gur Parasaadh Kinai Vakhiaanee ||","english":"By Guru's Grace, some speak of Him."},{"punjabi":"ਸਚੁ ਸਚੁ ਸਚੁ ਸਭੁ ਕੀਨਾ ॥","lareedar":"ਸਚੁਸਚੁਸਚੁਸਭੁਕੀਨਾ ॥","translit":"Sach Sach Sach Sabh Keenaa ||","english":"True, True, True is the Creator of all."},{"punjabi":"ਕੋਟਿ ਮਧੇ ਕਿਨੈ ਬਿਰਲੈ ਚੀਨਾ ॥","lareedar":"ਕੋਟਿਮਧੇਕਿਨੈਬਿਰਲੈਚੀਨਾ ॥","translit":"Kott Madhhae Kinai Biralai Cheenaa ||","english":"Out of millions, scarcely anyone knows Him."},{"punjabi":"ਭਲਾ ਭਲਾ ਭਲਾ ਤੇਰਾ ਰੂਪ ॥","lareedar":"ਭਲਾਭਲਾਭਲਾਤੇਰਾਰੂਪ ॥","translit":"Bhalaa Bhalaa Bhalaa Thaeraa Roop ||","english":"Beautiful, Beautiful, Beautiful is Your Sublime Form."},{"punjabi":"ਅਤਿ ਸੁੰਦਰ ਅਪਾਰ ਅਨੂਪ ॥","lareedar":"ਅਤਿਸੁੰਦਰਅਪਾਰਅਨੂਪ ॥","translit":"Ath Sundhar Apaar Anoop ||","english":"You are Exquisitely Beautiful, Infinite and Incomparable."},{"punjabi":"ਨਿਰਮਲ ਨਿਰਮਲ ਨਿਰਮਲ ਤੇਰੀ ਬਾਣੀ ॥","lareedar":"ਨਿਰਮਲਨਿਰਮਲਨਿਰਮਲਤੇਰੀਬਾਣੀ ॥","translit":"Niramal Niramal Niramal Thaeree Baanee ||","english":"Pure, Pure, Pure is the Word of Your Bani,"},{"punjabi":"ਘਟਿ ਘਟਿ ਸੁਨੀ ਸ੍ਰਵਨ ਬਖ੍ਯ੍ਯਾਣੀ ॥","lareedar":"ਘਟਿਘਟਿਸੁਨੀਸ੍ਰਵਨਬਖ੍ਯ੍ਯਾਣੀ ॥","translit":"Ghatt Ghatt Sunee Sravan Bakhyaanee ||","english":"Heard in each and every heart, spoken to the ears."},{"punjabi":"ਪਵਿਤ੍ਰ ਪਵਿਤ੍ਰ ਪਵਿਤ੍ਰ ਪੁਨੀਤ ॥","lareedar":"ਪਵਿਤ੍ਰਪਵਿਤ੍ਰਪਵਿਤ੍ਰਪੁਨੀਤ ॥","translit":"Pavithr Pavithr Pavithr Puneeth ||","english":"Holy, Holy, Holy and Sublimely Pure"},{"punjabi":"ਨਾਮੁ ਜਪੈ ਨਾਨਕ ਮਨਿ ਪ੍ਰੀਤਿ ॥੮॥੧੨॥","lareedar":"ਨਾਮੁਜਪੈਨਾਨਕਮਨਿਪ੍ਰੀਤਿ ॥੮ ॥੧੨ ॥","translit":"Naam Japai Naanak Man Preeth ||8||12||","english":"- chant the Naam, O Nanak, with heart-felt love. ||8||12||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਸੰਤ ਸਰਨਿ ਜੋ ਜਨੁ ਪਰੈ ਸੋ ਜਨੁ ਉਧਰਨਹਾਰ ॥","lareedar":"ਸੰਤਸਰਨਿਜੋਜਨੁਪਰੈਸੋਜਨੁਉਧਰਨਹਾਰ ॥","translit":"Santh Saran Jo Jan Parai So Jan Oudhharanehaar ||","english":"One who seeks the Sanctuary of the Saints shall be saved."},{"punjabi":"ਸੰਤ ਕੀ ਨਿੰਦਾ ਨਾਨਕਾ ਬਹੁਰਿ ਬਹੁਰਿ ਅਵਤਾਰ ॥੧॥","lareedar":"ਸੰਤਕੀਨਿੰਦਾਨਾਨਕਾਬਹੁਰਿਬਹੁਰਿਅਵਤਾਰ ॥੧ ॥","translit":"Santh Kee Nindhaa Naanakaa Bahur Bahur Avathaar ||1||","english":"One who slanders the Saints, O Nanak, shall be reincarnated over and over again. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਸੰਤ ਕੈ ਦੂਖਨਿ ਆਰਜਾ ਘਟੈ ॥","lareedar":"ਸੰਤਕੈਦੂਖਨਿਆਰਜਾਘਟੈ ॥","translit":"Santh Kai Dhookhan Aarajaa Ghattai ||","english":"Slandering the Saints, one's life is cut short."},{"punjabi":"ਸੰਤ ਕੈ ਦੂਖਨਿ ਜਮ ਤੇ ਨਹੀ ਛੁਟੈ ॥","lareedar":"ਸੰਤਕੈਦੂਖਨਿਜਮਤੇਨਹੀਛੁਟੈ ॥","translit":"Santh Kai Dhookhan Jam Thae Nehee Shhuttai ||","english":"Slandering the Saints, one shall not escape the Messenger of Death."}]},{"index":42,"ang":279,"lines":[{"punjabi":"ਸੰਤ ਕੈ ਦੂਖਨਿ ਸੁਖੁ ਸਭੁ ਜਾਇ ॥","lareedar":"ਸੰਤਕੈਦੂਖਨਿਸੁਖੁਸਭੁਜਾਇ ॥","translit":"Santh Kai Dhookhan Sukh Sabh Jaae ||","english":"Slandering the Saints, all happiness vanishes."},{"punjabi":"ਸੰਤ ਕੈ ਦੂਖਨਿ ਨਰਕ ਮਹਿ ਪਾਇ ॥","lareedar":"ਸੰਤਕੈਦੂਖਨਿਨਰਕਮਹਿਪਾਇ ॥","translit":"Santh Kai Dhookhan Narak Mehi Paae ||","english":"Slandering the Saints, one falls into hell."},{"punjabi":"ਸੰਤ ਕੈ ਦੂਖਨਿ ਮਤਿ ਹੋਇ ਮਲੀਨ ॥","lareedar":"ਸੰਤਕੈਦੂਖਨਿਮਤਿਹੋਇਮਲੀਨ ॥","translit":"Santh Kai Dhookhan Math Hoe Maleen ||","english":"Slandering the Saints, the intellect is polluted."},{"punjabi":"ਸੰਤ ਕੈ ਦੂਖਨਿ ਸੋਭਾ ਤੇ ਹੀਨ ॥","lareedar":"ਸੰਤਕੈਦੂਖਨਿਸੋਭਾਤੇਹੀਨ ॥","translit":"Santh Kai Dhookhan Sobhaa Thae Heen ||","english":"Slandering the Saints, one's reputation is lost."},{"punjabi":"ਸੰਤ ਕੇ ਹਤੇ ਕਉ ਰਖੈ ਨ ਕੋਇ ॥","lareedar":"ਸੰਤਕੇਹਤੇਕਉਰਖੈਨਕੋਇ ॥","translit":"Santh Kae Hathae Ko Rakhai N Koe ||","english":"One who is cursed by a Saint cannot be saved."},{"punjabi":"ਸੰਤ ਕੈ ਦੂਖਨਿ ਥਾਨ ਭ੍ਰਸਟੁ ਹੋਇ ॥","lareedar":"ਸੰਤਕੈਦੂਖਨਿਥਾਨਭ੍ਰਸਟੁਹੋਇ ॥","translit":"Santh Kai Dhookhan Thhaan Bhrasatt Hoe ||","english":"Slandering the Saints, one's place is defiled."},{"punjabi":"ਸੰਤ ਕ੍ਰਿਪਾਲ ਕ੍ਰਿਪਾ ਜੇ ਕਰੈ ॥","lareedar":"ਸੰਤਕ੍ਰਿਪਾਲਕ੍ਰਿਪਾਜੇਕਰੈ ॥","translit":"Santh Kirapaal Kirapaa Jae Karai ||","english":"But if the Compassionate Saint shows His Kindness,"},{"punjabi":"ਨਾਨਕ ਸੰਤਸੰਗਿ ਨਿੰਦਕੁ ਭੀ ਤਰੈ ॥੧॥","lareedar":"ਨਾਨਕਸੰਤਸੰਗਿਨਿੰਦਕੁਭੀਤਰੈ ॥੧ ॥","translit":"Naanak Santhasang Nindhak Bhee Tharai ||1||","english":"O Nanak, in the Company of the Saints, the slanderer may still be saved. ||1||"},{"punjabi":"ਸੰਤ ਕੇ ਦੂਖਨ ਤੇ ਮੁਖੁ ਭਵੈ ॥","lareedar":"ਸੰਤਕੇਦੂਖਨਤੇਮੁਖੁਭਵੈ ॥","translit":"Santh Kae Dhookhan Thae Mukh Bhavai ||","english":"Slandering the Saints, one becomes a wry-faced malcontent."},{"punjabi":"ਸੰਤਨ ਕੈ ਦੂਖਨਿ ਕਾਗ ਜਿਉ ਲਵੈ ॥","lareedar":"ਸੰਤਨਕੈਦੂਖਨਿਕਾਗਜਿਉਲਵੈ ॥","translit":"Santhan Kai Dhookhan Kaag Jio Lavai ||","english":"Slandering the Saints, one croaks like a raven."},{"punjabi":"ਸੰਤਨ ਕੈ ਦੂਖਨਿ ਸਰਪ ਜੋਨਿ ਪਾਇ ॥","lareedar":"ਸੰਤਨਕੈਦੂਖਨਿਸਰਪਜੋਨਿਪਾਇ ॥","translit":"Santhan Kai Dhookhan Sarap Jon Paae ||","english":"Slandering the Saints, one is reincarnated as a snake."},{"punjabi":"ਸੰਤ ਕੈ ਦੂਖਨਿ ਤ੍ਰਿਗਦ ਜੋਨਿ ਕਿਰਮਾਇ ॥","lareedar":"ਸੰਤਕੈਦੂਖਨਿਤ੍ਰਿਗਦਜੋਨਿਕਿਰਮਾਇ ॥","translit":"Santh Kai Dhookhan Thrigadh Jon Kiramaae ||","english":"Slandering the Saints, one is reincarnated as a wiggling worm."},{"punjabi":"ਸੰਤਨ ਕੈ ਦੂਖਨਿ ਤ੍ਰਿਸਨਾ ਮਹਿ ਜਲੈ ॥","lareedar":"ਸੰਤਨਕੈਦੂਖਨਿਤ੍ਰਿਸਨਾਮਹਿਜਲੈ ॥","translit":"Santhan Kai Dhookhan Thrisanaa Mehi Jalai ||","english":"Slandering the Saints, one burns in the fire of desire."},{"punjabi":"ਸੰਤ ਕੈ ਦੂਖਨਿ ਸਭੁ ਕੋ ਛਲੈ ॥","lareedar":"ਸੰਤਕੈਦੂਖਨਿਸਭੁਕੋਛਲੈ ॥","translit":"Santh Kai Dhookhan Sabh Ko Shhalai ||","english":"Slandering the Saints, one tries to deceive everyone."},{"punjabi":"ਸੰਤ ਕੈ ਦੂਖਨਿ ਤੇਜੁ ਸਭੁ ਜਾਇ ॥","lareedar":"ਸੰਤਕੈਦੂਖਨਿਤੇਜੁਸਭੁਜਾਇ ॥","translit":"Santh Kai Dhookhan Thaej Sabh Jaae ||","english":"Slandering the Saints, all one's influence vanishes."},{"punjabi":"ਸੰਤ ਕੈ ਦੂਖਨਿ ਨੀਚੁ ਨੀਚਾਇ ॥","lareedar":"ਸੰਤਕੈਦੂਖਨਿਨੀਚੁਨੀਚਾਇ ॥","translit":"Santh Kai Dhookhan Neech Neechaae ||","english":"Slandering the Saints, one becomes the lowest of the low."},{"punjabi":"ਸੰਤ ਦੋਖੀ ਕਾ ਥਾਉ ਕੋ ਨਾਹਿ ॥","lareedar":"ਸੰਤਦੋਖੀਕਾਥਾਉਕੋਨਾਹਿ ॥","translit":"Santh Dhokhee Kaa Thhaao Ko Naahi ||","english":"For the slanderer of the Saint, there is no place of rest."},{"punjabi":"ਨਾਨਕ ਸੰਤ ਭਾਵੈ ਤਾ ਓਇ ਭੀ ਗਤਿ ਪਾਹਿ ॥੨॥","lareedar":"ਨਾਨਕਸੰਤਭਾਵੈਤਾਓਇਭੀਗਤਿਪਾਹਿ ॥੨ ॥","translit":"Naanak Santh Bhaavai Thaa Oue Bhee Gath Paahi ||2||","english":"O Nanak, if it pleases the Saint, even then, he may be saved. ||2||"},{"punjabi":"ਸੰਤ ਕਾ ਨਿੰਦਕੁ ਮਹਾ ਅਤਤਾਈ ॥","lareedar":"ਸੰਤਕਾਨਿੰਦਕੁਮਹਾਅਤਤਾਈ ॥","translit":"Santh Kaa Nindhak Mehaa Athathaaee ||","english":"The slanderer of the Saint is the worst evil-doer."},{"punjabi":"ਸੰਤ ਕਾ ਨਿੰਦਕੁ ਖਿਨੁ ਟਿਕਨੁ ਨ ਪਾਈ ॥","lareedar":"ਸੰਤਕਾਨਿੰਦਕੁਖਿਨੁਟਿਕਨੁਨਪਾਈ ॥","translit":"Santh Kaa Nindhak Khin Ttikan N Paaee ||","english":"The slanderer of the Saint has not even a moment's rest."},{"punjabi":"ਸੰਤ ਕਾ ਨਿੰਦਕੁ ਮਹਾ ਹਤਿਆਰਾ ॥","lareedar":"ਸੰਤਕਾਨਿੰਦਕੁਮਹਾਹਤਿਆਰਾ ॥","translit":"Santh Kaa Nindhak Mehaa Hathiaaraa ||","english":"The slanderer of the Saint is a brutal butcher."},{"punjabi":"ਸੰਤ ਕਾ ਨਿੰਦਕੁ ਪਰਮੇਸੁਰਿ ਮਾਰਾ ॥","lareedar":"ਸੰਤਕਾਨਿੰਦਕੁਪਰਮੇਸੁਰਿਮਾਰਾ ॥","translit":"Santh Kaa Nindhak Paramaesur Maaraa ||","english":"The slanderer of the Saint is cursed by the Transcendent Lord."},{"punjabi":"ਸੰਤ ਕਾ ਨਿੰਦਕੁ ਰਾਜ ਤੇ ਹੀਨੁ ॥","lareedar":"ਸੰਤਕਾਨਿੰਦਕੁਰਾਜਤੇਹੀਨੁ ॥","translit":"Santh Kaa Nindhak Raaj Thae Heen ||","english":"The slanderer of the Saint has no kingdom."},{"punjabi":"ਸੰਤ ਕਾ ਨਿੰਦਕੁ ਦੁਖੀਆ ਅਰੁ ਦੀਨੁ ॥","lareedar":"ਸੰਤਕਾਨਿੰਦਕੁਦੁਖੀਆਅਰੁਦੀਨੁ ॥","translit":"Santh Kaa Nindhak Dhukheeaa Ar Dheen ||","english":"The slanderer of the Saint becomes miserable and poor."},{"punjabi":"ਸੰਤ ਕੇ ਨਿੰਦਕ ਕਉ ਸਰਬ ਰੋਗ ॥","lareedar":"ਸੰਤਕੇਨਿੰਦਕਕਉਸਰਬਰੋਗ ॥","translit":"Santh Kae Nindhak Ko Sarab Rog ||","english":"The slanderer of the Saint contracts all diseases."}]},{"index":43,"ang":280,"lines":[{"punjabi":"ਸੰਤ ਕੇ ਨਿੰਦਕ ਕਉ ਸਦਾ ਬਿਜੋਗ ॥","lareedar":"ਸੰਤਕੇਨਿੰਦਕਕਉਸਦਾਬਿਜੋਗ ॥","translit":"Santh Kae Nindhak Ko Sadhaa Bijog ||","english":"The slanderer of the Saint is forever separated."},{"punjabi":"ਸੰਤ ਕੀ ਨਿੰਦਾ ਦੋਖ ਮਹਿ ਦੋਖੁ ॥","lareedar":"ਸੰਤਕੀਨਿੰਦਾਦੋਖਮਹਿਦੋਖੁ ॥","translit":"Santh Kee Nindhaa Dhokh Mehi Dhokh ||","english":"To slander a Saint is the worst sin of sins."},{"punjabi":"ਨਾਨਕ ਸੰਤ ਭਾਵੈ ਤਾ ਉਸ ਕਾ ਭੀ ਹੋਇ ਮੋਖੁ ॥੩॥","lareedar":"ਨਾਨਕਸੰਤਭਾਵੈਤਾਉਸਕਾਭੀਹੋਇਮੋਖੁ ॥੩ ॥","translit":"Naanak Santh Bhaavai Thaa Ous Kaa Bhee Hoe Mokh ||3||","english":"O Nanak, if it pleases the Saint, then even this one may be liberated. ||3||"},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਸਦਾ ਅਪਵਿਤੁ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਸਦਾਅਪਵਿਤੁ ॥","translit":"Santh Kaa Dhokhee Sadhaa Apavith ||","english":"The slanderer of the Saint is forever impure."},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਕਿਸੈ ਕਾ ਨਹੀ ਮਿਤੁ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਕਿਸੈਕਾਨਹੀਮਿਤੁ ॥","translit":"Santh Kaa Dhokhee Kisai Kaa Nehee Mith ||","english":"The slanderer of the Saint is nobody's friend."},{"punjabi":"ਸੰਤ ਕੇ ਦੋਖੀ ਕਉ ਡਾਨੁ ਲਾਗੈ ॥","lareedar":"ਸੰਤਕੇਦੋਖੀਕਉਡਾਨੁਲਾਗੈ ॥","translit":"Santh Kae Dhokhee Ko Ddaan Laagai ||","english":"The slanderer of the Saint shall be punished."},{"punjabi":"ਸੰਤ ਕੇ ਦੋਖੀ ਕਉ ਸਭ ਤਿਆਗੈ ॥","lareedar":"ਸੰਤਕੇਦੋਖੀਕਉਸਭਤਿਆਗੈ ॥","translit":"Santh Kae Dhokhee Ko Sabh Thiaagai ||","english":"The slanderer of the Saint is abandoned by all."},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਮਹਾ ਅਹੰਕਾਰੀ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਮਹਾਅਹੰਕਾਰੀ ॥","translit":"Santh Kaa Dhokhee Mehaa Ahankaaree ||","english":"The slanderer of the Saint is totally egocentric."},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਸਦਾ ਬਿਕਾਰੀ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਸਦਾਬਿਕਾਰੀ ॥","translit":"Santh Kaa Dhokhee Sadhaa Bikaaree ||","english":"The slanderer of the Saint is forever corrupt."},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਜਨਮੈ ਮਰੈ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਜਨਮੈਮਰੈ ॥","translit":"Santh Kaa Dhokhee Janamai Marai ||","english":"The slanderer of the Saint must endure birth and death."},{"punjabi":"ਸੰਤ ਕੀ ਦੂਖਨਾ ਸੁਖ ਤੇ ਟਰੈ ॥","lareedar":"ਸੰਤਕੀਦੂਖਨਾਸੁਖਤੇਟਰੈ ॥","translit":"Santh Kee Dhookhanaa Sukh Thae Ttarai ||","english":"The slanderer of the Saint is devoid of peace."},{"punjabi":"ਸੰਤ ਕੇ ਦੋਖੀ ਕਉ ਨਾਹੀ ਠਾਉ ॥","lareedar":"ਸੰਤਕੇਦੋਖੀਕਉਨਾਹੀਠਾਉ ॥","translit":"Santh Kae Dhokhee Ko Naahee Thaao ||","english":"The slanderer of the Saint has no place of rest."},{"punjabi":"ਨਾਨਕ ਸੰਤ ਭਾਵੈ ਤਾ ਲਏ ਮਿਲਾਇ ॥੪॥","lareedar":"ਨਾਨਕਸੰਤਭਾਵੈਤਾਲਏਮਿਲਾਇ ॥੪ ॥","translit":"Naanak Santh Bhaavai Thaa Leae Milaae ||4||","english":"O Nanak, if it pleases the Saint, then even such a one may merge in union. ||4||"},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਅਧ ਬੀਚ ਤੇ ਟੂਟੈ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਅਧਬੀਚਤੇਟੂਟੈ ॥","translit":"Santh Kaa Dhokhee Adhh Beech Thae Ttoottai ||","english":"The slanderer of the Saint breaks down mid-way."},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਕਿਤੈ ਕਾਜਿ ਨ ਪਹੂਚੈ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਕਿਤੈਕਾਜਿਨਪਹੂਚੈ ॥","translit":"Santh Kaa Dhokhee Kithai Kaaj N Pehoochai ||","english":"The slanderer of the Saint cannot accomplish his tasks."},{"punjabi":"ਸੰਤ ਕੇ ਦੋਖੀ ਕਉ ਉਦਿਆਨ ਭ੍ਰਮਾਈਐ ॥","lareedar":"ਸੰਤਕੇਦੋਖੀਕਉਉਦਿਆਨਭ੍ਰਮਾਈਐ ॥","translit":"Santh Kae Dhokhee Ko Oudhiaan Bhramaaeeai ||","english":"The slanderer of the Saint wanders in the wilderness."},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਉਝੜਿ ਪਾਈਐ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਉਝੜਿਪਾਈਐ ॥","translit":"Santh Kaa Dhokhee Oujharr Paaeeai ||","english":"The slanderer of the Saint is misled into desolation."},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਅੰਤਰ ਤੇ ਥੋਥਾ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਅੰਤਰਤੇਥੋਥਾ ॥","translit":"Santh Kaa Dhokhee Anthar Thae Thhothhaa ||","english":"The slanderer of the Saint is empty inside,"},{"punjabi":"ਜਿਉ ਸਾਸ ਬਿਨਾ ਮਿਰਤਕ ਕੀ ਲੋਥਾ ॥","lareedar":"ਜਿਉਸਾਸਬਿਨਾਮਿਰਤਕਕੀਲੋਥਾ ॥","translit":"Jio Saas Binaa Mirathak Kee Lothhaa ||","english":"Like the corpse of a dead man, without the breath of life."},{"punjabi":"ਸੰਤ ਕੇ ਦੋਖੀ ਕੀ ਜੜ ਕਿਛੁ ਨਾਹਿ ॥","lareedar":"ਸੰਤਕੇਦੋਖੀਕੀਜੜਕਿਛੁਨਾਹਿ ॥","translit":"Santh Kae Dhokhee Kee Jarr Kishh Naahi ||","english":"The slanderer of the Saint has no heritage at all."},{"punjabi":"ਆਪਨ ਬੀਜਿ ਆਪੇ ਹੀ ਖਾਹਿ ॥","lareedar":"ਆਪਨਬੀਜਿਆਪੇਹੀਖਾਹਿ ॥","translit":"Aapan Beej Aapae Hee Khaahi ||","english":"He himself must eat what he has planted."},{"punjabi":"ਸੰਤ ਕੇ ਦੋਖੀ ਕਉ ਅਵਰੁ ਨ ਰਾਖਨਹਾਰੁ ॥","lareedar":"ਸੰਤਕੇਦੋਖੀਕਉਅਵਰੁਨਰਾਖਨਹਾਰੁ ॥","translit":"Santh Kae Dhokhee Ko Avar N Raakhanehaar ||","english":"The slanderer of the Saint cannot be saved by anyone else."},{"punjabi":"ਨਾਨਕ ਸੰਤ ਭਾਵੈ ਤਾ ਲਏ ਉਬਾਰਿ ॥੫॥","lareedar":"ਨਾਨਕਸੰਤਭਾਵੈਤਾਲਏਉਬਾਰਿ ॥੫ ॥","translit":"Naanak Santh Bhaavai Thaa Leae Oubaar ||5||","english":"O Nanak, if it pleases the Saint, then even he may be saved. ||5||"},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਇਉ ਬਿਲਲਾਇ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਇਉਬਿਲਲਾਇ ॥","translit":"Santh Kaa Dhokhee Eio Bilalaae ||","english":"The slanderer of the Saint bewails like this"},{"punjabi":"ਜਿਉ ਜਲ ਬਿਹੂਨ ਮਛੁਲੀ ਤੜਫੜਾਇ ॥","lareedar":"ਜਿਉਜਲਬਿਹੂਨਮਛੁਲੀਤੜਫੜਾਇ ॥","translit":"Jio Jal Bihoon Mashhulee Tharrafarraae ||","english":"Like a fish, out of water, writhing in agony."}]},{"index":44,"ang":280,"lines":[{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਭੂਖਾ ਨਹੀ ਰਾਜੈ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਭੂਖਾਨਹੀਰਾਜੈ ॥","translit":"Santh Kaa Dhokhee Bhookhaa Nehee Raajai ||","english":"The slanderer of the Saint is hungry and is never satisfied,"},{"punjabi":"ਜਿਉ ਪਾਵਕੁ ਈਧਨਿ ਨਹੀ ਧ੍ਰਾਪੈ ॥","lareedar":"ਜਿਉਪਾਵਕੁਈਧਨਿਨਹੀਧ੍ਰਾਪੈ ॥","translit":"Jio Paavak Eedhhan Nehee Dhhraapai ||","english":"As fire is not satisfied by fuel."},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਛੁਟੈ ਇਕੇਲਾ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਛੁਟੈਇਕੇਲਾ ॥","translit":"Santh Kaa Dhokhee Shhuttai Eikaelaa ||","english":"The slanderer of the Saint is left all alone,"},{"punjabi":"ਜਿਉ ਬੂਆੜੁ ਤਿਲੁ ਖੇਤ ਮਾਹਿ ਦੁਹੇਲਾ ॥","lareedar":"ਜਿਉਬੂਆੜੁਤਿਲੁਖੇਤਮਾਹਿਦੁਹੇਲਾ ॥","translit":"Jio Booaarr Thil Khaeth Maahi Dhuhaelaa ||","english":"Like the miserable barren sesame stalk abandoned in the field."},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਧਰਮ ਤੇ ਰਹਤ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਧਰਮਤੇਰਹਤ ॥","translit":"Santh Kaa Dhokhee Dhharam Thae Rehath ||","english":"The slanderer of the Saint is devoid of faith."},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਸਦ ਮਿਥਿਆ ਕਹਤ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਸਦਮਿਥਿਆਕਹਤ ॥","translit":"Santh Kaa Dhokhee Sadh Mithhiaa Kehath ||","english":"The slanderer of the Saint constantly lies."},{"punjabi":"ਕਿਰਤੁ ਨਿੰਦਕ ਕਾ ਧੁਰਿ ਹੀ ਪਇਆ ॥","lareedar":"ਕਿਰਤੁਨਿੰਦਕਕਾਧੁਰਿਹੀਪਇਆ ॥","translit":"Kirath Nindhak Kaa Dhhur Hee Paeiaa ||","english":"The fate of the slanderer is pre-ordained from the very beginning of time."},{"punjabi":"ਨਾਨਕ ਜੋ ਤਿਸੁ ਭਾਵੈ ਸੋਈ ਥਿਆ ॥੬॥","lareedar":"ਨਾਨਕਜੋਤਿਸੁਭਾਵੈਸੋਈਥਿਆ ॥੬ ॥","translit":"Naanak Jo This Bhaavai Soee Thhiaa ||6||","english":"O Nanak, whatever pleases God's Will comes to pass. ||6||"},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਬਿਗੜ ਰੂਪੁ ਹੋਇ ਜਾਇ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਬਿਗੜਰੂਪੁਹੋਇਜਾਇ ॥","translit":"Santh Kaa Dhokhee Bigarr Roop Hoe Jaae ||","english":"The slanderer of the Saint becomes deformed."},{"punjabi":"ਸੰਤ ਕੇ ਦੋਖੀ ਕਉ ਦਰਗਹ ਮਿਲੈ ਸਜਾਇ ॥","lareedar":"ਸੰਤਕੇਦੋਖੀਕਉਦਰਗਹਮਿਲੈਸਜਾਇ ॥","translit":"Santh Kae Dhokhee Ko Dharageh Milai Sajaae ||","english":"The slanderer of the Saint receives his punishment in the Court of the Lord."},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਸਦਾ ਸਹਕਾਈਐ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਸਦਾਸਹਕਾਈਐ ॥","translit":"Santh Kaa Dhokhee Sadhaa Sehakaaeeai ||","english":"The slanderer of the Saint is eternally in limbo."},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਨ ਮਰੈ ਨ ਜੀਵਾਈਐ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਨਮਰੈਨਜੀਵਾਈਐ ॥","translit":"Santh Kaa Dhokhee N Marai N Jeevaaeeai ||","english":"He does not die, but he does not live either."},{"punjabi":"ਸੰਤ ਕੇ ਦੋਖੀ ਕੀ ਪੁਜੈ ਨ ਆਸਾ ॥","lareedar":"ਸੰਤਕੇਦੋਖੀਕੀਪੁਜੈਨਆਸਾ ॥","translit":"Santh Kae Dhokhee Kee Pujai N Aasaa ||","english":"The hopes of the slanderer of the Saint are not fulfilled."},{"punjabi":"ਸੰਤ ਕਾ ਦੋਖੀ ਉਠਿ ਚਲੈ ਨਿਰਾਸਾ ॥","lareedar":"ਸੰਤਕਾਦੋਖੀਉਠਿਚਲੈਨਿਰਾਸਾ ॥","translit":"Santh Kaa Dhokhee Outh Chalai Niraasaa ||","english":"The slanderer of the Saint departs disappointed."},{"punjabi":"ਸੰਤ ਕੈ ਦੋਖਿ ਨ ਤ੍ਰਿਸਟੈ ਕੋਇ ॥","lareedar":"ਸੰਤਕੈਦੋਖਿਨਤ੍ਰਿਸਟੈਕੋਇ ॥","translit":"Santh Kai Dhokh N Thrisattai Koe ||","english":"Slandering the Saint, no one attains satisfaction."},{"punjabi":"ਜੈਸਾ ਭਾਵੈ ਤੈਸਾ ਕੋਈ ਹੋਇ ॥","lareedar":"ਜੈਸਾਭਾਵੈਤੈਸਾਕੋਈਹੋਇ ॥","translit":"Jaisaa Bhaavai Thaisaa Koee Hoe ||","english":"As it pleases the Lord, so do people become;"},{"punjabi":"ਪਇਆ ਕਿਰਤੁ ਨ ਮੇਟੈ ਕੋਇ ॥","lareedar":"ਪਇਆਕਿਰਤੁਨਮੇਟੈਕੋਇ ॥","translit":"Paeiaa Kirath N Maettai Koe ||","english":"No one can erase their past actions."},{"punjabi":"ਨਾਨਕ ਜਾਨੈ ਸਚਾ ਸੋਇ ॥੭॥","lareedar":"ਨਾਨਕਜਾਨੈਸਚਾਸੋਇ ॥੭ ॥","translit":"Naanak Jaanai Sachaa Soe ||7||","english":"O Nanak, the True Lord alone knows all. ||7||"},{"punjabi":"ਸਭ ਘਟ ਤਿਸ ਕੇ ਓਹੁ ਕਰਨੈਹਾਰੁ ॥","lareedar":"ਸਭਘਟਤਿਸਕੇਓਹੁਕਰਨੈਹਾਰੁ ॥","translit":"Sabh Ghatt This Kae Ouhu Karanaihaar ||","english":"All hearts are His; He is the Creator."},{"punjabi":"ਸਦਾ ਸਦਾ ਤਿਸ ਕਉ ਨਮਸਕਾਰੁ ॥","lareedar":"ਸਦਾਸਦਾਤਿਸਕਉਨਮਸਕਾਰੁ ॥","translit":"Sadhaa Sadhaa This Ko Namasakaar ||","english":"Forever and ever, I bow to Him in reverence."},{"punjabi":"ਪ੍ਰਭ ਕੀ ਉਸਤਤਿ ਕਰਹੁ ਦਿਨੁ ਰਾਤਿ ॥","lareedar":"ਪ੍ਰਭਕੀਉਸਤਤਿਕਰਹੁਦਿਨੁਰਾਤਿ ॥","translit":"Prabh Kee Ousathath Karahu Dhin Raath ||","english":"Praise God, day and night."},{"punjabi":"ਤਿਸਹਿ ਧਿਆਵਹੁ ਸਾਸਿ ਗਿਰਾਸਿ ॥","lareedar":"ਤਿਸਹਿਧਿਆਵਹੁਸਾਸਿਗਿਰਾਸਿ ॥","translit":"Thisehi Dhhiaavahu Saas Giraas ||","english":"Meditate on Him with every breath and morsel of food."},{"punjabi":"ਸਭੁ ਕਛੁ ਵਰਤੈ ਤਿਸ ਕਾ ਕੀਆ ॥","lareedar":"ਸਭੁਕਛੁਵਰਤੈਤਿਸਕਾਕੀਆ ॥","translit":"Sabh Kashh Varathai This Kaa Keeaa ||","english":"Everything happens as He wills."},{"punjabi":"ਜੈਸਾ ਕਰੇ ਤੈਸਾ ਕੋ ਥੀਆ ॥","lareedar":"ਜੈਸਾਕਰੇਤੈਸਾਕੋਥੀਆ ॥","translit":"Jaisaa Karae Thaisaa Ko Thheeaa ||","english":"As He wills, so people become."},{"punjabi":"ਅਪਨਾ ਖੇਲੁ ਆਪਿ ਕਰਨੈਹਾਰੁ ॥","lareedar":"ਅਪਨਾਖੇਲੁਆਪਿਕਰਨੈਹਾਰੁ ॥","translit":"Apanaa Khael Aap Karanaihaar ||","english":"He Himself is the play, and He Himself is the actor."}]},{"index":45,"ang":280,"lines":[{"punjabi":"ਦੂਸਰ ਕਉਨੁ ਕਹੈ ਬੀਚਾਰੁ ॥","lareedar":"ਦੂਸਰਕਉਨੁਕਹੈਬੀਚਾਰੁ ॥","translit":"Dhoosar Koun Kehai Beechaar ||","english":"Who else can speak or deliberate upon this?"},{"punjabi":"ਜਿਸ ਨੋ ਕ੍ਰਿਪਾ ਕਰੈ ਤਿਸੁ ਆਪਨ ਨਾਮੁ ਦੇਇ ॥","lareedar":"ਜਿਸਨੋਕ੍ਰਿਪਾਕਰੈਤਿਸੁਆਪਨਨਾਮੁਦੇਇ ॥","translit":"Jis No Kirapaa Karai This Aapan Naam Dhaee ||","english":"He Himself gives His Name to those, upon whom He bestows His Mercy."},{"punjabi":"ਬਡਭਾਗੀ ਨਾਨਕ ਜਨ ਸੇਇ ॥੮॥੧੩॥","lareedar":"ਬਡਭਾਗੀਨਾਨਕਜਨਸੇਇ ॥੮ ॥੧੩ ॥","translit":"Baddabhaagee Naanak Jan Saee ||8||13||","english":"Very fortunate, O Nanak, are those people. ||8||13||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਤਜਹੁ ਸਿਆਨਪ ਸੁਰਿ ਜਨਹੁ ਸਿਮਰਹੁ ਹਰਿ ਹਰਿ ਰਾਇ ॥","lareedar":"ਤਜਹੁਸਿਆਨਪਸੁਰਿਜਨਹੁਸਿਮਰਹੁਹਰਿਹਰਿਰਾਇ ॥","translit":"Thajahu Siaanap Sur Janahu Simarahu Har Har Raae ||","english":"Give up your cleverness, good people - remember the Lord God, your King!"},{"punjabi":"ਏਕ ਆਸ ਹਰਿ ਮਨਿ ਰਖਹੁ ਨਾਨਕ ਦੂਖੁ ਭਰਮੁ ਭਉ ਜਾਇ ॥੧॥","lareedar":"ਏਕਆਸਹਰਿਮਨਿਰਖਹੁਨਾਨਕਦੂਖੁਭਰਮੁਭਉਜਾਇ ॥੧ ॥","translit":"Eaek Aas Har Man Rakhahu Naanak Dhookh Bharam Bho Jaae ||1||","english":"Enshrine in your heart, your hopes in the One Lord. O Nanak, your pain, doubt and fear shall depart. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਮਾਨੁਖ ਕੀ ਟੇਕ ਬ੍ਰਿਥੀ ਸਭ ਜਾਨੁ ॥","lareedar":"ਮਾਨੁਖਕੀਟੇਕਬ੍ਰਿਥੀਸਭਜਾਨੁ ॥","translit":"Maanukh Kee Ttaek Brithhee Sabh Jaan ||","english":"Reliance on mortals is in vain - know this well."},{"punjabi":"ਦੇਵਨ ਕਉ ਏਕੈ ਭਗਵਾਨੁ ॥","lareedar":"ਦੇਵਨਕਉਏਕੈਭਗਵਾਨੁ ॥","translit":"Dhaevan Ko Eaekai Bhagavaan ||","english":"The Great Giver is the One Lord God."},{"punjabi":"ਜਿਸ ਕੈ ਦੀਐ ਰਹੈ ਅਘਾਇ ॥","lareedar":"ਜਿਸਕੈਦੀਐਰਹੈਅਘਾਇ ॥","translit":"Jis Kai Dheeai Rehai Aghaae ||","english":"By His gifts, we are satisfied,"},{"punjabi":"ਬਹੁਰਿ ਨ ਤ੍ਰਿਸਨਾ ਲਾਗੈ ਆਇ ॥","lareedar":"ਬਹੁਰਿਨਤ੍ਰਿਸਨਾਲਾਗੈਆਇ ॥","translit":"Bahur N Thrisanaa Laagai Aae ||","english":"And we suffer from thirst no longer."},{"punjabi":"ਮਾਰੈ ਰਾਖੈ ਏਕੋ ਆਪਿ ॥","lareedar":"ਮਾਰੈਰਾਖੈਏਕੋਆਪਿ ॥","translit":"Maarai Raakhai Eaeko Aap ||","english":"The One Lord Himself destroys and also preserves."},{"punjabi":"ਮਾਨੁਖ ਕੈ ਕਿਛੁ ਨਾਹੀ ਹਾਥਿ ॥","lareedar":"ਮਾਨੁਖਕੈਕਿਛੁਨਾਹੀਹਾਥਿ ॥","translit":"Maanukh Kai Kishh Naahee Haathh ||","english":"Nothing at all is in the hands of mortal beings."},{"punjabi":"ਤਿਸ ਕਾ ਹੁਕਮੁ ਬੂਝਿ ਸੁਖੁ ਹੋਇ ॥","lareedar":"ਤਿਸਕਾਹੁਕਮੁਬੂਝਿਸੁਖੁਹੋਇ ॥","translit":"This Kaa Hukam Boojh Sukh Hoe ||","english":"Understanding His Order, there is peace."},{"punjabi":"ਤਿਸ ਕਾ ਨਾਮੁ ਰਖੁ ਕੰਠਿ ਪਰੋਇ ॥","lareedar":"ਤਿਸਕਾਨਾਮੁਰਖੁਕੰਠਿਪਰੋਇ ॥","translit":"This Kaa Naam Rakh Kanth Paroe ||","english":"So take His Name, and wear it as your necklace."},{"punjabi":"ਸਿਮਰਿ ਸਿਮਰਿ ਸਿਮਰਿ ਪ੍ਰਭੁ ਸੋਇ ॥","lareedar":"ਸਿਮਰਿਸਿਮਰਿਸਿਮਰਿਪ੍ਰਭੁਸੋਇ ॥","translit":"Simar Simar Simar Prabh Soe ||","english":"Remember, remember, remember God in meditation."},{"punjabi":"ਨਾਨਕ ਬਿਘਨੁ ਨ ਲਾਗੈ ਕੋਇ ॥੧॥","lareedar":"ਨਾਨਕਬਿਘਨੁਨਲਾਗੈਕੋਇ ॥੧ ॥","translit":"Naanak Bighan N Laagai Koe ||1||","english":"O Nanak, no obstacle shall stand in your way. ||1||"},{"punjabi":"ਉਸਤਤਿ ਮਨ ਮਹਿ ਕਰਿ ਨਿਰੰਕਾਰ ॥","lareedar":"ਉਸਤਤਿਮਨਮਹਿਕਰਿਨਿਰੰਕਾਰ ॥","translit":"Ousathath Man Mehi Kar Nirankaar ||","english":"Praise the Formless Lord in your mind."},{"punjabi":"ਕਰਿ ਮਨ ਮੇਰੇ ਸਤਿ ਬਿਉਹਾਰ ॥","lareedar":"ਕਰਿਮਨਮੇਰੇਸਤਿਬਿਉਹਾਰ ॥","translit":"Kar Man Maerae Sath Biouhaar ||","english":"O my mind, make this your true occupation."},{"punjabi":"ਨਿਰਮਲ ਰਸਨਾ ਅੰਮ੍ਰਿਤੁ ਪੀਉ ॥","lareedar":"ਨਿਰਮਲਰਸਨਾਅੰਮ੍ਰਿਤੁਪੀਉ ॥","translit":"Niramal Rasanaa Anmrith Peeo ||","english":"Let your tongue become pure, drinking in the Ambrosial Nectar."},{"punjabi":"ਸਦਾ ਸੁਹੇਲਾ ਕਰਿ ਲੇਹਿ ਜੀਉ ॥","lareedar":"ਸਦਾਸੁਹੇਲਾਕਰਿਲੇਹਿਜੀਉ ॥","translit":"Sadhaa Suhaelaa Kar Laehi Jeeo ||","english":"Your soul shall be forever peaceful."},{"punjabi":"ਨੈਨਹੁ ਪੇਖੁ ਠਾਕੁਰ ਕਾ ਰੰਗੁ ॥","lareedar":"ਨੈਨਹੁਪੇਖੁਠਾਕੁਰਕਾਰੰਗੁ ॥","translit":"Nainahu Paekh Thaakur Kaa Rang ||","english":"With your eyes, see the wondrous play of your Lord and Master."},{"punjabi":"ਸਾਧਸੰਗਿ ਬਿਨਸੈ ਸਭ ਸੰਗੁ ॥","lareedar":"ਸਾਧਸੰਗਿਬਿਨਸੈਸਭਸੰਗੁ ॥","translit":"Saadhhasang Binasai Sabh Sang ||","english":"In the Company of the Holy, all other associations vanish."},{"punjabi":"ਚਰਨ ਚਲਉ ਮਾਰਗਿ ਗੋਬਿੰਦ ॥","lareedar":"ਚਰਨਚਲਉਮਾਰਗਿਗੋਬਿੰਦ ॥","translit":"Charan Chalo Maarag Gobindh ||","english":"With your feet, walk in the Way of the Lord."},{"punjabi":"ਮਿਟਹਿ ਪਾਪ ਜਪੀਐ ਹਰਿ ਬਿੰਦ ॥","lareedar":"ਮਿਟਹਿਪਾਪਜਪੀਐਹਰਿਬਿੰਦ ॥","translit":"Mittehi Paap Japeeai Har Bindh ||","english":"Sins are washed away, chanting the Lord's Name, even for a moment."}]},{"index":46,"ang":281,"lines":[{"punjabi":"ਕਰ ਹਰਿ ਕਰਮ ਸ੍ਰਵਨਿ ਹਰਿ ਕਥਾ ॥","lareedar":"ਕਰਹਰਿਕਰਮਸ੍ਰਵਨਿਹਰਿਕਥਾ ॥","translit":"Kar Har Karam Sravan Har Kathhaa ||","english":"So do the Lord's Work, and listen to the Lord's Sermon."},{"punjabi":"ਹਰਿ ਦਰਗਹ ਨਾਨਕ ਊਜਲ ਮਥਾ ॥੨॥","lareedar":"ਹਰਿਦਰਗਹਨਾਨਕਊਜਲਮਥਾ ॥੨ ॥","translit":"Har Dharageh Naanak Oojal Mathhaa ||2||","english":"In the Lord's Court, O Nanak, your face shall be radiant. ||2||"},{"punjabi":"ਬਡਭਾਗੀ ਤੇ ਜਨ ਜਗ ਮਾਹਿ ॥","lareedar":"ਬਡਭਾਗੀਤੇਜਨਜਗਮਾਹਿ ॥","translit":"Baddabhaagee Thae Jan Jag Maahi ||","english":"Very fortunate are those humble beings in this world,"},{"punjabi":"ਸਦਾ ਸਦਾ ਹਰਿ ਕੇ ਗੁਨ ਗਾਹਿ ॥","lareedar":"ਸਦਾਸਦਾਹਰਿਕੇਗੁਨਗਾਹਿ ॥","translit":"Sadhaa Sadhaa Har Kae Gun Gaahi ||","english":"Who sing the Glorious Praises of the Lord, forever and ever."},{"punjabi":"ਰਾਮ ਨਾਮ ਜੋ ਕਰਹਿ ਬੀਚਾਰ ॥","lareedar":"ਰਾਮਨਾਮਜੋਕਰਹਿਬੀਚਾਰ ॥","translit":"Raam Naam Jo Karehi Beechaar ||","english":"Those who dwell upon the Lord's Name,"},{"punjabi":"ਸੇ ਧਨਵੰਤ ਗਨੀ ਸੰਸਾਰ ॥","lareedar":"ਸੇਧਨਵੰਤਗਨੀਸੰਸਾਰ ॥","translit":"Sae Dhhanavanth Ganee Sansaar ||","english":"Are the most wealthy and prosperous in the world."},{"punjabi":"ਮਨਿ ਤਨਿ ਮੁਖਿ ਬੋਲਹਿ ਹਰਿ ਮੁਖੀ ॥","lareedar":"ਮਨਿਤਨਿਮੁਖਿਬੋਲਹਿਹਰਿਮੁਖੀ ॥","translit":"Man Than Mukh Bolehi Har Mukhee ||","english":"Those who speak of the Supreme Lord in thought, word and deed"},{"punjabi":"ਸਦਾ ਸਦਾ ਜਾਨਹੁ ਤੇ ਸੁਖੀ ॥","lareedar":"ਸਦਾਸਦਾਜਾਨਹੁਤੇਸੁਖੀ ॥","translit":"Sadhaa Sadhaa Jaanahu Thae Sukhee ||","english":"Know that they are peaceful and happy, forever and ever."},{"punjabi":"ਏਕੋ ਏਕੁ ਏਕੁ ਪਛਾਨੈ ॥","lareedar":"ਏਕੋਏਕੁਏਕੁਪਛਾਨੈ ॥","translit":"Eaeko Eaek Eaek Pashhaanai ||","english":"One who recognizes the One and only Lord as One,"},{"punjabi":"ਇਤ ਉਤ ਕੀ ਓਹੁ ਸੋਝੀ ਜਾਨੈ ॥","lareedar":"ਇਤਉਤਕੀਓਹੁਸੋਝੀਜਾਨੈ ॥","translit":"Eith Outh Kee Ouhu Sojhee Jaanai ||","english":"Understands this world and the next."},{"punjabi":"ਨਾਮ ਸੰਗਿ ਜਿਸ ਕਾ ਮਨੁ ਮਾਨਿਆ ॥","lareedar":"ਨਾਮਸੰਗਿਜਿਸਕਾਮਨੁਮਾਨਿਆ ॥","translit":"Naam Sang Jis Kaa Man Maaniaa ||","english":"One whose mind accepts the Company of the Naam,"},{"punjabi":"ਨਾਨਕ ਤਿਨਹਿ ਨਿਰੰਜਨੁ ਜਾਨਿਆ ॥੩॥","lareedar":"ਨਾਨਕਤਿਨਹਿਨਿਰੰਜਨੁਜਾਨਿਆ ॥੩ ॥","translit":"Naanak Thinehi Niranjan Jaaniaa ||3||","english":"The Name of the Lord, O Nanak, knows the Immaculate Lord. ||3||"},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਆਪਨ ਆਪੁ ਸੁਝੈ ॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਆਪਨਆਪੁਸੁਝੈ ॥","translit":"Gur Prasaadh Aapan Aap Sujhai ||","english":"By Guru's Grace, one understands himself;"},{"punjabi":"ਤਿਸ ਕੀ ਜਾਨਹੁ ਤ੍ਰਿਸਨਾ ਬੁਝੈ ॥","lareedar":"ਤਿਸਕੀਜਾਨਹੁਤ੍ਰਿਸਨਾਬੁਝੈ ॥","translit":"This Kee Jaanahu Thrisanaa Bujhai ||","english":"Know that then, his thirst is quenched."},{"punjabi":"ਸਾਧਸੰਗਿ ਹਰਿ ਹਰਿ ਜਸੁ ਕਹਤ ॥","lareedar":"ਸਾਧਸੰਗਿਹਰਿਹਰਿਜਸੁਕਹਤ ॥","translit":"Saadhhasang Har Har Jas Kehath ||","english":"In the Company of the Holy, one chants the Praises of the Lord, Har, Har."},{"punjabi":"ਸਰਬ ਰੋਗ ਤੇ ਓਹੁ ਹਰਿ ਜਨੁ ਰਹਤ ॥","lareedar":"ਸਰਬਰੋਗਤੇਓਹੁਹਰਿਜਨੁਰਹਤ ॥","translit":"Sarab Rog Thae Ouhu Har Jan Rehath ||","english":"Such a devotee of the Lord is free of all disease."},{"punjabi":"ਅਨਦਿਨੁ ਕੀਰਤਨੁ ਕੇਵਲ ਬਖ੍ਯ੍ਯਾਨੁ ॥","lareedar":"ਅਨਦਿਨੁਕੀਰਤਨੁਕੇਵਲਬਖ੍ਯ੍ਯਾਨੁ ॥","translit":"Anadhin Keerathan Kaeval Bakhyaan ||","english":"Night and day, sing the Kirtan, the Praises of the One Lord."},{"punjabi":"ਗ੍ਰਿਹਸਤ ਮਹਿ ਸੋਈ ਨਿਰਬਾਨੁ ॥","lareedar":"ਗ੍ਰਿਹਸਤਮਹਿਸੋਈਨਿਰਬਾਨੁ ॥","translit":"Grihasath Mehi Soee Nirabaan ||","english":"In the midst of your household, remain balanced and unattached."},{"punjabi":"ਏਕ ਊਪਰਿ ਜਿਸੁ ਜਨ ਕੀ ਆਸਾ ॥","lareedar":"ਏਕਊਪਰਿਜਿਸੁਜਨਕੀਆਸਾ ॥","translit":"Eaek Oopar Jis Jan Kee Aasaa ||","english":"One who places his hopes in the One Lord"},{"punjabi":"ਤਿਸ ਕੀ ਕਟੀਐ ਜਮ ਕੀ ਫਾਸਾ ॥","lareedar":"ਤਿਸਕੀਕਟੀਐਜਮਕੀਫਾਸਾ ॥","translit":"This Kee Katteeai Jam Kee Faasaa ||","english":"The noose of Death is cut away from his neck."},{"punjabi":"ਪਾਰਬ੍ਰਹਮ ਕੀ ਜਿਸੁ ਮਨਿ ਭੂਖ ॥","lareedar":"ਪਾਰਬ੍ਰਹਮਕੀਜਿਸੁਮਨਿਭੂਖ ॥","translit":"Paarabreham Kee Jis Man Bhookh ||","english":"One whose mind hungers for the Supreme Lord God,"},{"punjabi":"ਨਾਨਕ ਤਿਸਹਿ ਨ ਲਾਗਹਿ ਦੂਖ ॥੪॥","lareedar":"ਨਾਨਕਤਿਸਹਿਨਲਾਗਹਿਦੂਖ ॥੪ ॥","translit":"Naanak Thisehi N Laagehi Dhookh ||4||","english":"O Nanak, shall not suffer pain. ||4||"},{"punjabi":"ਜਿਸ ਕਉ ਹਰਿ ਪ੍ਰਭੁ ਮਨਿ ਚਿਤਿ ਆਵੈ ॥","lareedar":"ਜਿਸਕਉਹਰਿਪ੍ਰਭੁਮਨਿਚਿਤਿਆਵੈ ॥","translit":"Jis Ko Har Prabh Man Chith Aavai ||","english":"One who focuses his conscious mind on the Lord God"},{"punjabi":"ਸੋ ਸੰਤੁ ਸੁਹੇਲਾ ਨਹੀ ਡੁਲਾਵੈ ॥","lareedar":"ਸੋਸੰਤੁਸੁਹੇਲਾਨਹੀਡੁਲਾਵੈ ॥","translit":"So Santh Suhaelaa Nehee Ddulaavai ||","english":"- that Saint is at peace; he does not waver."},{"punjabi":"ਜਿਸੁ ਪ੍ਰਭੁ ਅਪੁਨਾ ਕਿਰਪਾ ਕਰੈ ॥","lareedar":"ਜਿਸੁਪ੍ਰਭੁਅਪੁਨਾਕਿਰਪਾਕਰੈ ॥","translit":"Jis Prabh Apunaa Kirapaa Karai ||","english":"Those unto whom God has granted His Grace"}]},{"index":47,"ang":281,"lines":[{"punjabi":"ਸੋ ਸੇਵਕੁ ਕਹੁ ਕਿਸ ਤੇ ਡਰੈ ॥","lareedar":"ਸੋਸੇਵਕੁਕਹੁਕਿਸਤੇਡਰੈ ॥","translit":"So Saevak Kahu Kis Thae Ddarai ||","english":"Who do those servants need to fear?"},{"punjabi":"ਜੈਸਾ ਸਾ ਤੈਸਾ ਦ੍ਰਿਸਟਾਇਆ ॥","lareedar":"ਜੈਸਾਸਾਤੈਸਾਦ੍ਰਿਸਟਾਇਆ ॥","translit":"Jaisaa Saa Thaisaa Dhrisattaaeiaa ||","english":"As God is, so does He appear;"},{"punjabi":"ਅਪੁਨੇ ਕਾਰਜ ਮਹਿ ਆਪਿ ਸਮਾਇਆ ॥","lareedar":"ਅਪੁਨੇਕਾਰਜਮਹਿਆਪਿਸਮਾਇਆ ॥","translit":"Apunae Kaaraj Mehi Aap Samaaeiaa ||","english":"In His Own creation, He Himself is pervading."},{"punjabi":"ਸੋਧਤ ਸੋਧਤ ਸੋਧਤ ਸੀਝਿਆ ॥","lareedar":"ਸੋਧਤਸੋਧਤਸੋਧਤਸੀਝਿਆ ॥","translit":"Sodhhath Sodhhath Sodhhath Seejhiaa ||","english":"Searching, searching, searching, and finally, success!"},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਤਤੁ ਸਭੁ ਬੂਝਿਆ ॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਤਤੁਸਭੁਬੂਝਿਆ ॥","translit":"Gur Prasaadh Thath Sabh Boojhiaa ||","english":"By Guru's Grace, the essence of all reality is understood."},{"punjabi":"ਜਬ ਦੇਖਉ ਤਬ ਸਭੁ ਕਿਛੁ ਮੂਲੁ ॥","lareedar":"ਜਬਦੇਖਉਤਬਸਭੁਕਿਛੁਮੂਲੁ ॥","translit":"Jab Dhaekho Thab Sabh Kishh Mool ||","english":"Wherever I look, there I see Him, at the root of all things."},{"punjabi":"ਨਾਨਕ ਸੋ ਸੂਖਮੁ ਸੋਈ ਅਸਥੂਲੁ ॥੫॥","lareedar":"ਨਾਨਕਸੋਸੂਖਮੁਸੋਈਅਸਥੂਲੁ ॥੫ ॥","translit":"Naanak So Sookham Soee Asathhool ||5||","english":"O Nanak, He is the subtle, and He is also the manifest. ||5||"},{"punjabi":"ਨਹ ਕਿਛੁ ਜਨਮੈ ਨਹ ਕਿਛੁ ਮਰੈ ॥","lareedar":"ਨਹਕਿਛੁਜਨਮੈਨਹਕਿਛੁਮਰੈ ॥","translit":"Neh Kishh Janamai Neh Kishh Marai ||","english":"Nothing is born, and nothing dies."},{"punjabi":"ਆਪਨ ਚਲਿਤੁ ਆਪ ਹੀ ਕਰੈ ॥","lareedar":"ਆਪਨਚਲਿਤੁਆਪਹੀਕਰੈ ॥","translit":"Aapan Chalith Aap Hee Karai ||","english":"He Himself stages His own drama."},{"punjabi":"ਆਵਨੁ ਜਾਵਨੁ ਦ੍ਰਿਸਟਿ ਅਨਦ੍ਰਿਸਟਿ ॥","lareedar":"ਆਵਨੁਜਾਵਨੁਦ੍ਰਿਸਟਿਅਨਦ੍ਰਿਸਟਿ ॥","translit":"Aavan Jaavan Dhrisatt Anadhrisatt ||","english":"Coming and going, seen and unseen,"},{"punjabi":"ਆਗਿਆਕਾਰੀ ਧਾਰੀ ਸਭ ਸ੍ਰਿਸਟਿ ॥","lareedar":"ਆਗਿਆਕਾਰੀਧਾਰੀਸਭਸ੍ਰਿਸਟਿ ॥","translit":"Aagiaakaaree Dhhaaree Sabh Srisatt ||","english":"All the world is obedient to His Will."},{"punjabi":"ਆਪੇ ਆਪਿ ਸਗਲ ਮਹਿ ਆਪਿ ॥","lareedar":"ਆਪੇਆਪਿਸਗਲਮਹਿਆਪਿ ॥","translit":"Aapae Aap Sagal Mehi Aap ||","english":"He Himself is All-in-Himself."},{"punjabi":"ਅਨਿਕ ਜੁਗਤਿ ਰਚਿ ਥਾਪਿ ਉਥਾਪਿ ॥","lareedar":"ਅਨਿਕਜੁਗਤਿਰਚਿਥਾਪਿਉਥਾਪਿ ॥","translit":"Anik Jugath Rach Thhaap Outhhaap ||","english":"In His many ways, He establishes and disestablishes."},{"punjabi":"ਅਬਿਨਾਸੀ ਨਾਹੀ ਕਿਛੁ ਖੰਡ ॥","lareedar":"ਅਬਿਨਾਸੀਨਾਹੀਕਿਛੁਖੰਡ ॥","translit":"Abinaasee Naahee Kishh Khandd ||","english":"He is Imperishable; nothing can be broken."},{"punjabi":"ਧਾਰਣ ਧਾਰਿ ਰਹਿਓ ਬ੍ਰਹਮੰਡ ॥","lareedar":"ਧਾਰਣਧਾਰਿਰਹਿਓਬ੍ਰਹਮੰਡ ॥","translit":"Dhhaaran Dhhaar Rehiou Brehamandd ||","english":"He lends His Support to maintain the Universe."},{"punjabi":"ਅਲਖ ਅਭੇਵ ਪੁਰਖ ਪਰਤਾਪ ॥","lareedar":"ਅਲਖਅਭੇਵਪੁਰਖਪਰਤਾਪ ॥","translit":"Alakh Abhaev Purakh Parathaap ||","english":"Unfathomable and Inscrutable is the Glory of the Lord."},{"punjabi":"ਆਪਿ ਜਪਾਏ ਤ ਨਾਨਕ ਜਾਪ ॥੬॥","lareedar":"ਆਪਿਜਪਾਏਤਨਾਨਕਜਾਪ ॥੬ ॥","translit":"Aap Japaaeae Th Naanak Jaap ||6||","english":"As He inspires us to meditate, O Nanak, so do we meditate. ||6||"},{"punjabi":"ਜਿਨ ਪ੍ਰਭੁ ਜਾਤਾ ਸੁ ਸੋਭਾਵੰਤ ॥","lareedar":"ਜਿਨਪ੍ਰਭੁਜਾਤਾਸੁਸੋਭਾਵੰਤ ॥","translit":"Jin Prabh Jaathaa S Sobhaavanth ||","english":"Those who know God are glorious."},{"punjabi":"ਸਗਲ ਸੰਸਾਰੁ ਉਧਰੈ ਤਿਨ ਮੰਤ ॥","lareedar":"ਸਗਲਸੰਸਾਰੁਉਧਰੈਤਿਨਮੰਤ ॥","translit":"Sagal Sansaar Oudhharai Thin Manth ||","english":"The whole world is redeemed by their teachings."},{"punjabi":"ਪ੍ਰਭ ਕੇ ਸੇਵਕ ਸਗਲ ਉਧਾਰਨ ॥","lareedar":"ਪ੍ਰਭਕੇਸੇਵਕਸਗਲਉਧਾਰਨ ॥","translit":"Prabh Kae Saevak Sagal Oudhhaaran ||","english":"God's servants redeem all."},{"punjabi":"ਪ੍ਰਭ ਕੇ ਸੇਵਕ ਦੂਖ ਬਿਸਾਰਨ ॥","lareedar":"ਪ੍ਰਭਕੇਸੇਵਕਦੂਖਬਿਸਾਰਨ ॥","translit":"Prabh Kae Saevak Dhookh Bisaaran ||","english":"God's servants cause sorrows to be forgotten."},{"punjabi":"ਆਪੇ ਮੇਲਿ ਲਏ ਕਿਰਪਾਲ ॥","lareedar":"ਆਪੇਮੇਲਿਲਏਕਿਰਪਾਲ ॥","translit":"Aapae Mael Leae Kirapaal ||","english":"The Merciful Lord unites them with Himself."},{"punjabi":"ਗੁਰ ਕਾ ਸਬਦੁ ਜਪਿ ਭਏ ਨਿਹਾਲ ॥","lareedar":"ਗੁਰਕਾਸਬਦੁਜਪਿਭਏਨਿਹਾਲ ॥","translit":"Gur Kaa Sabadh Jap Bheae Nihaal ||","english":"Chanting the Word of the Guru's Shabad, they become ecstatic."},{"punjabi":"ਉਨ ਕੀ ਸੇਵਾ ਸੋਈ ਲਾਗੈ ॥","lareedar":"ਉਨਕੀਸੇਵਾਸੋਈਲਾਗੈ ॥","translit":"Oun Kee Saevaa Soee Laagai ||","english":"He alone is committed to serve them,"},{"punjabi":"ਜਿਸ ਨੋ ਕ੍ਰਿਪਾ ਕਰਹਿ ਬਡਭਾਗੈ ॥","lareedar":"ਜਿਸਨੋਕ੍ਰਿਪਾਕਰਹਿਬਡਭਾਗੈ ॥","translit":"Jis No Kirapaa Karehi Baddabhaagai ||","english":"Upon whom God bestows His Mercy, by great good fortune."}]},{"index":48,"ang":282,"lines":[{"punjabi":"ਨਾਮੁ ਜਪਤ ਪਾਵਹਿ ਬਿਸ੍ਰਾਮੁ ॥","lareedar":"ਨਾਮੁਜਪਤਪਾਵਹਿਬਿਸ੍ਰਾਮੁ ॥","translit":"Naam Japath Paavehi Bisraam ||","english":"Those who chant the Naam find their place of rest."},{"punjabi":"ਨਾਨਕ ਤਿਨ ਪੁਰਖ ਕਉ ਊਤਮ ਕਰਿ ਮਾਨੁ ॥੭॥","lareedar":"ਨਾਨਕਤਿਨਪੁਰਖਕਉਊਤਮਕਰਿਮਾਨੁ ॥੭ ॥","translit":"Naanak Thin Purakh Ko Ootham Kar Maan ||7||","english":"O Nanak, respect those persons as the most noble. ||7||"},{"punjabi":"ਜੋ ਕਿਛੁ ਕਰੈ ਸੁ ਪ੍ਰਭ ਕੈ ਰੰਗਿ ॥","lareedar":"ਜੋਕਿਛੁਕਰੈਸੁਪ੍ਰਭਕੈਰੰਗਿ ॥","translit":"Jo Kishh Karai S Prabh Kai Rang ||","english":"Whatever you do, do it for the Love of God."},{"punjabi":"ਸਦਾ ਸਦਾ ਬਸੈ ਹਰਿ ਸੰਗਿ ॥","lareedar":"ਸਦਾਸਦਾਬਸੈਹਰਿਸੰਗਿ ॥","translit":"Sadhaa Sadhaa Basai Har Sang ||","english":"Forever and ever, abide with the Lord."},{"punjabi":"ਸਹਜ ਸੁਭਾਇ ਹੋਵੈ ਸੋ ਹੋਇ ॥","lareedar":"ਸਹਜਸੁਭਾਇਹੋਵੈਸੋਹੋਇ ॥","translit":"Sehaj Subhaae Hovai So Hoe ||","english":"By its own natural course, whatever will be will be."},{"punjabi":"ਕਰਣੈਹਾਰੁ ਪਛਾਣੈ ਸੋਇ ॥","lareedar":"ਕਰਣੈਹਾਰੁਪਛਾਣੈਸੋਇ ॥","translit":"Karanaihaar Pashhaanai Soe ||","english":"Acknowledge that Creator Lord;"},{"punjabi":"ਪ੍ਰਭ ਕਾ ਕੀਆ ਜਨ ਮੀਠ ਲਗਾਨਾ ॥","lareedar":"ਪ੍ਰਭਕਾਕੀਆਜਨਮੀਠਲਗਾਨਾ ॥","translit":"Prabh Kaa Keeaa Jan Meeth Lagaanaa ||","english":"God's doings are sweet to His humble servant."},{"punjabi":"ਜੈਸਾ ਸਾ ਤੈਸਾ ਦ੍ਰਿਸਟਾਨਾ ॥","lareedar":"ਜੈਸਾਸਾਤੈਸਾਦ੍ਰਿਸਟਾਨਾ ॥","translit":"Jaisaa Saa Thaisaa Dhrisattaanaa ||","english":"As He is, so does He appear."},{"punjabi":"ਜਿਸ ਤੇ ਉਪਜੇ ਤਿਸੁ ਮਾਹਿ ਸਮਾਏ ॥","lareedar":"ਜਿਸਤੇਉਪਜੇਤਿਸੁਮਾਹਿਸਮਾਏ ॥","translit":"Jis Thae Oupajae This Maahi Samaaeae ||","english":"From Him we came, and into Him we shall merge again."},{"punjabi":"ਓਇ ਸੁਖ ਨਿਧਾਨ ਉਨਹੂ ਬਨਿ ਆਏ ॥","lareedar":"ਓਇਸੁਖਨਿਧਾਨਉਨਹੂਬਨਿਆਏ ॥","translit":"Oue Sukh Nidhhaan Ounehoo Ban Aaeae ||","english":"He is the treasure of peace, and so does His servant become."},{"punjabi":"ਆਪਸ ਕਉ ਆਪਿ ਦੀਨੋ ਮਾਨੁ ॥","lareedar":"ਆਪਸਕਉਆਪਿਦੀਨੋਮਾਨੁ ॥","translit":"Aapas Ko Aap Dheeno Maan ||","english":"Unto His own, He has given His honor."},{"punjabi":"ਨਾਨਕ ਪ੍ਰਭ ਜਨੁ ਏਕੋ ਜਾਨੁ ॥੮॥੧੪॥","lareedar":"ਨਾਨਕਪ੍ਰਭਜਨੁਏਕੋਜਾਨੁ ॥੮ ॥੧੪ ॥","translit":"Naanak Prabh Jan Eaeko Jaan ||8||14||","english":"O Nanak, know that God and His humble servant are one and the same. ||8||14||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਸਰਬ ਕਲਾ ਭਰਪੂਰ ਪ੍ਰਭ ਬਿਰਥਾ ਜਾਨਨਹਾਰ ॥","lareedar":"ਸਰਬਕਲਾਭਰਪੂਰਪ੍ਰਭਬਿਰਥਾਜਾਨਨਹਾਰ ॥","translit":"Sarab Kalaa Bharapoor Prabh Birathhaa Jaananehaar ||","english":"God is totally imbued with all powers; He is the Knower of our troubles."},{"punjabi":"ਜਾ ਕੈ ਸਿਮਰਨਿ ਉਧਰੀਐ ਨਾਨਕ ਤਿਸੁ ਬਲਿਹਾਰ ॥੧॥","lareedar":"ਜਾਕੈਸਿਮਰਨਿਉਧਰੀਐਨਾਨਕਤਿਸੁਬਲਿਹਾਰ ॥੧ ॥","translit":"Jaa Kai Simaran Oudhhareeai Naanak This Balihaar ||1||","english":"Meditating in remembrance on Him, we are saved; Nanak is a sacrifice to Him. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਟੂਟੀ ਗਾਢਨਹਾਰ ਗੋੁਪਾਲ ॥","lareedar":"ਟੂਟੀਗਾਢਨਹਾਰਗੋੁਪਾਲ ॥","translit":"Ttoottee Gaadtanehaar Guopaal ||","english":"The Lord of the World is the Mender of the broken."},{"punjabi":"ਸਰਬ ਜੀਆ ਆਪੇ ਪ੍ਰਤਿਪਾਲ ॥","lareedar":"ਸਰਬਜੀਆਆਪੇਪ੍ਰਤਿਪਾਲ ॥","translit":"Sarab Jeeaa Aapae Prathipaal ||","english":"He Himself cherishes all beings."},{"punjabi":"ਸਗਲ ਕੀ ਚਿੰਤਾ ਜਿਸੁ ਮਨ ਮਾਹਿ ॥","lareedar":"ਸਗਲਕੀਚਿੰਤਾਜਿਸੁਮਨਮਾਹਿ ॥","translit":"Sagal Kee Chinthaa Jis Man Maahi ||","english":"The cares of all are on His Mind;"},{"punjabi":"ਤਿਸ ਤੇ ਬਿਰਥਾ ਕੋਈ ਨਾਹਿ ॥","lareedar":"ਤਿਸਤੇਬਿਰਥਾਕੋਈਨਾਹਿ ॥","translit":"This Thae Birathhaa Koee Naahi ||","english":"No one is turned away from Him."},{"punjabi":"ਰੇ ਮਨ ਮੇਰੇ ਸਦਾ ਹਰਿ ਜਾਪਿ ॥","lareedar":"ਰੇਮਨਮੇਰੇਸਦਾਹਰਿਜਾਪਿ ॥","translit":"Rae Man Maerae Sadhaa Har Jaap ||","english":"O my mind, meditate forever on the Lord."},{"punjabi":"ਅਬਿਨਾਸੀ ਪ੍ਰਭੁ ਆਪੇ ਆਪਿ ॥","lareedar":"ਅਬਿਨਾਸੀਪ੍ਰਭੁਆਪੇਆਪਿ ॥","translit":"Abinaasee Prabh Aapae Aap ||","english":"The Imperishable Lord God is Himself All-in-all."},{"punjabi":"ਆਪਨ ਕੀਆ ਕਛੂ ਨ ਹੋਇ ॥","lareedar":"ਆਪਨਕੀਆਕਛੂਨਹੋਇ ॥","translit":"Aapan Keeaa Kashhoo N Hoe ||","english":"By one's own actions, nothing is accomplished,"},{"punjabi":"ਜੇ ਸਉ ਪ੍ਰਾਨੀ ਲੋਚੈ ਕੋਇ ॥","lareedar":"ਜੇਸਉਪ੍ਰਾਨੀਲੋਚੈਕੋਇ ॥","translit":"Jae So Praanee Lochai Koe ||","english":"Even though the mortal may wish it so, hundreds of times."},{"punjabi":"ਤਿਸੁ ਬਿਨੁ ਨਾਹੀ ਤੇਰੈ ਕਿਛੁ ਕਾਮ ॥","lareedar":"ਤਿਸੁਬਿਨੁਨਾਹੀਤੇਰੈਕਿਛੁਕਾਮ ॥","translit":"This Bin Naahee Thaerai Kishh Kaam ||","english":"Without Him, nothing is of any use to you."}]},{"index":49,"ang":282,"lines":[{"punjabi":"ਗਤਿ ਨਾਨਕ ਜਪਿ ਏਕ ਹਰਿ ਨਾਮ ॥੧॥","lareedar":"ਗਤਿਨਾਨਕਜਪਿਏਕਹਰਿਨਾਮ ॥੧ ॥","translit":"Gath Naanak Jap Eaek Har Naam ||1||","english":"Salvation, O Nanak, is attained by chanting the Name of the One Lord. ||1||"},{"punjabi":"ਰੂਪਵੰਤੁ ਹੋਇ ਨਾਹੀ ਮੋਹੈ ॥","lareedar":"ਰੂਪਵੰਤੁਹੋਇਨਾਹੀਮੋਹੈ ॥","translit":"Roopavanth Hoe Naahee Mohai ||","english":"One who is good-looking should not be vain;"},{"punjabi":"ਪ੍ਰਭ ਕੀ ਜੋਤਿ ਸਗਲ ਘਟ ਸੋਹੈ ॥","lareedar":"ਪ੍ਰਭਕੀਜੋਤਿਸਗਲਘਟਸੋਹੈ ॥","translit":"Prabh Kee Joth Sagal Ghatt Sohai ||","english":"The Light of God is in all hearts."},{"punjabi":"ਧਨਵੰਤਾ ਹੋਇ ਕਿਆ ਕੋ ਗਰਬੈ ॥","lareedar":"ਧਨਵੰਤਾਹੋਇਕਿਆਕੋਗਰਬੈ ॥","translit":"Dhhanavanthaa Hoe Kiaa Ko Garabai ||","english":"Why should anyone be proud of being rich?"},{"punjabi":"ਜਾ ਸਭੁ ਕਿਛੁ ਤਿਸ ਕਾ ਦੀਆ ਦਰਬੈ ॥","lareedar":"ਜਾਸਭੁਕਿਛੁਤਿਸਕਾਦੀਆਦਰਬੈ ॥","translit":"Jaa Sabh Kishh This Kaa Dheeaa Dharabai ||","english":"All riches are His gifts."},{"punjabi":"ਅਤਿ ਸੂਰਾ ਜੇ ਕੋਊ ਕਹਾਵੈ ॥","lareedar":"ਅਤਿਸੂਰਾਜੇਕੋਊਕਹਾਵੈ ॥","translit":"Ath Sooraa Jae Kooo Kehaavai ||","english":"One may call himself a great hero,"},{"punjabi":"ਪ੍ਰਭ ਕੀ ਕਲਾ ਬਿਨਾ ਕਹ ਧਾਵੈ ॥","lareedar":"ਪ੍ਰਭਕੀਕਲਾਬਿਨਾਕਹਧਾਵੈ ॥","translit":"Prabh Kee Kalaa Binaa Keh Dhhaavai ||","english":"But without God's Power, what can anyone do?"},{"punjabi":"ਜੇ ਕੋ ਹੋਇ ਬਹੈ ਦਾਤਾਰੁ ॥","lareedar":"ਜੇਕੋਹੋਇਬਹੈਦਾਤਾਰੁ ॥","translit":"Jae Ko Hoe Behai Dhaathaar ||","english":"One who brags about giving to charities"},{"punjabi":"ਤਿਸੁ ਦੇਨਹਾਰੁ ਜਾਨੈ ਗਾਵਾਰੁ ॥","lareedar":"ਤਿਸੁਦੇਨਹਾਰੁਜਾਨੈਗਾਵਾਰੁ ॥","translit":"This Dhaenehaar Jaanai Gaavaar ||","english":"The Great Giver shall judge him to be a fool."},{"punjabi":"ਜਿਸੁ ਗੁਰ ਪ੍ਰਸਾਦਿ ਤੂਟੈ ਹਉ ਰੋਗੁ ॥","lareedar":"ਜਿਸੁਗੁਰਪ੍ਰਸਾਦਿਤੂਟੈਹਉਰੋਗੁ ॥","translit":"Jis Gur Prasaadh Thoottai Ho Rog ||","english":"One who, by Guru's Grace, is cured of the disease of ego"},{"punjabi":"ਨਾਨਕ ਸੋ ਜਨੁ ਸਦਾ ਅਰੋਗੁ ॥੨॥","lareedar":"ਨਾਨਕਸੋਜਨੁਸਦਾਅਰੋਗੁ ॥੨ ॥","translit":"Naanak So Jan Sadhaa Arog ||2||","english":"- O Nanak, that person is forever healthy. ||2||"},{"punjabi":"ਜਿਉ ਮੰਦਰ ਕਉ ਥਾਮੈ ਥੰਮਨੁ ॥","lareedar":"ਜਿਉਮੰਦਰਕਉਥਾਮੈਥੰਮਨੁ ॥","translit":"Jio Mandhar Ko Thhaamai Thhanman ||","english":"As a palace is supported by its pillars,"},{"punjabi":"ਤਿਉ ਗੁਰ ਕਾ ਸਬਦੁ ਮਨਹਿ ਅਸਥੰਮਨੁ ॥","lareedar":"ਤਿਉਗੁਰਕਾਸਬਦੁਮਨਹਿਅਸਥੰਮਨੁ ॥","translit":"Thio Gur Kaa Sabadh Manehi Asathhanman ||","english":"So does the Guru's Word support the mind."},{"punjabi":"ਜਿਉ ਪਾਖਾਣੁ ਨਾਵ ਚੜਿ ਤਰੈ ॥","lareedar":"ਜਿਉਪਾਖਾਣੁਨਾਵਚੜਿਤਰੈ ॥","translit":"Jio Paakhaan Naav Charr Tharai ||","english":"As a stone placed in a boat can cross over the river,"},{"punjabi":"ਪ੍ਰਾਣੀ ਗੁਰ ਚਰਣ ਲਗਤੁ ਨਿਸਤਰੈ ॥","lareedar":"ਪ੍ਰਾਣੀਗੁਰਚਰਣਲਗਤੁਨਿਸਤਰੈ ॥","translit":"Praanee Gur Charan Lagath Nisatharai ||","english":"So is the mortal saved, grasping hold of the Guru's Feet."},{"punjabi":"ਜਿਉ ਅੰਧਕਾਰ ਦੀਪਕ ਪਰਗਾਸੁ ॥","lareedar":"ਜਿਉਅੰਧਕਾਰਦੀਪਕਪਰਗਾਸੁ ॥","translit":"Jio Andhhakaar Dheepak Paragaas ||","english":"As the darkness is illuminated by the lamp,"},{"punjabi":"ਗੁਰ ਦਰਸਨੁ ਦੇਖਿ ਮਨਿ ਹੋਇ ਬਿਗਾਸੁ ॥","lareedar":"ਗੁਰਦਰਸਨੁਦੇਖਿਮਨਿਹੋਇਬਿਗਾਸੁ ॥","translit":"Gur Dharasan Dhaekh Man Hoe Bigaas ||","english":"So does the mind blossom forth, beholding the Blessed Vision of the Guru's Darshan."},{"punjabi":"ਜਿਉ ਮਹਾ ਉਦਿਆਨ ਮਹਿ ਮਾਰਗੁ ਪਾਵੈ ॥","lareedar":"ਜਿਉਮਹਾਉਦਿਆਨਮਹਿਮਾਰਗੁਪਾਵੈ ॥","translit":"Jio Mehaa Oudhiaan Mehi Maarag Paavai ||","english":"The path is found through the great wilderness by joining the Saadh Sangat,"},{"punjabi":"ਤਿਉ ਸਾਧੂ ਸੰਗਿ ਮਿਲਿ ਜੋਤਿ ਪ੍ਰਗਟਾਵੈ ॥","lareedar":"ਤਿਉਸਾਧੂਸੰਗਿਮਿਲਿਜੋਤਿਪ੍ਰਗਟਾਵੈ ॥","translit":"Thio Saadhhoo Sang Mil Joth Pragattaavai ||","english":"The Company of the Holy, and one's light shines forth."},{"punjabi":"ਤਿਨ ਸੰਤਨ ਕੀ ਬਾਛਉ ਧੂਰਿ ॥","lareedar":"ਤਿਨਸੰਤਨਕੀਬਾਛਉਧੂਰਿ ॥","translit":"Thin Santhan Kee Baashho Dhhoor ||","english":"I seek the dust of the feet of those Saints;"},{"punjabi":"ਨਾਨਕ ਕੀ ਹਰਿ ਲੋਚਾ ਪੂਰਿ ॥੩॥","lareedar":"ਨਾਨਕਕੀਹਰਿਲੋਚਾਪੂਰਿ ॥੩ ॥","translit":"Naanak Kee Har Lochaa Poor ||3||","english":"O Lord, fulfill Nanak's longing! ||3||"},{"punjabi":"ਮਨ ਮੂਰਖ ਕਾਹੇ ਬਿਲਲਾਈਐ ॥","lareedar":"ਮਨਮੂਰਖਕਾਹੇਬਿਲਲਾਈਐ ॥","translit":"Man Moorakh Kaahae Bilalaaeeai ||","english":"O foolish mind, why do you cry and bewail?"},{"punjabi":"ਪੁਰਬ ਲਿਖੇ ਕਾ ਲਿਖਿਆ ਪਾਈਐ ॥","lareedar":"ਪੁਰਬਲਿਖੇਕਾਲਿਖਿਆਪਾਈਐ ॥","translit":"Purab Likhae Kaa Likhiaa Paaeeai ||","english":"You shall obtain your pre-ordained destiny."},{"punjabi":"ਦੂਖ ਸੂਖ ਪ੍ਰਭ ਦੇਵਨਹਾਰੁ ॥","lareedar":"ਦੂਖਸੂਖਪ੍ਰਭਦੇਵਨਹਾਰੁ ॥","translit":"Dhookh Sookh Prabh Dhaevanehaar ||","english":"God is the Giver of pain and pleasure."},{"punjabi":"ਅਵਰ ਤਿਆਗਿ ਤੂ ਤਿਸਹਿ ਚਿਤਾਰੁ ॥","lareedar":"ਅਵਰਤਿਆਗਿਤੂਤਿਸਹਿਚਿਤਾਰੁ ॥","translit":"Avar Thiaag Thoo Thisehi Chithaar ||","english":"Abandon others, and think of Him alone."}]},{"index":50,"ang":283,"lines":[{"punjabi":"ਜੋ ਕਛੁ ਕਰੈ ਸੋਈ ਸੁਖੁ ਮਾਨੁ ॥","lareedar":"ਜੋਕਛੁਕਰੈਸੋਈਸੁਖੁਮਾਨੁ ॥","translit":"Jo Kashh Karai Soee Sukh Maan ||","english":"Whatever He does - take comfort in that."},{"punjabi":"ਭੂਲਾ ਕਾਹੇ ਫਿਰਹਿ ਅਜਾਨ ॥","lareedar":"ਭੂਲਾਕਾਹੇਫਿਰਹਿਅਜਾਨ ॥","translit":"Bhoolaa Kaahae Firehi Ajaan ||","english":"Why do you wander around, you ignorant fool?"},{"punjabi":"ਕਉਨ ਬਸਤੁ ਆਈ ਤੇਰੈ ਸੰਗ ॥","lareedar":"ਕਉਨਬਸਤੁਆਈਤੇਰੈਸੰਗ ॥","translit":"Koun Basath Aaee Thaerai Sang ||","english":"What things did you bring with you?"},{"punjabi":"ਲਪਟਿ ਰਹਿਓ ਰਸਿ ਲੋਭੀ ਪਤੰਗ ॥","lareedar":"ਲਪਟਿਰਹਿਓਰਸਿਲੋਭੀਪਤੰਗ ॥","translit":"Lapatt Rehiou Ras Lobhee Pathang ||","english":"You cling to worldly pleasures like a greedy moth."},{"punjabi":"ਰਾਮ ਨਾਮ ਜਪਿ ਹਿਰਦੇ ਮਾਹਿ ॥","lareedar":"ਰਾਮਨਾਮਜਪਿਹਿਰਦੇਮਾਹਿ ॥","translit":"Raam Naam Jap Hiradhae Maahi ||","english":"Dwell upon the Lord's Name in your heart."},{"punjabi":"ਨਾਨਕ ਪਤਿ ਸੇਤੀ ਘਰਿ ਜਾਹਿ ॥੪॥","lareedar":"ਨਾਨਕਪਤਿਸੇਤੀਘਰਿਜਾਹਿ ॥੪ ॥","translit":"Naanak Path Saethee Ghar Jaahi ||4||","english":"O Nanak, thus you shall return to your home with honor. ||4||"},{"punjabi":"ਜਿਸੁ ਵਖਰ ਕਉ ਲੈਨਿ ਤੂ ਆਇਆ ॥","lareedar":"ਜਿਸੁਵਖਰਕਉਲੈਨਿਤੂਆਇਆ ॥","translit":"Jis Vakhar Ko Lain Thoo Aaeiaa ||","english":"This merchandise, which you have come to obtai"},{"punjabi":"ਰਾਮ ਨਾਮੁ ਸੰਤਨ ਘਰਿ ਪਾਇਆ ॥","lareedar":"ਰਾਮਨਾਮੁਸੰਤਨਘਰਿਪਾਇਆ ॥","translit":"Raam Naam Santhan Ghar Paaeiaa ||","english":"N - the Lord's Name is obtained in the home of the Saints."},{"punjabi":"ਤਜਿ ਅਭਿਮਾਨੁ ਲੇਹੁ ਮਨ ਮੋਲਿ ॥","lareedar":"ਤਜਿਅਭਿਮਾਨੁਲੇਹੁਮਨਮੋਲਿ ॥","translit":"Thaj Abhimaan Laehu Man Mol ||","english":"Renounce your egotistical pride, and with your mind,"},{"punjabi":"ਰਾਮ ਨਾਮੁ ਹਿਰਦੇ ਮਹਿ ਤੋਲਿ ॥","lareedar":"ਰਾਮਨਾਮੁਹਿਰਦੇਮਹਿਤੋਲਿ ॥","translit":"Raam Naam Hiradhae Mehi Thol ||","english":"Purchase the Lord's Name - measure it out within your heart."},{"punjabi":"ਲਾਦਿ ਖੇਪ ਸੰਤਹ ਸੰਗਿ ਚਾਲੁ ॥","lareedar":"ਲਾਦਿਖੇਪਸੰਤਹਸੰਗਿਚਾਲੁ ॥","translit":"Laadh Khaep Santheh Sang Chaal ||","english":"Load up this merchandise, and set out with the Saints."},{"punjabi":"ਅਵਰ ਤਿਆਗਿ ਬਿਖਿਆ ਜੰਜਾਲ ॥","lareedar":"ਅਵਰਤਿਆਗਿਬਿਖਿਆਜੰਜਾਲ ॥","translit":"Avar Thiaag Bikhiaa Janjaal ||","english":"Give up other corrupt entanglements."},{"punjabi":"ਧੰਨਿ ਧੰਨਿ ਕਹੈ ਸਭੁ ਕੋਇ ॥","lareedar":"ਧੰਨਿਧੰਨਿਕਹੈਸਭੁਕੋਇ ॥","translit":"Dhhann Dhhann Kehai Sabh Koe ||","english":"\"Blessed, blessed\", everyone will call you,"},{"punjabi":"ਮੁਖ ਊਜਲ ਹਰਿ ਦਰਗਹ ਸੋਇ ॥","lareedar":"ਮੁਖਊਜਲਹਰਿਦਰਗਹਸੋਇ ॥","translit":"Mukh Oojal Har Dharageh Soe ||","english":"And your face shall be radiant in the Court of the Lord."},{"punjabi":"ਇਹੁ ਵਾਪਾਰੁ ਵਿਰਲਾ ਵਾਪਾਰੈ ॥","lareedar":"ਇਹੁਵਾਪਾਰੁਵਿਰਲਾਵਾਪਾਰੈ ॥","translit":"Eihu Vaapaar Viralaa Vaapaarai ||","english":"In this trade, only a few are trading."},{"punjabi":"ਨਾਨਕ ਤਾ ਕੈ ਸਦ ਬਲਿਹਾਰੈ ॥੫॥","lareedar":"ਨਾਨਕਤਾਕੈਸਦਬਲਿਹਾਰੈ ॥੫ ॥","translit":"Naanak Thaa Kai Sadh Balihaarai ||5||","english":"Nanak is forever a sacrifice to them. ||5||"},{"punjabi":"ਚਰਨ ਸਾਧ ਕੇ ਧੋਇ ਧੋਇ ਪੀਉ ॥","lareedar":"ਚਰਨਸਾਧਕੇਧੋਇਧੋਇਪੀਉ ॥","translit":"Charan Saadhh Kae Dhhoe Dhhoe Peeo ||","english":"Wash the feet of the Holy, and drink in this water."},{"punjabi":"ਅਰਪਿ ਸਾਧ ਕਉ ਅਪਨਾ ਜੀਉ ॥","lareedar":"ਅਰਪਿਸਾਧਕਉਅਪਨਾਜੀਉ ॥","translit":"Arap Saadhh Ko Apanaa Jeeo ||","english":"Dedicate your soul to the Holy."},{"punjabi":"ਸਾਧ ਕੀ ਧੂਰਿ ਕਰਹੁ ਇਸਨਾਨੁ ॥","lareedar":"ਸਾਧਕੀਧੂਰਿਕਰਹੁਇਸਨਾਨੁ ॥","translit":"Saadhh Kee Dhhoor Karahu Eisanaan ||","english":"Take your cleansing bath in the dust of the feet of the Holy."},{"punjabi":"ਸਾਧ ਊਪਰਿ ਜਾਈਐ ਕੁਰਬਾਨੁ ॥","lareedar":"ਸਾਧਊਪਰਿਜਾਈਐਕੁਰਬਾਨੁ ॥","translit":"Saadhh Oopar Jaaeeai Kurabaan ||","english":"To the Holy, make your life a sacrifice."},{"punjabi":"ਸਾਧ ਸੇਵਾ ਵਡਭਾਗੀ ਪਾਈਐ ॥","lareedar":"ਸਾਧਸੇਵਾਵਡਭਾਗੀਪਾਈਐ ॥","translit":"Saadhh Saevaa Vaddabhaagee Paaeeai ||","english":"Service to the Holy is obtained by great good fortune."},{"punjabi":"ਸਾਧਸੰਗਿ ਹਰਿ ਕੀਰਤਨੁ ਗਾਈਐ ॥","lareedar":"ਸਾਧਸੰਗਿਹਰਿਕੀਰਤਨੁਗਾਈਐ ॥","translit":"Saadhhasang Har Keerathan Gaaeeai ||","english":"In the Saadh Sangat, the Company of the Holy, the Kirtan of the Lord's Praise is sung."},{"punjabi":"ਅਨਿਕ ਬਿਘਨ ਤੇ ਸਾਧੂ ਰਾਖੈ ॥","lareedar":"ਅਨਿਕਬਿਘਨਤੇਸਾਧੂਰਾਖੈ ॥","translit":"Anik Bighan Thae Saadhhoo Raakhai ||","english":"From all sorts of dangers, the Saint saves us."},{"punjabi":"ਹਰਿ ਗੁਨ ਗਾਇ ਅੰਮ੍ਰਿਤ ਰਸੁ ਚਾਖੈ ॥","lareedar":"ਹਰਿਗੁਨਗਾਇਅੰਮ੍ਰਿਤਰਸੁਚਾਖੈ ॥","translit":"Har Gun Gaae Anmrith Ras Chaakhai ||","english":"Singing the Glorious Praises of the Lord, we taste the ambrosial essence."},{"punjabi":"ਓਟ ਗਹੀ ਸੰਤਹ ਦਰਿ ਆਇਆ ॥","lareedar":"ਓਟਗਹੀਸੰਤਹਦਰਿਆਇਆ ॥","translit":"Outt Gehee Santheh Dhar Aaeiaa ||","english":"Seeking the Protection of the Saints, we have come to their door."}]},{"index":51,"ang":283,"lines":[{"punjabi":"ਸਰਬ ਸੂਖ ਨਾਨਕ ਤਿਹ ਪਾਇਆ ॥੬॥","lareedar":"ਸਰਬਸੂਖਨਾਨਕਤਿਹਪਾਇਆ ॥੬ ॥","translit":"Sarab Sookh Naanak Thih Paaeiaa ||6||","english":"All comforts, O Nanak, are so obtained. ||6||"},{"punjabi":"ਮਿਰਤਕ ਕਉ ਜੀਵਾਲਨਹਾਰ ॥","lareedar":"ਮਿਰਤਕਕਉਜੀਵਾਲਨਹਾਰ ॥","translit":"Mirathak Ko Jeevaalanehaar ||","english":"He infuses life back into the dead."},{"punjabi":"ਭੂਖੇ ਕਉ ਦੇਵਤ ਅਧਾਰ ॥","lareedar":"ਭੂਖੇਕਉਦੇਵਤਅਧਾਰ ॥","translit":"Bhookhae Ko Dhaevath Adhhaar ||","english":"He gives food to the hungry."},{"punjabi":"ਸਰਬ ਨਿਧਾਨ ਜਾ ਕੀ ਦ੍ਰਿਸਟੀ ਮਾਹਿ ॥","lareedar":"ਸਰਬਨਿਧਾਨਜਾਕੀਦ੍ਰਿਸਟੀਮਾਹਿ ॥","translit":"Sarab Nidhhaan Jaa Kee Dhrisattee Maahi ||","english":"All treasures are within His Glance of Grace."},{"punjabi":"ਪੁਰਬ ਲਿਖੇ ਕਾ ਲਹਣਾ ਪਾਹਿ ॥","lareedar":"ਪੁਰਬਲਿਖੇਕਾਲਹਣਾਪਾਹਿ ॥","translit":"Purab Likhae Kaa Lehanaa Paahi ||","english":"People obtain that which they are pre-ordained to receive."},{"punjabi":"ਸਭੁ ਕਿਛੁ ਤਿਸ ਕਾ ਓਹੁ ਕਰਨੈ ਜੋਗੁ ॥","lareedar":"ਸਭੁਕਿਛੁਤਿਸਕਾਓਹੁਕਰਨੈਜੋਗੁ ॥","translit":"Sabh Kishh This Kaa Ouhu Karanai Jog ||","english":"All things are His; He is the Doer of all."},{"punjabi":"ਤਿਸੁ ਬਿਨੁ ਦੂਸਰ ਹੋਆ ਨ ਹੋਗੁ ॥","lareedar":"ਤਿਸੁਬਿਨੁਦੂਸਰਹੋਆਨਹੋਗੁ ॥","translit":"This Bin Dhoosar Hoaa N Hog ||","english":"Other than Him, there has never been any other, and there shall never be."},{"punjabi":"ਜਪਿ ਜਨ ਸਦਾ ਸਦਾ ਦਿਨੁ ਰੈਣੀ ॥","lareedar":"ਜਪਿਜਨਸਦਾਸਦਾਦਿਨੁਰੈਣੀ ॥","translit":"Jap Jan Sadhaa Sadhaa Dhin Rainee ||","english":"Meditate on Him forever and ever, day and night."},{"punjabi":"ਸਭ ਤੇ ਊਚ ਨਿਰਮਲ ਇਹ ਕਰਣੀ ॥","lareedar":"ਸਭਤੇਊਚਨਿਰਮਲਇਹਕਰਣੀ ॥","translit":"Sabh Thae Ooch Niramal Eih Karanee ||","english":"This way of life is exalted and immaculate."},{"punjabi":"ਕਰਿ ਕਿਰਪਾ ਜਿਸ ਕਉ ਨਾਮੁ ਦੀਆ ॥","lareedar":"ਕਰਿਕਿਰਪਾਜਿਸਕਉਨਾਮੁਦੀਆ ॥","translit":"Kar Kirapaa Jis Ko Naam Dheeaa ||","english":"One whom the Lord, in His Grace, blesses with His Name"},{"punjabi":"ਨਾਨਕ ਸੋ ਜਨੁ ਨਿਰਮਲੁ ਥੀਆ ॥੭॥","lareedar":"ਨਾਨਕਸੋਜਨੁਨਿਰਮਲੁਥੀਆ ॥੭ ॥","translit":"Naanak So Jan Niramal Thheeaa ||7||","english":"- O Nanak, that person becomes immaculate and pure. ||7||"},{"punjabi":"ਜਾ ਕੈ ਮਨਿ ਗੁਰ ਕੀ ਪਰਤੀਤਿ ॥","lareedar":"ਜਾਕੈਮਨਿਗੁਰਕੀਪਰਤੀਤਿ ॥","translit":"Jaa Kai Man Gur Kee Paratheeth ||","english":"One who has faith in the Guru in his mind"},{"punjabi":"ਤਿਸੁ ਜਨ ਆਵੈ ਹਰਿ ਪ੍ਰਭੁ ਚੀਤਿ ॥","lareedar":"ਤਿਸੁਜਨਆਵੈਹਰਿਪ੍ਰਭੁਚੀਤਿ ॥","translit":"This Jan Aavai Har Prabh Cheeth ||","english":"Comes to dwell upon the Lord God."},{"punjabi":"ਭਗਤੁ ਭਗਤੁ ਸੁਨੀਐ ਤਿਹੁ ਲੋਇ ॥","lareedar":"ਭਗਤੁਭਗਤੁਸੁਨੀਐਤਿਹੁਲੋਇ ॥","translit":"Bhagath Bhagath Suneeai Thihu Loe ||","english":"He is acclaimed as a devotee, a humble devotee throughout the three worlds."},{"punjabi":"ਜਾ ਕੈ ਹਿਰਦੈ ਏਕੋ ਹੋਇ ॥","lareedar":"ਜਾਕੈਹਿਰਦੈਏਕੋਹੋਇ ॥","translit":"Jaa Kai Hiradhai Eaeko Hoe ||","english":"The One Lord is in his heart."},{"punjabi":"ਸਚੁ ਕਰਣੀ ਸਚੁ ਤਾ ਕੀ ਰਹਤ ॥","lareedar":"ਸਚੁਕਰਣੀਸਚੁਤਾਕੀਰਹਤ ॥","translit":"Sach Karanee Sach Thaa Kee Rehath ||","english":"True are his actions; true are his ways."},{"punjabi":"ਸਚੁ ਹਿਰਦੈ ਸਤਿ ਮੁਖਿ ਕਹਤ ॥","lareedar":"ਸਚੁਹਿਰਦੈਸਤਿਮੁਖਿਕਹਤ ॥","translit":"Sach Hiradhai Sath Mukh Kehath ||","english":"True is his heart; Truth is what he speaks with his mouth."},{"punjabi":"ਸਾਚੀ ਦ੍ਰਿਸਟਿ ਸਾਚਾ ਆਕਾਰੁ ॥","lareedar":"ਸਾਚੀਦ੍ਰਿਸਟਿਸਾਚਾਆਕਾਰੁ ॥","translit":"Saachee Dhrisatt Saachaa Aakaar ||","english":"True is his vision; true is his form."},{"punjabi":"ਸਚੁ ਵਰਤੈ ਸਾਚਾ ਪਾਸਾਰੁ ॥","lareedar":"ਸਚੁਵਰਤੈਸਾਚਾਪਾਸਾਰੁ ॥","translit":"Sach Varathai Saachaa Paasaar ||","english":"He distributes Truth and he spreads Truth."},{"punjabi":"ਪਾਰਬ੍ਰਹਮੁ ਜਿਨਿ ਸਚੁ ਕਰਿ ਜਾਤਾ ॥","lareedar":"ਪਾਰਬ੍ਰਹਮੁਜਿਨਿਸਚੁਕਰਿਜਾਤਾ ॥","translit":"Paarabreham Jin Sach Kar Jaathaa ||","english":"One who recognizes the Supreme Lord God as True"},{"punjabi":"ਨਾਨਕ ਸੋ ਜਨੁ ਸਚਿ ਸਮਾਤਾ ॥੮॥੧੫॥","lareedar":"ਨਾਨਕਸੋਜਨੁਸਚਿਸਮਾਤਾ ॥੮ ॥੧੫ ॥","translit":"Naanak So Jan Sach Samaathaa ||8||15||","english":"- O Nanak, that humble being is absorbed into the True One. ||8||15||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਰੂਪੁ ਨ ਰੇਖ ਨ ਰੰਗੁ ਕਿਛੁ ਤ੍ਰਿਹੁ ਗੁਣ ਤੇ ਪ੍ਰਭ ਭਿੰਨ ॥","lareedar":"ਰੂਪੁਨਰੇਖਨਰੰਗੁਕਿਛੁਤ੍ਰਿਹੁਗੁਣਤੇਪ੍ਰਭਭਿੰਨ ॥","translit":"Roop N Raekh N Rang Kishh Thrihu Gun Thae Prabh Bhinn ||","english":"He has no form, no shape, no color; God is beyond the three qualities."},{"punjabi":"ਤਿਸਹਿ ਬੁਝਾਏ ਨਾਨਕਾ ਜਿਸੁ ਹੋਵੈ ਸੁਪ੍ਰਸੰਨ ॥੧॥","lareedar":"ਤਿਸਹਿਬੁਝਾਏਨਾਨਕਾਜਿਸੁਹੋਵੈਸੁਪ੍ਰਸੰਨ ॥੧ ॥","translit":"Thisehi Bujhaaeae Naanakaa Jis Hovai Suprasann ||1||","english":"They alone understand Him, O Nanak, with whom He is pleased. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"}]},{"index":52,"ang":283,"lines":[{"punjabi":"ਅਬਿਨਾਸੀ ਪ੍ਰਭੁ ਮਨ ਮਹਿ ਰਾਖੁ ॥","lareedar":"ਅਬਿਨਾਸੀਪ੍ਰਭੁਮਨਮਹਿਰਾਖੁ ॥","translit":"Abinaasee Prabh Man Mehi Raakh ||","english":"Keep the Immortal Lord God enshrined within your mind."},{"punjabi":"ਮਾਨੁਖ ਕੀ ਤੂ ਪ੍ਰੀਤਿ ਤਿਆਗੁ ॥","lareedar":"ਮਾਨੁਖਕੀਤੂਪ੍ਰੀਤਿਤਿਆਗੁ ॥","translit":"Maanukh Kee Thoo Preeth Thiaag ||","english":"Renounce your love and attachment to people."},{"punjabi":"ਤਿਸ ਤੇ ਪਰੈ ਨਾਹੀ ਕਿਛੁ ਕੋਇ ॥","lareedar":"ਤਿਸਤੇਪਰੈਨਾਹੀਕਿਛੁਕੋਇ ॥","translit":"This Thae Parai Naahee Kishh Koe ||","english":"Beyond Him, there is nothing at all."},{"punjabi":"ਸਰਬ ਨਿਰੰਤਰਿ ਏਕੋ ਸੋਇ ॥","lareedar":"ਸਰਬਨਿਰੰਤਰਿਏਕੋਸੋਇ ॥","translit":"Sarab Niranthar Eaeko Soe ||","english":"The One Lord is pervading among all."},{"punjabi":"ਆਪੇ ਬੀਨਾ ਆਪੇ ਦਾਨਾ ॥","lareedar":"ਆਪੇਬੀਨਾਆਪੇਦਾਨਾ ॥","translit":"Aapae Beenaa Aapae Dhaanaa ||","english":"He Himself is All-seeing; He Himself is All-knowing,"},{"punjabi":"ਗਹਿਰ ਗੰਭੀਰੁ ਗਹੀਰੁ ਸੁਜਾਨਾ ॥","lareedar":"ਗਹਿਰਗੰਭੀਰੁਗਹੀਰੁਸੁਜਾਨਾ ॥","translit":"Gehir Ganbheer Geheer Sujaanaa ||","english":"Unfathomable, Profound, Deep and All-knowing."},{"punjabi":"ਪਾਰਬ੍ਰਹਮ ਪਰਮੇਸੁਰ ਗੋਬਿੰਦ ॥","lareedar":"ਪਾਰਬ੍ਰਹਮਪਰਮੇਸੁਰਗੋਬਿੰਦ ॥","translit":"Paarabreham Paramaesur Gobindh ||","english":"He is the Supreme Lord God, the Transcendent Lord, the Lord of the Universe,"},{"punjabi":"ਕ੍ਰਿਪਾ ਨਿਧਾਨ ਦਇਆਲ ਬਖਸੰਦ ॥","lareedar":"ਕ੍ਰਿਪਾਨਿਧਾਨਦਇਆਲਬਖਸੰਦ ॥","translit":"Kirapaa Nidhhaan Dhaeiaal Bakhasandh ||","english":"The Treasure of mercy, compassion and forgiveness."},{"punjabi":"ਸਾਧ ਤੇਰੇ ਕੀ ਚਰਨੀ ਪਾਉ ॥","lareedar":"ਸਾਧਤੇਰੇਕੀਚਰਨੀਪਾਉ ॥","translit":"Saadhh Thaerae Kee Charanee Paao ||","english":"To fall at the Feet of Your Holy Beings"},{"punjabi":"ਨਾਨਕ ਕੈ ਮਨਿ ਇਹੁ ਅਨਰਾਉ ॥੧॥","lareedar":"ਨਾਨਕਕੈਮਨਿਇਹੁਅਨਰਾਉ ॥੧ ॥","translit":"Naanak Kai Man Eihu Anaraao ||1||","english":"- this is the longing of Nanak's mind. ||1||"},{"punjabi":"ਮਨਸਾ ਪੂਰਨ ਸਰਨਾ ਜੋਗ ॥","lareedar":"ਮਨਸਾਪੂਰਨਸਰਨਾਜੋਗ ॥","translit":"Manasaa Pooran Saranaa Jog ||","english":"He is the Fulfiller of wishes, who can give us Sanctuary;"},{"punjabi":"ਜੋ ਕਰਿ ਪਾਇਆ ਸੋਈ ਹੋਗੁ ॥","lareedar":"ਜੋਕਰਿਪਾਇਆਸੋਈਹੋਗੁ ॥","translit":"Jo Kar Paaeiaa Soee Hog ||","english":"That which He has written, comes to pass."},{"punjabi":"ਹਰਨ ਭਰਨ ਜਾ ਕਾ ਨੇਤ੍ਰ ਫੋਰੁ ॥","lareedar":"ਹਰਨਭਰਨਜਾਕਾਨੇਤ੍ਰਫੋਰੁ ॥","translit":"Haran Bharan Jaa Kaa Naethr For ||","english":"He destroys and creates in the twinkling of an eye."},{"punjabi":"ਤਿਸ ਕਾ ਮੰਤ੍ਰੁ ਨ ਜਾਨੈ ਹੋਰੁ ॥","lareedar":"ਤਿਸਕਾਮੰਤ੍ਰੁਨਜਾਨੈਹੋਰੁ ॥","translit":"This Kaa Manthra N Jaanai Hor ||","english":"No one else knows the mystery of His ways."},{"punjabi":"ਅਨਦ ਰੂਪ ਮੰਗਲ ਸਦ ਜਾ ਕੈ ॥","lareedar":"ਅਨਦਰੂਪਮੰਗਲਸਦਜਾਕੈ ॥","translit":"Anadh Roop Mangal Sadh Jaa Kai ||","english":"He is the embodiment of ecstasy and everlasting joy."},{"punjabi":"ਸਰਬ ਥੋਕ ਸੁਨੀਅਹਿ ਘਰਿ ਤਾ ਕੈ ॥","lareedar":"ਸਰਬਥੋਕਸੁਨੀਅਹਿਘਰਿਤਾਕੈ ॥","translit":"Sarab Thhok Suneeahi Ghar Thaa Kai ||","english":"I have heard that all things are in His home."},{"punjabi":"ਰਾਜ ਮਹਿ ਰਾਜੁ ਜੋਗ ਮਹਿ ਜੋਗੀ ॥","lareedar":"ਰਾਜਮਹਿਰਾਜੁਜੋਗਮਹਿਜੋਗੀ ॥","translit":"Raaj Mehi Raaj Jog Mehi Jogee ||","english":"Among kings, He is the King; among yogis, He is the Yogi."},{"punjabi":"ਤਪ ਮਹਿ ਤਪੀਸਰੁ ਗ੍ਰਿਹਸਤ ਮਹਿ ਭੋਗੀ ॥","lareedar":"ਤਪਮਹਿਤਪੀਸਰੁਗ੍ਰਿਹਸਤਮਹਿਭੋਗੀ ॥","translit":"Thap Mehi Thapeesar Grihasath Mehi Bhogee ||","english":"Among ascetics, He is the Ascetic; among householders, He is the Enjoyer."},{"punjabi":"ਧਿਆਇ ਧਿਆਇ ਭਗਤਹ ਸੁਖੁ ਪਾਇਆ ॥","lareedar":"ਧਿਆਇਧਿਆਇਭਗਤਹਸੁਖੁਪਾਇਆ ॥","translit":"Dhhiaae Dhhiaae Bhagatheh Sukh Paaeiaa ||","english":"By constant meditation, His devotee finds peace."},{"punjabi":"ਨਾਨਕ ਤਿਸੁ ਪੁਰਖ ਕਾ ਕਿਨੈ ਅੰਤੁ ਨ ਪਾਇਆ ॥੨॥","lareedar":"ਨਾਨਕਤਿਸੁਪੁਰਖਕਾਕਿਨੈਅੰਤੁਨਪਾਇਆ ॥੨ ॥","translit":"Naanak This Purakh Kaa Kinai Anth N Paaeiaa ||2||","english":"O Nanak, no one has found the limits of that Supreme Being. ||2||"},{"punjabi":"ਜਾ ਕੀ ਲੀਲਾ ਕੀ ਮਿਤਿ ਨਾਹਿ ॥","lareedar":"ਜਾਕੀਲੀਲਾਕੀਮਿਤਿਨਾਹਿ ॥","translit":"Jaa Kee Leelaa Kee Mith Naahi ||","english":"There is no limit to His play."},{"punjabi":"ਸਗਲ ਦੇਵ ਹਾਰੇ ਅਵਗਾਹਿ ॥","lareedar":"ਸਗਲਦੇਵਹਾਰੇਅਵਗਾਹਿ ॥","translit":"Sagal Dhaev Haarae Avagaahi ||","english":"All the demigods have grown weary of searching for it."},{"punjabi":"ਪਿਤਾ ਕਾ ਜਨਮੁ ਕਿ ਜਾਨੈ ਪੂਤੁ ॥","lareedar":"ਪਿਤਾਕਾਜਨਮੁਕਿਜਾਨੈਪੂਤੁ ॥","translit":"Pithaa Kaa Janam K Jaanai Pooth ||","english":"What does the son know of his father's birth?"},{"punjabi":"ਸਗਲ ਪਰੋਈ ਅਪੁਨੈ ਸੂਤਿ ॥","lareedar":"ਸਗਲਪਰੋਈਅਪੁਨੈਸੂਤਿ ॥","translit":"Sagal Paroee Apunai Sooth ||","english":"All are strung upon His string."},{"punjabi":"ਸੁਮਤਿ ਗਿਆਨੁ ਧਿਆਨੁ ਜਿਨ ਦੇਇ ॥","lareedar":"ਸੁਮਤਿਗਿਆਨੁਧਿਆਨੁਜਿਨਦੇਇ ॥","translit":"Sumath Giaan Dhhiaan Jin Dhaee ||","english":"He bestows good sense, spiritual wisdom and meditation"}]},{"index":53,"ang":284,"lines":[{"punjabi":"ਜਨ ਦਾਸ ਨਾਮੁ ਧਿਆਵਹਿ ਸੇਇ ॥","lareedar":"ਜਨਦਾਸਨਾਮੁਧਿਆਵਹਿਸੇਇ ॥","translit":"Jan Dhaas Naam Dhhiaavehi Saee ||","english":"On His humble servants and slaves who meditate on the Naam."},{"punjabi":"ਤਿਹੁ ਗੁਣ ਮਹਿ ਜਾ ਕਉ ਭਰਮਾਏ ॥","lareedar":"ਤਿਹੁਗੁਣਮਹਿਜਾਕਉਭਰਮਾਏ ॥","translit":"Thihu Gun Mehi Jaa Ko Bharamaaeae ||","english":"He leads some astray in the three qualities;"},{"punjabi":"ਜਨਮਿ ਮਰੈ ਫਿਰਿ ਆਵੈ ਜਾਏ ॥","lareedar":"ਜਨਮਿਮਰੈਫਿਰਿਆਵੈਜਾਏ ॥","translit":"Janam Marai Fir Aavai Jaaeae ||","english":"They are born and die, coming and going over and over again."},{"punjabi":"ਊਚ ਨੀਚ ਤਿਸ ਕੇ ਅਸਥਾਨ ॥","lareedar":"ਊਚਨੀਚਤਿਸਕੇਅਸਥਾਨ ॥","translit":"Ooch Neech This Kae Asathhaan ||","english":"The high and the low are His places."},{"punjabi":"ਜੈਸਾ ਜਨਾਵੈ ਤੈਸਾ ਨਾਨਕ ਜਾਨ ॥੩॥","lareedar":"ਜੈਸਾਜਨਾਵੈਤੈਸਾਨਾਨਕਜਾਨ ॥੩ ॥","translit":"Jaisaa Janaavai Thaisaa Naanak Jaan ||3||","english":"As He inspires us to know Him, O Nanak, so is He known. ||3||"},{"punjabi":"ਨਾਨਾ ਰੂਪ ਨਾਨਾ ਜਾ ਕੇ ਰੰਗ ॥","lareedar":"ਨਾਨਾਰੂਪਨਾਨਾਜਾਕੇਰੰਗ ॥","translit":"Naanaa Roop Naanaa Jaa Kae Rang ||","english":"Many are His forms; many are His colors."},{"punjabi":"ਨਾਨਾ ਭੇਖ ਕਰਹਿ ਇਕ ਰੰਗ ॥","lareedar":"ਨਾਨਾਭੇਖਕਰਹਿਇਕਰੰਗ ॥","translit":"Naanaa Bhaekh Karehi Eik Rang ||","english":"Many are the appearances which He assumes, and yet He is still the One."},{"punjabi":"ਨਾਨਾ ਬਿਧਿ ਕੀਨੋ ਬਿਸਥਾਰੁ ॥","lareedar":"ਨਾਨਾਬਿਧਿਕੀਨੋਬਿਸਥਾਰੁ ॥","translit":"Naanaa Bidhh Keeno Bisathhaar ||","english":"In so many ways, He has extended Himself."},{"punjabi":"ਪ੍ਰਭੁ ਅਬਿਨਾਸੀ ਏਕੰਕਾਰੁ ॥","lareedar":"ਪ੍ਰਭੁਅਬਿਨਾਸੀਏਕੰਕਾਰੁ ॥","translit":"Prabh Abinaasee Eaekankaar ||","english":"The Eternal Lord God is the One, the Creator."},{"punjabi":"ਨਾਨਾ ਚਲਿਤ ਕਰੇ ਖਿਨ ਮਾਹਿ ॥","lareedar":"ਨਾਨਾਚਲਿਤਕਰੇਖਿਨਮਾਹਿ ॥","translit":"Naanaa Chalith Karae Khin Maahi ||","english":"He performs His many plays in an instant."},{"punjabi":"ਪੂਰਿ ਰਹਿਓ ਪੂਰਨੁ ਸਭ ਠਾਇ ॥","lareedar":"ਪੂਰਿਰਹਿਓਪੂਰਨੁਸਭਠਾਇ ॥","translit":"Poor Rehiou Pooran Sabh Thaae ||","english":"The Perfect Lord is pervading all places."},{"punjabi":"ਨਾਨਾ ਬਿਧਿ ਕਰਿ ਬਨਤ ਬਨਾਈ ॥","lareedar":"ਨਾਨਾਬਿਧਿਕਰਿਬਨਤਬਨਾਈ ॥","translit":"Naanaa Bidhh Kar Banath Banaaee ||","english":"In so many ways, He created the creation."},{"punjabi":"ਅਪਨੀ ਕੀਮਤਿ ਆਪੇ ਪਾਈ ॥","lareedar":"ਅਪਨੀਕੀਮਤਿਆਪੇਪਾਈ ॥","translit":"Apanee Keemath Aapae Paaee ||","english":"He alone can estimate His worth."},{"punjabi":"ਸਭ ਘਟ ਤਿਸ ਕੇ ਸਭ ਤਿਸ ਕੇ ਠਾਉ ॥","lareedar":"ਸਭਘਟਤਿਸਕੇਸਭਤਿਸਕੇਠਾਉ ॥","translit":"Sabh Ghatt This Kae Sabh This Kae Thaao ||","english":"All hearts are His, and all places are His."},{"punjabi":"ਜਪਿ ਜਪਿ ਜੀਵੈ ਨਾਨਕ ਹਰਿ ਨਾਉ ॥੪॥","lareedar":"ਜਪਿਜਪਿਜੀਵੈਨਾਨਕਹਰਿਨਾਉ ॥੪ ॥","translit":"Jap Jap Jeevai Naanak Har Naao ||4||","english":"Nanak lives by chanting, chanting the Name of the Lord. ||4||"},{"punjabi":"ਨਾਮ ਕੇ ਧਾਰੇ ਸਗਲੇ ਜੰਤ ॥","lareedar":"ਨਾਮਕੇਧਾਰੇਸਗਲੇਜੰਤ ॥","translit":"Naam Kae Dhhaarae Sagalae Janth ||","english":"The Naam is the Support of all creatures."},{"punjabi":"ਨਾਮ ਕੇ ਧਾਰੇ ਖੰਡ ਬ੍ਰਹਮੰਡ ॥","lareedar":"ਨਾਮਕੇਧਾਰੇਖੰਡਬ੍ਰਹਮੰਡ ॥","translit":"Naam Kae Dhhaarae Khandd Brehamandd ||","english":"The Naam is the Support of the earth and solar systems."},{"punjabi":"ਨਾਮ ਕੇ ਧਾਰੇ ਸਿਮ੍ਰਿਤਿ ਬੇਦ ਪੁਰਾਨ ॥","lareedar":"ਨਾਮਕੇਧਾਰੇਸਿਮ੍ਰਿਤਿਬੇਦਪੁਰਾਨ ॥","translit":"Naam Kae Dhhaarae Simrith Baedh Puraan ||","english":"The Naam is the Support of the Simritees, the Vedas and the Puraanas."},{"punjabi":"ਨਾਮ ਕੇ ਧਾਰੇ ਸੁਨਨ ਗਿਆਨ ਧਿਆਨ ॥","lareedar":"ਨਾਮਕੇਧਾਰੇਸੁਨਨਗਿਆਨਧਿਆਨ ॥","translit":"Naam Kae Dhhaarae Sunan Giaan Dhhiaan ||","english":"The Naam is the Support by which we hear of spiritual wisdom and meditation."},{"punjabi":"ਨਾਮ ਕੇ ਧਾਰੇ ਆਗਾਸ ਪਾਤਾਲ ॥","lareedar":"ਨਾਮਕੇਧਾਰੇਆਗਾਸਪਾਤਾਲ ॥","translit":"Naam Kae Dhhaarae Aagaas Paathaal ||","english":"The Naam is the Support of the Akaashic ethers and the nether regions."},{"punjabi":"ਨਾਮ ਕੇ ਧਾਰੇ ਸਗਲ ਆਕਾਰ ॥","lareedar":"ਨਾਮਕੇਧਾਰੇਸਗਲਆਕਾਰ ॥","translit":"Naam Kae Dhhaarae Sagal Aakaar ||","english":"The Naam is the Support of all bodies."},{"punjabi":"ਨਾਮ ਕੇ ਧਾਰੇ ਪੁਰੀਆ ਸਭ ਭਵਨ ॥","lareedar":"ਨਾਮਕੇਧਾਰੇਪੁਰੀਆਸਭਭਵਨ ॥","translit":"Naam Kae Dhhaarae Pureeaa Sabh Bhavan ||","english":"The Naam is the Support of all worlds and realms."},{"punjabi":"ਨਾਮ ਕੈ ਸੰਗਿ ਉਧਰੇ ਸੁਨਿ ਸ੍ਰਵਨ ॥","lareedar":"ਨਾਮਕੈਸੰਗਿਉਧਰੇਸੁਨਿਸ੍ਰਵਨ ॥","translit":"Naam Kai Sang Oudhharae Sun Sravan ||","english":"Associating with the Naam, listening to it with the ears, one is saved."},{"punjabi":"ਕਰਿ ਕਿਰਪਾ ਜਿਸੁ ਆਪਨੈ ਨਾਮਿ ਲਾਏ ॥","lareedar":"ਕਰਿਕਿਰਪਾਜਿਸੁਆਪਨੈਨਾਮਿਲਾਏ ॥","translit":"Kar Kirapaa Jis Aapanai Naam Laaeae ||","english":"Those whom the Lord mercifully attaches to His Naam"},{"punjabi":"ਨਾਨਕ ਚਉਥੇ ਪਦ ਮਹਿ ਸੋ ਜਨੁ ਗਤਿ ਪਾਏ ॥੫॥","lareedar":"ਨਾਨਕਚਉਥੇਪਦਮਹਿਸੋਜਨੁਗਤਿਪਾਏ ॥੫ ॥","translit":"Naanak Chouthhae Padh Mehi So Jan Gath Paaeae ||5||","english":"- O Nanak, in the fourth state, those humble servants attain salvation. ||5||"}]},{"index":54,"ang":284,"lines":[{"punjabi":"ਰੂਪੁ ਸਤਿ ਜਾ ਕਾ ਸਤਿ ਅਸਥਾਨੁ ॥","lareedar":"ਰੂਪੁਸਤਿਜਾਕਾਸਤਿਅਸਥਾਨੁ ॥","translit":"Roop Sath Jaa Kaa Sath Asathhaan ||","english":"His form is true, and true is His place."},{"punjabi":"ਪੁਰਖੁ ਸਤਿ ਕੇਵਲ ਪਰਧਾਨੁ ॥","lareedar":"ਪੁਰਖੁਸਤਿਕੇਵਲਪਰਧਾਨੁ ॥","translit":"Purakh Sath Kaeval Paradhhaan ||","english":"His personality is true - He alone is supreme."},{"punjabi":"ਕਰਤੂਤਿ ਸਤਿ ਸਤਿ ਜਾ ਕੀ ਬਾਣੀ ॥","lareedar":"ਕਰਤੂਤਿਸਤਿਸਤਿਜਾਕੀਬਾਣੀ ॥","translit":"Karathooth Sath Sath Jaa Kee Baanee ||","english":"His acts are true, and true is His Word."},{"punjabi":"ਸਤਿ ਪੁਰਖ ਸਭ ਮਾਹਿ ਸਮਾਣੀ ॥","lareedar":"ਸਤਿਪੁਰਖਸਭਮਾਹਿਸਮਾਣੀ ॥","translit":"Sath Purakh Sabh Maahi Samaanee ||","english":"The True Lord is permeating all."},{"punjabi":"ਸਤਿ ਕਰਮੁ ਜਾ ਕੀ ਰਚਨਾ ਸਤਿ ॥","lareedar":"ਸਤਿਕਰਮੁਜਾਕੀਰਚਨਾਸਤਿ ॥","translit":"Sath Karam Jaa Kee Rachanaa Sath ||","english":"True are His actions; His creation is true."},{"punjabi":"ਮੂਲੁ ਸਤਿ ਸਤਿ ਉਤਪਤਿ ॥","lareedar":"ਮੂਲੁਸਤਿਸਤਿਉਤਪਤਿ ॥","translit":"Mool Sath Sath Outhapath ||","english":"His root is true, and true is what originates from it."},{"punjabi":"ਸਤਿ ਕਰਣੀ ਨਿਰਮਲ ਨਿਰਮਲੀ ॥","lareedar":"ਸਤਿਕਰਣੀਨਿਰਮਲਨਿਰਮਲੀ ॥","translit":"Sath Karanee Niramal Niramalee ||","english":"True is His lifestyle, the purest of the pure."},{"punjabi":"ਜਿਸਹਿ ਬੁਝਾਏ ਤਿਸਹਿ ਸਭ ਭਲੀ ॥","lareedar":"ਜਿਸਹਿਬੁਝਾਏਤਿਸਹਿਸਭਭਲੀ ॥","translit":"Jisehi Bujhaaeae Thisehi Sabh Bhalee ||","english":"All goes well for those who know Him."},{"punjabi":"ਸਤਿ ਨਾਮੁ ਪ੍ਰਭ ਕਾ ਸੁਖਦਾਈ ॥","lareedar":"ਸਤਿਨਾਮੁਪ੍ਰਭਕਾਸੁਖਦਾਈ ॥","translit":"Sath Naam Prabh Kaa Sukhadhaaee ||","english":"The True Name of God is the Giver of peace."},{"punjabi":"ਬਿਸ੍ਵਾਸੁ ਸਤਿ ਨਾਨਕ ਗੁਰ ਤੇ ਪਾਈ ॥੬॥","lareedar":"ਬਿਸ੍ਵਾਸੁਸਤਿਨਾਨਕਗੁਰਤੇਪਾਈ ॥੬ ॥","translit":"Bisvaas Sath Naanak Gur Thae Paaee ||6||","english":"Nanak has obtained true faith from the Guru. ||6||"},{"punjabi":"ਸਤਿ ਬਚਨ ਸਾਧੂ ਉਪਦੇਸ ॥","lareedar":"ਸਤਿਬਚਨਸਾਧੂਉਪਦੇਸ ॥","translit":"Sath Bachan Saadhhoo Oupadhaes ||","english":"True are the Teachings, and the Instructions of the Holy."},{"punjabi":"ਸਤਿ ਤੇ ਜਨ ਜਾ ਕੈ ਰਿਦੈ ਪ੍ਰਵੇਸ ॥","lareedar":"ਸਤਿਤੇਜਨਜਾਕੈਰਿਦੈਪ੍ਰਵੇਸ ॥","translit":"Sath Thae Jan Jaa Kai Ridhai Pravaes ||","english":"True are those into whose hearts He enters."},{"punjabi":"ਸਤਿ ਨਿਰਤਿ ਬੂਝੈ ਜੇ ਕੋਇ ॥","lareedar":"ਸਤਿਨਿਰਤਿਬੂਝੈਜੇਕੋਇ ॥","translit":"Sath Nirath Boojhai Jae Koe ||","english":"One who knows and loves the Truth"},{"punjabi":"ਨਾਮੁ ਜਪਤ ਤਾ ਕੀ ਗਤਿ ਹੋਇ ॥","lareedar":"ਨਾਮੁਜਪਤਤਾਕੀਗਤਿਹੋਇ ॥","translit":"Naam Japath Thaa Kee Gath Hoe ||","english":"Chanting the Naam, he obtains salvation."},{"punjabi":"ਆਪਿ ਸਤਿ ਕੀਆ ਸਭੁ ਸਤਿ ॥","lareedar":"ਆਪਿਸਤਿਕੀਆਸਭੁਸਤਿ ॥","translit":"Aap Sath Keeaa Sabh Sath ||","english":"He Himself is True, and all that He has made is true."},{"punjabi":"ਆਪੇ ਜਾਨੈ ਅਪਨੀ ਮਿਤਿ ਗਤਿ ॥","lareedar":"ਆਪੇਜਾਨੈਅਪਨੀਮਿਤਿਗਤਿ ॥","translit":"Aapae Jaanai Apanee Mith Gath ||","english":"He Himself knows His own state and condition."},{"punjabi":"ਜਿਸ ਕੀ ਸ੍ਰਿਸਟਿ ਸੁ ਕਰਣੈਹਾਰੁ ॥","lareedar":"ਜਿਸਕੀਸ੍ਰਿਸਟਿਸੁਕਰਣੈਹਾਰੁ ॥","translit":"Jis Kee Srisatt S Karanaihaar ||","english":"He is the Creator Lord of His world."},{"punjabi":"ਅਵਰ ਨ ਬੂਝਿ ਕਰਤ ਬੀਚਾਰੁ ॥","lareedar":"ਅਵਰਨਬੂਝਿਕਰਤਬੀਚਾਰੁ ॥","translit":"Avar N Boojh Karath Beechaar ||","english":"No one else understands Him, although they may try."},{"punjabi":"ਕਰਤੇ ਕੀ ਮਿਤਿ ਨ ਜਾਨੈ ਕੀਆ ॥","lareedar":"ਕਰਤੇਕੀਮਿਤਿਨਜਾਨੈਕੀਆ ॥","translit":"Karathae Kee Mith N Jaanai Keeaa ||","english":"The created cannot know the extent of the Creator."},{"punjabi":"ਨਾਨਕ ਜੋ ਤਿਸੁ ਭਾਵੈ ਸੋ ਵਰਤੀਆ ॥੭॥","lareedar":"ਨਾਨਕਜੋਤਿਸੁਭਾਵੈਸੋਵਰਤੀਆ ॥੭ ॥","translit":"Naanak Jo This Bhaavai So Varatheeaa ||7||","english":"O Nanak, whatever pleases Him comes to pass. ||7||"},{"punjabi":"ਬਿਸਮਨ ਬਿਸਮ ਭਏ ਬਿਸਮਾਦ ॥","lareedar":"ਬਿਸਮਨਬਿਸਮਭਏਬਿਸਮਾਦ ॥","translit":"Bisaman Bisam Bheae Bisamaadh ||","english":"Gazing upon His wondrous wonder, I am wonder-struck and amazed!"},{"punjabi":"ਜਿਨਿ ਬੂਝਿਆ ਤਿਸੁ ਆਇਆ ਸ੍ਵਾਦ ॥","lareedar":"ਜਿਨਿਬੂਝਿਆਤਿਸੁਆਇਆਸ੍ਵਾਦ ॥","translit":"Jin Boojhiaa This Aaeiaa Svaadh ||","english":"One who realizes this, comes to taste this state of joy."},{"punjabi":"ਪ੍ਰਭ ਕੈ ਰੰਗਿ ਰਾਚਿ ਜਨ ਰਹੇ ॥","lareedar":"ਪ੍ਰਭਕੈਰੰਗਿਰਾਚਿਜਨਰਹੇ ॥","translit":"Prabh Kai Rang Raach Jan Rehae ||","english":"God's humble servants remain absorbed in His Love."},{"punjabi":"ਗੁਰ ਕੈ ਬਚਨਿ ਪਦਾਰਥ ਲਹੇ ॥","lareedar":"ਗੁਰਕੈਬਚਨਿਪਦਾਰਥਲਹੇ ॥","translit":"Gur Kai Bachan Padhaarathh Lehae ||","english":"Following the Guru's Teachings, they receive the four cardinal blessings."},{"punjabi":"ਓਇ ਦਾਤੇ ਦੁਖ ਕਾਟਨਹਾਰ ॥","lareedar":"ਓਇਦਾਤੇਦੁਖਕਾਟਨਹਾਰ ॥","translit":"Oue Dhaathae Dhukh Kaattanehaar ||","english":"They are the givers, the dispellers of pain."}]},{"index":55,"ang":285,"lines":[{"punjabi":"ਜਾ ਕੈ ਸੰਗਿ ਤਰੈ ਸੰਸਾਰ ॥","lareedar":"ਜਾਕੈਸੰਗਿਤਰੈਸੰਸਾਰ ॥","translit":"Jaa Kai Sang Tharai Sansaar ||","english":"In their company, the world is saved."},{"punjabi":"ਜਨ ਕਾ ਸੇਵਕੁ ਸੋ ਵਡਭਾਗੀ ॥","lareedar":"ਜਨਕਾਸੇਵਕੁਸੋਵਡਭਾਗੀ ॥","translit":"Jan Kaa Saevak So Vaddabhaagee ||","english":"The slave of the Lord's servant is so very blessed."},{"punjabi":"ਜਨ ਕੈ ਸੰਗਿ ਏਕ ਲਿਵ ਲਾਗੀ ॥","lareedar":"ਜਨਕੈਸੰਗਿਏਕਲਿਵਲਾਗੀ ॥","translit":"Jan Kai Sang Eaek Liv Laagee ||","english":"In the company of His servant, one becomes attached to the Love of the One."},{"punjabi":"ਗੁਨ ਗੋਬਿਦ ਕੀਰਤਨੁ ਜਨੁ ਗਾਵੈ ॥","lareedar":"ਗੁਨਗੋਬਿਦਕੀਰਤਨੁਜਨੁਗਾਵੈ ॥","translit":"Gun Gobidh Keerathan Jan Gaavai ||","english":"His humble servant sings the Kirtan, the songs of the glory of God."},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਨਾਨਕ ਫਲੁ ਪਾਵੈ ॥੮॥੧੬॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਨਾਨਕਫਲੁਪਾਵੈ ॥੮ ॥੧੬ ॥","translit":"Gur Prasaadh Naanak Fal Paavai ||8||16||","english":"By Guru's Grace, O Nanak, he receives the fruits of his rewards. ||8||16||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਆਦਿ ਸਚੁ ਜੁਗਾਦਿ ਸਚੁ ॥","lareedar":"ਆਦਿਸਚੁਜੁਗਾਦਿਸਚੁ ॥","translit":"Aadh Sach Jugaadh Sach ||","english":"True in the beginning, True throughout the ages,"},{"punjabi":"ਹੈ ਭਿ ਸਚੁ ਨਾਨਕ ਹੋਸੀ ਭਿ ਸਚੁ ॥੧॥","lareedar":"ਹੈਭਿਸਚੁਨਾਨਕਹੋਸੀਭਿਸਚੁ ॥੧ ॥","translit":"Hai Bh Sach Naanak Hosee Bh Sach ||1||","english":"True here and now. O Nanak, He shall forever be True. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਚਰਨ ਸਤਿ ਸਤਿ ਪਰਸਨਹਾਰ ॥","lareedar":"ਚਰਨਸਤਿਸਤਿਪਰਸਨਹਾਰ ॥","translit":"Charan Sath Sath Parasanehaar ||","english":"His Lotus Feet are True, and True are those who touch Them."},{"punjabi":"ਪੂਜਾ ਸਤਿ ਸਤਿ ਸੇਵਦਾਰ ॥","lareedar":"ਪੂਜਾਸਤਿਸਤਿਸੇਵਦਾਰ ॥","translit":"Poojaa Sath Sath Saevadhaar ||","english":"His devotional worship is True, and True are those who worship Him."},{"punjabi":"ਦਰਸਨੁ ਸਤਿ ਸਤਿ ਪੇਖਨਹਾਰ ॥","lareedar":"ਦਰਸਨੁਸਤਿਸਤਿਪੇਖਨਹਾਰ ॥","translit":"Dharasan Sath Sath Paekhanehaar ||","english":"The Blessing of His Vision is True, and True are those who behold it."},{"punjabi":"ਨਾਮੁ ਸਤਿ ਸਤਿ ਧਿਆਵਨਹਾਰ ॥","lareedar":"ਨਾਮੁਸਤਿਸਤਿਧਿਆਵਨਹਾਰ ॥","translit":"Naam Sath Sath Dhhiaavanehaar ||","english":"His Naam is True, and True are those who meditate on it."},{"punjabi":"ਆਪਿ ਸਤਿ ਸਤਿ ਸਭ ਧਾਰੀ ॥","lareedar":"ਆਪਿਸਤਿਸਤਿਸਭਧਾਰੀ ॥","translit":"Aap Sath Sath Sabh Dhhaaree ||","english":"He Himself is True, and True is all that He sustains."},{"punjabi":"ਆਪੇ ਗੁਣ ਆਪੇ ਗੁਣਕਾਰੀ ॥","lareedar":"ਆਪੇਗੁਣਆਪੇਗੁਣਕਾਰੀ ॥","translit":"Aapae Gun Aapae Gunakaaree ||","english":"He Himself is virtuous goodness, and He Himself is the Bestower of virtue."},{"punjabi":"ਸਬਦੁ ਸਤਿ ਸਤਿ ਪ੍ਰਭੁ ਬਕਤਾ ॥","lareedar":"ਸਬਦੁਸਤਿਸਤਿਪ੍ਰਭੁਬਕਤਾ ॥","translit":"Sabadh Sath Sath Prabh Bakathaa ||","english":"The Word of His Shabad is True, and True are those who speak of God."},{"punjabi":"ਸੁਰਤਿ ਸਤਿ ਸਤਿ ਜਸੁ ਸੁਨਤਾ ॥","lareedar":"ਸੁਰਤਿਸਤਿਸਤਿਜਸੁਸੁਨਤਾ ॥","translit":"Surath Sath Sath Jas Sunathaa ||","english":"Those ears are True, and True are those who listen to His Praises."},{"punjabi":"ਬੁਝਨਹਾਰ ਕਉ ਸਤਿ ਸਭ ਹੋਇ ॥","lareedar":"ਬੁਝਨਹਾਰਕਉਸਤਿਸਭਹੋਇ ॥","translit":"Bujhanehaar Ko Sath Sabh Hoe ||","english":"All is True to one who understands."},{"punjabi":"ਨਾਨਕ ਸਤਿ ਸਤਿ ਪ੍ਰਭੁ ਸੋਇ ॥੧॥","lareedar":"ਨਾਨਕਸਤਿਸਤਿਪ੍ਰਭੁਸੋਇ ॥੧ ॥","translit":"Naanak Sath Sath Prabh Soe ||1||","english":"O Nanak, True, True is He, the Lord God. ||1||"},{"punjabi":"ਸਤਿ ਸਰੂਪੁ ਰਿਦੈ ਜਿਨਿ ਮਾਨਿਆ ॥","lareedar":"ਸਤਿਸਰੂਪੁਰਿਦੈਜਿਨਿਮਾਨਿਆ ॥","translit":"Sath Saroop Ridhai Jin Maaniaa ||","english":"One who believes in the Embodiment of Truth with all his heart"},{"punjabi":"ਕਰਨ ਕਰਾਵਨ ਤਿਨਿ ਮੂਲੁ ਪਛਾਨਿਆ ॥","lareedar":"ਕਰਨਕਰਾਵਨਤਿਨਿਮੂਲੁਪਛਾਨਿਆ ॥","translit":"Karan Karaavan Thin Mool Pashhaaniaa ||","english":"Recognizes the Cause of causes as the Root of all."},{"punjabi":"ਜਾ ਕੈ ਰਿਦੈ ਬਿਸ੍ਵਾਸੁ ਪ੍ਰਭ ਆਇਆ ॥","lareedar":"ਜਾਕੈਰਿਦੈਬਿਸ੍ਵਾਸੁਪ੍ਰਭਆਇਆ ॥","translit":"Jaa Kai Ridhai Bisvaas Prabh Aaeiaa ||","english":"One whose heart is filled with faith in God"},{"punjabi":"ਤਤੁ ਗਿਆਨੁ ਤਿਸੁ ਮਨਿ ਪ੍ਰਗਟਾਇਆ ॥","lareedar":"ਤਤੁਗਿਆਨੁਤਿਸੁਮਨਿਪ੍ਰਗਟਾਇਆ ॥","translit":"Thath Giaan This Man Pragattaaeiaa ||","english":"The essence of spiritual wisdom is revealed to his mind."},{"punjabi":"ਭੈ ਤੇ ਨਿਰਭਉ ਹੋਇ ਬਸਾਨਾ ॥","lareedar":"ਭੈਤੇਨਿਰਭਉਹੋਇਬਸਾਨਾ ॥","translit":"Bhai Thae Nirabho Hoe Basaanaa ||","english":"Coming out of fear, he comes to live without fear."},{"punjabi":"ਜਿਸ ਤੇ ਉਪਜਿਆ ਤਿਸੁ ਮਾਹਿ ਸਮਾਨਾ ॥","lareedar":"ਜਿਸਤੇਉਪਜਿਆਤਿਸੁਮਾਹਿਸਮਾਨਾ ॥","translit":"Jis Thae Oupajiaa This Maahi Samaanaa ||","english":"He is absorbed into the One, from whom he originated."}]},{"index":56,"ang":285,"lines":[{"punjabi":"ਬਸਤੁ ਮਾਹਿ ਲੇ ਬਸਤੁ ਗਡਾਈ ॥","lareedar":"ਬਸਤੁਮਾਹਿਲੇਬਸਤੁਗਡਾਈ ॥","translit":"Basath Maahi Lae Basath Gaddaaee ||","english":"When something blends with its own,"},{"punjabi":"ਤਾ ਕਉ ਭਿੰਨ ਨ ਕਹਨਾ ਜਾਈ ॥","lareedar":"ਤਾਕਉਭਿੰਨਨਕਹਨਾਜਾਈ ॥","translit":"Thaa Ko Bhinn N Kehanaa Jaaee ||","english":"It cannot be said to be separate from it."},{"punjabi":"ਬੂਝੈ ਬੂਝਨਹਾਰੁ ਬਿਬੇਕ ॥","lareedar":"ਬੂਝੈਬੂਝਨਹਾਰੁਬਿਬੇਕ ॥","translit":"Boojhai Boojhanehaar Bibaek ||","english":"This is understood only by one of discerning understanding."},{"punjabi":"ਨਾਰਾਇਨ ਮਿਲੇ ਨਾਨਕ ਏਕ ॥੨॥","lareedar":"ਨਾਰਾਇਨਮਿਲੇਨਾਨਕਏਕ ॥੨ ॥","translit":"Naaraaein Milae Naanak Eaek ||2||","english":"Meeting with the Lord, O Nanak, he becomes one with Him. ||2||"},{"punjabi":"ਠਾਕੁਰ ਕਾ ਸੇਵਕੁ ਆਗਿਆਕਾਰੀ ॥","lareedar":"ਠਾਕੁਰਕਾਸੇਵਕੁਆਗਿਆਕਾਰੀ ॥","translit":"Thaakur Kaa Saevak Aagiaakaaree ||","english":"The servant is obedient to his Lord and Master."},{"punjabi":"ਠਾਕੁਰ ਕਾ ਸੇਵਕੁ ਸਦਾ ਪੂਜਾਰੀ ॥","lareedar":"ਠਾਕੁਰਕਾਸੇਵਕੁਸਦਾਪੂਜਾਰੀ ॥","translit":"Thaakur Kaa Saevak Sadhaa Poojaaree ||","english":"The servant worships his Lord and Master forever."},{"punjabi":"ਠਾਕੁਰ ਕੇ ਸੇਵਕ ਕੈ ਮਨਿ ਪਰਤੀਤਿ ॥","lareedar":"ਠਾਕੁਰਕੇਸੇਵਕਕੈਮਨਿਪਰਤੀਤਿ ॥","translit":"Thaakur Kae Saevak Kai Man Paratheeth ||","english":"The servant of the Lord Master has faith in his mind."},{"punjabi":"ਠਾਕੁਰ ਕੇ ਸੇਵਕ ਕੀ ਨਿਰਮਲ ਰੀਤਿ ॥","lareedar":"ਠਾਕੁਰਕੇਸੇਵਕਕੀਨਿਰਮਲਰੀਤਿ ॥","translit":"Thaakur Kae Saevak Kee Niramal Reeth ||","english":"The servant of the Lord Master lives a pure lifestyle."},{"punjabi":"ਠਾਕੁਰ ਕਉ ਸੇਵਕੁ ਜਾਨੈ ਸੰਗਿ ॥","lareedar":"ਠਾਕੁਰਕਉਸੇਵਕੁਜਾਨੈਸੰਗਿ ॥","translit":"Thaakur Ko Saevak Jaanai Sang ||","english":"The servant of the Lord Master knows that the Lord is with him."},{"punjabi":"ਪ੍ਰਭ ਕਾ ਸੇਵਕੁ ਨਾਮ ਕੈ ਰੰਗਿ ॥","lareedar":"ਪ੍ਰਭਕਾਸੇਵਕੁਨਾਮਕੈਰੰਗਿ ॥","translit":"Prabh Kaa Saevak Naam Kai Rang ||","english":"God's servant is attuned to the Naam, the Name of the Lord."},{"punjabi":"ਸੇਵਕ ਕਉ ਪ੍ਰਭ ਪਾਲਨਹਾਰਾ ॥","lareedar":"ਸੇਵਕਕਉਪ੍ਰਭਪਾਲਨਹਾਰਾ ॥","translit":"Saevak Ko Prabh Paalanehaaraa ||","english":"God is the Cherisher of His servant."},{"punjabi":"ਸੇਵਕ ਕੀ ਰਾਖੈ ਨਿਰੰਕਾਰਾ ॥","lareedar":"ਸੇਵਕਕੀਰਾਖੈਨਿਰੰਕਾਰਾ ॥","translit":"Saevak Kee Raakhai Nirankaaraa ||","english":"The Formless Lord preserves His servant."},{"punjabi":"ਸੋ ਸੇਵਕੁ ਜਿਸੁ ਦਇਆ ਪ੍ਰਭੁ ਧਾਰੈ ॥","lareedar":"ਸੋਸੇਵਕੁਜਿਸੁਦਇਆਪ੍ਰਭੁਧਾਰੈ ॥","translit":"So Saevak Jis Dhaeiaa Prabh Dhhaarai ||","english":"Unto His servant, God bestows His Mercy."},{"punjabi":"ਨਾਨਕ ਸੋ ਸੇਵਕੁ ਸਾਸਿ ਸਾਸਿ ਸਮਾਰੈ ॥੩॥","lareedar":"ਨਾਨਕਸੋਸੇਵਕੁਸਾਸਿਸਾਸਿਸਮਾਰੈ ॥੩ ॥","translit":"Naanak So Saevak Saas Saas Samaarai ||3||","english":"O Nanak, that servant remembers Him with each and every breath. ||3||"},{"punjabi":"ਅਪੁਨੇ ਜਨ ਕਾ ਪਰਦਾ ਢਾਕੈ ॥","lareedar":"ਅਪੁਨੇਜਨਕਾਪਰਦਾਢਾਕੈ ॥","translit":"Apunae Jan Kaa Paradhaa Dtaakai ||","english":"He covers the faults of His servant."},{"punjabi":"ਅਪਨੇ ਸੇਵਕ ਕੀ ਸਰਪਰ ਰਾਖੈ ॥","lareedar":"ਅਪਨੇਸੇਵਕਕੀਸਰਪਰਰਾਖੈ ॥","translit":"Apanae Saevak Kee Sarapar Raakhai ||","english":"He surely preserves the honor of His servant."},{"punjabi":"ਅਪਨੇ ਦਾਸ ਕਉ ਦੇਇ ਵਡਾਈ ॥","lareedar":"ਅਪਨੇਦਾਸਕਉਦੇਇਵਡਾਈ ॥","translit":"Apanae Dhaas Ko Dhaee Vaddaaee ||","english":"He blesses His slave with greatness."},{"punjabi":"ਅਪਨੇ ਸੇਵਕ ਕਉ ਨਾਮੁ ਜਪਾਈ ॥","lareedar":"ਅਪਨੇਸੇਵਕਕਉਨਾਮੁਜਪਾਈ ॥","translit":"Apanae Saevak Ko Naam Japaaee ||","english":"He inspires His servant to chant the Naam, the Name of the Lord."},{"punjabi":"ਅਪਨੇ ਸੇਵਕ ਕੀ ਆਪਿ ਪਤਿ ਰਾਖੈ ॥","lareedar":"ਅਪਨੇਸੇਵਕਕੀਆਪਿਪਤਿਰਾਖੈ ॥","translit":"Apanae Saevak Kee Aap Path Raakhai ||","english":"He Himself preserves the honor of His servant."},{"punjabi":"ਤਾ ਕੀ ਗਤਿ ਮਿਤਿ ਕੋਇ ਨ ਲਾਖੈ ॥","lareedar":"ਤਾਕੀਗਤਿਮਿਤਿਕੋਇਨਲਾਖੈ ॥","translit":"Thaa Kee Gath Mith Koe N Laakhai ||","english":"No one knows His state and extent."},{"punjabi":"ਪ੍ਰਭ ਕੇ ਸੇਵਕ ਕਉ ਕੋ ਨ ਪਹੂਚੈ ॥","lareedar":"ਪ੍ਰਭਕੇਸੇਵਕਕਉਕੋਨਪਹੂਚੈ ॥","translit":"Prabh Kae Saevak Ko Ko N Pehoochai ||","english":"No one is equal to the servant of God."},{"punjabi":"ਪ੍ਰਭ ਕੇ ਸੇਵਕ ਊਚ ਤੇ ਊਚੇ ॥","lareedar":"ਪ੍ਰਭਕੇਸੇਵਕਊਚਤੇਊਚੇ ॥","translit":"Prabh Kae Saevak Ooch Thae Oochae ||","english":"The servant of God is the highest of the high."},{"punjabi":"ਜੋ ਪ੍ਰਭਿ ਅਪਨੀ ਸੇਵਾ ਲਾਇਆ ॥","lareedar":"ਜੋਪ੍ਰਭਿਅਪਨੀਸੇਵਾਲਾਇਆ ॥","translit":"Jo Prabh Apanee Saevaa Laaeiaa ||","english":"One whom God applies to His own service, O Nanak"},{"punjabi":"ਨਾਨਕ ਸੋ ਸੇਵਕੁ ਦਹ ਦਿਸਿ ਪ੍ਰਗਟਾਇਆ ॥੪॥","lareedar":"ਨਾਨਕਸੋਸੇਵਕੁਦਹਦਿਸਿਪ੍ਰਗਟਾਇਆ ॥੪ ॥","translit":"Naanak So Saevak Dheh Dhis Pragattaaeiaa ||4||","english":"- that servant is famous in the ten directions. ||4||"},{"punjabi":"ਨੀਕੀ ਕੀਰੀ ਮਹਿ ਕਲ ਰਾਖੈ ॥","lareedar":"ਨੀਕੀਕੀਰੀਮਹਿਕਲਰਾਖੈ ॥","translit":"Neekee Keeree Mehi Kal Raakhai ||","english":"He infuses His Power into the tiny ant;"}]},{"index":57,"ang":285,"lines":[{"punjabi":"ਭਸਮ ਕਰੈ ਲਸਕਰ ਕੋਟਿ ਲਾਖੈ ॥","lareedar":"ਭਸਮਕਰੈਲਸਕਰਕੋਟਿਲਾਖੈ ॥","translit":"Bhasam Karai Lasakar Kott Laakhai ||","english":"It can then reduce the armies of millions to ashes"},{"punjabi":"ਜਿਸ ਕਾ ਸਾਸੁ ਨ ਕਾਢਤ ਆਪਿ ॥","lareedar":"ਜਿਸਕਾਸਾਸੁਨਕਾਢਤਆਪਿ ॥","translit":"Jis Kaa Saas N Kaadtath Aap ||","english":"Those whose breath of life He Himself does not take away"},{"punjabi":"ਤਾ ਕਉ ਰਾਖਤ ਦੇ ਕਰਿ ਹਾਥ ॥","lareedar":"ਤਾਕਉਰਾਖਤਦੇਕਰਿਹਾਥ ॥","translit":"Thaa Ko Raakhath Dhae Kar Haathh ||","english":"He preserves them, and holds out His Hands to protect them."},{"punjabi":"ਮਾਨਸ ਜਤਨ ਕਰਤ ਬਹੁ ਭਾਤਿ ॥","lareedar":"ਮਾਨਸਜਤਨਕਰਤਬਹੁਭਾਤਿ ॥","translit":"Maanas Jathan Karath Bahu Bhaath ||","english":"You may make all sorts of efforts,"},{"punjabi":"ਤਿਸ ਕੇ ਕਰਤਬ ਬਿਰਥੇ ਜਾਤਿ ॥","lareedar":"ਤਿਸਕੇਕਰਤਬਬਿਰਥੇਜਾਤਿ ॥","translit":"This Kae Karathab Birathhae Jaath ||","english":"But these attempts are in vain."},{"punjabi":"ਮਾਰੈ ਨ ਰਾਖੈ ਅਵਰੁ ਨ ਕੋਇ ॥","lareedar":"ਮਾਰੈਨਰਾਖੈਅਵਰੁਨਕੋਇ ॥","translit":"Maarai N Raakhai Avar N Koe ||","english":"No one else can kill or preserve"},{"punjabi":"ਸਰਬ ਜੀਆ ਕਾ ਰਾਖਾ ਸੋਇ ॥","lareedar":"ਸਰਬਜੀਆਕਾਰਾਖਾਸੋਇ ॥","translit":"Sarab Jeeaa Kaa Raakhaa Soe ||","english":"He is the Protector of all beings."},{"punjabi":"ਕਾਹੇ ਸੋਚ ਕਰਹਿ ਰੇ ਪ੍ਰਾਣੀ ॥","lareedar":"ਕਾਹੇਸੋਚਕਰਹਿਰੇਪ੍ਰਾਣੀ ॥","translit":"Kaahae Soch Karehi Rae Praanee ||","english":"So why are you so anxious, O mortal?"},{"punjabi":"ਜਪਿ ਨਾਨਕ ਪ੍ਰਭ ਅਲਖ ਵਿਡਾਣੀ ॥੫॥","lareedar":"ਜਪਿਨਾਨਕਪ੍ਰਭਅਲਖਵਿਡਾਣੀ ॥੫ ॥","translit":"Jap Naanak Prabh Alakh Viddaanee ||5||","english":"Meditate, O Nanak, on God, the invisible, the wonderful! ||5||"},{"punjabi":"ਬਾਰੰ ਬਾਰ ਬਾਰ ਪ੍ਰਭੁ ਜਪੀਐ ॥","lareedar":"ਬਾਰੰਬਾਰਬਾਰਪ੍ਰਭੁਜਪੀਐ ॥","translit":"Baaran Baar Baar Prabh Japeeai ||","english":"Time after time, again and again, meditate on God."},{"punjabi":"ਪੀ ਅੰਮ੍ਰਿਤੁ ਇਹੁ ਮਨੁ ਤਨੁ ਧ੍ਰਪੀਐ ॥","lareedar":"ਪੀਅੰਮ੍ਰਿਤੁਇਹੁਮਨੁਤਨੁਧ੍ਰਪੀਐ ॥","translit":"Pee Anmrith Eihu Man Than Dhhrapeeai ||","english":"Drinking in this Nectar, this mind and body are satisfied."},{"punjabi":"ਨਾਮ ਰਤਨੁ ਜਿਨਿ ਗੁਰਮੁਖਿ ਪਾਇਆ ॥","lareedar":"ਨਾਮਰਤਨੁਜਿਨਿਗੁਰਮੁਖਿਪਾਇਆ ॥","translit":"Naam Rathan Jin Guramukh Paaeiaa ||","english":"The jewel of the Naam is obtained by the Gurmukhs;"},{"punjabi":"ਤਿਸੁ ਕਿਛੁ ਅਵਰੁ ਨਾਹੀ ਦ੍ਰਿਸਟਾਇਆ ॥","lareedar":"ਤਿਸੁਕਿਛੁਅਵਰੁਨਾਹੀਦ੍ਰਿਸਟਾਇਆ ॥","translit":"This Kishh Avar Naahee Dhrisattaaeiaa ||","english":"They see no other than God."},{"punjabi":"ਨਾਮੁ ਧਨੁ ਨਾਮੋ ਰੂਪੁ ਰੰਗੁ ॥","lareedar":"ਨਾਮੁਧਨੁਨਾਮੋਰੂਪੁਰੰਗੁ ॥","translit":"Naam Dhhan Naamo Roop Rang ||","english":"Unto them, the Naam is wealth, the Naam is beauty and delight."},{"punjabi":"ਨਾਮੋ ਸੁਖੁ ਹਰਿ ਨਾਮ ਕਾ ਸੰਗੁ ॥","lareedar":"ਨਾਮੋਸੁਖੁਹਰਿਨਾਮਕਾਸੰਗੁ ॥","translit":"Naamo Sukh Har Naam Kaa Sang ||","english":"The Naam is peace, the Lord's Name is their companion."},{"punjabi":"ਨਾਮ ਰਸਿ ਜੋ ਜਨ ਤ੍ਰਿਪਤਾਨੇ ॥","lareedar":"ਨਾਮਰਸਿਜੋਜਨਤ੍ਰਿਪਤਾਨੇ ॥","translit":"Naam Ras Jo Jan Thripathaanae ||","english":"Those who are satisfied by the essence of the Naam"},{"punjabi":"ਮਨ ਤਨ ਨਾਮਹਿ ਨਾਮਿ ਸਮਾਨੇ ॥","lareedar":"ਮਨਤਨਨਾਮਹਿਨਾਮਿਸਮਾਨੇ ॥","translit":"Man Than Naamehi Naam Samaanae ||","english":"Their minds and bodies are drenched with the Naam."},{"punjabi":"ਊਠਤ ਬੈਠਤ ਸੋਵਤ ਨਾਮ ॥","lareedar":"ਊਠਤਬੈਠਤਸੋਵਤਨਾਮ ॥","translit":"Oothath Baithath Sovath Naam ||","english":"While standing up, sitting down and sleeping, the Naam,"},{"punjabi":"ਕਹੁ ਨਾਨਕ ਜਨ ਕੈ ਸਦ ਕਾਮ ॥੬॥","lareedar":"ਕਹੁਨਾਨਕਜਨਕੈਸਦਕਾਮ ॥੬ ॥","translit":"Kahu Naanak Jan Kai Sadh Kaam ||6||","english":"Says Nanak, is forever the occupation of God's humble servant. ||6||"},{"punjabi":"ਬੋਲਹੁ ਜਸੁ ਜਿਹਬਾ ਦਿਨੁ ਰਾਤਿ ॥","lareedar":"ਬੋਲਹੁਜਸੁਜਿਹਬਾਦਿਨੁਰਾਤਿ ॥","translit":"Bolahu Jas Jihabaa Dhin Raath ||","english":"Chant His Praises with your tongue, day and night."},{"punjabi":"ਪ੍ਰਭਿ ਅਪਨੈ ਜਨ ਕੀਨੀ ਦਾਤਿ ॥","lareedar":"ਪ੍ਰਭਿਅਪਨੈਜਨਕੀਨੀਦਾਤਿ ॥","translit":"Prabh Apanai Jan Keenee Dhaath ||","english":"God Himself has given this gift to His servants."},{"punjabi":"ਕਰਹਿ ਭਗਤਿ ਆਤਮ ਕੈ ਚਾਇ ॥","lareedar":"ਕਰਹਿਭਗਤਿਆਤਮਕੈਚਾਇ ॥","translit":"Karehi Bhagath Aatham Kai Chaae ||","english":"Performing devotional worship with heart-felt love,"},{"punjabi":"ਪ੍ਰਭ ਅਪਨੇ ਸਿਉ ਰਹਹਿ ਸਮਾਇ ॥","lareedar":"ਪ੍ਰਭਅਪਨੇਸਿਉਰਹਹਿਸਮਾਇ ॥","translit":"Prabh Apanae Sio Rehehi Samaae ||","english":"They remain absorbed in God Himself."},{"punjabi":"ਜੋ ਹੋਆ ਹੋਵਤ ਸੋ ਜਾਨੈ ॥","lareedar":"ਜੋਹੋਆਹੋਵਤਸੋਜਾਨੈ ॥","translit":"Jo Hoaa Hovath So Jaanai ||","english":"They know the past and the present."},{"punjabi":"ਪ੍ਰਭ ਅਪਨੇ ਕਾ ਹੁਕਮੁ ਪਛਾਨੈ ॥","lareedar":"ਪ੍ਰਭਅਪਨੇਕਾਹੁਕਮੁਪਛਾਨੈ ॥","translit":"Prabh Apanae Kaa Hukam Pashhaanai ||","english":"They recognize God's Own Command."}]},{"index":58,"ang":286,"lines":[{"punjabi":"ਤਿਸ ਕੀ ਮਹਿਮਾ ਕਉਨ ਬਖਾਨਉ ॥","lareedar":"ਤਿਸਕੀਮਹਿਮਾਕਉਨਬਖਾਨਉ ॥","translit":"This Kee Mehimaa Koun Bakhaano ||","english":"Who can describe His Glory?"},{"punjabi":"ਤਿਸ ਕਾ ਗੁਨੁ ਕਹਿ ਏਕ ਨ ਜਾਨਉ ॥","lareedar":"ਤਿਸਕਾਗੁਨੁਕਹਿਏਕਨਜਾਨਉ ॥","translit":"This Kaa Gun Kehi Eaek N Jaano ||","english":"I cannot describe even one of His virtuous qualities."},{"punjabi":"ਆਠ ਪਹਰ ਪ੍ਰਭ ਬਸਹਿ ਹਜੂਰੇ ॥","lareedar":"ਆਠਪਹਰਪ੍ਰਭਬਸਹਿਹਜੂਰੇ ॥","translit":"Aath Pehar Prabh Basehi Hajoorae ||","english":"Those who dwell in God's Presence, twenty-four hours a day"},{"punjabi":"ਕਹੁ ਨਾਨਕ ਸੇਈ ਜਨ ਪੂਰੇ ॥੭॥","lareedar":"ਕਹੁਨਾਨਕਸੇਈਜਨਪੂਰੇ ॥੭ ॥","translit":"Kahu Naanak Saeee Jan Poorae ||7||","english":"- says Nanak, they are the perfect persons. ||7||"},{"punjabi":"ਮਨ ਮੇਰੇ ਤਿਨ ਕੀ ਓਟ ਲੇਹਿ ॥","lareedar":"ਮਨਮੇਰੇਤਿਨਕੀਓਟਲੇਹਿ ॥","translit":"Man Maerae Thin Kee Outt Laehi ||","english":"O my mind, seek their protection;"},{"punjabi":"ਮਨੁ ਤਨੁ ਅਪਨਾ ਤਿਨ ਜਨ ਦੇਹਿ ॥","lareedar":"ਮਨੁਤਨੁਅਪਨਾਤਿਨਜਨਦੇਹਿ ॥","translit":"Man Than Apanaa Thin Jan Dhaehi ||","english":"Give your mind and body to those humble beings."},{"punjabi":"ਜਿਨਿ ਜਨਿ ਅਪਨਾ ਪ੍ਰਭੂ ਪਛਾਤਾ ॥","lareedar":"ਜਿਨਿਜਨਿਅਪਨਾਪ੍ਰਭੂਪਛਾਤਾ ॥","translit":"Jin Jan Apanaa Prabhoo Pashhaathaa ||","english":"Those humble beings who recognizes God"},{"punjabi":"ਸੋ ਜਨੁ ਸਰਬ ਥੋਕ ਕਾ ਦਾਤਾ ॥","lareedar":"ਸੋਜਨੁਸਰਬਥੋਕਕਾਦਾਤਾ ॥","translit":"So Jan Sarab Thhok Kaa Dhaathaa ||","english":"Are the givers of all things."},{"punjabi":"ਤਿਸ ਕੀ ਸਰਨਿ ਸਰਬ ਸੁਖ ਪਾਵਹਿ ॥","lareedar":"ਤਿਸਕੀਸਰਨਿਸਰਬਸੁਖਪਾਵਹਿ ॥","translit":"This Kee Saran Sarab Sukh Paavehi ||","english":"In His Sanctuary, all comforts are obtained."},{"punjabi":"ਤਿਸ ਕੈ ਦਰਸਿ ਸਭ ਪਾਪ ਮਿਟਾਵਹਿ ॥","lareedar":"ਤਿਸਕੈਦਰਸਿਸਭਪਾਪਮਿਟਾਵਹਿ ॥","translit":"This Kai Dharas Sabh Paap Mittaavehi ||","english":"By the Blessing of His Darshan, all sins are erased."},{"punjabi":"ਅਵਰ ਸਿਆਨਪ ਸਗਲੀ ਛਾਡੁ ॥","lareedar":"ਅਵਰਸਿਆਨਪਸਗਲੀਛਾਡੁ ॥","translit":"Avar Siaanap Sagalee Shhaadd ||","english":"So renounce all other clever devices,"},{"punjabi":"ਤਿਸੁ ਜਨ ਕੀ ਤੂ ਸੇਵਾ ਲਾਗੁ ॥","lareedar":"ਤਿਸੁਜਨਕੀਤੂਸੇਵਾਲਾਗੁ ॥","translit":"This Jan Kee Thoo Saevaa Laag ||","english":"And enjoin yourself to the service of those servants."},{"punjabi":"ਆਵਨੁ ਜਾਨੁ ਨ ਹੋਵੀ ਤੇਰਾ ॥","lareedar":"ਆਵਨੁਜਾਨੁਨਹੋਵੀਤੇਰਾ ॥","translit":"Aavan Jaan N Hovee Thaeraa ||","english":"Your comings and goings shall be ended."},{"punjabi":"ਨਾਨਕ ਤਿਸੁ ਜਨ ਕੇ ਪੂਜਹੁ ਸਦ ਪੈਰਾ ॥੮॥੧੭॥","lareedar":"ਨਾਨਕਤਿਸੁਜਨਕੇਪੂਜਹੁਸਦਪੈਰਾ ॥੮ ॥੧੭ ॥","translit":"Naanak This Jan Kae Poojahu Sadh Pairaa ||8||17||","english":"O Nanak, worship the feet of God's humble servants forever. ||8||17||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਸਤਿ ਪੁਰਖੁ ਜਿਨਿ ਜਾਨਿਆ ਸਤਿਗੁਰੁ ਤਿਸ ਕਾ ਨਾਉ ॥","lareedar":"ਸਤਿਪੁਰਖੁਜਿਨਿਜਾਨਿਆਸਤਿਗੁਰੁਤਿਸਕਾਨਾਉ ॥","translit":"Sath Purakh Jin Jaaniaa Sathigur This Kaa Naao ||","english":"The one who knows the True Lord God, is called the True Guru."},{"punjabi":"ਤਿਸ ਕੈ ਸੰਗਿ ਸਿਖੁ ਉਧਰੈ ਨਾਨਕ ਹਰਿ ਗੁਨ ਗਾਉ ॥੧॥","lareedar":"ਤਿਸਕੈਸੰਗਿਸਿਖੁਉਧਰੈਨਾਨਕਹਰਿਗੁਨਗਾਉ ॥੧ ॥","translit":"This Kai Sang Sikh Oudhharai Naanak Har Gun Gaao ||1||","english":"In His Company, the Sikh is saved, O Nanak, singing the Glorious Praises of the Lord. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਸਤਿਗੁਰੁ ਸਿਖ ਕੀ ਕਰੈ ਪ੍ਰਤਿਪਾਲ ॥","lareedar":"ਸਤਿਗੁਰੁਸਿਖਕੀਕਰੈਪ੍ਰਤਿਪਾਲ ॥","translit":"Sathigur Sikh Kee Karai Prathipaal ||","english":"The True Guru cherishes His Sikh."},{"punjabi":"ਸੇਵਕ ਕਉ ਗੁਰੁ ਸਦਾ ਦਇਆਲ ॥","lareedar":"ਸੇਵਕਕਉਗੁਰੁਸਦਾਦਇਆਲ ॥","translit":"Saevak Ko Gur Sadhaa Dhaeiaal ||","english":"The Guru is always merciful to His servant."},{"punjabi":"ਸਿਖ ਕੀ ਗੁਰੁ ਦੁਰਮਤਿ ਮਲੁ ਹਿਰੈ ॥","lareedar":"ਸਿਖਕੀਗੁਰੁਦੁਰਮਤਿਮਲੁਹਿਰੈ ॥","translit":"Sikh Kee Gur Dhuramath Mal Hirai ||","english":"The Guru washes away the filth of the evil intellect of His Sikh."},{"punjabi":"ਗੁਰ ਬਚਨੀ ਹਰਿ ਨਾਮੁ ਉਚਰੈ ॥","lareedar":"ਗੁਰਬਚਨੀਹਰਿਨਾਮੁਉਚਰੈ ॥","translit":"Gur Bachanee Har Naam Oucharai ||","english":"Through the Guru's Teachings, he chants the Lord's Name."},{"punjabi":"ਸਤਿਗੁਰੁ ਸਿਖ ਕੇ ਬੰਧਨ ਕਾਟੈ ॥","lareedar":"ਸਤਿਗੁਰੁਸਿਖਕੇਬੰਧਨਕਾਟੈ ॥","translit":"Sathigur Sikh Kae Bandhhan Kaattai ||","english":"The True Guru cuts away the bonds of His Sikh."},{"punjabi":"ਗੁਰ ਕਾ ਸਿਖੁ ਬਿਕਾਰ ਤੇ ਹਾਟੈ ॥","lareedar":"ਗੁਰਕਾਸਿਖੁਬਿਕਾਰਤੇਹਾਟੈ ॥","translit":"Gur Kaa Sikh Bikaar Thae Haattai ||","english":"The Sikh of the Guru abstains from evil deeds."},{"punjabi":"ਸਤਿਗੁਰੁ ਸਿਖ ਕਉ ਨਾਮ ਧਨੁ ਦੇਇ ॥","lareedar":"ਸਤਿਗੁਰੁਸਿਖਕਉਨਾਮਧਨੁਦੇਇ ॥","translit":"Sathigur Sikh Ko Naam Dhhan Dhaee ||","english":"The True Guru gives His Sikh the wealth of the Naam."}]},{"index":59,"ang":286,"lines":[{"punjabi":"ਗੁਰ ਕਾ ਸਿਖੁ ਵਡਭਾਗੀ ਹੇ ॥","lareedar":"ਗੁਰਕਾਸਿਖੁਵਡਭਾਗੀਹੇ ॥","translit":"Gur Kaa Sikh Vaddabhaagee Hae ||","english":"The Sikh of the Guru is very fortunate."},{"punjabi":"ਸਤਿਗੁਰੁ ਸਿਖ ਕਾ ਹਲਤੁ ਪਲਤੁ ਸਵਾਰੈ ॥","lareedar":"ਸਤਿਗੁਰੁਸਿਖਕਾਹਲਤੁਪਲਤੁਸਵਾਰੈ ॥","translit":"Sathigur Sikh Kaa Halath Palath Savaarai ||","english":"The True Guru arranges this world and the next for His Sikh."},{"punjabi":"ਨਾਨਕ ਸਤਿਗੁਰੁ ਸਿਖ ਕਉ ਜੀਅ ਨਾਲਿ ਸਮਾਰੈ ॥੧॥","lareedar":"ਨਾਨਕਸਤਿਗੁਰੁਸਿਖਕਉਜੀਅਨਾਲਿਸਮਾਰੈ ॥੧ ॥","translit":"Naanak Sathigur Sikh Ko Jeea Naal Samaarai ||1||","english":"O Nanak, with the fullness of His heart, the True Guru mends His Sikh. ||1||"},{"punjabi":"ਗੁਰ ਕੈ ਗ੍ਰਿਹਿ ਸੇਵਕੁ ਜੋ ਰਹੈ ॥","lareedar":"ਗੁਰਕੈਗ੍ਰਿਹਿਸੇਵਕੁਜੋਰਹੈ ॥","translit":"Gur Kai Grihi Saevak Jo Rehai ||","english":"That selfless servant, who lives in the Guru's household,"},{"punjabi":"ਗੁਰ ਕੀ ਆਗਿਆ ਮਨ ਮਹਿ ਸਹੈ ॥","lareedar":"ਗੁਰਕੀਆਗਿਆਮਨਮਹਿਸਹੈ ॥","translit":"Gur Kee Aagiaa Man Mehi Sehai ||","english":"Is to obey the Guru's Commands with all his mind."},{"punjabi":"ਆਪਸ ਕਉ ਕਰਿ ਕਛੁ ਨ ਜਨਾਵੈ ॥","lareedar":"ਆਪਸਕਉਕਰਿਕਛੁਨਜਨਾਵੈ ॥","translit":"Aapas Ko Kar Kashh N Janaavai ||","english":"He is not to call attention to himself in any way."},{"punjabi":"ਹਰਿ ਹਰਿ ਨਾਮੁ ਰਿਦੈ ਸਦ ਧਿਆਵੈ ॥","lareedar":"ਹਰਿਹਰਿਨਾਮੁਰਿਦੈਸਦਧਿਆਵੈ ॥","translit":"Har Har Naam Ridhai Sadh Dhhiaavai ||","english":"He is to meditate constantly within his heart on the Name of the Lord."},{"punjabi":"ਮਨੁ ਬੇਚੈ ਸਤਿਗੁਰ ਕੈ ਪਾਸਿ ॥","lareedar":"ਮਨੁਬੇਚੈਸਤਿਗੁਰਕੈਪਾਸਿ ॥","translit":"Man Baechai Sathigur Kai Paas ||","english":"One who sells his mind to the True Guru"},{"punjabi":"ਤਿਸੁ ਸੇਵਕ ਕੇ ਕਾਰਜ ਰਾਸਿ ॥","lareedar":"ਤਿਸੁਸੇਵਕਕੇਕਾਰਜਰਾਸਿ ॥","translit":"This Saevak Kae Kaaraj Raas ||","english":"- that humble servant's affairs are resolved."},{"punjabi":"ਸੇਵਾ ਕਰਤ ਹੋਇ ਨਿਹਕਾਮੀ ॥","lareedar":"ਸੇਵਾਕਰਤਹੋਇਨਿਹਕਾਮੀ ॥","translit":"Saevaa Karath Hoe Nihakaamee ||","english":"One who performs selfless service, without thought of reward,"},{"punjabi":"ਤਿਸ ਕਉ ਹੋਤ ਪਰਾਪਤਿ ਸੁਆਮੀ ॥","lareedar":"ਤਿਸਕਉਹੋਤਪਰਾਪਤਿਸੁਆਮੀ ॥","translit":"This Ko Hoth Paraapath Suaamee ||","english":"Shall attain his Lord and Master."},{"punjabi":"ਅਪਨੀ ਕ੍ਰਿਪਾ ਜਿਸੁ ਆਪਿ ਕਰੇਇ ॥","lareedar":"ਅਪਨੀਕ੍ਰਿਪਾਜਿਸੁਆਪਿਕਰੇਇ ॥","translit":"Apanee Kirapaa Jis Aap Karaee ||","english":"He Himself grants His Grace;"},{"punjabi":"ਨਾਨਕ ਸੋ ਸੇਵਕੁ ਗੁਰ ਕੀ ਮਤਿ ਲੇਇ ॥੨॥","lareedar":"ਨਾਨਕਸੋਸੇਵਕੁਗੁਰਕੀਮਤਿਲੇਇ ॥੨ ॥","translit":"Naanak So Saevak Gur Kee Math Laee ||2||","english":"O Nanak, that selfless servant lives the Guru's Teachings. ||2||"},{"punjabi":"ਬੀਸ ਬਿਸਵੇ ਗੁਰ ਕਾ ਮਨੁ ਮਾਨੈ ॥","lareedar":"ਬੀਸਬਿਸਵੇਗੁਰਕਾਮਨੁਮਾਨੈ ॥","translit":"Bees Bisavae Gur Kaa Man Maanai ||","english":"One who obeys the Guru's Teachings one hundred per cent"},{"punjabi":"ਸੋ ਸੇਵਕੁ ਪਰਮੇਸੁਰ ਕੀ ਗਤਿ ਜਾਨੈ ॥","lareedar":"ਸੋਸੇਵਕੁਪਰਮੇਸੁਰਕੀਗਤਿਜਾਨੈ ॥","translit":"So Saevak Paramaesur Kee Gath Jaanai ||","english":"That selfless servant comes to know the state of the Transcendent Lord."},{"punjabi":"ਸੋ ਸਤਿਗੁਰੁ ਜਿਸੁ ਰਿਦੈ ਹਰਿ ਨਾਉ ॥","lareedar":"ਸੋਸਤਿਗੁਰੁਜਿਸੁਰਿਦੈਹਰਿਨਾਉ ॥","translit":"So Sathigur Jis Ridhai Har Naao ||","english":"The True Guru's Heart is filled with the Name of the Lord."},{"punjabi":"ਅਨਿਕ ਬਾਰ ਗੁਰ ਕਉ ਬਲਿ ਜਾਉ ॥","lareedar":"ਅਨਿਕਬਾਰਗੁਰਕਉਬਲਿਜਾਉ ॥","translit":"Anik Baar Gur Ko Bal Jaao ||","english":"So many times, I am a sacrifice to the Guru."},{"punjabi":"ਸਰਬ ਨਿਧਾਨ ਜੀਅ ਕਾ ਦਾਤਾ ॥","lareedar":"ਸਰਬਨਿਧਾਨਜੀਅਕਾਦਾਤਾ ॥","translit":"Sarab Nidhhaan Jeea Kaa Dhaathaa ||","english":"He is the treasure of everything, the Giver of life."},{"punjabi":"ਆਠ ਪਹਰ ਪਾਰਬ੍ਰਹਮ ਰੰਗਿ ਰਾਤਾ ॥","lareedar":"ਆਠਪਹਰਪਾਰਬ੍ਰਹਮਰੰਗਿਰਾਤਾ ॥","translit":"Aath Pehar Paarabreham Rang Raathaa ||","english":"Twenty-four hours a day, He is imbued with the Love of the Supreme Lord God."},{"punjabi":"ਬ੍ਰਹਮ ਮਹਿ ਜਨੁ ਜਨ ਮਹਿ ਪਾਰਬ੍ਰਹਮੁ ॥","lareedar":"ਬ੍ਰਹਮਮਹਿਜਨੁਜਨਮਹਿਪਾਰਬ੍ਰਹਮੁ ॥","translit":"Breham Mehi Jan Jan Mehi Paarabreham ||","english":"The servant is in God, and God is in the servant."},{"punjabi":"ਏਕਹਿ ਆਪਿ ਨਹੀ ਕਛੁ ਭਰਮੁ ॥","lareedar":"ਏਕਹਿਆਪਿਨਹੀਕਛੁਭਰਮੁ ॥","translit":"Eaekehi Aap Nehee Kashh Bharam ||","english":"He Himself is One - there is no doubt about this."},{"punjabi":"ਸਹਸ ਸਿਆਨਪ ਲਇਆ ਨ ਜਾਈਐ ॥","lareedar":"ਸਹਸਸਿਆਨਪਲਇਆਨਜਾਈਐ ॥","translit":"Sehas Siaanap Laeiaa N Jaaeeai ||","english":"By thousands of clever tricks, He is not found."},{"punjabi":"ਨਾਨਕ ਐਸਾ ਗੁਰੁ ਬਡਭਾਗੀ ਪਾਈਐ ॥੩॥","lareedar":"ਨਾਨਕਐਸਾਗੁਰੁਬਡਭਾਗੀਪਾਈਐ ॥੩ ॥","translit":"Naanak Aisaa Gur Baddabhaagee Paaeeai ||3||","english":"O Nanak, such a Guru is obtained by the greatest good fortune. ||3||"},{"punjabi":"ਸਫਲ ਦਰਸਨੁ ਪੇਖਤ ਪੁਨੀਤ ॥","lareedar":"ਸਫਲਦਰਸਨੁਪੇਖਤਪੁਨੀਤ ॥","translit":"Safal Dharasan Paekhath Puneeth ||","english":"Blessed is His Darshan; receiving it, one is purified."},{"punjabi":"ਪਰਸਤ ਚਰਨ ਗਤਿ ਨਿਰਮਲ ਰੀਤਿ ॥","lareedar":"ਪਰਸਤਚਰਨਗਤਿਨਿਰਮਲਰੀਤਿ ॥","translit":"Parasath Charan Gath Niramal Reeth ||","english":"Touching His Feet, one's conduct and lifestyle become pure."}]},{"index":60,"ang":287,"lines":[{"punjabi":"ਭੇਟਤ ਸੰਗਿ ਰਾਮ ਗੁਨ ਰਵੇ ॥","lareedar":"ਭੇਟਤਸੰਗਿਰਾਮਗੁਨਰਵੇ ॥","translit":"Bhaettath Sang Raam Gun Ravae ||","english":"Abiding in His Company, one chants the Lord's Praise,"},{"punjabi":"ਪਾਰਬ੍ਰਹਮ ਕੀ ਦਰਗਹ ਗਵੇ ॥","lareedar":"ਪਾਰਬ੍ਰਹਮਕੀਦਰਗਹਗਵੇ ॥","translit":"Paarabreham Kee Dharageh Gavae ||","english":"And reaches the Court of the Supreme Lord God."},{"punjabi":"ਸੁਨਿ ਕਰਿ ਬਚਨ ਕਰਨ ਆਘਾਨੇ ॥","lareedar":"ਸੁਨਿਕਰਿਬਚਨਕਰਨਆਘਾਨੇ ॥","translit":"Sun Kar Bachan Karan Aaghaanae ||","english":"Listening to His Teachings, one's ears are satisfied."},{"punjabi":"ਮਨਿ ਸੰਤੋਖੁ ਆਤਮ ਪਤੀਆਨੇ ॥","lareedar":"ਮਨਿਸੰਤੋਖੁਆਤਮਪਤੀਆਨੇ ॥","translit":"Man Santhokh Aatham Patheeaanae ||","english":"The mind is contented, and the soul is fulfilled."},{"punjabi":"ਪੂਰਾ ਗੁਰੁ ਅਖ੍ਯ੍ਯਓ ਜਾ ਕਾ ਮੰਤ੍ਰ ॥","lareedar":"ਪੂਰਾਗੁਰੁਅਖ੍ਯ੍ਯਓਜਾਕਾਮੰਤ੍ਰ ॥","translit":"Pooraa Gur Akhyou Jaa Kaa Manthr ||","english":"The Guru is perfect; His Teachings are everlasting."},{"punjabi":"ਅੰਮ੍ਰਿਤ ਦ੍ਰਿਸਟਿ ਪੇਖੈ ਹੋਇ ਸੰਤ ॥","lareedar":"ਅੰਮ੍ਰਿਤਦ੍ਰਿਸਟਿਪੇਖੈਹੋਇਸੰਤ ॥","translit":"Anmrith Dhrisatt Paekhai Hoe Santh ||","english":"Beholding His Ambrosial Glance, one becomes saintly."},{"punjabi":"ਗੁਣ ਬਿਅੰਤ ਕੀਮਤਿ ਨਹੀ ਪਾਇ ॥","lareedar":"ਗੁਣਬਿਅੰਤਕੀਮਤਿਨਹੀਪਾਇ ॥","translit":"Gun Bianth Keemath Nehee Paae ||","english":"Endless are His virtuous qualities; His worth cannot be appraised."},{"punjabi":"ਨਾਨਕ ਜਿਸੁ ਭਾਵੈ ਤਿਸੁ ਲਏ ਮਿਲਾਇ ॥੪॥","lareedar":"ਨਾਨਕਜਿਸੁਭਾਵੈਤਿਸੁਲਏਮਿਲਾਇ ॥੪ ॥","translit":"Naanak Jis Bhaavai This Leae Milaae ||4||","english":"O Nanak, one who pleases Him is united with Him. ||4||"},{"punjabi":"ਜਿਹਬਾ ਏਕ ਉਸਤਤਿ ਅਨੇਕ ॥","lareedar":"ਜਿਹਬਾਏਕਉਸਤਤਿਅਨੇਕ ॥","translit":"Jihabaa Eaek Ousathath Anaek ||","english":"The tongue is one, but His Praises are many."},{"punjabi":"ਸਤਿ ਪੁਰਖ ਪੂਰਨ ਬਿਬੇਕ ॥","lareedar":"ਸਤਿਪੁਰਖਪੂਰਨਬਿਬੇਕ ॥","translit":"Sath Purakh Pooran Bibaek ||","english":"The True Lord, of perfect perfection -"},{"punjabi":"ਕਾਹੂ ਬੋਲ ਨ ਪਹੁਚਤ ਪ੍ਰਾਨੀ ॥","lareedar":"ਕਾਹੂਬੋਲਨਪਹੁਚਤਪ੍ਰਾਨੀ ॥","translit":"Kaahoo Bol N Pahuchath Praanee ||","english":"No speech can take the mortal to Him."},{"punjabi":"ਅਗਮ ਅਗੋਚਰ ਪ੍ਰਭ ਨਿਰਬਾਨੀ ॥","lareedar":"ਅਗਮਅਗੋਚਰਪ੍ਰਭਨਿਰਬਾਨੀ ॥","translit":"Agam Agochar Prabh Nirabaanee ||","english":"God is Inaccessible, Incomprehensible, balanced in the state of Nirvaanaa."},{"punjabi":"ਨਿਰਾਹਾਰ ਨਿਰਵੈਰ ਸੁਖਦਾਈ ॥","lareedar":"ਨਿਰਾਹਾਰਨਿਰਵੈਰਸੁਖਦਾਈ ॥","translit":"Niraahaar Niravair Sukhadhaaee ||","english":"He is not sustained by food; He has no hatred or vengeance; He is the Giver of peace."},{"punjabi":"ਤਾ ਕੀ ਕੀਮਤਿ ਕਿਨੈ ਨ ਪਾਈ ॥","lareedar":"ਤਾਕੀਕੀਮਤਿਕਿਨੈਨਪਾਈ ॥","translit":"Thaa Kee Keemath Kinai N Paaee ||","english":"No one can estimate His worth."},{"punjabi":"ਅਨਿਕ ਭਗਤ ਬੰਦਨ ਨਿਤ ਕਰਹਿ ॥","lareedar":"ਅਨਿਕਭਗਤਬੰਦਨਨਿਤਕਰਹਿ ॥","translit":"Anik Bhagath Bandhan Nith Karehi ||","english":"Countless devotees continually bow in reverence to Him."},{"punjabi":"ਚਰਨ ਕਮਲ ਹਿਰਦੈ ਸਿਮਰਹਿ ॥","lareedar":"ਚਰਨਕਮਲਹਿਰਦੈਸਿਮਰਹਿ ॥","translit":"Charan Kamal Hiradhai Simarehi ||","english":"In their hearts, they meditate on His Lotus Feet."},{"punjabi":"ਸਦ ਬਲਿਹਾਰੀ ਸਤਿਗੁਰ ਅਪਨੇ ॥","lareedar":"ਸਦਬਲਿਹਾਰੀਸਤਿਗੁਰਅਪਨੇ ॥","translit":"Sadh Balihaaree Sathigur Apanae ||","english":"Nanak is forever a sacrifice to the True Guru;"},{"punjabi":"ਨਾਨਕ ਜਿਸੁ ਪ੍ਰਸਾਦਿ ਐਸਾ ਪ੍ਰਭੁ ਜਪਨੇ ॥੫॥","lareedar":"ਨਾਨਕਜਿਸੁਪ੍ਰਸਾਦਿਐਸਾਪ੍ਰਭੁਜਪਨੇ ॥੫ ॥","translit":"Naanak Jis Prasaadh Aisaa Prabh Japanae ||5||","english":"By His Grace, he meditates on God. ||5||"},{"punjabi":"ਇਹੁ ਹਰਿ ਰਸੁ ਪਾਵੈ ਜਨੁ ਕੋਇ ॥","lareedar":"ਇਹੁਹਰਿਰਸੁਪਾਵੈਜਨੁਕੋਇ ॥","translit":"Eihu Har Ras Paavai Jan Koe ||","english":"Only a few obtain this ambrosial essence of the Lord's Name."},{"punjabi":"ਅੰਮ੍ਰਿਤੁ ਪੀਵੈ ਅਮਰੁ ਸੋ ਹੋਇ ॥","lareedar":"ਅੰਮ੍ਰਿਤੁਪੀਵੈਅਮਰੁਸੋਹੋਇ ॥","translit":"Anmrith Peevai Amar So Hoe ||","english":"Drinking in this Nectar, one becomes immortal."},{"punjabi":"ਉਸੁ ਪੁਰਖ ਕਾ ਨਾਹੀ ਕਦੇ ਬਿਨਾਸ ॥","lareedar":"ਉਸੁਪੁਰਖਕਾਨਾਹੀਕਦੇਬਿਨਾਸ ॥","translit":"Ous Purakh Kaa Naahee Kadhae Binaas ||","english":"That person whose mind is illuminated"},{"punjabi":"ਜਾ ਕੈ ਮਨਿ ਪ੍ਰਗਟੇ ਗੁਨਤਾਸ ॥","lareedar":"ਜਾਕੈਮਨਿਪ੍ਰਗਟੇਗੁਨਤਾਸ ॥","translit":"Jaa Kai Man Pragattae Gunathaas ||","english":"By the treasure of excellence, never dies."},{"punjabi":"ਆਠ ਪਹਰ ਹਰਿ ਕਾ ਨਾਮੁ ਲੇਇ ॥","lareedar":"ਆਠਪਹਰਹਰਿਕਾਨਾਮੁਲੇਇ ॥","translit":"Aath Pehar Har Kaa Naam Laee ||","english":"Twenty-four hours a day, he takes the Name of the Lord."},{"punjabi":"ਸਚੁ ਉਪਦੇਸੁ ਸੇਵਕ ਕਉ ਦੇਇ ॥","lareedar":"ਸਚੁਉਪਦੇਸੁਸੇਵਕਕਉਦੇਇ ॥","translit":"Sach Oupadhaes Saevak Ko Dhaee ||","english":"The Lord gives true instruction to His servant."},{"punjabi":"ਮੋਹ ਮਾਇਆ ਕੈ ਸੰਗਿ ਨ ਲੇਪੁ ॥","lareedar":"ਮੋਹਮਾਇਆਕੈਸੰਗਿਨਲੇਪੁ ॥","translit":"Moh Maaeiaa Kai Sang N Laep ||","english":"He is not polluted by emotional attachment to Maya."}]},{"index":61,"ang":287,"lines":[{"punjabi":"ਮਨ ਮਹਿ ਰਾਖੈ ਹਰਿ ਹਰਿ ਏਕੁ ॥","lareedar":"ਮਨਮਹਿਰਾਖੈਹਰਿਹਰਿਏਕੁ ॥","translit":"Man Mehi Raakhai Har Har Eaek ||","english":"In his mind, he cherishes the One Lord, Har, Har."},{"punjabi":"ਅੰਧਕਾਰ ਦੀਪਕ ਪਰਗਾਸੇ ॥","lareedar":"ਅੰਧਕਾਰਦੀਪਕਪਰਗਾਸੇ ॥","translit":"Andhhakaar Dheepak Paragaasae ||","english":"In the pitch darkness, a lamp shines forth."},{"punjabi":"ਨਾਨਕ ਭਰਮ ਮੋਹ ਦੁਖ ਤਹ ਤੇ ਨਾਸੇ ॥੬॥","lareedar":"ਨਾਨਕਭਰਮਮੋਹਦੁਖਤਹਤੇਨਾਸੇ ॥੬ ॥","translit":"Naanak Bharam Moh Dhukh Theh Thae Naasae ||6||","english":"O Nanak, doubt, emotional attachment and pain are erased. ||6||"},{"punjabi":"ਤਪਤਿ ਮਾਹਿ ਠਾਢਿ ਵਰਤਾਈ ॥","lareedar":"ਤਪਤਿਮਾਹਿਠਾਢਿਵਰਤਾਈ ॥","translit":"Thapath Maahi Thaadt Varathaaee ||","english":"In the burning heat, a soothing coolness prevails."},{"punjabi":"ਅਨਦੁ ਭਇਆ ਦੁਖ ਨਾਠੇ ਭਾਈ ॥","lareedar":"ਅਨਦੁਭਇਆਦੁਖਨਾਠੇਭਾਈ ॥","translit":"Anadh Bhaeiaa Dhukh Naathae Bhaaee ||","english":"Happiness ensues and pain departs, O Siblings of Destiny."},{"punjabi":"ਜਨਮ ਮਰਨ ਕੇ ਮਿਟੇ ਅੰਦੇਸੇ ॥","lareedar":"ਜਨਮਮਰਨਕੇਮਿਟੇਅੰਦੇਸੇ ॥","translit":"Janam Maran Kae Mittae Andhaesae ||","english":"The fear of birth and death is dispelled,"},{"punjabi":"ਸਾਧੂ ਕੇ ਪੂਰਨ ਉਪਦੇਸੇ ॥","lareedar":"ਸਾਧੂਕੇਪੂਰਨਉਪਦੇਸੇ ॥","translit":"Saadhhoo Kae Pooran Oupadhaesae ||","english":"By the perfect Teachings of the Holy Saint."},{"punjabi":"ਭਉ ਚੂਕਾ ਨਿਰਭਉ ਹੋਇ ਬਸੇ ॥","lareedar":"ਭਉਚੂਕਾਨਿਰਭਉਹੋਇਬਸੇ ॥","translit":"Bho Chookaa Nirabho Hoe Basae ||","english":"Fear is lifted, and one abides in fearlessness."},{"punjabi":"ਸਗਲ ਬਿਆਧਿ ਮਨ ਤੇ ਖੈ ਨਸੇ ॥","lareedar":"ਸਗਲਬਿਆਧਿਮਨਤੇਖੈਨਸੇ ॥","translit":"Sagal Biaadhh Man Thae Khai Nasae ||","english":"All evils are dispelled from the mind."},{"punjabi":"ਜਿਸ ਕਾ ਸਾ ਤਿਨਿ ਕਿਰਪਾ ਧਾਰੀ ॥","lareedar":"ਜਿਸਕਾਸਾਤਿਨਿਕਿਰਪਾਧਾਰੀ ॥","translit":"Jis Kaa Saa Thin Kirapaa Dhhaaree ||","english":"He takes us into His favor as His own."},{"punjabi":"ਸਾਧਸੰਗਿ ਜਪਿ ਨਾਮੁ ਮੁਰਾਰੀ ॥","lareedar":"ਸਾਧਸੰਗਿਜਪਿਨਾਮੁਮੁਰਾਰੀ ॥","translit":"Saadhhasang Jap Naam Muraaree ||","english":"In the Company of the Holy, chant the Naam, the Name of the Lord."},{"punjabi":"ਥਿਤਿ ਪਾਈ ਚੂਕੇ ਭ੍ਰਮ ਗਵਨ ॥","lareedar":"ਥਿਤਿਪਾਈਚੂਕੇਭ੍ਰਮਗਵਨ ॥","translit":"Thhith Paaee Chookae Bhram Gavan ||","english":"Stability is attained; doubt and wandering cease,"},{"punjabi":"ਸੁਨਿ ਨਾਨਕ ਹਰਿ ਹਰਿ ਜਸੁ ਸ੍ਰਵਨ ॥੭॥","lareedar":"ਸੁਨਿਨਾਨਕਹਰਿਹਰਿਜਸੁਸ੍ਰਵਨ ॥੭ ॥","translit":"Sun Naanak Har Har Jas Sravan ||7||","english":"O Nanak, listening with one's ears to the Praises of the Lord, Har, Har. ||7||"},{"punjabi":"ਨਿਰਗੁਨੁ ਆਪਿ ਸਰਗੁਨੁ ਭੀ ਓਹੀ ॥","lareedar":"ਨਿਰਗੁਨੁਆਪਿਸਰਗੁਨੁਭੀਓਹੀ ॥","translit":"Niragun Aap Saragun Bhee Ouhee ||","english":"He Himself is absolute and unrelated; He Himself is also involved and related."},{"punjabi":"ਕਲਾ ਧਾਰਿ ਜਿਨਿ ਸਗਲੀ ਮੋਹੀ ॥","lareedar":"ਕਲਾਧਾਰਿਜਿਨਿਸਗਲੀਮੋਹੀ ॥","translit":"Kalaa Dhhaar Jin Sagalee Mohee ||","english":"Manifesting His power, He fascinates the entire world."},{"punjabi":"ਅਪਨੇ ਚਰਿਤ ਪ੍ਰਭਿ ਆਪਿ ਬਨਾਏ ॥","lareedar":"ਅਪਨੇਚਰਿਤਪ੍ਰਭਿਆਪਿਬਨਾਏ ॥","translit":"Apanae Charith Prabh Aap Banaaeae ||","english":"God Himself sets His play in motion."},{"punjabi":"ਅਪੁਨੀ ਕੀਮਤਿ ਆਪੇ ਪਾਏ ॥","lareedar":"ਅਪੁਨੀਕੀਮਤਿਆਪੇਪਾਏ ॥","translit":"Apunee Keemath Aapae Paaeae ||","english":"Only He Himself can estimate His worth."},{"punjabi":"ਹਰਿ ਬਿਨੁ ਦੂਜਾ ਨਾਹੀ ਕੋਇ ॥","lareedar":"ਹਰਿਬਿਨੁਦੂਜਾਨਾਹੀਕੋਇ ॥","translit":"Har Bin Dhoojaa Naahee Koe ||","english":"There is none, other than the Lord."},{"punjabi":"ਸਰਬ ਨਿਰੰਤਰਿ ਏਕੋ ਸੋਇ ॥","lareedar":"ਸਰਬਨਿਰੰਤਰਿਏਕੋਸੋਇ ॥","translit":"Sarab Niranthar Eaeko Soe ||","english":"Permeating all, He is the One."},{"punjabi":"ਓਤਿ ਪੋਤਿ ਰਵਿਆ ਰੂਪ ਰੰਗ ॥","lareedar":"ਓਤਿਪੋਤਿਰਵਿਆਰੂਪਰੰਗ ॥","translit":"Outh Poth Raviaa Roop Rang ||","english":"Through and through, He pervades in form and color."},{"punjabi":"ਭਏ ਪ੍ਰਗਾਸ ਸਾਧ ਕੈ ਸੰਗ ॥","lareedar":"ਭਏਪ੍ਰਗਾਸਸਾਧਕੈਸੰਗ ॥","translit":"Bheae Pragaas Saadhh Kai Sang ||","english":"He is revealed in the Company of the Holy."},{"punjabi":"ਰਚਿ ਰਚਨਾ ਅਪਨੀ ਕਲ ਧਾਰੀ ॥","lareedar":"ਰਚਿਰਚਨਾਅਪਨੀਕਲਧਾਰੀ ॥","translit":"Rach Rachanaa Apanee Kal Dhhaaree ||","english":"Having created the creation, He infuses His own power into it."},{"punjabi":"ਅਨਿਕ ਬਾਰ ਨਾਨਕ ਬਲਿਹਾਰੀ ॥੮॥੧੮॥","lareedar":"ਅਨਿਕਬਾਰਨਾਨਕਬਲਿਹਾਰੀ ॥੮ ॥੧੮ ॥","translit":"Anik Baar Naanak Balihaaree ||8||18||","english":"So many times, Nanak is a sacrifice to Him. ||8||18||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਸਾਥਿ ਨ ਚਾਲੈ ਬਿਨੁ ਭਜਨ ਬਿਖਿਆ ਸਗਲੀ ਛਾਰੁ ॥","lareedar":"ਸਾਥਿਨਚਾਲੈਬਿਨੁਭਜਨਬਿਖਿਆਸਗਲੀਛਾਰੁ ॥","translit":"Saathh N Chaalai Bin Bhajan Bikhiaa Sagalee Shhaar ||","english":"Nothing shall go along with you, except your devotion. All corruption is like ashes."}]},{"index":62,"ang":288,"lines":[{"punjabi":"ਹਰਿ ਹਰਿ ਨਾਮੁ ਕਮਾਵਨਾ ਨਾਨਕ ਇਹੁ ਧਨੁ ਸਾਰੁ ॥੧॥","lareedar":"ਹਰਿਹਰਿਨਾਮੁਕਮਾਵਨਾਨਾਨਕਇਹੁਧਨੁਸਾਰੁ ॥੧ ॥","translit":"Har Har Naam Kamaavanaa Naanak Eihu Dhhan Saar ||1||","english":"Practice the Name of the Lord, Har, Har. O Nanak, this is the most excellent wealth. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਸੰਤ ਜਨਾ ਮਿਲਿ ਕਰਹੁ ਬੀਚਾਰੁ ॥","lareedar":"ਸੰਤਜਨਾਮਿਲਿਕਰਹੁਬੀਚਾਰੁ ॥","translit":"Santh Janaa Mil Karahu Beechaar ||","english":"Joining the Company of the Saints, practice deep meditation."},{"punjabi":"ਏਕੁ ਸਿਮਰਿ ਨਾਮ ਆਧਾਰੁ ॥","lareedar":"ਏਕੁਸਿਮਰਿਨਾਮਆਧਾਰੁ ॥","translit":"Eaek Simar Naam Aadhhaar ||","english":"Remember the One, and take the Support of the Naam, the Name of the Lord."},{"punjabi":"ਅਵਰਿ ਉਪਾਵ ਸਭਿ ਮੀਤ ਬਿਸਾਰਹੁ ॥","lareedar":"ਅਵਰਿਉਪਾਵਸਭਿਮੀਤਬਿਸਾਰਹੁ ॥","translit":"Avar Oupaav Sabh Meeth Bisaarahu ||","english":"Forget all other efforts, O my friend"},{"punjabi":"ਚਰਨ ਕਮਲ ਰਿਦ ਮਹਿ ਉਰਿ ਧਾਰਹੁ ॥","lareedar":"ਚਰਨਕਮਲਰਿਦਮਹਿਉਰਿਧਾਰਹੁ ॥","translit":"Charan Kamal Ridh Mehi Our Dhhaarahu ||","english":"- enshrine the Lord's Lotus Feet within your heart."},{"punjabi":"ਕਰਨ ਕਾਰਨ ਸੋ ਪ੍ਰਭੁ ਸਮਰਥੁ ॥","lareedar":"ਕਰਨਕਾਰਨਸੋਪ੍ਰਭੁਸਮਰਥੁ ॥","translit":"Karan Kaaran So Prabh Samarathh ||","english":"God is All-powerful; He is the Cause of causes."},{"punjabi":"ਦ੍ਰਿੜੁ ਕਰਿ ਗਹਹੁ ਨਾਮੁ ਹਰਿ ਵਥੁ ॥","lareedar":"ਦ੍ਰਿੜੁਕਰਿਗਹਹੁਨਾਮੁਹਰਿਵਥੁ ॥","translit":"Dhrirr Kar Gehahu Naam Har Vathh ||","english":"Grasp firmly the object of the Lord's Name."},{"punjabi":"ਇਹੁ ਧਨੁ ਸੰਚਹੁ ਹੋਵਹੁ ਭਗਵੰਤ ॥","lareedar":"ਇਹੁਧਨੁਸੰਚਹੁਹੋਵਹੁਭਗਵੰਤ ॥","translit":"Eihu Dhhan Sanchahu Hovahu Bhagavanth ||","english":"Gather this wealth, and become very fortunate."},{"punjabi":"ਸੰਤ ਜਨਾ ਕਾ ਨਿਰਮਲ ਮੰਤ ॥","lareedar":"ਸੰਤਜਨਾਕਾਨਿਰਮਲਮੰਤ ॥","translit":"Santh Janaa Kaa Niramal Manth ||","english":"Pure are the instructions of the humble Saints."},{"punjabi":"ਏਕ ਆਸ ਰਾਖਹੁ ਮਨ ਮਾਹਿ ॥","lareedar":"ਏਕਆਸਰਾਖਹੁਮਨਮਾਹਿ ॥","translit":"Eaek Aas Raakhahu Man Maahi ||","english":"Keep faith in the One Lord within your mind."},{"punjabi":"ਸਰਬ ਰੋਗ ਨਾਨਕ ਮਿਟਿ ਜਾਹਿ ॥੧॥","lareedar":"ਸਰਬਰੋਗਨਾਨਕਮਿਟਿਜਾਹਿ ॥੧ ॥","translit":"Sarab Rog Naanak Mitt Jaahi ||1||","english":"All disease, O Nanak, shall then be dispelled. ||1||"},{"punjabi":"ਜਿਸੁ ਧਨ ਕਉ ਚਾਰਿ ਕੁੰਟ ਉਠਿ ਧਾਵਹਿ ॥","lareedar":"ਜਿਸੁਧਨਕਉਚਾਰਿਕੁੰਟਉਠਿਧਾਵਹਿ ॥","translit":"Jis Dhhan Ko Chaar Kuntt Outh Dhhaavehi ||","english":"The wealth which you chase after in the four directions"},{"punjabi":"ਸੋ ਧਨੁ ਹਰਿ ਸੇਵਾ ਤੇ ਪਾਵਹਿ ॥","lareedar":"ਸੋਧਨੁਹਰਿਸੇਵਾਤੇਪਾਵਹਿ ॥","translit":"So Dhhan Har Saevaa Thae Paavehi ||","english":"You shall obtain that wealth by serving the Lord."},{"punjabi":"ਜਿਸੁ ਸੁਖ ਕਉ ਨਿਤ ਬਾਛਹਿ ਮੀਤ ॥","lareedar":"ਜਿਸੁਸੁਖਕਉਨਿਤਬਾਛਹਿਮੀਤ ॥","translit":"Jis Sukh Ko Nith Baashhehi Meeth ||","english":"The peace, which you always yearn for, O friend"},{"punjabi":"ਸੋ ਸੁਖੁ ਸਾਧੂ ਸੰਗਿ ਪਰੀਤਿ ॥","lareedar":"ਸੋਸੁਖੁਸਾਧੂਸੰਗਿਪਰੀਤਿ ॥","translit":"So Sukh Saadhhoo Sang Pareeth ||","english":"That peace comes by the love of the Company of the Holy."},{"punjabi":"ਜਿਸੁ ਸੋਭਾ ਕਉ ਕਰਹਿ ਭਲੀ ਕਰਨੀ ॥","lareedar":"ਜਿਸੁਸੋਭਾਕਉਕਰਹਿਭਲੀਕਰਨੀ ॥","translit":"Jis Sobhaa Ko Karehi Bhalee Karanee ||","english":"The glory, for which you perform good deeds"},{"punjabi":"ਸਾ ਸੋਭਾ ਭਜੁ ਹਰਿ ਕੀ ਸਰਨੀ ॥","lareedar":"ਸਾਸੋਭਾਭਜੁਹਰਿਕੀਸਰਨੀ ॥","translit":"Saa Sobhaa Bhaj Har Kee Saranee ||","english":"- you shall obtain that glory by seeking the Lord's Sanctuary."},{"punjabi":"ਅਨਿਕ ਉਪਾਵੀ ਰੋਗੁ ਨ ਜਾਇ ॥","lareedar":"ਅਨਿਕਉਪਾਵੀਰੋਗੁਨਜਾਇ ॥","translit":"Anik Oupaavee Rog N Jaae ||","english":"All sorts of remedies have not cured the disease"},{"punjabi":"ਰੋਗੁ ਮਿਟੈ ਹਰਿ ਅਵਖਧੁ ਲਾਇ ॥","lareedar":"ਰੋਗੁਮਿਟੈਹਰਿਅਵਖਧੁਲਾਇ ॥","translit":"Rog Mittai Har Avakhadhh Laae ||","english":"- the disease is cured only by giving the medicine of the Lord's Name."},{"punjabi":"ਸਰਬ ਨਿਧਾਨ ਮਹਿ ਹਰਿ ਨਾਮੁ ਨਿਧਾਨੁ ॥","lareedar":"ਸਰਬਨਿਧਾਨਮਹਿਹਰਿਨਾਮੁਨਿਧਾਨੁ ॥","translit":"Sarab Nidhhaan Mehi Har Naam Nidhhaan ||","english":"Of all treasures, the Lord's Name is the supreme treasure."},{"punjabi":"ਜਪਿ ਨਾਨਕ ਦਰਗਹਿ ਪਰਵਾਨੁ ॥੨॥","lareedar":"ਜਪਿਨਾਨਕਦਰਗਹਿਪਰਵਾਨੁ ॥੨ ॥","translit":"Jap Naanak Dharagehi Paravaan ||2||","english":"Chant it, O Nanak, and be accepted in the Court of the Lord. ||2||"},{"punjabi":"ਮਨੁ ਪਰਬੋਧਹੁ ਹਰਿ ਕੈ ਨਾਇ ॥","lareedar":"ਮਨੁਪਰਬੋਧਹੁਹਰਿਕੈਨਾਇ ॥","translit":"Man Parabodhhahu Har Kai Naae ||","english":"Enlighten your mind with the Name of the Lord."},{"punjabi":"ਦਹ ਦਿਸਿ ਧਾਵਤ ਆਵੈ ਠਾਇ ॥","lareedar":"ਦਹਦਿਸਿਧਾਵਤਆਵੈਠਾਇ ॥","translit":"Dheh Dhis Dhhaavath Aavai Thaae ||","english":"Having wandered around in the ten directions, it comes to its place of rest."},{"punjabi":"ਤਾ ਕਉ ਬਿਘਨੁ ਨ ਲਾਗੈ ਕੋਇ ॥","lareedar":"ਤਾਕਉਬਿਘਨੁਨਲਾਗੈਕੋਇ ॥","translit":"Thaa Ko Bighan N Laagai Koe ||","english":"No obstacle stands in the way of one"}]},{"index":63,"ang":288,"lines":[{"punjabi":"ਜਾ ਕੈ ਰਿਦੈ ਬਸੈ ਹਰਿ ਸੋਇ ॥","lareedar":"ਜਾਕੈਰਿਦੈਬਸੈਹਰਿਸੋਇ ॥","translit":"Jaa Kai Ridhai Basai Har Soe ||","english":"Whose heart is filled with the Lord."},{"punjabi":"ਕਲਿ ਤਾਤੀ ਠਾਂਢਾ ਹਰਿ ਨਾਉ ॥","lareedar":"ਕਲਿਤਾਤੀਠਾਂਢਾਹਰਿਨਾਉ ॥","translit":"Kal Thaathee Thaandtaa Har Naao ||","english":"The Dark Age of Kali Yuga is so hot; the Lord's Name is soothing and cool."},{"punjabi":"ਸਿਮਰਿ ਸਿਮਰਿ ਸਦਾ ਸੁਖ ਪਾਉ ॥","lareedar":"ਸਿਮਰਿਸਿਮਰਿਸਦਾਸੁਖਪਾਉ ॥","translit":"Simar Simar Sadhaa Sukh Paao ||","english":"Remember, remember it in meditation, and obtain everlasting peace."},{"punjabi":"ਭਉ ਬਿਨਸੈ ਪੂਰਨ ਹੋਇ ਆਸ ॥","lareedar":"ਭਉਬਿਨਸੈਪੂਰਨਹੋਇਆਸ ॥","translit":"Bho Binasai Pooran Hoe Aas ||","english":"Your fear shall be dispelled, and your hopes shall be fulfilled."},{"punjabi":"ਭਗਤਿ ਭਾਇ ਆਤਮ ਪਰਗਾਸ ॥","lareedar":"ਭਗਤਿਭਾਇਆਤਮਪਰਗਾਸ ॥","translit":"Bhagath Bhaae Aatham Paragaas ||","english":"By devotional worship and loving adoration, your soul shall be enlightened."},{"punjabi":"ਤਿਤੁ ਘਰਿ ਜਾਇ ਬਸੈ ਅਬਿਨਾਸੀ ॥","lareedar":"ਤਿਤੁਘਰਿਜਾਇਬਸੈਅਬਿਨਾਸੀ ॥","translit":"Thith Ghar Jaae Basai Abinaasee ||","english":"You shall go to that home, and live forever."},{"punjabi":"ਕਹੁ ਨਾਨਕ ਕਾਟੀ ਜਮ ਫਾਸੀ ॥੩॥","lareedar":"ਕਹੁਨਾਨਕਕਾਟੀਜਮਫਾਸੀ ॥੩ ॥","translit":"Kahu Naanak Kaattee Jam Faasee ||3||","english":"Says Nanak, the noose of death is cut away. ||3||"},{"punjabi":"ਤਤੁ ਬੀਚਾਰੁ ਕਹੈ ਜਨੁ ਸਾਚਾ ॥","lareedar":"ਤਤੁਬੀਚਾਰੁਕਹੈਜਨੁਸਾਚਾ ॥","translit":"Thath Beechaar Kehai Jan Saachaa ||","english":"One who contemplates the essence of reality, is said to be the true person."},{"punjabi":"ਜਨਮਿ ਮਰੈ ਸੋ ਕਾਚੋ ਕਾਚਾ ॥","lareedar":"ਜਨਮਿਮਰੈਸੋਕਾਚੋਕਾਚਾ ॥","translit":"Janam Marai So Kaacho Kaachaa ||","english":"Birth and death are the lot of the false and the insincere."},{"punjabi":"ਆਵਾ ਗਵਨੁ ਮਿਟੈ ਪ੍ਰਭ ਸੇਵ ॥","lareedar":"ਆਵਾਗਵਨੁਮਿਟੈਪ੍ਰਭਸੇਵ ॥","translit":"Aavaa Gavan Mittai Prabh Saev ||","english":"Coming and going in reincarnation is ended by serving God."},{"punjabi":"ਆਪੁ ਤਿਆਗਿ ਸਰਨਿ ਗੁਰਦੇਵ ॥","lareedar":"ਆਪੁਤਿਆਗਿਸਰਨਿਗੁਰਦੇਵ ॥","translit":"Aap Thiaag Saran Guradhaev ||","english":"Give up your selfishness and conceit, and seek the Sanctuary of the Divine Guru."},{"punjabi":"ਇਉ ਰਤਨ ਜਨਮ ਕਾ ਹੋਇ ਉਧਾਰੁ ॥","lareedar":"ਇਉਰਤਨਜਨਮਕਾਹੋਇਉਧਾਰੁ ॥","translit":"Eio Rathan Janam Kaa Hoe Oudhhaar ||","english":"Thus the jewel of this human life is saved."},{"punjabi":"ਹਰਿ ਹਰਿ ਸਿਮਰਿ ਪ੍ਰਾਨ ਆਧਾਰੁ ॥","lareedar":"ਹਰਿਹਰਿਸਿਮਰਿਪ੍ਰਾਨਆਧਾਰੁ ॥","translit":"Har Har Simar Praan Aadhhaar ||","english":"Remember the Lord, Har, Har, the Support of the breath of life."},{"punjabi":"ਅਨਿਕ ਉਪਾਵ ਨ ਛੂਟਨਹਾਰੇ ॥","lareedar":"ਅਨਿਕਉਪਾਵਨਛੂਟਨਹਾਰੇ ॥","translit":"Anik Oupaav N Shhoottanehaarae ||","english":"By all sorts of efforts, people are not saved"},{"punjabi":"ਸਿੰਮ੍ਰਿਤਿ ਸਾਸਤ ਬੇਦ ਬੀਚਾਰੇ ॥","lareedar":"ਸਿੰਮ੍ਰਿਤਿਸਾਸਤਬੇਦਬੀਚਾਰੇ ॥","translit":"Sinmrith Saasath Baedh Beechaarae ||","english":"Not by studying the Simritees, the Shaastras or the Vedas."},{"punjabi":"ਹਰਿ ਕੀ ਭਗਤਿ ਕਰਹੁ ਮਨੁ ਲਾਇ ॥","lareedar":"ਹਰਿਕੀਭਗਤਿਕਰਹੁਮਨੁਲਾਇ ॥","translit":"Har Kee Bhagath Karahu Man Laae ||","english":"Worship the Lord with whole-hearted devotion."},{"punjabi":"ਮਨਿ ਬੰਛਤ ਨਾਨਕ ਫਲ ਪਾਇ ॥੪॥","lareedar":"ਮਨਿਬੰਛਤਨਾਨਕਫਲਪਾਇ ॥੪ ॥","translit":"Man Banshhath Naanak Fal Paae ||4||","english":"O Nanak, you shall obtain the fruits of your mind's desire. ||4||"},{"punjabi":"ਸੰਗਿ ਨ ਚਾਲਸਿ ਤੇਰੈ ਧਨਾ ॥","lareedar":"ਸੰਗਿਨਚਾਲਸਿਤੇਰੈਧਨਾ ॥","translit":"Sang N Chaalas Thaerai Dhhanaa ||","english":"Your wealth shall not go with you;"},{"punjabi":"ਤੂੰ ਕਿਆ ਲਪਟਾਵਹਿ ਮੂਰਖ ਮਨਾ ॥","lareedar":"ਤੂੰਕਿਆਲਪਟਾਵਹਿਮੂਰਖਮਨਾ ॥","translit":"Thoon Kiaa Lapattaavehi Moorakh Manaa ||","english":"Why do you cling to it, you fool?"},{"punjabi":"ਸੁਤ ਮੀਤ ਕੁਟੰਬ ਅਰੁ ਬਨਿਤਾ ॥","lareedar":"ਸੁਤਮੀਤਕੁਟੰਬਅਰੁਬਨਿਤਾ ॥","translit":"Suth Meeth Kuttanb Ar Banithaa ||","english":"Children, friends, family and spouse"},{"punjabi":"ਇਨ ਤੇ ਕਹਹੁ ਤੁਮ ਕਵਨ ਸਨਾਥਾ ॥","lareedar":"ਇਨਤੇਕਹਹੁਤੁਮਕਵਨਸਨਾਥਾ ॥","translit":"Ein Thae Kehahu Thum Kavan Sanaathhaa ||","english":"Who of these shall accompany you?"},{"punjabi":"ਰਾਜ ਰੰਗ ਮਾਇਆ ਬਿਸਥਾਰ ॥","lareedar":"ਰਾਜਰੰਗਮਾਇਆਬਿਸਥਾਰ ॥","translit":"Raaj Rang Maaeiaa Bisathhaar ||","english":"Power, pleasure, and the vast expanse of Maya"},{"punjabi":"ਇਨ ਤੇ ਕਹਹੁ ਕਵਨ ਛੁਟਕਾਰ ॥","lareedar":"ਇਨਤੇਕਹਹੁਕਵਨਛੁਟਕਾਰ ॥","translit":"Ein Thae Kehahu Kavan Shhuttakaar ||","english":"Who has ever escaped from these?"},{"punjabi":"ਅਸੁ ਹਸਤੀ ਰਥ ਅਸਵਾਰੀ ॥","lareedar":"ਅਸੁਹਸਤੀਰਥਅਸਵਾਰੀ ॥","translit":"As Hasathee Rathh Asavaaree ||","english":"Horses, elephants, chariots and pageantry"},{"punjabi":"ਝੂਠਾ ਡੰਫੁ ਝੂਠੁ ਪਾਸਾਰੀ ॥","lareedar":"ਝੂਠਾਡੰਫੁਝੂਠੁਪਾਸਾਰੀ ॥","translit":"Jhoothaa Ddanf Jhooth Paasaaree ||","english":"- false shows and false displays."}]},{"index":64,"ang":288,"lines":[{"punjabi":"ਜਿਨਿ ਦੀਏ ਤਿਸੁ ਬੁਝੈ ਨ ਬਿਗਾਨਾ ॥","lareedar":"ਜਿਨਿਦੀਏਤਿਸੁਬੁਝੈਨਬਿਗਾਨਾ ॥","translit":"Jin Dheeeae This Bujhai N Bigaanaa ||","english":"The fool does not acknowledge the One who gave this;"},{"punjabi":"ਨਾਮੁ ਬਿਸਾਰਿ ਨਾਨਕ ਪਛੁਤਾਨਾ ॥੫॥","lareedar":"ਨਾਮੁਬਿਸਾਰਿਨਾਨਕਪਛੁਤਾਨਾ ॥੫ ॥","translit":"Naam Bisaar Naanak Pashhuthaanaa ||5||","english":"Forgetting the Naam, O Nanak, he will repent in the end. ||5||"},{"punjabi":"ਗੁਰ ਕੀ ਮਤਿ ਤੂੰ ਲੇਹਿ ਇਆਨੇ ॥","lareedar":"ਗੁਰਕੀਮਤਿਤੂੰਲੇਹਿਇਆਨੇ ॥","translit":"Gur Kee Math Thoon Laehi Eiaanae ||","english":"Take the Guru's advice, you ignorant fool;"},{"punjabi":"ਭਗਤਿ ਬਿਨਾ ਬਹੁ ਡੂਬੇ ਸਿਆਨੇ ॥","lareedar":"ਭਗਤਿਬਿਨਾਬਹੁਡੂਬੇਸਿਆਨੇ ॥","translit":"Bhagath Binaa Bahu Ddoobae Siaanae ||","english":"Without devotion, even the clever have drowned."},{"punjabi":"ਹਰਿ ਕੀ ਭਗਤਿ ਕਰਹੁ ਮਨ ਮੀਤ ॥","lareedar":"ਹਰਿਕੀਭਗਤਿਕਰਹੁਮਨਮੀਤ ॥","translit":"Har Kee Bhagath Karahu Man Meeth ||","english":"Worship the Lord with heart-felt devotion, my friend;"},{"punjabi":"ਨਿਰਮਲ ਹੋਇ ਤੁਮ੍ਹ੍ਹਾਰੋ ਚੀਤ ॥","lareedar":"ਨਿਰਮਲਹੋਇਤੁਮ੍ਹ੍ਹਾਰੋਚੀਤ ॥","translit":"Niramal Hoe Thumhaaro Cheeth ||","english":"Your consciousness shall become pure."},{"punjabi":"ਚਰਨ ਕਮਲ ਰਾਖਹੁ ਮਨ ਮਾਹਿ ॥","lareedar":"ਚਰਨਕਮਲਰਾਖਹੁਮਨਮਾਹਿ ॥","translit":"Charan Kamal Raakhahu Man Maahi ||","english":"Enshrine the Lord's Lotus Feet in your mind;"},{"punjabi":"ਜਨਮ ਜਨਮ ਕੇ ਕਿਲਬਿਖ ਜਾਹਿ ॥","lareedar":"ਜਨਮਜਨਮਕੇਕਿਲਬਿਖਜਾਹਿ ॥","translit":"Janam Janam Kae Kilabikh Jaahi ||","english":"The sins of countless lifetimes shall depart."},{"punjabi":"ਆਪਿ ਜਪਹੁ ਅਵਰਾ ਨਾਮੁ ਜਪਾਵਹੁ ॥","lareedar":"ਆਪਿਜਪਹੁਅਵਰਾਨਾਮੁਜਪਾਵਹੁ ॥","translit":"Aap Japahu Avaraa Naam Japaavahu ||","english":"Chant the Naam yourself, and inspire others to chant it as well."},{"punjabi":"ਸੁਨਤ ਕਹਤ ਰਹਤ ਗਤਿ ਪਾਵਹੁ ॥","lareedar":"ਸੁਨਤਕਹਤਰਹਤਗਤਿਪਾਵਹੁ ॥","translit":"Sunath Kehath Rehath Gath Paavahu ||","english":"Hearing, speaking and living it, emancipation is obtained."},{"punjabi":"ਸਾਰ ਭੂਤ ਸਤਿ ਹਰਿ ਕੋ ਨਾਉ ॥","lareedar":"ਸਾਰਭੂਤਸਤਿਹਰਿਕੋਨਾਉ ॥","translit":"Saar Bhooth Sath Har Ko Naao ||","english":"The essential reality is the True Name of the Lord."},{"punjabi":"ਸਹਜਿ ਸੁਭਾਇ ਨਾਨਕ ਗੁਨ ਗਾਉ ॥੬॥","lareedar":"ਸਹਜਿਸੁਭਾਇਨਾਨਕਗੁਨਗਾਉ ॥੬ ॥","translit":"Sehaj Subhaae Naanak Gun Gaao ||6||","english":"With intuitive ease, O Nanak, sing His Glorious Praises. ||6||"},{"punjabi":"ਗੁਨ ਗਾਵਤ ਤੇਰੀ ਉਤਰਸਿ ਮੈਲੁ ॥","lareedar":"ਗੁਨਗਾਵਤਤੇਰੀਉਤਰਸਿਮੈਲੁ ॥","translit":"Gun Gaavath Thaeree Outharas Mail ||","english":"Chanting His Glories, your filth shall be washed off."},{"punjabi":"ਬਿਨਸਿ ਜਾਇ ਹਉਮੈ ਬਿਖੁ ਫੈਲੁ ॥","lareedar":"ਬਿਨਸਿਜਾਇਹਉਮੈਬਿਖੁਫੈਲੁ ॥","translit":"Binas Jaae Houmai Bikh Fail ||","english":"The all-consuming poison of ego will be gone."},{"punjabi":"ਹੋਹਿ ਅਚਿੰਤੁ ਬਸੈ ਸੁਖ ਨਾਲਿ ॥","lareedar":"ਹੋਹਿਅਚਿੰਤੁਬਸੈਸੁਖਨਾਲਿ ॥","translit":"Hohi Achinth Basai Sukh Naal ||","english":"You shall become carefree, and you shall dwell in peace."},{"punjabi":"ਸਾਸਿ ਗ੍ਰਾਸਿ ਹਰਿ ਨਾਮੁ ਸਮਾਲਿ ॥","lareedar":"ਸਾਸਿਗ੍ਰਾਸਿਹਰਿਨਾਮੁਸਮਾਲਿ ॥","translit":"Saas Graas Har Naam Samaal ||","english":"With every breath and every morsel of food, cherish the Lord's Name."},{"punjabi":"ਛਾਡਿ ਸਿਆਨਪ ਸਗਲੀ ਮਨਾ ॥","lareedar":"ਛਾਡਿਸਿਆਨਪਸਗਲੀਮਨਾ ॥","translit":"Shhaadd Siaanap Sagalee Manaa ||","english":"Renounce all clever tricks, O mind."},{"punjabi":"ਸਾਧਸੰਗਿ ਪਾਵਹਿ ਸਚੁ ਧਨਾ ॥","lareedar":"ਸਾਧਸੰਗਿਪਾਵਹਿਸਚੁਧਨਾ ॥","translit":"Saadhhasang Paavehi Sach Dhhanaa ||","english":"In the Company of the Holy, you shall obtain the true wealth."},{"punjabi":"ਹਰਿ ਪੂੰਜੀ ਸੰਚਿ ਕਰਹੁ ਬਿਉਹਾਰੁ ॥","lareedar":"ਹਰਿਪੂੰਜੀਸੰਚਿਕਰਹੁਬਿਉਹਾਰੁ ॥","translit":"Har Poonjee Sanch Karahu Biouhaar ||","english":"So gather the Lord's Name as your capital, and trade in it."},{"punjabi":"ਈਹਾ ਸੁਖੁ ਦਰਗਹ ਜੈਕਾਰੁ ॥","lareedar":"ਈਹਾਸੁਖੁਦਰਗਹਜੈਕਾਰੁ ॥","translit":"Eehaa Sukh Dharageh Jaikaar ||","english":"In this world you shall be at peace, and in the Court of the Lord, you shall be acclaimed."},{"punjabi":"ਸਰਬ ਨਿਰੰਤਰਿ ਏਕੋ ਦੇਖੁ ॥","lareedar":"ਸਰਬਨਿਰੰਤਰਿਏਕੋਦੇਖੁ ॥","translit":"Sarab Niranthar Eaeko Dhaekh ||","english":"See the One permeating all;"},{"punjabi":"ਕਹੁ ਨਾਨਕ ਜਾ ਕੈ ਮਸਤਕਿ ਲੇਖੁ ॥੭॥","lareedar":"ਕਹੁਨਾਨਕਜਾਕੈਮਸਤਕਿਲੇਖੁ ॥੭ ॥","translit":"Kahu Naanak Jaa Kai Masathak Laekh ||7||","english":"Says Nanak, your destiny is pre-ordained. ||7||"},{"punjabi":"ਏਕੋ ਜਪਿ ਏਕੋ ਸਾਲਾਹਿ ॥","lareedar":"ਏਕੋਜਪਿਏਕੋਸਾਲਾਹਿ ॥","translit":"Eaeko Jap Eaeko Saalaahi ||","english":"Meditate on the One, and worship the One."},{"punjabi":"ਏਕੁ ਸਿਮਰਿ ਏਕੋ ਮਨ ਆਹਿ ॥","lareedar":"ਏਕੁਸਿਮਰਿਏਕੋਮਨਆਹਿ ॥","translit":"Eaek Simar Eaeko Man Aahi ||","english":"Remember the One, and yearn for the One in your mind."},{"punjabi":"ਏਕਸ ਕੇ ਗੁਨ ਗਾਉ ਅਨੰਤ ॥","lareedar":"ਏਕਸਕੇਗੁਨਗਾਉਅਨੰਤ ॥","translit":"Eaekas Kae Gun Gaao Ananth ||","english":"Sing the endless Glorious Praises of the One."}]},{"index":65,"ang":289,"lines":[{"punjabi":"ਮਨਿ ਤਨਿ ਜਾਪਿ ਏਕ ਭਗਵੰਤ ॥","lareedar":"ਮਨਿਤਨਿਜਾਪਿਏਕਭਗਵੰਤ ॥","translit":"Man Than Jaap Eaek Bhagavanth ||","english":"With mind and body, meditate on the One Lord God."},{"punjabi":"ਏਕੋ ਏਕੁ ਏਕੁ ਹਰਿ ਆਪਿ ॥","lareedar":"ਏਕੋਏਕੁਏਕੁਹਰਿਆਪਿ ॥","translit":"Eaeko Eaek Eaek Har Aap ||","english":"The One Lord Himself is the One and Only."},{"punjabi":"ਪੂਰਨ ਪੂਰਿ ਰਹਿਓ ਪ੍ਰਭੁ ਬਿਆਪਿ ॥","lareedar":"ਪੂਰਨਪੂਰਿਰਹਿਓਪ੍ਰਭੁਬਿਆਪਿ ॥","translit":"Pooran Poor Rehiou Prabh Biaap ||","english":"The Pervading Lord God is totally permeating all."},{"punjabi":"ਅਨਿਕ ਬਿਸਥਾਰ ਏਕ ਤੇ ਭਏ ॥","lareedar":"ਅਨਿਕਬਿਸਥਾਰਏਕਤੇਭਏ ॥","translit":"Anik Bisathhaar Eaek Thae Bheae ||","english":"The many expanses of the creation have all come from the One."},{"punjabi":"ਏਕੁ ਅਰਾਧਿ ਪਰਾਛਤ ਗਏ ॥","lareedar":"ਏਕੁਅਰਾਧਿਪਰਾਛਤਗਏ ॥","translit":"Eaek Araadhh Paraashhath Geae ||","english":"Adoring the One, past sins are removed."},{"punjabi":"ਮਨ ਤਨ ਅੰਤਰਿ ਏਕੁ ਪ੍ਰਭੁ ਰਾਤਾ ॥","lareedar":"ਮਨਤਨਅੰਤਰਿਏਕੁਪ੍ਰਭੁਰਾਤਾ ॥","translit":"Man Than Anthar Eaek Prabh Raathaa ||","english":"Mind and body within are imbued with the One God."},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਨਾਨਕ ਇਕੁ ਜਾਤਾ ॥੮॥੧੯॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਨਾਨਕਇਕੁਜਾਤਾ ॥੮ ॥੧੯ ॥","translit":"Gur Prasaadh Naanak Eik Jaathaa ||8||19||","english":"By Guru's Grace, O Nanak, the One is known. ||8||19||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਫਿਰਤ ਫਿਰਤ ਪ੍ਰਭ ਆਇਆ ਪਰਿਆ ਤਉ ਸਰਨਾਇ ॥","lareedar":"ਫਿਰਤਫਿਰਤਪ੍ਰਭਆਇਆਪਰਿਆਤਉਸਰਨਾਇ ॥","translit":"Firath Firath Prabh Aaeiaa Pariaa Tho Saranaae ||","english":"After wandering and wandering, O God, I have come, and entered Your Sanctuary."},{"punjabi":"ਨਾਨਕ ਕੀ ਪ੍ਰਭ ਬੇਨਤੀ ਅਪਨੀ ਭਗਤੀ ਲਾਇ ॥੧॥","lareedar":"ਨਾਨਕਕੀਪ੍ਰਭਬੇਨਤੀਅਪਨੀਭਗਤੀਲਾਇ ॥੧ ॥","translit":"Naanak Kee Prabh Baenathee Apanee Bhagathee Laae ||1||","english":"This is Nanak's prayer, O God: please, attach me to Your devotional service. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਜਾਚਕ ਜਨੁ ਜਾਚੈ ਪ੍ਰਭ ਦਾਨੁ ॥","lareedar":"ਜਾਚਕਜਨੁਜਾਚੈਪ੍ਰਭਦਾਨੁ ॥","translit":"Jaachak Jan Jaachai Prabh Dhaan ||","english":"I am a beggar; I beg for this gift from You:"},{"punjabi":"ਕਰਿ ਕਿਰਪਾ ਦੇਵਹੁ ਹਰਿ ਨਾਮੁ ॥","lareedar":"ਕਰਿਕਿਰਪਾਦੇਵਹੁਹਰਿਨਾਮੁ ॥","translit":"Kar Kirapaa Dhaevahu Har Naam ||","english":"Please, by Your Mercy, Lord, give me Your Name."},{"punjabi":"ਸਾਧ ਜਨਾ ਕੀ ਮਾਗਉ ਧੂਰਿ ॥","lareedar":"ਸਾਧਜਨਾਕੀਮਾਗਉਧੂਰਿ ॥","translit":"Saadhh Janaa Kee Maago Dhhoor ||","english":"I ask for the dust of the feet of the Holy."},{"punjabi":"ਪਾਰਬ੍ਰਹਮ ਮੇਰੀ ਸਰਧਾ ਪੂਰਿ ॥","lareedar":"ਪਾਰਬ੍ਰਹਮਮੇਰੀਸਰਧਾਪੂਰਿ ॥","translit":"Paarabreham Maeree Saradhhaa Poor ||","english":"O Supreme Lord God, please fulfill my yearning;"},{"punjabi":"ਸਦਾ ਸਦਾ ਪ੍ਰਭ ਕੇ ਗੁਨ ਗਾਵਉ ॥","lareedar":"ਸਦਾਸਦਾਪ੍ਰਭਕੇਗੁਨਗਾਵਉ ॥","translit":"Sadhaa Sadhaa Prabh Kae Gun Gaavo ||","english":"May I sing the Glorious Praises of God forever and ever."},{"punjabi":"ਸਾਸਿ ਸਾਸਿ ਪ੍ਰਭ ਤੁਮਹਿ ਧਿਆਵਉ ॥","lareedar":"ਸਾਸਿਸਾਸਿਪ੍ਰਭਤੁਮਹਿਧਿਆਵਉ ॥","translit":"Saas Saas Prabh Thumehi Dhhiaavo ||","english":"With each and every breath, may I meditate on You, O God."},{"punjabi":"ਚਰਨ ਕਮਲ ਸਿਉ ਲਾਗੈ ਪ੍ਰੀਤਿ ॥","lareedar":"ਚਰਨਕਮਲਸਿਉਲਾਗੈਪ੍ਰੀਤਿ ॥","translit":"Charan Kamal Sio Laagai Preeth ||","english":"May I enshrine affection for Your Lotus Feet."},{"punjabi":"ਭਗਤਿ ਕਰਉ ਪ੍ਰਭ ਕੀ ਨਿਤ ਨੀਤਿ ॥","lareedar":"ਭਗਤਿਕਰਉਪ੍ਰਭਕੀਨਿਤਨੀਤਿ ॥","translit":"Bhagath Karo Prabh Kee Nith Neeth ||","english":"May I perform devotional worship to God each and every day."},{"punjabi":"ਏਕ ਓਟ ਏਕੋ ਆਧਾਰੁ ॥","lareedar":"ਏਕਓਟਏਕੋਆਧਾਰੁ ॥","translit":"Eaek Outt Eaeko Aadhhaar ||","english":"You are my only Shelter, my only Support."},{"punjabi":"ਨਾਨਕੁ ਮਾਗੈ ਨਾਮੁ ਪ੍ਰਭ ਸਾਰੁ ॥੧॥","lareedar":"ਨਾਨਕੁਮਾਗੈਨਾਮੁਪ੍ਰਭਸਾਰੁ ॥੧ ॥","translit":"Naanak Maagai Naam Prabh Saar ||1||","english":"Nanak asks for the most sublime, the Naam, the Name of God. ||1||"},{"punjabi":"ਪ੍ਰਭ ਕੀ ਦ੍ਰਿਸਟਿ ਮਹਾ ਸੁਖੁ ਹੋਇ ॥","lareedar":"ਪ੍ਰਭਕੀਦ੍ਰਿਸਟਿਮਹਾਸੁਖੁਹੋਇ ॥","translit":"Prabh Kee Dhrisatt Mehaa Sukh Hoe ||","english":"By God's Gracious Glance, there is great peace."},{"punjabi":"ਹਰਿ ਰਸੁ ਪਾਵੈ ਬਿਰਲਾ ਕੋਇ ॥","lareedar":"ਹਰਿਰਸੁਪਾਵੈਬਿਰਲਾਕੋਇ ॥","translit":"Har Ras Paavai Biralaa Koe ||","english":"Rare are those who obtain the juice of the Lord's essence."},{"punjabi":"ਜਿਨ ਚਾਖਿਆ ਸੇ ਜਨ ਤ੍ਰਿਪਤਾਨੇ ॥","lareedar":"ਜਿਨਚਾਖਿਆਸੇਜਨਤ੍ਰਿਪਤਾਨੇ ॥","translit":"Jin Chaakhiaa Sae Jan Thripathaanae ||","english":"Those who taste it are satisfied."},{"punjabi":"ਪੂਰਨ ਪੁਰਖ ਨਹੀ ਡੋਲਾਨੇ ॥","lareedar":"ਪੂਰਨਪੁਰਖਨਹੀਡੋਲਾਨੇ ॥","translit":"Pooran Purakh Nehee Ddolaanae ||","english":"They are fulfilled and realized beings - they do not waver."}]},{"index":66,"ang":289,"lines":[{"punjabi":"ਸੁਭਰ ਭਰੇ ਪ੍ਰੇਮ ਰਸ ਰੰਗਿ ॥","lareedar":"ਸੁਭਰਭਰੇਪ੍ਰੇਮਰਸਰੰਗਿ ॥","translit":"Subhar Bharae Praem Ras Rang ||","english":"They are totally filled to over-flowing with the sweet delight of His Love."},{"punjabi":"ਉਪਜੈ ਚਾਉ ਸਾਧ ਕੈ ਸੰਗਿ ॥","lareedar":"ਉਪਜੈਚਾਉਸਾਧਕੈਸੰਗਿ ॥","translit":"Oupajai Chaao Saadhh Kai Sang ||","english":"Spiritual delight wells up within, in the Saadh Sangat, the Company of the Holy."},{"punjabi":"ਪਰੇ ਸਰਨਿ ਆਨ ਸਭ ਤਿਆਗਿ ॥","lareedar":"ਪਰੇਸਰਨਿਆਨਸਭਤਿਆਗਿ ॥","translit":"Parae Saran Aan Sabh Thiaag ||","english":"Taking to His Sanctuary, they forsake all others."},{"punjabi":"ਅੰਤਰਿ ਪ੍ਰਗਾਸ ਅਨਦਿਨੁ ਲਿਵ ਲਾਗਿ ॥","lareedar":"ਅੰਤਰਿਪ੍ਰਗਾਸਅਨਦਿਨੁਲਿਵਲਾਗਿ ॥","translit":"Anthar Pragaas Anadhin Liv Laag ||","english":"Deep within, they are enlightened, and they center themselves on Him, day and night."},{"punjabi":"ਬਡਭਾਗੀ ਜਪਿਆ ਪ੍ਰਭੁ ਸੋਇ ॥","lareedar":"ਬਡਭਾਗੀਜਪਿਆਪ੍ਰਭੁਸੋਇ ॥","translit":"Baddabhaagee Japiaa Prabh Soe ||","english":"Most fortunate are those who meditate on God."},{"punjabi":"ਨਾਨਕ ਨਾਮਿ ਰਤੇ ਸੁਖੁ ਹੋਇ ॥੨॥","lareedar":"ਨਾਨਕਨਾਮਿਰਤੇਸੁਖੁਹੋਇ ॥੨ ॥","translit":"Naanak Naam Rathae Sukh Hoe ||2||","english":"O Nanak, attuned to the Naam, they are at peace. ||2||"},{"punjabi":"ਸੇਵਕ ਕੀ ਮਨਸਾ ਪੂਰੀ ਭਈ ॥","lareedar":"ਸੇਵਕਕੀਮਨਸਾਪੂਰੀਭਈ ॥","translit":"Saevak Kee Manasaa Pooree Bhee ||","english":"The wishes of the Lord's servant are fulfilled."},{"punjabi":"ਸਤਿਗੁਰ ਤੇ ਨਿਰਮਲ ਮਤਿ ਲਈ ॥","lareedar":"ਸਤਿਗੁਰਤੇਨਿਰਮਲਮਤਿਲਈ ॥","translit":"Sathigur Thae Niramal Math Lee ||","english":"From the True Guru, the pure teachings are obtained."},{"punjabi":"ਜਨ ਕਉ ਪ੍ਰਭੁ ਹੋਇਓ ਦਇਆਲੁ ॥","lareedar":"ਜਨਕਉਪ੍ਰਭੁਹੋਇਓਦਇਆਲੁ ॥","translit":"Jan Ko Prabh Hoeiou Dhaeiaal ||","english":"Unto His humble servant, God has shown His kindness."},{"punjabi":"ਸੇਵਕੁ ਕੀਨੋ ਸਦਾ ਨਿਹਾਲੁ ॥","lareedar":"ਸੇਵਕੁਕੀਨੋਸਦਾਨਿਹਾਲੁ ॥","translit":"Saevak Keeno Sadhaa Nihaal ||","english":"He has made His servant eternally happy."},{"punjabi":"ਬੰਧਨ ਕਾਟਿ ਮੁਕਤਿ ਜਨੁ ਭਇਆ ॥","lareedar":"ਬੰਧਨਕਾਟਿਮੁਕਤਿਜਨੁਭਇਆ ॥","translit":"Bandhhan Kaatt Mukath Jan Bhaeiaa ||","english":"The bonds of His humble servant are cut away, and he is liberated."},{"punjabi":"ਜਨਮ ਮਰਨ ਦੂਖੁ ਭ੍ਰਮੁ ਗਇਆ ॥","lareedar":"ਜਨਮਮਰਨਦੂਖੁਭ੍ਰਮੁਗਇਆ ॥","translit":"Janam Maran Dhookh Bhram Gaeiaa ||","english":"The pains of birth and death, and doubt are gone."},{"punjabi":"ਇਛ ਪੁਨੀ ਸਰਧਾ ਸਭ ਪੂਰੀ ॥","lareedar":"ਇਛਪੁਨੀਸਰਧਾਸਭਪੂਰੀ ॥","translit":"Eishh Punee Saradhhaa Sabh Pooree ||","english":"Desires are satisfied, and faith is fully rewarded,"},{"punjabi":"ਰਵਿ ਰਹਿਆ ਸਦ ਸੰਗਿ ਹਜੂਰੀ ॥","lareedar":"ਰਵਿਰਹਿਆਸਦਸੰਗਿਹਜੂਰੀ ॥","translit":"Rav Rehiaa Sadh Sang Hajooree ||","english":"Imbued forever with His all-pervading peace."},{"punjabi":"ਜਿਸ ਕਾ ਸਾ ਤਿਨਿ ਲੀਆ ਮਿਲਾਇ ॥","lareedar":"ਜਿਸਕਾਸਾਤਿਨਿਲੀਆਮਿਲਾਇ ॥","translit":"Jis Kaa Saa Thin Leeaa Milaae ||","english":"He is His - he merges in Union with Him."},{"punjabi":"ਨਾਨਕ ਭਗਤੀ ਨਾਮਿ ਸਮਾਇ ॥੩॥","lareedar":"ਨਾਨਕਭਗਤੀਨਾਮਿਸਮਾਇ ॥੩ ॥","translit":"Naanak Bhagathee Naam Samaae ||3||","english":"Nanak is absorbed in devotional worship of the Naam. ||3||"},{"punjabi":"ਸੋ ਕਿਉ ਬਿਸਰੈ ਜਿ ਘਾਲ ਨ ਭਾਨੈ ॥","lareedar":"ਸੋਕਿਉਬਿਸਰੈਜਿਘਾਲਨਭਾਨੈ ॥","translit":"So Kio Bisarai J Ghaal N Bhaanai ||","english":"Why forget Him, who does not overlook our efforts?"},{"punjabi":"ਸੋ ਕਿਉ ਬਿਸਰੈ ਜਿ ਕੀਆ ਜਾਨੈ ॥","lareedar":"ਸੋਕਿਉਬਿਸਰੈਜਿਕੀਆਜਾਨੈ ॥","translit":"So Kio Bisarai J Keeaa Jaanai ||","english":"Why forget Him, who acknowledges what we do?"},{"punjabi":"ਸੋ ਕਿਉ ਬਿਸਰੈ ਜਿਨਿ ਸਭੁ ਕਿਛੁ ਦੀਆ ॥","lareedar":"ਸੋਕਿਉਬਿਸਰੈਜਿਨਿਸਭੁਕਿਛੁਦੀਆ ॥","translit":"So Kio Bisarai Jin Sabh Kishh Dheeaa ||","english":"Why forget Him, who has given us everything?"},{"punjabi":"ਸੋ ਕਿਉ ਬਿਸਰੈ ਜਿ ਜੀਵਨ ਜੀਆ ॥","lareedar":"ਸੋਕਿਉਬਿਸਰੈਜਿਜੀਵਨਜੀਆ ॥","translit":"So Kio Bisarai J Jeevan Jeeaa ||","english":"Why forget Him, who is the Life of the living beings?"},{"punjabi":"ਸੋ ਕਿਉ ਬਿਸਰੈ ਜਿ ਅਗਨਿ ਮਹਿ ਰਾਖੈ ॥","lareedar":"ਸੋਕਿਉਬਿਸਰੈਜਿਅਗਨਿਮਹਿਰਾਖੈ ॥","translit":"So Kio Bisarai J Agan Mehi Raakhai ||","english":"Why forget Him, who preserves us in the fire of the womb?"},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਕੋ ਬਿਰਲਾ ਲਾਖੈ ॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਕੋਬਿਰਲਾਲਾਖੈ ॥","translit":"Gur Prasaadh Ko Biralaa Laakhai ||","english":"By Guru's Grace, rare is the one who realizes this."},{"punjabi":"ਸੋ ਕਿਉ ਬਿਸਰੈ ਜਿ ਬਿਖੁ ਤੇ ਕਾਢੈ ॥","lareedar":"ਸੋਕਿਉਬਿਸਰੈਜਿਬਿਖੁਤੇਕਾਢੈ ॥","translit":"So Kio Bisarai J Bikh Thae Kaadtai ||","english":"Why forget Him, who lifts us up out of corruption?"},{"punjabi":"ਜਨਮ ਜਨਮ ਕਾ ਟੂਟਾ ਗਾਢੈ ॥","lareedar":"ਜਨਮਜਨਮਕਾਟੂਟਾਗਾਢੈ ॥","translit":"Janam Janam Kaa Ttoottaa Gaadtai ||","english":"Those separated from Him for countless lifetimes, are re-united with Him once again."},{"punjabi":"ਗੁਰਿ ਪੂਰੈ ਤਤੁ ਇਹੈ ਬੁਝਾਇਆ ॥","lareedar":"ਗੁਰਿਪੂਰੈਤਤੁਇਹੈਬੁਝਾਇਆ ॥","translit":"Gur Poorai Thath Eihai Bujhaaeiaa ||","english":"Through the Perfect Guru, this essential reality is understood."}]},{"index":67,"ang":290,"lines":[{"punjabi":"ਪ੍ਰਭੁ ਅਪਨਾ ਨਾਨਕ ਜਨ ਧਿਆਇਆ ॥੪॥","lareedar":"ਪ੍ਰਭੁਅਪਨਾਨਾਨਕਜਨਧਿਆਇਆ ॥੪ ॥","translit":"Prabh Apanaa Naanak Jan Dhhiaaeiaa ||4||","english":"O Nanak, God's humble servants meditate on Him. ||4||"},{"punjabi":"ਸਾਜਨ ਸੰਤ ਕਰਹੁ ਇਹੁ ਕਾਮੁ ॥","lareedar":"ਸਾਜਨਸੰਤਕਰਹੁਇਹੁਕਾਮੁ ॥","translit":"Saajan Santh Karahu Eihu Kaam ||","english":"O friends, O Saints, make this your work."},{"punjabi":"ਆਨ ਤਿਆਗਿ ਜਪਹੁ ਹਰਿ ਨਾਮੁ ॥","lareedar":"ਆਨਤਿਆਗਿਜਪਹੁਹਰਿਨਾਮੁ ॥","translit":"Aan Thiaag Japahu Har Naam ||","english":"Renounce everything else, and chant the Name of the Lord."},{"punjabi":"ਸਿਮਰਿ ਸਿਮਰਿ ਸਿਮਰਿ ਸੁਖ ਪਾਵਹੁ ॥","lareedar":"ਸਿਮਰਿਸਿਮਰਿਸਿਮਰਿਸੁਖਪਾਵਹੁ ॥","translit":"Simar Simar Simar Sukh Paavahu ||","english":"Meditate, meditate, meditate in remembrance of Him, and find peace."},{"punjabi":"ਆਪਿ ਜਪਹੁ ਅਵਰਹ ਨਾਮੁ ਜਪਾਵਹੁ ॥","lareedar":"ਆਪਿਜਪਹੁਅਵਰਹਨਾਮੁਜਪਾਵਹੁ ॥","translit":"Aap Japahu Avareh Naam Japaavahu ||","english":"Chant the Naam yourself, and inspire others to chant it."},{"punjabi":"ਭਗਤਿ ਭਾਇ ਤਰੀਐ ਸੰਸਾਰੁ ॥","lareedar":"ਭਗਤਿਭਾਇਤਰੀਐਸੰਸਾਰੁ ॥","translit":"Bhagath Bhaae Thareeai Sansaar ||","english":"By loving devotional worship, you shall cross over the world-ocean."},{"punjabi":"ਬਿਨੁ ਭਗਤੀ ਤਨੁ ਹੋਸੀ ਛਾਰੁ ॥","lareedar":"ਬਿਨੁਭਗਤੀਤਨੁਹੋਸੀਛਾਰੁ ॥","translit":"Bin Bhagathee Than Hosee Shhaar ||","english":"Without devotional meditation, the body will be just ashes."},{"punjabi":"ਸਰਬ ਕਲਿਆਣ ਸੂਖ ਨਿਧਿ ਨਾਮੁ ॥","lareedar":"ਸਰਬਕਲਿਆਣਸੂਖਨਿਧਿਨਾਮੁ ॥","translit":"Sarab Kaliaan Sookh Nidhh Naam ||","english":"All joys and comforts are in the treasure of the Naam."},{"punjabi":"ਬੂਡਤ ਜਾਤ ਪਾਏ ਬਿਸ੍ਰਾਮੁ ॥","lareedar":"ਬੂਡਤਜਾਤਪਾਏਬਿਸ੍ਰਾਮੁ ॥","translit":"Booddath Jaath Paaeae Bisraam ||","english":"Even the drowning can reach the place of rest and safety."},{"punjabi":"ਸਗਲ ਦੂਖ ਕਾ ਹੋਵਤ ਨਾਸੁ ॥","lareedar":"ਸਗਲਦੂਖਕਾਹੋਵਤਨਾਸੁ ॥","translit":"Sagal Dhookh Kaa Hovath Naas ||","english":"All sorrows shall vanish."},{"punjabi":"ਨਾਨਕ ਨਾਮੁ ਜਪਹੁ ਗੁਨਤਾਸੁ ॥੫॥","lareedar":"ਨਾਨਕਨਾਮੁਜਪਹੁਗੁਨਤਾਸੁ ॥੫ ॥","translit":"Naanak Naam Japahu Gunathaas ||5||","english":"O Nanak, chant the Naam, the treasure of excellence. ||5||"},{"punjabi":"ਉਪਜੀ ਪ੍ਰੀਤਿ ਪ੍ਰੇਮ ਰਸੁ ਚਾਉ ॥","lareedar":"ਉਪਜੀਪ੍ਰੀਤਿਪ੍ਰੇਮਰਸੁਚਾਉ ॥","translit":"Oupajee Preeth Praem Ras Chaao ||","english":"Love and affection, and the taste of yearning, have welled up within;"},{"punjabi":"ਮਨ ਤਨ ਅੰਤਰਿ ਇਹੀ ਸੁਆਉ ॥","lareedar":"ਮਨਤਨਅੰਤਰਿਇਹੀਸੁਆਉ ॥","translit":"Man Than Anthar Eihee Suaao ||","english":"Within my mind and body, this is my purpose:"},{"punjabi":"ਨੇਤ੍ਰਹੁ ਪੇਖਿ ਦਰਸੁ ਸੁਖੁ ਹੋਇ ॥","lareedar":"ਨੇਤ੍ਰਹੁਪੇਖਿਦਰਸੁਸੁਖੁਹੋਇ ॥","translit":"Naethrahu Paekh Dharas Sukh Hoe ||","english":"Beholding with my eyes His Blessed Vision, I am at peace."},{"punjabi":"ਮਨੁ ਬਿਗਸੈ ਸਾਧ ਚਰਨ ਧੋਇ ॥","lareedar":"ਮਨੁਬਿਗਸੈਸਾਧਚਰਨਧੋਇ ॥","translit":"Man Bigasai Saadhh Charan Dhhoe ||","english":"My mind blossoms forth in ecstasy, washing the feet of the Holy."},{"punjabi":"ਭਗਤ ਜਨਾ ਕੈ ਮਨਿ ਤਨਿ ਰੰਗੁ ॥","lareedar":"ਭਗਤਜਨਾਕੈਮਨਿਤਨਿਰੰਗੁ ॥","translit":"Bhagath Janaa Kai Man Than Rang ||","english":"The minds and bodies of His devotees are infused with His Love."},{"punjabi":"ਬਿਰਲਾ ਕੋਊ ਪਾਵੈ ਸੰਗੁ ॥","lareedar":"ਬਿਰਲਾਕੋਊਪਾਵੈਸੰਗੁ ॥","translit":"Biralaa Kooo Paavai Sang ||","english":"Rare is the one who obtains their company."},{"punjabi":"ਏਕ ਬਸਤੁ ਦੀਜੈ ਕਰਿ ਮਇਆ ॥","lareedar":"ਏਕਬਸਤੁਦੀਜੈਕਰਿਮਇਆ ॥","translit":"Eaek Basath Dheejai Kar Maeiaa ||","english":"Show Your mercy - please, grant me this one request:"},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਨਾਮੁ ਜਪਿ ਲਇਆ ॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਨਾਮੁਜਪਿਲਇਆ ॥","translit":"Gur Prasaadh Naam Jap Laeiaa ||","english":"By Guru's Grace, may I chant the Naam."},{"punjabi":"ਤਾ ਕੀ ਉਪਮਾ ਕਹੀ ਨ ਜਾਇ ॥","lareedar":"ਤਾਕੀਉਪਮਾਕਹੀਨਜਾਇ ॥","translit":"Thaa Kee Oupamaa Kehee N Jaae ||","english":"His Praises cannot be spoken;"},{"punjabi":"ਨਾਨਕ ਰਹਿਆ ਸਰਬ ਸਮਾਇ ॥੬॥","lareedar":"ਨਾਨਕਰਹਿਆਸਰਬਸਮਾਇ ॥੬ ॥","translit":"Naanak Rehiaa Sarab Samaae ||6||","english":"O Nanak, He is contained among all. ||6||"},{"punjabi":"ਪ੍ਰਭ ਬਖਸੰਦ ਦੀਨ ਦਇਆਲ ॥","lareedar":"ਪ੍ਰਭਬਖਸੰਦਦੀਨਦਇਆਲ ॥","translit":"Prabh Bakhasandh Dheen Dhaeiaal ||","english":"God, the Forgiving Lord, is kind to the poor."},{"punjabi":"ਭਗਤਿ ਵਛਲ ਸਦਾ ਕਿਰਪਾਲ ॥","lareedar":"ਭਗਤਿਵਛਲਸਦਾਕਿਰਪਾਲ ॥","translit":"Bhagath Vashhal Sadhaa Kirapaal ||","english":"He loves His devotees, and He is always merciful to them."},{"punjabi":"ਅਨਾਥ ਨਾਥ ਗੋਬਿੰਦ ਗੁਪਾਲ ॥","lareedar":"ਅਨਾਥਨਾਥਗੋਬਿੰਦਗੁਪਾਲ ॥","translit":"Anaathh Naathh Gobindh Gupaal ||","english":"The Patron of the patronless, the Lord of the Universe, the Sustainer of the world,"},{"punjabi":"ਸਰਬ ਘਟਾ ਕਰਤ ਪ੍ਰਤਿਪਾਲ ॥","lareedar":"ਸਰਬਘਟਾਕਰਤਪ੍ਰਤਿਪਾਲ ॥","translit":"Sarab Ghattaa Karath Prathipaal ||","english":"The Nourisher of all beings."}]},{"index":68,"ang":290,"lines":[{"punjabi":"ਆਦਿ ਪੁਰਖ ਕਾਰਣ ਕਰਤਾਰ ॥","lareedar":"ਆਦਿਪੁਰਖਕਾਰਣਕਰਤਾਰ ॥","translit":"Aadh Purakh Kaaran Karathaar ||","english":"The Primal Being, the Creator of the Creation."},{"punjabi":"ਭਗਤ ਜਨਾ ਕੇ ਪ੍ਰਾਨ ਅਧਾਰ ॥","lareedar":"ਭਗਤਜਨਾਕੇਪ੍ਰਾਨਅਧਾਰ ॥","translit":"Bhagath Janaa Kae Praan Adhhaar ||","english":"The Support of the breath of life of His devotees."},{"punjabi":"ਜੋ ਜੋ ਜਪੈ ਸੁ ਹੋਇ ਪੁਨੀਤ ॥","lareedar":"ਜੋਜੋਜਪੈਸੁਹੋਇਪੁਨੀਤ ॥","translit":"Jo Jo Japai S Hoe Puneeth ||","english":"Whoever meditates on Him is sanctified,"},{"punjabi":"ਭਗਤਿ ਭਾਇ ਲਾਵੈ ਮਨ ਹੀਤ ॥","lareedar":"ਭਗਤਿਭਾਇਲਾਵੈਮਨਹੀਤ ॥","translit":"Bhagath Bhaae Laavai Man Heeth ||","english":"Focusing the mind in loving devotional worship."},{"punjabi":"ਹਮ ਨਿਰਗੁਨੀਆਰ ਨੀਚ ਅਜਾਨ ॥","lareedar":"ਹਮਨਿਰਗੁਨੀਆਰਨੀਚਅਜਾਨ ॥","translit":"Ham Niraguneeaar Neech Ajaan ||","english":"I am unworthy, lowly and ignorant."},{"punjabi":"ਨਾਨਕ ਤੁਮਰੀ ਸਰਨਿ ਪੁਰਖ ਭਗਵਾਨ ॥੭॥","lareedar":"ਨਾਨਕਤੁਮਰੀਸਰਨਿਪੁਰਖਭਗਵਾਨ ॥੭ ॥","translit":"Naanak Thumaree Saran Purakh Bhagavaan ||7||","english":"Nanak has entered Your Sanctuary, O Supreme Lord God. ||7||"},{"punjabi":"ਸਰਬ ਬੈਕੁੰਠ ਮੁਕਤਿ ਮੋਖ ਪਾਏ ॥","lareedar":"ਸਰਬਬੈਕੁੰਠਮੁਕਤਿਮੋਖਪਾਏ ॥","translit":"Sarab Baikunth Mukath Mokh Paaeae ||","english":"Everything is obtained: the heavens, liberation and deliverance,"},{"punjabi":"ਏਕ ਨਿਮਖ ਹਰਿ ਕੇ ਗੁਨ ਗਾਏ ॥","lareedar":"ਏਕਨਿਮਖਹਰਿਕੇਗੁਨਗਾਏ ॥","translit":"Eaek Nimakh Har Kae Gun Gaaeae ||","english":"If one sings the Lord's Glories, even for an instant."},{"punjabi":"ਅਨਿਕ ਰਾਜ ਭੋਗ ਬਡਿਆਈ ॥","lareedar":"ਅਨਿਕਰਾਜਭੋਗਬਡਿਆਈ ॥","translit":"Anik Raaj Bhog Baddiaaee ||","english":"So many realms of power, pleasures and great glories,"},{"punjabi":"ਹਰਿ ਕੇ ਨਾਮ ਕੀ ਕਥਾ ਮਨਿ ਭਾਈ ॥","lareedar":"ਹਰਿਕੇਨਾਮਕੀਕਥਾਮਨਿਭਾਈ ॥","translit":"Har Kae Naam Kee Kathhaa Man Bhaaee ||","english":"Come to one whose mind is pleased with the Sermon of the Lord's Name."},{"punjabi":"ਬਹੁ ਭੋਜਨ ਕਾਪਰ ਸੰਗੀਤ ॥","lareedar":"ਬਹੁਭੋਜਨਕਾਪਰਸੰਗੀਤ ॥","translit":"Bahu Bhojan Kaapar Sangeeth ||","english":"Abundant foods, clothes and music"},{"punjabi":"ਰਸਨਾ ਜਪਤੀ ਹਰਿ ਹਰਿ ਨੀਤ ॥","lareedar":"ਰਸਨਾਜਪਤੀਹਰਿਹਰਿਨੀਤ ॥","translit":"Rasanaa Japathee Har Har Neeth ||","english":"Come to one whose tongue continually chants the Lord's Name, Har, Har."},{"punjabi":"ਭਲੀ ਸੁ ਕਰਨੀ ਸੋਭਾ ਧਨਵੰਤ ॥","lareedar":"ਭਲੀਸੁਕਰਨੀਸੋਭਾਧਨਵੰਤ ॥","translit":"Bhalee S Karanee Sobhaa Dhhanavanth ||","english":"His actions are good, he is glorious and wealthy;"},{"punjabi":"ਹਿਰਦੈ ਬਸੇ ਪੂਰਨ ਗੁਰ ਮੰਤ ॥","lareedar":"ਹਿਰਦੈਬਸੇਪੂਰਨਗੁਰਮੰਤ ॥","translit":"Hiradhai Basae Pooran Gur Manth ||","english":"The Mantra of the Perfect Guru dwells within his heart."},{"punjabi":"ਸਾਧਸੰਗਿ ਪ੍ਰਭ ਦੇਹੁ ਨਿਵਾਸ ॥","lareedar":"ਸਾਧਸੰਗਿਪ੍ਰਭਦੇਹੁਨਿਵਾਸ ॥","translit":"Saadhhasang Prabh Dhaehu Nivaas ||","english":"O God, grant me a home in the Company of the Holy."},{"punjabi":"ਸਰਬ ਸੂਖ ਨਾਨਕ ਪਰਗਾਸ ॥੮॥੨੦॥","lareedar":"ਸਰਬਸੂਖਨਾਨਕਪਰਗਾਸ ॥੮ ॥੨੦ ॥","translit":"Sarab Sookh Naanak Paragaas ||8||20||","english":"All pleasures, O Nanak, are so revealed. ||8||20||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਸਰਗੁਨ ਨਿਰਗੁਨ ਨਿਰੰਕਾਰ ਸੁੰਨ ਸਮਾਧੀ ਆਪਿ ॥","lareedar":"ਸਰਗੁਨਨਿਰਗੁਨਨਿਰੰਕਾਰਸੁੰਨਸਮਾਧੀਆਪਿ ॥","translit":"Saragun Niragun Nirankaar Sunn Samaadhhee Aap ||","english":"He possesses all qualities; He transcends all qualities; He is the Formless Lord. He Himself is in Primal Samaadhi."},{"punjabi":"ਆਪਨ ਕੀਆ ਨਾਨਕਾ ਆਪੇ ਹੀ ਫਿਰਿ ਜਾਪਿ ॥੧॥","lareedar":"ਆਪਨਕੀਆਨਾਨਕਾਆਪੇਹੀਫਿਰਿਜਾਪਿ ॥੧ ॥","translit":"Aapan Keeaa Naanakaa Aapae Hee Fir Jaap ||1||","english":"Through His Creation, O Nanak, He meditates on Himself. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਜਬ ਅਕਾਰੁ ਇਹੁ ਕਛੁ ਨ ਦ੍ਰਿਸਟੇਤਾ ॥","lareedar":"ਜਬਅਕਾਰੁਇਹੁਕਛੁਨਦ੍ਰਿਸਟੇਤਾ ॥","translit":"Jab Akaar Eihu Kashh N Dhrisattaethaa ||","english":"When this world had not yet appeared in any form,"},{"punjabi":"ਪਾਪ ਪੁੰਨ ਤਬ ਕਹ ਤੇ ਹੋਤਾ ॥","lareedar":"ਪਾਪਪੁੰਨਤਬਕਹਤੇਹੋਤਾ ॥","translit":"Paap Punn Thab Keh Thae Hothaa ||","english":"Who then committed sins and performed good deeds?"},{"punjabi":"ਜਬ ਧਾਰੀ ਆਪਨ ਸੁੰਨ ਸਮਾਧਿ ॥","lareedar":"ਜਬਧਾਰੀਆਪਨਸੁੰਨਸਮਾਧਿ ॥","translit":"Jab Dhhaaree Aapan Sunn Samaadhh ||","english":"When the Lord Himself was in Profound Samaadhi,"},{"punjabi":"ਤਬ ਬੈਰ ਬਿਰੋਧ ਕਿਸੁ ਸੰਗਿ ਕਮਾਤਿ ॥","lareedar":"ਤਬਬੈਰਬਿਰੋਧਕਿਸੁਸੰਗਿਕਮਾਤਿ ॥","translit":"Thab Bair Birodhh Kis Sang Kamaath ||","english":"Then against whom were hate and jealousy directed?"},{"punjabi":"ਜਬ ਇਸ ਕਾ ਬਰਨੁ ਚਿਹਨੁ ਨ ਜਾਪਤ ॥","lareedar":"ਜਬਇਸਕਾਬਰਨੁਚਿਹਨੁਨਜਾਪਤ ॥","translit":"Jab Eis Kaa Baran Chihan N Jaapath ||","english":"When there was no color or shape to be seen,"}]},{"index":69,"ang":290,"lines":[{"punjabi":"ਤਬ ਹਰਖ ਸੋਗ ਕਹੁ ਕਿਸਹਿ ਬਿਆਪਤ ॥","lareedar":"ਤਬਹਰਖਸੋਗਕਹੁਕਿਸਹਿਬਿਆਪਤ ॥","translit":"Thab Harakh Sog Kahu Kisehi Biaapath ||","english":"Then who experienced joy and sorrow?"},{"punjabi":"ਜਬ ਆਪਨ ਆਪ ਆਪਿ ਪਾਰਬ੍ਰਹਮ ॥","lareedar":"ਜਬਆਪਨਆਪਆਪਿਪਾਰਬ੍ਰਹਮ ॥","translit":"Jab Aapan Aap Aap Paarabreham ||","english":"When the Supreme Lord Himself was Himself All-in-all,"},{"punjabi":"ਤਬ ਮੋਹ ਕਹਾ ਕਿਸੁ ਹੋਵਤ ਭਰਮ ॥","lareedar":"ਤਬਮੋਹਕਹਾਕਿਸੁਹੋਵਤਭਰਮ ॥","translit":"Thab Moh Kehaa Kis Hovath Bharam ||","english":"Then where was emotional attachment, and who had doubts?"},{"punjabi":"ਆਪਨ ਖੇਲੁ ਆਪਿ ਵਰਤੀਜਾ ॥","lareedar":"ਆਪਨਖੇਲੁਆਪਿਵਰਤੀਜਾ ॥","translit":"Aapan Khael Aap Varatheejaa ||","english":"He Himself has staged His own drama;"},{"punjabi":"ਨਾਨਕ ਕਰਨੈਹਾਰੁ ਨ ਦੂਜਾ ॥੧॥","lareedar":"ਨਾਨਕਕਰਨੈਹਾਰੁਨਦੂਜਾ ॥੧ ॥","translit":"Naanak Karanaihaar N Dhoojaa ||1||","english":"O Nanak, there is no other Creator. ||1||"},{"punjabi":"ਜਬ ਹੋਵਤ ਪ੍ਰਭ ਕੇਵਲ ਧਨੀ ॥","lareedar":"ਜਬਹੋਵਤਪ੍ਰਭਕੇਵਲਧਨੀ ॥","translit":"Jab Hovath Prabh Kaeval Dhhanee ||","english":"When there was only God the Master,"},{"punjabi":"ਤਬ ਬੰਧ ਮੁਕਤਿ ਕਹੁ ਕਿਸ ਕਉ ਗਨੀ ॥","lareedar":"ਤਬਬੰਧਮੁਕਤਿਕਹੁਕਿਸਕਉਗਨੀ ॥","translit":"Thab Bandhh Mukath Kahu Kis Ko Ganee ||","english":"Then who was called bound or liberated?"},{"punjabi":"ਜਬ ਏਕਹਿ ਹਰਿ ਅਗਮ ਅਪਾਰ ॥","lareedar":"ਜਬਏਕਹਿਹਰਿਅਗਮਅਪਾਰ ॥","translit":"Jab Eaekehi Har Agam Apaar ||","english":"When there was only the Lord, Unfathomable and Infinite,"},{"punjabi":"ਤਬ ਨਰਕ ਸੁਰਗ ਕਹੁ ਕਉਨ ਅਉਤਾਰ ॥","lareedar":"ਤਬਨਰਕਸੁਰਗਕਹੁਕਉਨਅਉਤਾਰ ॥","translit":"Thab Narak Surag Kahu Koun Aouthaar ||","english":"Then who entered hell, and who entered heaven?"},{"punjabi":"ਜਬ ਨਿਰਗੁਨ ਪ੍ਰਭ ਸਹਜ ਸੁਭਾਇ ॥","lareedar":"ਜਬਨਿਰਗੁਨਪ੍ਰਭਸਹਜਸੁਭਾਇ ॥","translit":"Jab Niragun Prabh Sehaj Subhaae ||","english":"When God was without attributes, in absolute poise,"},{"punjabi":"ਤਬ ਸਿਵ ਸਕਤਿ ਕਹਹੁ ਕਿਤੁ ਠਾਇ ॥","lareedar":"ਤਬਸਿਵਸਕਤਿਕਹਹੁਕਿਤੁਠਾਇ ॥","translit":"Thab Siv Sakath Kehahu Kith Thaae ||","english":"Then where was mind and where was matter - where was Shiva and Shakti?"},{"punjabi":"ਜਬ ਆਪਹਿ ਆਪਿ ਅਪਨੀ ਜੋਤਿ ਧਰੈ ॥","lareedar":"ਜਬਆਪਹਿਆਪਿਅਪਨੀਜੋਤਿਧਰੈ ॥","translit":"Jab Aapehi Aap Apanee Joth Dhharai ||","english":"When He held His Own Light unto Himself,"},{"punjabi":"ਤਬ ਕਵਨ ਨਿਡਰੁ ਕਵਨ ਕਤ ਡਰੈ ॥","lareedar":"ਤਬਕਵਨਨਿਡਰੁਕਵਨਕਤਡਰੈ ॥","translit":"Thab Kavan Niddar Kavan Kath Ddarai ||","english":"Then who was fearless, and who was afraid?"},{"punjabi":"ਆਪਨ ਚਲਿਤ ਆਪਿ ਕਰਨੈਹਾਰ ॥","lareedar":"ਆਪਨਚਲਿਤਆਪਿਕਰਨੈਹਾਰ ॥","translit":"Aapan Chalith Aap Karanaihaar ||","english":"He Himself is the Performer in His own plays;"},{"punjabi":"ਨਾਨਕ ਠਾਕੁਰ ਅਗਮ ਅਪਾਰ ॥੨॥","lareedar":"ਨਾਨਕਠਾਕੁਰਅਗਮਅਪਾਰ ॥੨ ॥","translit":"Naanak Thaakur Agam Apaar ||2||","english":"O Nanak, the Lord Master is Unfathomable and Infinite. ||2||"},{"punjabi":"ਅਬਿਨਾਸੀ ਸੁਖ ਆਪਨ ਆਸਨ ॥","lareedar":"ਅਬਿਨਾਸੀਸੁਖਆਪਨਆਸਨ ॥","translit":"Abinaasee Sukh Aapan Aasan ||","english":"When the Immortal Lord was seated at ease,"},{"punjabi":"ਤਹ ਜਨਮ ਮਰਨ ਕਹੁ ਕਹਾ ਬਿਨਾਸਨ ॥","lareedar":"ਤਹਜਨਮਮਰਨਕਹੁਕਹਾਬਿਨਾਸਨ ॥","translit":"Theh Janam Maran Kahu Kehaa Binaasan ||","english":"Then where was birth, death and dissolution?"},{"punjabi":"ਜਬ ਪੂਰਨ ਕਰਤਾ ਪ੍ਰਭੁ ਸੋਇ ॥","lareedar":"ਜਬਪੂਰਨਕਰਤਾਪ੍ਰਭੁਸੋਇ ॥","translit":"Jab Pooran Karathaa Prabh Soe ||","english":"When there was only God, the Perfect Creator,"},{"punjabi":"ਤਬ ਜਮ ਕੀ ਤ੍ਰਾਸ ਕਹਹੁ ਕਿਸੁ ਹੋਇ ॥","lareedar":"ਤਬਜਮਕੀਤ੍ਰਾਸਕਹਹੁਕਿਸੁਹੋਇ ॥","translit":"Thab Jam Kee Thraas Kehahu Kis Hoe ||","english":"Then who was afraid of death?"},{"punjabi":"ਜਬ ਅਬਿਗਤ ਅਗੋਚਰ ਪ੍ਰਭ ਏਕਾ ॥","lareedar":"ਜਬਅਬਿਗਤਅਗੋਚਰਪ੍ਰਭਏਕਾ ॥","translit":"Jab Abigath Agochar Prabh Eaekaa ||","english":"When there was only the One Lord, unmanifest and incomprehensible,"},{"punjabi":"ਤਬ ਚਿਤ੍ਰ ਗੁਪਤ ਕਿਸੁ ਪੂਛਤ ਲੇਖਾ ॥","lareedar":"ਤਬਚਿਤ੍ਰਗੁਪਤਕਿਸੁਪੂਛਤਲੇਖਾ ॥","translit":"Thab Chithr Gupath Kis Pooshhath Laekhaa ||","english":"Then who was called to account by the recording scribes of the conscious and the subconscious?"},{"punjabi":"ਜਬ ਨਾਥ ਨਿਰੰਜਨ ਅਗੋਚਰ ਅਗਾਧੇ ॥","lareedar":"ਜਬਨਾਥਨਿਰੰਜਨਅਗੋਚਰਅਗਾਧੇ ॥","translit":"Jab Naathh Niranjan Agochar Agaadhhae ||","english":"When there was only the Immaculate, Incomprehensible, Unfathomable Master,"},{"punjabi":"ਤਬ ਕਉਨ ਛੁਟੇ ਕਉਨ ਬੰਧਨ ਬਾਧੇ ॥","lareedar":"ਤਬਕਉਨਛੁਟੇਕਉਨਬੰਧਨਬਾਧੇ ॥","translit":"Thab Koun Shhuttae Koun Bandhhan Baadhhae ||","english":"Then who was emancipated, and who was held in bondage?"},{"punjabi":"ਆਪਨ ਆਪ ਆਪ ਹੀ ਅਚਰਜਾ ॥","lareedar":"ਆਪਨਆਪਆਪਹੀਅਚਰਜਾ ॥","translit":"Aapan Aap Aap Hee Acharajaa ||","english":"He Himself, in and of Himself, is the most wonderful."},{"punjabi":"ਨਾਨਕ ਆਪਨ ਰੂਪ ਆਪ ਹੀ ਉਪਰਜਾ ॥੩॥","lareedar":"ਨਾਨਕਆਪਨਰੂਪਆਪਹੀਉਪਰਜਾ ॥੩ ॥","translit":"Naanak Aapan Roop Aap Hee Ouparajaa ||3||","english":"O Nanak, He Himself created His Own Form. ||3||"}]},{"index":70,"ang":291,"lines":[{"punjabi":"ਜਹ ਨਿਰਮਲ ਪੁਰਖੁ ਪੁਰਖ ਪਤਿ ਹੋਤਾ ॥","lareedar":"ਜਹਨਿਰਮਲਪੁਰਖੁਪੁਰਖਪਤਿਹੋਤਾ ॥","translit":"Jeh Niramal Purakh Purakh Path Hothaa ||","english":"When there was only the Immaculate Being, the Lord of beings,"},{"punjabi":"ਤਹ ਬਿਨੁ ਮੈਲੁ ਕਹਹੁ ਕਿਆ ਧੋਤਾ ॥","lareedar":"ਤਹਬਿਨੁਮੈਲੁਕਹਹੁਕਿਆਧੋਤਾ ॥","translit":"Theh Bin Mail Kehahu Kiaa Dhhothaa ||","english":"There was no filth, so what was there to be washed clean?"},{"punjabi":"ਜਹ ਨਿਰੰਜਨ ਨਿਰੰਕਾਰ ਨਿਰਬਾਨ ॥","lareedar":"ਜਹਨਿਰੰਜਨਨਿਰੰਕਾਰਨਿਰਬਾਨ ॥","translit":"Jeh Niranjan Nirankaar Nirabaan ||","english":"When there was only the Pure, Formless Lord in Nirvaanaa,"},{"punjabi":"ਤਹ ਕਉਨ ਕਉ ਮਾਨ ਕਉਨ ਅਭਿਮਾਨ ॥","lareedar":"ਤਹਕਉਨਕਉਮਾਨਕਉਨਅਭਿਮਾਨ ॥","translit":"Theh Koun Ko Maan Koun Abhimaan ||","english":"Then who was honored, and who was dishonored?"},{"punjabi":"ਜਹ ਸਰੂਪ ਕੇਵਲ ਜਗਦੀਸ ॥","lareedar":"ਜਹਸਰੂਪਕੇਵਲਜਗਦੀਸ ॥","translit":"Jeh Saroop Kaeval Jagadhees ||","english":"When there was only the Form of the Lord of the Universe,"},{"punjabi":"ਤਹ ਛਲ ਛਿਦ੍ਰ ਲਗਤ ਕਹੁ ਕੀਸ ॥","lareedar":"ਤਹਛਲਛਿਦ੍ਰਲਗਤਕਹੁਕੀਸ ॥","translit":"Theh Shhal Shhidhr Lagath Kahu Kees ||","english":"Then who was tainted by fraud and sin?"},{"punjabi":"ਜਹ ਜੋਤਿ ਸਰੂਪੀ ਜੋਤਿ ਸੰਗਿ ਸਮਾਵੈ ॥","lareedar":"ਜਹਜੋਤਿਸਰੂਪੀਜੋਤਿਸੰਗਿਸਮਾਵੈ ॥","translit":"Jeh Joth Saroopee Joth Sang Samaavai ||","english":"When the Embodiment of Light was immersed in His Own Light,"},{"punjabi":"ਤਹ ਕਿਸਹਿ ਭੂਖ ਕਵਨੁ ਤ੍ਰਿਪਤਾਵੈ ॥","lareedar":"ਤਹਕਿਸਹਿਭੂਖਕਵਨੁਤ੍ਰਿਪਤਾਵੈ ॥","translit":"Theh Kisehi Bhookh Kavan Thripathaavai ||","english":"Then who was hungry, and who was satisfied?"},{"punjabi":"ਕਰਨ ਕਰਾਵਨ ਕਰਨੈਹਾਰੁ ॥","lareedar":"ਕਰਨਕਰਾਵਨਕਰਨੈਹਾਰੁ ॥","translit":"Karan Karaavan Karanaihaar ||","english":"He is the Cause of causes, the Creator Lord."},{"punjabi":"ਨਾਨਕ ਕਰਤੇ ਕਾ ਨਾਹਿ ਸੁਮਾਰੁ ॥੪॥","lareedar":"ਨਾਨਕਕਰਤੇਕਾਨਾਹਿਸੁਮਾਰੁ ॥੪ ॥","translit":"Naanak Karathae Kaa Naahi Sumaar ||4||","english":"O Nanak, the Creator is beyond calculation. ||4||"},{"punjabi":"ਜਬ ਅਪਨੀ ਸੋਭਾ ਆਪਨ ਸੰਗਿ ਬਨਾਈ ॥","lareedar":"ਜਬਅਪਨੀਸੋਭਾਆਪਨਸੰਗਿਬਨਾਈ ॥","translit":"Jab Apanee Sobhaa Aapan Sang Banaaee ||","english":"When His Glory was contained within Himself,"},{"punjabi":"ਤਬ ਕਵਨ ਮਾਇ ਬਾਪ ਮਿਤ੍ਰ ਸੁਤ ਭਾਈ ॥","lareedar":"ਤਬਕਵਨਮਾਇਬਾਪਮਿਤ੍ਰਸੁਤਭਾਈ ॥","translit":"Thab Kavan Maae Baap Mithr Suth Bhaaee ||","english":"Then who was mother, father, friend, child or sibling?"},{"punjabi":"ਜਹ ਸਰਬ ਕਲਾ ਆਪਹਿ ਪਰਬੀਨ ॥","lareedar":"ਜਹਸਰਬਕਲਾਆਪਹਿਪਰਬੀਨ ॥","translit":"Jeh Sarab Kalaa Aapehi Parabeen ||","english":"When all power and wisdom was latent within Him,"},{"punjabi":"ਤਹ ਬੇਦ ਕਤੇਬ ਕਹਾ ਕੋਊ ਚੀਨ ॥","lareedar":"ਤਹਬੇਦਕਤੇਬਕਹਾਕੋਊਚੀਨ ॥","translit":"Theh Baedh Kathaeb Kehaa Kooo Cheen ||","english":"Then where were the Vedas and the scriptures, and who was there to read them?"},{"punjabi":"ਜਬ ਆਪਨ ਆਪੁ ਆਪਿ ਉਰਿ ਧਾਰੈ ॥","lareedar":"ਜਬਆਪਨਆਪੁਆਪਿਉਰਿਧਾਰੈ ॥","translit":"Jab Aapan Aap Aap Our Dhhaarai ||","english":"When He kept Himself, All-in-all, unto His Own Heart,"},{"punjabi":"ਤਉ ਸਗਨ ਅਪਸਗਨ ਕਹਾ ਬੀਚਾਰੈ ॥","lareedar":"ਤਉਸਗਨਅਪਸਗਨਕਹਾਬੀਚਾਰੈ ॥","translit":"Tho Sagan Apasagan Kehaa Beechaarai ||","english":"Then who considered omens to be good or bad?"},{"punjabi":"ਜਹ ਆਪਨ ਊਚ ਆਪਨ ਆਪਿ ਨੇਰਾ ॥","lareedar":"ਜਹਆਪਨਊਚਆਪਨਆਪਿਨੇਰਾ ॥","translit":"Jeh Aapan Ooch Aapan Aap Naeraa ||","english":"When He Himself was lofty, and He Himself was near at hand,"},{"punjabi":"ਤਹ ਕਉਨ ਠਾਕੁਰੁ ਕਉਨੁ ਕਹੀਐ ਚੇਰਾ ॥","lareedar":"ਤਹਕਉਨਠਾਕੁਰੁਕਉਨੁਕਹੀਐਚੇਰਾ ॥","translit":"Theh Koun Thaakur Koun Keheeai Chaeraa ||","english":"Then who was called master, and who was called disciple?"},{"punjabi":"ਬਿਸਮਨ ਬਿਸਮ ਰਹੇ ਬਿਸਮਾਦ ॥","lareedar":"ਬਿਸਮਨਬਿਸਮਰਹੇਬਿਸਮਾਦ ॥","translit":"Bisaman Bisam Rehae Bisamaadh ||","english":"We are wonder-struck at the wondrous wonder of the Lord."},{"punjabi":"ਨਾਨਕ ਅਪਨੀ ਗਤਿ ਜਾਨਹੁ ਆਪਿ ॥੫॥","lareedar":"ਨਾਨਕਅਪਨੀਗਤਿਜਾਨਹੁਆਪਿ ॥੫ ॥","translit":"Naanak Apanee Gath Jaanahu Aap ||5||","english":"O Nanak, He alone knows His own state. ||5||"},{"punjabi":"ਜਹ ਅਛਲ ਅਛੇਦ ਅਭੇਦ ਸਮਾਇਆ ॥","lareedar":"ਜਹਅਛਲਅਛੇਦਅਭੇਦਸਮਾਇਆ ॥","translit":"Jeh Ashhal Ashhaedh Abhaedh Samaaeiaa ||","english":"When the Undeceiveable, Impenetrable, Inscrutable One was self-absorbed,"},{"punjabi":"ਊਹਾ ਕਿਸਹਿ ਬਿਆਪਤ ਮਾਇਆ ॥","lareedar":"ਊਹਾਕਿਸਹਿਬਿਆਪਤਮਾਇਆ ॥","translit":"Oohaa Kisehi Biaapath Maaeiaa ||","english":"Then who was swayed by Maya?"},{"punjabi":"ਆਪਸ ਕਉ ਆਪਹਿ ਆਦੇਸੁ ॥","lareedar":"ਆਪਸਕਉਆਪਹਿਆਦੇਸੁ ॥","translit":"Aapas Ko Aapehi Aadhaes ||","english":"When He paid homage to Himself,"},{"punjabi":"ਤਿਹੁ ਗੁਣ ਕਾ ਨਾਹੀ ਪਰਵੇਸੁ ॥","lareedar":"ਤਿਹੁਗੁਣਕਾਨਾਹੀਪਰਵੇਸੁ ॥","translit":"Thihu Gun Kaa Naahee Paravaes ||","english":"Then the three qualities were not prevailing."},{"punjabi":"ਜਹ ਏਕਹਿ ਏਕ ਏਕ ਭਗਵੰਤਾ ॥","lareedar":"ਜਹਏਕਹਿਏਕਏਕਭਗਵੰਤਾ ॥","translit":"Jeh Eaekehi Eaek Eaek Bhagavanthaa ||","english":"When there was only the One, the One and Only Lord God,"}]},{"index":71,"ang":291,"lines":[{"punjabi":"ਤਹ ਕਉਨੁ ਅਚਿੰਤੁ ਕਿਸੁ ਲਾਗੈ ਚਿੰਤਾ ॥","lareedar":"ਤਹਕਉਨੁਅਚਿੰਤੁਕਿਸੁਲਾਗੈਚਿੰਤਾ ॥","translit":"Theh Koun Achinth Kis Laagai Chinthaa ||","english":"Then who was not anxious, and who felt anxiety?"},{"punjabi":"ਜਹ ਆਪਨ ਆਪੁ ਆਪਿ ਪਤੀਆਰਾ ॥","lareedar":"ਜਹਆਪਨਆਪੁਆਪਿਪਤੀਆਰਾ ॥","translit":"Jeh Aapan Aap Aap Patheeaaraa ||","english":"When He Himself was satisfied with Himself,"},{"punjabi":"ਤਹ ਕਉਨੁ ਕਥੈ ਕਉਨੁ ਸੁਨਨੈਹਾਰਾ ॥","lareedar":"ਤਹਕਉਨੁਕਥੈਕਉਨੁਸੁਨਨੈਹਾਰਾ ॥","translit":"Theh Koun Kathhai Koun Sunanaihaaraa ||","english":"Then who spoke and who listened?"},{"punjabi":"ਬਹੁ ਬੇਅੰਤ ਊਚ ਤੇ ਊਚਾ ॥","lareedar":"ਬਹੁਬੇਅੰਤਊਚਤੇਊਚਾ ॥","translit":"Bahu Baeanth Ooch Thae Oochaa ||","english":"He is vast and infinite, the highest of the high."},{"punjabi":"ਨਾਨਕ ਆਪਸ ਕਉ ਆਪਹਿ ਪਹੂਚਾ ॥੬॥","lareedar":"ਨਾਨਕਆਪਸਕਉਆਪਹਿਪਹੂਚਾ ॥੬ ॥","translit":"Naanak Aapas Ko Aapehi Pehoochaa ||6||","english":"O Nanak, He alone can reach Himself. ||6||"},{"punjabi":"ਜਹ ਆਪਿ ਰਚਿਓ ਪਰਪੰਚੁ ਅਕਾਰੁ ॥","lareedar":"ਜਹਆਪਿਰਚਿਓਪਰਪੰਚੁਅਕਾਰੁ ॥","translit":"Jeh Aap Rachiou Parapanch Akaar ||","english":"When He Himself fashioned the visible world of the creation,"},{"punjabi":"ਤਿਹੁ ਗੁਣ ਮਹਿ ਕੀਨੋ ਬਿਸਥਾਰੁ ॥","lareedar":"ਤਿਹੁਗੁਣਮਹਿਕੀਨੋਬਿਸਥਾਰੁ ॥","translit":"Thihu Gun Mehi Keeno Bisathhaar ||","english":"He made the world subject to the three dispositions."},{"punjabi":"ਪਾਪੁ ਪੁੰਨੁ ਤਹ ਭਈ ਕਹਾਵਤ ॥","lareedar":"ਪਾਪੁਪੁੰਨੁਤਹਭਈਕਹਾਵਤ ॥","translit":"Paap Punn Theh Bhee Kehaavath ||","english":"Sin and virtue then began to be spoken of."},{"punjabi":"ਕੋਊ ਨਰਕ ਕੋਊ ਸੁਰਗ ਬੰਛਾਵਤ ॥","lareedar":"ਕੋਊਨਰਕਕੋਊਸੁਰਗਬੰਛਾਵਤ ॥","translit":"Kooo Narak Kooo Surag Banshhaavath ||","english":"Some have gone to hell, and some yearn for paradise."},{"punjabi":"ਆਲ ਜਾਲ ਮਾਇਆ ਜੰਜਾਲ ॥","lareedar":"ਆਲਜਾਲਮਾਇਆਜੰਜਾਲ ॥","translit":"Aal Jaal Maaeiaa Janjaal ||","english":"Worldly snares and entanglements of Maya,"},{"punjabi":"ਹਉਮੈ ਮੋਹ ਭਰਮ ਭੈ ਭਾਰ ॥","lareedar":"ਹਉਮੈਮੋਹਭਰਮਭੈਭਾਰ ॥","translit":"Houmai Moh Bharam Bhai Bhaar ||","english":"Egotism, attachment, doubt and loads of fear;"},{"punjabi":"ਦੂਖ ਸੂਖ ਮਾਨ ਅਪਮਾਨ ॥","lareedar":"ਦੂਖਸੂਖਮਾਨਅਪਮਾਨ ॥","translit":"Dhookh Sookh Maan Apamaan ||","english":"Pain and pleasure, honor and dishonor"},{"punjabi":"ਅਨਿਕ ਪ੍ਰਕਾਰ ਕੀਓ ਬਖ੍ਯ੍ਯਾਨ ॥","lareedar":"ਅਨਿਕਪ੍ਰਕਾਰਕੀਓਬਖ੍ਯ੍ਯਾਨ ॥","translit":"Anik Prakaar Keeou Bakhyaan ||","english":"These came to be described in various ways."},{"punjabi":"ਆਪਨ ਖੇਲੁ ਆਪਿ ਕਰਿ ਦੇਖੈ ॥","lareedar":"ਆਪਨਖੇਲੁਆਪਿਕਰਿਦੇਖੈ ॥","translit":"Aapan Khael Aap Kar Dhaekhai ||","english":"He Himself creates and beholds His own drama."},{"punjabi":"ਖੇਲੁ ਸੰਕੋਚੈ ਤਉ ਨਾਨਕ ਏਕੈ ॥੭॥","lareedar":"ਖੇਲੁਸੰਕੋਚੈਤਉਨਾਨਕਏਕੈ ॥੭ ॥","translit":"Khael Sankochai Tho Naanak Eaekai ||7||","english":"He winds up the drama, and then, O Nanak, He alone remains. ||7||"},{"punjabi":"ਜਹ ਅਬਿਗਤੁ ਭਗਤੁ ਤਹ ਆਪਿ ॥","lareedar":"ਜਹਅਬਿਗਤੁਭਗਤੁਤਹਆਪਿ ॥","translit":"Jeh Abigath Bhagath Theh Aap ||","english":"Wherever the Eternal Lord's devotee is, He Himself is there."},{"punjabi":"ਜਹ ਪਸਰੈ ਪਾਸਾਰੁ ਸੰਤ ਪਰਤਾਪਿ ॥","lareedar":"ਜਹਪਸਰੈਪਾਸਾਰੁਸੰਤਪਰਤਾਪਿ ॥","translit":"Jeh Pasarai Paasaar Santh Parathaap ||","english":"He unfolds the expanse of His creation for the glory of His Saint."},{"punjabi":"ਦੁਹੂ ਪਾਖ ਕਾ ਆਪਹਿ ਧਨੀ ॥","lareedar":"ਦੁਹੂਪਾਖਕਾਆਪਹਿਧਨੀ ॥","translit":"Dhuhoo Paakh Kaa Aapehi Dhhanee ||","english":"He Himself is the Master of both worlds."},{"punjabi":"ਉਨ ਕੀ ਸੋਭਾ ਉਨਹੂ ਬਨੀ ॥","lareedar":"ਉਨਕੀਸੋਭਾਉਨਹੂਬਨੀ ॥","translit":"Oun Kee Sobhaa Ounehoo Banee ||","english":"His Praise is to Himself alone."},{"punjabi":"ਆਪਹਿ ਕਉਤਕ ਕਰੈ ਅਨਦ ਚੋਜ ॥","lareedar":"ਆਪਹਿਕਉਤਕਕਰੈਅਨਦਚੋਜ ॥","translit":"Aapehi Kouthak Karai Anadh Choj ||","english":"He Himself performs and plays His amusements and games."},{"punjabi":"ਆਪਹਿ ਰਸ ਭੋਗਨ ਨਿਰਜੋਗ ॥","lareedar":"ਆਪਹਿਰਸਭੋਗਨਨਿਰਜੋਗ ॥","translit":"Aapehi Ras Bhogan Nirajog ||","english":"He Himself enjoys pleasures, and yet He is unaffected and untouched."},{"punjabi":"ਜਿਸੁ ਭਾਵੈ ਤਿਸੁ ਆਪਨ ਨਾਇ ਲਾਵੈ ॥","lareedar":"ਜਿਸੁਭਾਵੈਤਿਸੁਆਪਨਨਾਇਲਾਵੈ ॥","translit":"Jis Bhaavai This Aapan Naae Laavai ||","english":"He attaches whomever He pleases to His Name."},{"punjabi":"ਜਿਸੁ ਭਾਵੈ ਤਿਸੁ ਖੇਲ ਖਿਲਾਵੈ ॥","lareedar":"ਜਿਸੁਭਾਵੈਤਿਸੁਖੇਲਖਿਲਾਵੈ ॥","translit":"Jis Bhaavai This Khael Khilaavai ||","english":"He causes whomever He pleases to play in His play."},{"punjabi":"ਬੇਸੁਮਾਰ ਅਥਾਹ ਅਗਨਤ ਅਤੋਲੈ ॥","lareedar":"ਬੇਸੁਮਾਰਅਥਾਹਅਗਨਤਅਤੋਲੈ ॥","translit":"Baesumaar Athhaah Aganath Atholai ||","english":"He is beyond calculation, beyond measure, uncountable and unfathomable."},{"punjabi":"ਜਿਉ ਬੁਲਾਵਹੁ ਤਿਉ ਨਾਨਕ ਦਾਸ ਬੋਲੈ ॥੮॥੨੧॥","lareedar":"ਜਿਉਬੁਲਾਵਹੁਤਿਉਨਾਨਕਦਾਸਬੋਲੈ ॥੮ ॥੨੧ ॥","translit":"Jio Bulaavahu Thio Naanak Dhaas Bolai ||8||21||","english":"As You inspire him to speak, O Lord, so does servant Nanak speak. ||8||21||"}]},{"index":72,"ang":292,"lines":[{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਜੀਅ ਜੰਤ ਕੇ ਠਾਕੁਰਾ ਆਪੇ ਵਰਤਣਹਾਰ ॥","lareedar":"ਜੀਅਜੰਤਕੇਠਾਕੁਰਾਆਪੇਵਰਤਣਹਾਰ ॥","translit":"Jeea Janth Kae Thaakuraa Aapae Varathanehaar ||","english":"O Lord and Master of all beings and creatures, You Yourself are prevailing everywhere."},{"punjabi":"ਨਾਨਕ ਏਕੋ ਪਸਰਿਆ ਦੂਜਾ ਕਹ ਦ੍ਰਿਸਟਾਰ ॥੧॥","lareedar":"ਨਾਨਕਏਕੋਪਸਰਿਆਦੂਜਾਕਹਦ੍ਰਿਸਟਾਰ ॥੧ ॥","translit":"Naanak Eaeko Pasariaa Dhoojaa Keh Dhrisattaar ||1||","english":"O Nanak, The One is All-pervading; where is any other to be seen? ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਆਪਿ ਕਥੈ ਆਪਿ ਸੁਨਨੈਹਾਰੁ ॥","lareedar":"ਆਪਿਕਥੈਆਪਿਸੁਨਨੈਹਾਰੁ ॥","translit":"Aap Kathhai Aap Sunanaihaar ||","english":"He Himself is the speaker, and He Himself is the listener."},{"punjabi":"ਆਪਹਿ ਏਕੁ ਆਪਿ ਬਿਸਥਾਰੁ ॥","lareedar":"ਆਪਹਿਏਕੁਆਪਿਬਿਸਥਾਰੁ ॥","translit":"Aapehi Eaek Aap Bisathhaar ||","english":"He Himself is the One, and He Himself is the many."},{"punjabi":"ਜਾ ਤਿਸੁ ਭਾਵੈ ਤਾ ਸ੍ਰਿਸਟਿ ਉਪਾਏ ॥","lareedar":"ਜਾਤਿਸੁਭਾਵੈਤਾਸ੍ਰਿਸਟਿਉਪਾਏ ॥","translit":"Jaa This Bhaavai Thaa Srisatt Oupaaeae ||","english":"When it pleases Him, He creates the world."},{"punjabi":"ਆਪਨੈ ਭਾਣੈ ਲਏ ਸਮਾਏ ॥","lareedar":"ਆਪਨੈਭਾਣੈਲਏਸਮਾਏ ॥","translit":"Aapanai Bhaanai Leae Samaaeae ||","english":"As He pleases, He absorbs it back into Himself."},{"punjabi":"ਤੁਮ ਤੇ ਭਿੰਨ ਨਹੀ ਕਿਛੁ ਹੋਇ ॥","lareedar":"ਤੁਮਤੇਭਿੰਨਨਹੀਕਿਛੁਹੋਇ ॥","translit":"Thum Thae Bhinn Nehee Kishh Hoe ||","english":"Without You, nothing can be done."},{"punjabi":"ਆਪਨ ਸੂਤਿ ਸਭੁ ਜਗਤੁ ਪਰੋਇ ॥","lareedar":"ਆਪਨਸੂਤਿਸਭੁਜਗਤੁਪਰੋਇ ॥","translit":"Aapan Sooth Sabh Jagath Paroe ||","english":"Upon Your thread, You have strung the whole world."},{"punjabi":"ਜਾ ਕਉ ਪ੍ਰਭ ਜੀਉ ਆਪਿ ਬੁਝਾਏ ॥","lareedar":"ਜਾਕਉਪ੍ਰਭਜੀਉਆਪਿਬੁਝਾਏ ॥","translit":"Jaa Ko Prabh Jeeo Aap Bujhaaeae ||","english":"One whom God Himself inspires to understand"},{"punjabi":"ਸਚੁ ਨਾਮੁ ਸੋਈ ਜਨੁ ਪਾਏ ॥","lareedar":"ਸਚੁਨਾਮੁਸੋਈਜਨੁਪਾਏ ॥","translit":"Sach Naam Soee Jan Paaeae ||","english":"- that person obtains the True Name."},{"punjabi":"ਸੋ ਸਮਦਰਸੀ ਤਤ ਕਾ ਬੇਤਾ ॥","lareedar":"ਸੋਸਮਦਰਸੀਤਤਕਾਬੇਤਾ ॥","translit":"So Samadharasee Thath Kaa Baethaa ||","english":"He looks impartially upon all, and he knows the essential reality."},{"punjabi":"ਨਾਨਕ ਸਗਲ ਸ੍ਰਿਸਟਿ ਕਾ ਜੇਤਾ ॥੧॥","lareedar":"ਨਾਨਕਸਗਲਸ੍ਰਿਸਟਿਕਾਜੇਤਾ ॥੧ ॥","translit":"Naanak Sagal Srisatt Kaa Jaethaa ||1||","english":"O Nanak, he conquers the whole world. ||1||"},{"punjabi":"ਜੀਅ ਜੰਤ੍ਰ ਸਭ ਤਾ ਕੈ ਹਾਥ ॥","lareedar":"ਜੀਅਜੰਤ੍ਰਸਭਤਾਕੈਹਾਥ ॥","translit":"Jeea Janthr Sabh Thaa Kai Haathh ||","english":"All beings and creatures are in His Hands."},{"punjabi":"ਦੀਨ ਦਇਆਲ ਅਨਾਥ ਕੋ ਨਾਥੁ ॥","lareedar":"ਦੀਨਦਇਆਲਅਨਾਥਕੋਨਾਥੁ ॥","translit":"Dheen Dhaeiaal Anaathh Ko Naathh ||","english":"He is Merciful to the meek, the Patron of the patronless."},{"punjabi":"ਜਿਸੁ ਰਾਖੈ ਤਿਸੁ ਕੋਇ ਨ ਮਾਰੈ ॥","lareedar":"ਜਿਸੁਰਾਖੈਤਿਸੁਕੋਇਨਮਾਰੈ ॥","translit":"Jis Raakhai This Koe N Maarai ||","english":"No one can kill those who are protected by Him."},{"punjabi":"ਸੋ ਮੂਆ ਜਿਸੁ ਮਨਹੁ ਬਿਸਾਰੈ ॥","lareedar":"ਸੋਮੂਆਜਿਸੁਮਨਹੁਬਿਸਾਰੈ ॥","translit":"So Mooaa Jis Manahu Bisaarai ||","english":"One who is forgotten by God, is already dead."},{"punjabi":"ਤਿਸੁ ਤਜਿ ਅਵਰ ਕਹਾ ਕੋ ਜਾਇ ॥","lareedar":"ਤਿਸੁਤਜਿਅਵਰਕਹਾਕੋਜਾਇ ॥","translit":"This Thaj Avar Kehaa Ko Jaae ||","english":"Leaving Him, where else could anyone go?"},{"punjabi":"ਸਭ ਸਿਰਿ ਏਕੁ ਨਿਰੰਜਨ ਰਾਇ ॥","lareedar":"ਸਭਸਿਰਿਏਕੁਨਿਰੰਜਨਰਾਇ ॥","translit":"Sabh Sir Eaek Niranjan Raae ||","english":"Over the heads of all is the One, the Immaculate King."},{"punjabi":"ਜੀਅ ਕੀ ਜੁਗਤਿ ਜਾ ਕੈ ਸਭ ਹਾਥਿ ॥","lareedar":"ਜੀਅਕੀਜੁਗਤਿਜਾਕੈਸਭਹਾਥਿ ॥","translit":"Jeea Kee Jugath Jaa Kai Sabh Haathh ||","english":"The ways and means of all beings are in His Hands."},{"punjabi":"ਅੰਤਰਿ ਬਾਹਰਿ ਜਾਨਹੁ ਸਾਥਿ ॥","lareedar":"ਅੰਤਰਿਬਾਹਰਿਜਾਨਹੁਸਾਥਿ ॥","translit":"Anthar Baahar Jaanahu Saathh ||","english":"Inwardly and outwardly, know that He is with you."},{"punjabi":"ਗੁਨ ਨਿਧਾਨ ਬੇਅੰਤ ਅਪਾਰ ॥","lareedar":"ਗੁਨਨਿਧਾਨਬੇਅੰਤਅਪਾਰ ॥","translit":"Gun Nidhhaan Baeanth Apaar ||","english":"He is the Ocean of excellence, infinite and endless."},{"punjabi":"ਨਾਨਕ ਦਾਸ ਸਦਾ ਬਲਿਹਾਰ ॥੨॥","lareedar":"ਨਾਨਕਦਾਸਸਦਾਬਲਿਹਾਰ ॥੨ ॥","translit":"Naanak Dhaas Sadhaa Balihaar ||2||","english":"Slave Nanak is forever a sacrifice to Him. ||2||"},{"punjabi":"ਪੂਰਨ ਪੂਰਿ ਰਹੇ ਦਇਆਲ ॥","lareedar":"ਪੂਰਨਪੂਰਿਰਹੇਦਇਆਲ ॥","translit":"Pooran Poor Rehae Dhaeiaal ||","english":"The Perfect, Merciful Lord is pervading everywhere."}]},{"index":73,"ang":292,"lines":[{"punjabi":"ਸਭ ਊਪਰਿ ਹੋਵਤ ਕਿਰਪਾਲ ॥","lareedar":"ਸਭਊਪਰਿਹੋਵਤਕਿਰਪਾਲ ॥","translit":"Sabh Oopar Hovath Kirapaal ||","english":"His kindness extends to all."},{"punjabi":"ਅਪਨੇ ਕਰਤਬ ਜਾਨੈ ਆਪਿ ॥","lareedar":"ਅਪਨੇਕਰਤਬਜਾਨੈਆਪਿ ॥","translit":"Apanae Karathab Jaanai Aap ||","english":"He Himself knows His own ways."},{"punjabi":"ਅੰਤਰਜਾਮੀ ਰਹਿਓ ਬਿਆਪਿ ॥","lareedar":"ਅੰਤਰਜਾਮੀਰਹਿਓਬਿਆਪਿ ॥","translit":"Antharajaamee Rehiou Biaap ||","english":"The Inner-knower, the Searcher of hearts, is present everywhere."},{"punjabi":"ਪ੍ਰਤਿਪਾਲੈ ਜੀਅਨ ਬਹੁ ਭਾਤਿ ॥","lareedar":"ਪ੍ਰਤਿਪਾਲੈਜੀਅਨਬਹੁਭਾਤਿ ॥","translit":"Prathipaalai Jeean Bahu Bhaath ||","english":"He cherishes His living beings in so many ways."},{"punjabi":"ਜੋ ਜੋ ਰਚਿਓ ਸੁ ਤਿਸਹਿ ਧਿਆਤਿ ॥","lareedar":"ਜੋਜੋਰਚਿਓਸੁਤਿਸਹਿਧਿਆਤਿ ॥","translit":"Jo Jo Rachiou S Thisehi Dhhiaath ||","english":"That which He has created meditates on Him."},{"punjabi":"ਜਿਸੁ ਭਾਵੈ ਤਿਸੁ ਲਏ ਮਿਲਾਇ ॥","lareedar":"ਜਿਸੁਭਾਵੈਤਿਸੁਲਏਮਿਲਾਇ ॥","translit":"Jis Bhaavai This Leae Milaae ||","english":"Whoever pleases Him, He blends into Himself."},{"punjabi":"ਭਗਤਿ ਕਰਹਿ ਹਰਿ ਕੇ ਗੁਣ ਗਾਇ ॥","lareedar":"ਭਗਤਿਕਰਹਿਹਰਿਕੇਗੁਣਗਾਇ ॥","translit":"Bhagath Karehi Har Kae Gun Gaae ||","english":"They perform His devotional service and sing the Glorious Praises of the Lord."},{"punjabi":"ਮਨ ਅੰਤਰਿ ਬਿਸ੍ਵਾਸੁ ਕਰਿ ਮਾਨਿਆ ॥","lareedar":"ਮਨਅੰਤਰਿਬਿਸ੍ਵਾਸੁਕਰਿਮਾਨਿਆ ॥","translit":"Man Anthar Bisvaas Kar Maaniaa ||","english":"With heart-felt faith, they believe in Him."},{"punjabi":"ਕਰਨਹਾਰੁ ਨਾਨਕ ਇਕੁ ਜਾਨਿਆ ॥੩॥","lareedar":"ਕਰਨਹਾਰੁਨਾਨਕਇਕੁਜਾਨਿਆ ॥੩ ॥","translit":"Karanehaar Naanak Eik Jaaniaa ||3||","english":"O Nanak, they realize the One, the Creator Lord. ||3||"},{"punjabi":"ਜਨੁ ਲਾਗਾ ਹਰਿ ਏਕੈ ਨਾਇ ॥","lareedar":"ਜਨੁਲਾਗਾਹਰਿਏਕੈਨਾਇ ॥","translit":"Jan Laagaa Har Eaekai Naae ||","english":"The Lord's humble servant is committed to His Name."},{"punjabi":"ਤਿਸ ਕੀ ਆਸ ਨ ਬਿਰਥੀ ਜਾਇ ॥","lareedar":"ਤਿਸਕੀਆਸਨਬਿਰਥੀਜਾਇ ॥","translit":"This Kee Aas N Birathhee Jaae ||","english":"His hopes do not go in vain."},{"punjabi":"ਸੇਵਕ ਕਉ ਸੇਵਾ ਬਨਿ ਆਈ ॥","lareedar":"ਸੇਵਕਕਉਸੇਵਾਬਨਿਆਈ ॥","translit":"Saevak Ko Saevaa Ban Aaee ||","english":"The servant's purpose is to serve;"},{"punjabi":"ਹੁਕਮੁ ਬੂਝਿ ਪਰਮ ਪਦੁ ਪਾਈ ॥","lareedar":"ਹੁਕਮੁਬੂਝਿਪਰਮਪਦੁਪਾਈ ॥","translit":"Hukam Boojh Param Padh Paaee ||","english":"Obeying the Lord's Command, the supreme status is obtained."},{"punjabi":"ਇਸ ਤੇ ਊਪਰਿ ਨਹੀ ਬੀਚਾਰੁ ॥","lareedar":"ਇਸਤੇਊਪਰਿਨਹੀਬੀਚਾਰੁ ॥","translit":"Eis Thae Oopar Nehee Beechaar ||","english":"Beyond this, he has no other thought."},{"punjabi":"ਜਾ ਕੈ ਮਨਿ ਬਸਿਆ ਨਿਰੰਕਾਰੁ ॥","lareedar":"ਜਾਕੈਮਨਿਬਸਿਆਨਿਰੰਕਾਰੁ ॥","translit":"Jaa Kai Man Basiaa Nirankaar ||","english":"Within his mind, the Formless Lord abides."},{"punjabi":"ਬੰਧਨ ਤੋਰਿ ਭਏ ਨਿਰਵੈਰ ॥","lareedar":"ਬੰਧਨਤੋਰਿਭਏਨਿਰਵੈਰ ॥","translit":"Bandhhan Thor Bheae Niravair ||","english":"His bonds are cut away, and he becomes free of hatred."},{"punjabi":"ਅਨਦਿਨੁ ਪੂਜਹਿ ਗੁਰ ਕੇ ਪੈਰ ॥","lareedar":"ਅਨਦਿਨੁਪੂਜਹਿਗੁਰਕੇਪੈਰ ॥","translit":"Anadhin Poojehi Gur Kae Pair ||","english":"Night and day, he worships the Feet of the Guru."},{"punjabi":"ਇਹ ਲੋਕ ਸੁਖੀਏ ਪਰਲੋਕ ਸੁਹੇਲੇ ॥","lareedar":"ਇਹਲੋਕਸੁਖੀਏਪਰਲੋਕਸੁਹੇਲੇ ॥","translit":"Eih Lok Sukheeeae Paralok Suhaelae ||","english":"He is at peace in this world, and happy in the next."},{"punjabi":"ਨਾਨਕ ਹਰਿ ਪ੍ਰਭਿ ਆਪਹਿ ਮੇਲੇ ॥੪॥","lareedar":"ਨਾਨਕਹਰਿਪ੍ਰਭਿਆਪਹਿਮੇਲੇ ॥੪ ॥","translit":"Naanak Har Prabh Aapehi Maelae ||4||","english":"O Nanak, the Lord God unites him with Himself. ||4||"},{"punjabi":"ਸਾਧਸੰਗਿ ਮਿਲਿ ਕਰਹੁ ਅਨੰਦ ॥","lareedar":"ਸਾਧਸੰਗਿਮਿਲਿਕਰਹੁਅਨੰਦ ॥","translit":"Saadhhasang Mil Karahu Anandh ||","english":"Join the Company of the Holy, and be happy."},{"punjabi":"ਗੁਨ ਗਾਵਹੁ ਪ੍ਰਭ ਪਰਮਾਨੰਦ ॥","lareedar":"ਗੁਨਗਾਵਹੁਪ੍ਰਭਪਰਮਾਨੰਦ ॥","translit":"Gun Gaavahu Prabh Paramaanandh ||","english":"Sing the Glories of God, the embodiment of supreme bliss."},{"punjabi":"ਰਾਮ ਨਾਮ ਤਤੁ ਕਰਹੁ ਬੀਚਾਰੁ ॥","lareedar":"ਰਾਮਨਾਮਤਤੁਕਰਹੁਬੀਚਾਰੁ ॥","translit":"Raam Naam Thath Karahu Beechaar ||","english":"Contemplate the essence of the Lord's Name."},{"punjabi":"ਦ੍ਰੁਲਭ ਦੇਹ ਕਾ ਕਰਹੁ ਉਧਾਰੁ ॥","lareedar":"ਦ੍ਰੁਲਭਦੇਹਕਾਕਰਹੁਉਧਾਰੁ ॥","translit":"Dhraalabh Dhaeh Kaa Karahu Oudhhaar ||","english":"Redeem this human body, so difficult to obtain."},{"punjabi":"ਅੰਮ੍ਰਿਤ ਬਚਨ ਹਰਿ ਕੇ ਗੁਨ ਗਾਉ ॥","lareedar":"ਅੰਮ੍ਰਿਤਬਚਨਹਰਿਕੇਗੁਨਗਾਉ ॥","translit":"Anmrith Bachan Har Kae Gun Gaao ||","english":"Sing the Ambrosial Words of the Lord's Glorious Praises;"},{"punjabi":"ਪ੍ਰਾਨ ਤਰਨ ਕਾ ਇਹੈ ਸੁਆਉ ॥","lareedar":"ਪ੍ਰਾਨਤਰਨਕਾਇਹੈਸੁਆਉ ॥","translit":"Praan Tharan Kaa Eihai Suaao ||","english":"This is the way to save your mortal soul."}]},{"index":74,"ang":293,"lines":[{"punjabi":"ਆਠ ਪਹਰ ਪ੍ਰਭ ਪੇਖਹੁ ਨੇਰਾ ॥","lareedar":"ਆਠਪਹਰਪ੍ਰਭਪੇਖਹੁਨੇਰਾ ॥","translit":"Aath Pehar Prabh Paekhahu Naeraa ||","english":"Behold God near at hand, twenty-four hours a day."},{"punjabi":"ਮਿਟੈ ਅਗਿਆਨੁ ਬਿਨਸੈ ਅੰਧੇਰਾ ॥","lareedar":"ਮਿਟੈਅਗਿਆਨੁਬਿਨਸੈਅੰਧੇਰਾ ॥","translit":"Mittai Agiaan Binasai Andhhaeraa ||","english":"Ignorance shall depart, and darkness shall be dispelled."},{"punjabi":"ਸੁਨਿ ਉਪਦੇਸੁ ਹਿਰਦੈ ਬਸਾਵਹੁ ॥","lareedar":"ਸੁਨਿਉਪਦੇਸੁਹਿਰਦੈਬਸਾਵਹੁ ॥","translit":"Sun Oupadhaes Hiradhai Basaavahu ||","english":"Listen to the Teachings, and enshrine them in your heart."},{"punjabi":"ਮਨ ਇਛੇ ਨਾਨਕ ਫਲ ਪਾਵਹੁ ॥੫॥","lareedar":"ਮਨਇਛੇਨਾਨਕਫਲਪਾਵਹੁ ॥੫ ॥","translit":"Man Eishhae Naanak Fal Paavahu ||5||","english":"O Nanak, you shall obtain the fruits of your mind's desires. ||5||"},{"punjabi":"ਹਲਤੁ ਪਲਤੁ ਦੁਇ ਲੇਹੁ ਸਵਾਰਿ ॥","lareedar":"ਹਲਤੁਪਲਤੁਦੁਇਲੇਹੁਸਵਾਰਿ ॥","translit":"Halath Palath Dhue Laehu Savaar ||","english":"Embellish both this world and the next;"},{"punjabi":"ਰਾਮ ਨਾਮੁ ਅੰਤਰਿ ਉਰਿ ਧਾਰਿ ॥","lareedar":"ਰਾਮਨਾਮੁਅੰਤਰਿਉਰਿਧਾਰਿ ॥","translit":"Raam Naam Anthar Our Dhhaar ||","english":"Enshrine the Lord's Name deep within your heart."},{"punjabi":"ਪੂਰੇ ਗੁਰ ਕੀ ਪੂਰੀ ਦੀਖਿਆ ॥","lareedar":"ਪੂਰੇਗੁਰਕੀਪੂਰੀਦੀਖਿਆ ॥","translit":"Poorae Gur Kee Pooree Dheekhiaa ||","english":"Perfect are the Teachings of the Perfect Guru."},{"punjabi":"ਜਿਸੁ ਮਨਿ ਬਸੈ ਤਿਸੁ ਸਾਚੁ ਪਰੀਖਿਆ ॥","lareedar":"ਜਿਸੁਮਨਿਬਸੈਤਿਸੁਸਾਚੁਪਰੀਖਿਆ ॥","translit":"Jis Man Basai This Saach Pareekhiaa ||","english":"That person, within whose mind it abides, realizes the Truth."},{"punjabi":"ਮਨਿ ਤਨਿ ਨਾਮੁ ਜਪਹੁ ਲਿਵ ਲਾਇ ॥","lareedar":"ਮਨਿਤਨਿਨਾਮੁਜਪਹੁਲਿਵਲਾਇ ॥","translit":"Man Than Naam Japahu Liv Laae ||","english":"With your mind and body, chant the Naam; lovingly attune yourself to it."},{"punjabi":"ਦੂਖੁ ਦਰਦੁ ਮਨ ਤੇ ਭਉ ਜਾਇ ॥","lareedar":"ਦੂਖੁਦਰਦੁਮਨਤੇਭਉਜਾਇ ॥","translit":"Dhookh Dharadh Man Thae Bho Jaae ||","english":"Sorrow, pain and fear shall depart from your mind."},{"punjabi":"ਸਚੁ ਵਾਪਾਰੁ ਕਰਹੁ ਵਾਪਾਰੀ ॥","lareedar":"ਸਚੁਵਾਪਾਰੁਕਰਹੁਵਾਪਾਰੀ ॥","translit":"Sach Vaapaar Karahu Vaapaaree ||","english":"Deal in the true trade, O trader,"},{"punjabi":"ਦਰਗਹ ਨਿਬਹੈ ਖੇਪ ਤੁਮਾਰੀ ॥","lareedar":"ਦਰਗਹਨਿਬਹੈਖੇਪਤੁਮਾਰੀ ॥","translit":"Dharageh Nibehai Khaep Thumaaree ||","english":"And your merchandise shall be safe in the Court of the Lord."},{"punjabi":"ਏਕਾ ਟੇਕ ਰਖਹੁ ਮਨ ਮਾਹਿ ॥","lareedar":"ਏਕਾਟੇਕਰਖਹੁਮਨਮਾਹਿ ॥","translit":"Eaekaa Ttaek Rakhahu Man Maahi ||","english":"Keep the Support of the One in your mind."},{"punjabi":"ਨਾਨਕ ਬਹੁਰਿ ਨ ਆਵਹਿ ਜਾਹਿ ॥੬॥","lareedar":"ਨਾਨਕਬਹੁਰਿਨਆਵਹਿਜਾਹਿ ॥੬ ॥","translit":"Naanak Bahur N Aavehi Jaahi ||6||","english":"O Nanak, you shall not have to come and go in reincarnation again. ||6||"},{"punjabi":"ਤਿਸ ਤੇ ਦੂਰਿ ਕਹਾ ਕੋ ਜਾਇ ॥","lareedar":"ਤਿਸਤੇਦੂਰਿਕਹਾਕੋਜਾਇ ॥","translit":"This Thae Dhoor Kehaa Ko Jaae ||","english":"Where can anyone go, to get away from Him?"},{"punjabi":"ਉਬਰੈ ਰਾਖਨਹਾਰੁ ਧਿਆਇ ॥","lareedar":"ਉਬਰੈਰਾਖਨਹਾਰੁਧਿਆਇ ॥","translit":"Oubarai Raakhanehaar Dhhiaae ||","english":"Meditating on the Protector Lord, you shall be saved."},{"punjabi":"ਨਿਰਭਉ ਜਪੈ ਸਗਲ ਭਉ ਮਿਟੈ ॥","lareedar":"ਨਿਰਭਉਜਪੈਸਗਲਭਉਮਿਟੈ ॥","translit":"Nirabho Japai Sagal Bho Mittai ||","english":"Meditating on the Fearless Lord, all fear departs."},{"punjabi":"ਪ੍ਰਭ ਕਿਰਪਾ ਤੇ ਪ੍ਰਾਣੀ ਛੁਟੈ ॥","lareedar":"ਪ੍ਰਭਕਿਰਪਾਤੇਪ੍ਰਾਣੀਛੁਟੈ ॥","translit":"Prabh Kirapaa Thae Praanee Shhuttai ||","english":"By God's Grace, mortals are released."},{"punjabi":"ਜਿਸੁ ਪ੍ਰਭੁ ਰਾਖੈ ਤਿਸੁ ਨਾਹੀ ਦੂਖ ॥","lareedar":"ਜਿਸੁਪ੍ਰਭੁਰਾਖੈਤਿਸੁਨਾਹੀਦੂਖ ॥","translit":"Jis Prabh Raakhai This Naahee Dhookh ||","english":"One who is protected by God never suffers in pain."},{"punjabi":"ਨਾਮੁ ਜਪਤ ਮਨਿ ਹੋਵਤ ਸੂਖ ॥","lareedar":"ਨਾਮੁਜਪਤਮਨਿਹੋਵਤਸੂਖ ॥","translit":"Naam Japath Man Hovath Sookh ||","english":"Chanting the Naam, the mind becomes peaceful."},{"punjabi":"ਚਿੰਤਾ ਜਾਇ ਮਿਟੈ ਅਹੰਕਾਰੁ ॥","lareedar":"ਚਿੰਤਾਜਾਇਮਿਟੈਅਹੰਕਾਰੁ ॥","translit":"Chinthaa Jaae Mittai Ahankaar ||","english":"Anxiety departs, and ego is eliminated."},{"punjabi":"ਤਿਸੁ ਜਨ ਕਉ ਕੋਇ ਨ ਪਹੁਚਨਹਾਰੁ ॥","lareedar":"ਤਿਸੁਜਨਕਉਕੋਇਨਪਹੁਚਨਹਾਰੁ ॥","translit":"This Jan Ko Koe N Pahuchanehaar ||","english":"No one can equal that humble servant."},{"punjabi":"ਸਿਰ ਊਪਰਿ ਠਾਢਾ ਗੁਰੁ ਸੂਰਾ ॥","lareedar":"ਸਿਰਊਪਰਿਠਾਢਾਗੁਰੁਸੂਰਾ ॥","translit":"Sir Oopar Thaadtaa Gur Sooraa ||","english":"The Brave and Powerful Guru stands over his head."},{"punjabi":"ਨਾਨਕ ਤਾ ਕੇ ਕਾਰਜ ਪੂਰਾ ॥੭॥","lareedar":"ਨਾਨਕਤਾਕੇਕਾਰਜਪੂਰਾ ॥੭ ॥","translit":"Naanak Thaa Kae Kaaraj Pooraa ||7||","english":"O Nanak, his efforts are fulfilled. ||7||"},{"punjabi":"ਮਤਿ ਪੂਰੀ ਅੰਮ੍ਰਿਤੁ ਜਾ ਕੀ ਦ੍ਰਿਸਟਿ ॥","lareedar":"ਮਤਿਪੂਰੀਅੰਮ੍ਰਿਤੁਜਾਕੀਦ੍ਰਿਸਟਿ ॥","translit":"Math Pooree Anmrith Jaa Kee Dhrisatt ||","english":"His wisdom is perfect, and His Glance is Ambrosial."}]},{"index":75,"ang":293,"lines":[{"punjabi":"ਦਰਸਨੁ ਪੇਖਤ ਉਧਰਤ ਸ੍ਰਿਸਟਿ ॥","lareedar":"ਦਰਸਨੁਪੇਖਤਉਧਰਤਸ੍ਰਿਸਟਿ ॥","translit":"Dharasan Paekhath Oudhharath Srisatt ||","english":"Beholding His Vision, the universe is saved."},{"punjabi":"ਚਰਨ ਕਮਲ ਜਾ ਕੇ ਅਨੂਪ ॥","lareedar":"ਚਰਨਕਮਲਜਾਕੇਅਨੂਪ ॥","translit":"Charan Kamal Jaa Kae Anoop ||","english":"His Lotus Feet are incomparably beautiful."},{"punjabi":"ਸਫਲ ਦਰਸਨੁ ਸੁੰਦਰ ਹਰਿ ਰੂਪ ॥","lareedar":"ਸਫਲਦਰਸਨੁਸੁੰਦਰਹਰਿਰੂਪ ॥","translit":"Safal Dharasan Sundhar Har Roop ||","english":"The Blessed Vision of His Darshan is fruitful and rewarding; His Lordly Form is beautiful."},{"punjabi":"ਧੰਨੁ ਸੇਵਾ ਸੇਵਕੁ ਪਰਵਾਨੁ ॥","lareedar":"ਧੰਨੁਸੇਵਾਸੇਵਕੁਪਰਵਾਨੁ ॥","translit":"Dhhann Saevaa Saevak Paravaan ||","english":"Blessed is His service; His servant is famous."},{"punjabi":"ਅੰਤਰਜਾਮੀ ਪੁਰਖੁ ਪ੍ਰਧਾਨੁ ॥","lareedar":"ਅੰਤਰਜਾਮੀਪੁਰਖੁਪ੍ਰਧਾਨੁ ॥","translit":"Antharajaamee Purakh Pradhhaan ||","english":"The Inner-knower, the Searcher of hearts, is the most exalted Supreme Being."},{"punjabi":"ਜਿਸੁ ਮਨਿ ਬਸੈ ਸੁ ਹੋਤ ਨਿਹਾਲੁ ॥","lareedar":"ਜਿਸੁਮਨਿਬਸੈਸੁਹੋਤਨਿਹਾਲੁ ॥","translit":"Jis Man Basai S Hoth Nihaal ||","english":"That one, within whose mind He abides, is blissfully happy."},{"punjabi":"ਤਾ ਕੈ ਨਿਕਟਿ ਨ ਆਵਤ ਕਾਲੁ ॥","lareedar":"ਤਾਕੈਨਿਕਟਿਨਆਵਤਕਾਲੁ ॥","translit":"Thaa Kai Nikatt N Aavath Kaal ||","english":"Death does not draw near him."},{"punjabi":"ਅਮਰ ਭਏ ਅਮਰਾ ਪਦੁ ਪਾਇਆ ॥","lareedar":"ਅਮਰਭਏਅਮਰਾਪਦੁਪਾਇਆ ॥","translit":"Amar Bheae Amaraa Padh Paaeiaa ||","english":"One becomes immortal, and obtains the immortal status,"},{"punjabi":"ਸਾਧਸੰਗਿ ਨਾਨਕ ਹਰਿ ਧਿਆਇਆ ॥੮॥੨੨॥","lareedar":"ਸਾਧਸੰਗਿਨਾਨਕਹਰਿਧਿਆਇਆ ॥੮ ॥੨੨ ॥","translit":"Saadhhasang Naanak Har Dhhiaaeiaa ||8||22||","english":"Meditating on the Lord, O Nanak, in the Company of the Holy. ||8||22||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਗਿਆਨ ਅੰਜਨੁ ਗੁਰਿ ਦੀਆ ਅਗਿਆਨ ਅੰਧੇਰ ਬਿਨਾਸੁ ॥","lareedar":"ਗਿਆਨਅੰਜਨੁਗੁਰਿਦੀਆਅਗਿਆਨਅੰਧੇਰਬਿਨਾਸੁ ॥","translit":"Giaan Anjan Gur Dheeaa Agiaan Andhhaer Binaas ||","english":"The Guru has given the healing ointment of spiritual wisdom, and dispelled the darkness of ignorance."},{"punjabi":"ਹਰਿ ਕਿਰਪਾ ਤੇ ਸੰਤ ਭੇਟਿਆ ਨਾਨਕ ਮਨਿ ਪਰਗਾਸੁ ॥੧॥","lareedar":"ਹਰਿਕਿਰਪਾਤੇਸੰਤਭੇਟਿਆਨਾਨਕਮਨਿਪਰਗਾਸੁ ॥੧ ॥","translit":"Har Kirapaa Thae Santh Bhaettiaa Naanak Man Paragaas ||1||","english":"By the Lord's Grace, I have met the Saint; O Nanak, my mind is enlightened. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਸੰਤਸੰਗਿ ਅੰਤਰਿ ਪ੍ਰਭੁ ਡੀਠਾ ॥","lareedar":"ਸੰਤਸੰਗਿਅੰਤਰਿਪ੍ਰਭੁਡੀਠਾ ॥","translit":"Santhasang Anthar Prabh Ddeethaa ||","english":"In the Society of the Saints, I see God deep within my being."},{"punjabi":"ਨਾਮੁ ਪ੍ਰਭੂ ਕਾ ਲਾਗਾ ਮੀਠਾ ॥","lareedar":"ਨਾਮੁਪ੍ਰਭੂਕਾਲਾਗਾਮੀਠਾ ॥","translit":"Naam Prabhoo Kaa Laagaa Meethaa ||","english":"God's Name is sweet to me."},{"punjabi":"ਸਗਲ ਸਮਿਗ੍ਰੀ ਏਕਸੁ ਘਟ ਮਾਹਿ ॥","lareedar":"ਸਗਲਸਮਿਗ੍ਰੀਏਕਸੁਘਟਮਾਹਿ ॥","translit":"Sagal Samigree Eaekas Ghatt Maahi ||","english":"All things are contained in the Heart of the One,"},{"punjabi":"ਅਨਿਕ ਰੰਗ ਨਾਨਾ ਦ੍ਰਿਸਟਾਹਿ ॥","lareedar":"ਅਨਿਕਰੰਗਨਾਨਾਦ੍ਰਿਸਟਾਹਿ ॥","translit":"Anik Rang Naanaa Dhrisattaahi ||","english":"Although they appear in so many various colors."},{"punjabi":"ਨਉ ਨਿਧਿ ਅੰਮ੍ਰਿਤੁ ਪ੍ਰਭ ਕਾ ਨਾਮੁ ॥","lareedar":"ਨਉਨਿਧਿਅੰਮ੍ਰਿਤੁਪ੍ਰਭਕਾਨਾਮੁ ॥","translit":"No Nidhh Anmrith Prabh Kaa Naam ||","english":"The nine treasures are in the Ambrosial Name of God."},{"punjabi":"ਦੇਹੀ ਮਹਿ ਇਸ ਕਾ ਬਿਸ੍ਰਾਮੁ ॥","lareedar":"ਦੇਹੀਮਹਿਇਸਕਾਬਿਸ੍ਰਾਮੁ ॥","translit":"Dhaehee Mehi Eis Kaa Bisraam ||","english":"Within the human body is its place of rest."},{"punjabi":"ਸੁੰਨ ਸਮਾਧਿ ਅਨਹਤ ਤਹ ਨਾਦ ॥","lareedar":"ਸੁੰਨਸਮਾਧਿਅਨਹਤਤਹਨਾਦ ॥","translit":"Sunn Samaadhh Anehath Theh Naadh ||","english":"The Deepest Samaadhi, and the unstruck sound current of the Naad are there."},{"punjabi":"ਕਹਨੁ ਨ ਜਾਈ ਅਚਰਜ ਬਿਸਮਾਦ ॥","lareedar":"ਕਹਨੁਨਜਾਈਅਚਰਜਬਿਸਮਾਦ ॥","translit":"Kehan N Jaaee Acharaj Bisamaadh ||","english":"The wonder and marvel of it cannot be described."},{"punjabi":"ਤਿਨਿ ਦੇਖਿਆ ਜਿਸੁ ਆਪਿ ਦਿਖਾਏ ॥","lareedar":"ਤਿਨਿਦੇਖਿਆਜਿਸੁਆਪਿਦਿਖਾਏ ॥","translit":"Thin Dhaekhiaa Jis Aap Dhikhaaeae ||","english":"He alone sees it, unto whom God Himself reveals it."},{"punjabi":"ਨਾਨਕ ਤਿਸੁ ਜਨ ਸੋਝੀ ਪਾਏ ॥੧॥","lareedar":"ਨਾਨਕਤਿਸੁਜਨਸੋਝੀਪਾਏ ॥੧ ॥","translit":"Naanak This Jan Sojhee Paaeae ||1||","english":"O Nanak, that humble being understands. ||1||"},{"punjabi":"ਸੋ ਅੰਤਰਿ ਸੋ ਬਾਹਰਿ ਅਨੰਤ ॥","lareedar":"ਸੋਅੰਤਰਿਸੋਬਾਹਰਿਅਨੰਤ ॥","translit":"So Anthar So Baahar Ananth ||","english":"The Infinite Lord is inside, and outside as well."},{"punjabi":"ਘਟਿ ਘਟਿ ਬਿਆਪਿ ਰਹਿਆ ਭਗਵੰਤ ॥","lareedar":"ਘਟਿਘਟਿਬਿਆਪਿਰਹਿਆਭਗਵੰਤ ॥","translit":"Ghatt Ghatt Biaap Rehiaa Bhagavanth ||","english":"Deep within each and every heart, the Lord God is pervading."}]},{"index":76,"ang":293,"lines":[{"punjabi":"ਧਰਨਿ ਮਾਹਿ ਆਕਾਸ ਪਇਆਲ ॥","lareedar":"ਧਰਨਿਮਾਹਿਆਕਾਸਪਇਆਲ ॥","translit":"Dhharan Maahi Aakaas Paeiaal ||","english":"In the earth, in the Akaashic ethers, and in the nether regions of the underworld"},{"punjabi":"ਸਰਬ ਲੋਕ ਪੂਰਨ ਪ੍ਰਤਿਪਾਲ ॥","lareedar":"ਸਰਬਲੋਕਪੂਰਨਪ੍ਰਤਿਪਾਲ ॥","translit":"Sarab Lok Pooran Prathipaal ||","english":"In all worlds, He is the Perfect Cherisher."},{"punjabi":"ਬਨਿ ਤਿਨਿ ਪਰਬਤਿ ਹੈ ਪਾਰਬ੍ਰਹਮੁ ॥","lareedar":"ਬਨਿਤਿਨਿਪਰਬਤਿਹੈਪਾਰਬ੍ਰਹਮੁ ॥","translit":"Ban Thin Parabath Hai Paarabreham ||","english":"In the forests, fields and mountains, He is the Supreme Lord God."},{"punjabi":"ਜੈਸੀ ਆਗਿਆ ਤੈਸਾ ਕਰਮੁ ॥","lareedar":"ਜੈਸੀਆਗਿਆਤੈਸਾਕਰਮੁ ॥","translit":"Jaisee Aagiaa Thaisaa Karam ||","english":"As He orders, so do His creatures act."},{"punjabi":"ਪਉਣ ਪਾਣੀ ਬੈਸੰਤਰ ਮਾਹਿ ॥","lareedar":"ਪਉਣਪਾਣੀਬੈਸੰਤਰਮਾਹਿ ॥","translit":"Poun Paanee Baisanthar Maahi ||","english":"He permeates the winds and the waters."},{"punjabi":"ਚਾਰਿ ਕੁੰਟ ਦਹ ਦਿਸੇ ਸਮਾਹਿ ॥","lareedar":"ਚਾਰਿਕੁੰਟਦਹਦਿਸੇਸਮਾਹਿ ॥","translit":"Chaar Kuntt Dheh Dhisae Samaahi ||","english":"He is pervading in the four corners and in the ten directions."},{"punjabi":"ਤਿਸ ਤੇ ਭਿੰਨ ਨਹੀ ਕੋ ਠਾਉ ॥","lareedar":"ਤਿਸਤੇਭਿੰਨਨਹੀਕੋਠਾਉ ॥","translit":"This Thae Bhinn Nehee Ko Thaao ||","english":"Without Him, there is no place at all."},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਨਾਨਕ ਸੁਖੁ ਪਾਉ ॥੨॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਨਾਨਕਸੁਖੁਪਾਉ ॥੨ ॥","translit":"Gur Prasaadh Naanak Sukh Paao ||2||","english":"By Guru's Grace, O Nanak, peace is obtained. ||2||"},{"punjabi":"ਬੇਦ ਪੁਰਾਨ ਸਿੰਮ੍ਰਿਤਿ ਮਹਿ ਦੇਖੁ ॥","lareedar":"ਬੇਦਪੁਰਾਨਸਿੰਮ੍ਰਿਤਿਮਹਿਦੇਖੁ ॥","translit":"Baedh Puraan Sinmrith Mehi Dhaekh ||","english":"See Him in the Vedas, the Puraanas and the Simritees."},{"punjabi":"ਸਸੀਅਰ ਸੂਰ ਨਖ੍ਯ੍ਯਤ੍ਰ ਮਹਿ ਏਕੁ ॥","lareedar":"ਸਸੀਅਰਸੂਰਨਖ੍ਯ੍ਯਤ੍ਰਮਹਿਏਕੁ ॥","translit":"Saseear Soor Nakhyathr Mehi Eaek ||","english":"In the moon, the sun and the stars, He is the One."},{"punjabi":"ਬਾਣੀ ਪ੍ਰਭ ਕੀ ਸਭੁ ਕੋ ਬੋਲੈ ॥","lareedar":"ਬਾਣੀਪ੍ਰਭਕੀਸਭੁਕੋਬੋਲੈ ॥","translit":"Baanee Prabh Kee Sabh Ko Bolai ||","english":"The Bani of God's Word is spoken by everyone."},{"punjabi":"ਆਪਿ ਅਡੋਲੁ ਨ ਕਬਹੂ ਡੋਲੈ ॥","lareedar":"ਆਪਿਅਡੋਲੁਨਕਬਹੂਡੋਲੈ ॥","translit":"Aap Addol N Kabehoo Ddolai ||","english":"He Himself is unwavering - He never wavers."},{"punjabi":"ਸਰਬ ਕਲਾ ਕਰਿ ਖੇਲੈ ਖੇਲ ॥","lareedar":"ਸਰਬਕਲਾਕਰਿਖੇਲੈਖੇਲ ॥","translit":"Sarab Kalaa Kar Khaelai Khael ||","english":"With absolute power, He plays His play."},{"punjabi":"ਮੋਲਿ ਨ ਪਾਈਐ ਗੁਣਹ ਅਮੋਲ ॥","lareedar":"ਮੋਲਿਨਪਾਈਐਗੁਣਹਅਮੋਲ ॥","translit":"Mol N Paaeeai Guneh Amol ||","english":"His value cannot be estimated; His virtues are invaluable."},{"punjabi":"ਸਰਬ ਜੋਤਿ ਮਹਿ ਜਾ ਕੀ ਜੋਤਿ ॥","lareedar":"ਸਰਬਜੋਤਿਮਹਿਜਾਕੀਜੋਤਿ ॥","translit":"Sarab Joth Mehi Jaa Kee Joth ||","english":"In all light, is His Light."},{"punjabi":"ਧਾਰਿ ਰਹਿਓ ਸੁਆਮੀ ਓਤਿ ਪੋਤਿ ॥","lareedar":"ਧਾਰਿਰਹਿਓਸੁਆਮੀਓਤਿਪੋਤਿ ॥","translit":"Dhhaar Rehiou Suaamee Outh Poth ||","english":"The Lord and Master supports the weave of the fabric of the universe."},{"punjabi":"ਗੁਰ ਪਰਸਾਦਿ ਭਰਮ ਕਾ ਨਾਸੁ ॥","lareedar":"ਗੁਰਪਰਸਾਦਿਭਰਮਕਾਨਾਸੁ ॥","translit":"Gur Parasaadh Bharam Kaa Naas ||","english":"By Guru's Grace, doubt is dispelled."},{"punjabi":"ਨਾਨਕ ਤਿਨ ਮਹਿ ਏਹੁ ਬਿਸਾਸੁ ॥੩॥","lareedar":"ਨਾਨਕਤਿਨਮਹਿਏਹੁਬਿਸਾਸੁ ॥੩ ॥","translit":"Naanak Thin Mehi Eaehu Bisaas ||3||","english":"O Nanak, this faith is firmly implanted within. ||3||"},{"punjabi":"ਸੰਤ ਜਨਾ ਕਾ ਪੇਖਨੁ ਸਭੁ ਬ੍ਰਹਮ ॥","lareedar":"ਸੰਤਜਨਾਕਾਪੇਖਨੁਸਭੁਬ੍ਰਹਮ ॥","translit":"Santh Janaa Kaa Paekhan Sabh Breham ||","english":"In the eye of the Saint, everything is God."},{"punjabi":"ਸੰਤ ਜਨਾ ਕੈ ਹਿਰਦੈ ਸਭਿ ਧਰਮ ॥","lareedar":"ਸੰਤਜਨਾਕੈਹਿਰਦੈਸਭਿਧਰਮ ॥","translit":"Santh Janaa Kai Hiradhai Sabh Dhharam ||","english":"In the heart of the Saint, everything is Dharma."},{"punjabi":"ਸੰਤ ਜਨਾ ਸੁਨਹਿ ਸੁਭ ਬਚਨ ॥","lareedar":"ਸੰਤਜਨਾਸੁਨਹਿਸੁਭਬਚਨ ॥","translit":"Santh Janaa Sunehi Subh Bachan ||","english":"The Saint hears words of goodness."},{"punjabi":"ਸਰਬ ਬਿਆਪੀ ਰਾਮ ਸੰਗਿ ਰਚਨ ॥","lareedar":"ਸਰਬਬਿਆਪੀਰਾਮਸੰਗਿਰਚਨ ॥","translit":"Sarab Biaapee Raam Sang Rachan ||","english":"He is absorbed in the All-pervading Lord."},{"punjabi":"ਜਿਨਿ ਜਾਤਾ ਤਿਸ ਕੀ ਇਹ ਰਹਤ ॥","lareedar":"ਜਿਨਿਜਾਤਾਤਿਸਕੀਇਹਰਹਤ ॥","translit":"Jin Jaathaa This Kee Eih Rehath ||","english":"This is the way of life of one who knows God."},{"punjabi":"ਸਤਿ ਬਚਨ ਸਾਧੂ ਸਭਿ ਕਹਤ ॥","lareedar":"ਸਤਿਬਚਨਸਾਧੂਸਭਿਕਹਤ ॥","translit":"Sath Bachan Saadhhoo Sabh Kehath ||","english":"True are all the words spoken by the Holy."},{"punjabi":"ਜੋ ਜੋ ਹੋਇ ਸੋਈ ਸੁਖੁ ਮਾਨੈ ॥","lareedar":"ਜੋਜੋਹੋਇਸੋਈਸੁਖੁਮਾਨੈ ॥","translit":"Jo Jo Hoe Soee Sukh Maanai ||","english":"Whatever happens, he peacefully accepts."}]},{"index":77,"ang":294,"lines":[{"punjabi":"ਕਰਨ ਕਰਾਵਨਹਾਰੁ ਪ੍ਰਭੁ ਜਾਨੈ ॥","lareedar":"ਕਰਨਕਰਾਵਨਹਾਰੁਪ੍ਰਭੁਜਾਨੈ ॥","translit":"Karan Karaavanehaar Prabh Jaanai ||","english":"He knows God as the Doer, the Cause of causes."},{"punjabi":"ਅੰਤਰਿ ਬਸੇ ਬਾਹਰਿ ਭੀ ਓਹੀ ॥","lareedar":"ਅੰਤਰਿਬਸੇਬਾਹਰਿਭੀਓਹੀ ॥","translit":"Anthar Basae Baahar Bhee Ouhee ||","english":"He dwells inside, and outside as well."},{"punjabi":"ਨਾਨਕ ਦਰਸਨੁ ਦੇਖਿ ਸਭ ਮੋਹੀ ॥੪॥","lareedar":"ਨਾਨਕਦਰਸਨੁਦੇਖਿਸਭਮੋਹੀ ॥੪ ॥","translit":"Naanak Dharasan Dhaekh Sabh Mohee ||4||","english":"O Nanak, beholding the Blessed Vision of His Darshan, all are fascinated. ||4||"},{"punjabi":"ਆਪਿ ਸਤਿ ਕੀਆ ਸਭੁ ਸਤਿ ॥","lareedar":"ਆਪਿਸਤਿਕੀਆਸਭੁਸਤਿ ॥","translit":"Aap Sath Keeaa Sabh Sath ||","english":"He Himself is True, and all that He has made is True."},{"punjabi":"ਤਿਸੁ ਪ੍ਰਭ ਤੇ ਸਗਲੀ ਉਤਪਤਿ ॥","lareedar":"ਤਿਸੁਪ੍ਰਭਤੇਸਗਲੀਉਤਪਤਿ ॥","translit":"This Prabh Thae Sagalee Outhapath ||","english":"The entire creation came from God."},{"punjabi":"ਤਿਸੁ ਭਾਵੈ ਤਾ ਕਰੇ ਬਿਸਥਾਰੁ ॥","lareedar":"ਤਿਸੁਭਾਵੈਤਾਕਰੇਬਿਸਥਾਰੁ ॥","translit":"This Bhaavai Thaa Karae Bisathhaar ||","english":"As it pleases Him, He creates the expanse."},{"punjabi":"ਤਿਸੁ ਭਾਵੈ ਤਾ ਏਕੰਕਾਰੁ ॥","lareedar":"ਤਿਸੁਭਾਵੈਤਾਏਕੰਕਾਰੁ ॥","translit":"This Bhaavai Thaa Eaekankaar ||","english":"As it pleases Him, He becomes the One and Only again."},{"punjabi":"ਅਨਿਕ ਕਲਾ ਲਖੀ ਨਹ ਜਾਇ ॥","lareedar":"ਅਨਿਕਕਲਾਲਖੀਨਹਜਾਇ ॥","translit":"Anik Kalaa Lakhee Neh Jaae ||","english":"His powers are so numerous, they cannot be known."},{"punjabi":"ਜਿਸੁ ਭਾਵੈ ਤਿਸੁ ਲਏ ਮਿਲਾਇ ॥","lareedar":"ਜਿਸੁਭਾਵੈਤਿਸੁਲਏਮਿਲਾਇ ॥","translit":"Jis Bhaavai This Leae Milaae ||","english":"As it pleases Him, He merges us into Himself again."},{"punjabi":"ਕਵਨ ਨਿਕਟਿ ਕਵਨ ਕਹੀਐ ਦੂਰਿ ॥","lareedar":"ਕਵਨਨਿਕਟਿਕਵਨਕਹੀਐਦੂਰਿ ॥","translit":"Kavan Nikatt Kavan Keheeai Dhoor ||","english":"Who is near, and who is far away?"},{"punjabi":"ਆਪੇ ਆਪਿ ਆਪ ਭਰਪੂਰਿ ॥","lareedar":"ਆਪੇਆਪਿਆਪਭਰਪੂਰਿ ॥","translit":"Aapae Aap Aap Bharapoor ||","english":"He Himself is Himself pervading everywhere."},{"punjabi":"ਅੰਤਰਗਤਿ ਜਿਸੁ ਆਪਿ ਜਨਾਏ ॥","lareedar":"ਅੰਤਰਗਤਿਜਿਸੁਆਪਿਜਨਾਏ ॥","translit":"Antharagath Jis Aap Janaaeae ||","english":"One whom God causes to know that He is within the heart"},{"punjabi":"ਨਾਨਕ ਤਿਸੁ ਜਨ ਆਪਿ ਬੁਝਾਏ ॥੫॥","lareedar":"ਨਾਨਕਤਿਸੁਜਨਆਪਿਬੁਝਾਏ ॥੫ ॥","translit":"Naanak This Jan Aap Bujhaaeae ||5||","english":"- O Nanak, He causes that person to understand Him. ||5||"},{"punjabi":"ਸਰਬ ਭੂਤ ਆਪਿ ਵਰਤਾਰਾ ॥","lareedar":"ਸਰਬਭੂਤਆਪਿਵਰਤਾਰਾ ॥","translit":"Sarab Bhooth Aap Varathaaraa ||","english":"In all forms, He Himself is pervading."},{"punjabi":"ਸਰਬ ਨੈਨ ਆਪਿ ਪੇਖਨਹਾਰਾ ॥","lareedar":"ਸਰਬਨੈਨਆਪਿਪੇਖਨਹਾਰਾ ॥","translit":"Sarab Nain Aap Paekhanehaaraa ||","english":"Through all eyes, He Himself is watching."},{"punjabi":"ਸਗਲ ਸਮਗ੍ਰੀ ਜਾ ਕਾ ਤਨਾ ॥","lareedar":"ਸਗਲਸਮਗ੍ਰੀਜਾਕਾਤਨਾ ॥","translit":"Sagal Samagree Jaa Kaa Thanaa ||","english":"All the creation is His Body."},{"punjabi":"ਆਪਨ ਜਸੁ ਆਪ ਹੀ ਸੁਨਾ ॥","lareedar":"ਆਪਨਜਸੁਆਪਹੀਸੁਨਾ ॥","translit":"Aapan Jas Aap Hee Sunaa ||","english":"He Himself listens to His Own Praise."},{"punjabi":"ਆਵਨ ਜਾਨੁ ਇਕੁ ਖੇਲੁ ਬਨਾਇਆ ॥","lareedar":"ਆਵਨਜਾਨੁਇਕੁਖੇਲੁਬਨਾਇਆ ॥","translit":"Aavan Jaan Eik Khael Banaaeiaa ||","english":"The One has created the drama of coming and going."},{"punjabi":"ਆਗਿਆਕਾਰੀ ਕੀਨੀ ਮਾਇਆ ॥","lareedar":"ਆਗਿਆਕਾਰੀਕੀਨੀਮਾਇਆ ॥","translit":"Aagiaakaaree Keenee Maaeiaa ||","english":"He made Maya subservient to His Will."},{"punjabi":"ਸਭ ਕੈ ਮਧਿ ਅਲਿਪਤੋ ਰਹੈ ॥","lareedar":"ਸਭਕੈਮਧਿਅਲਿਪਤੋਰਹੈ ॥","translit":"Sabh Kai Madhh Alipatho Rehai ||","english":"In the midst of all, He remains unattached."},{"punjabi":"ਜੋ ਕਿਛੁ ਕਹਣਾ ਸੁ ਆਪੇ ਕਹੈ ॥","lareedar":"ਜੋਕਿਛੁਕਹਣਾਸੁਆਪੇਕਹੈ ॥","translit":"Jo Kishh Kehanaa S Aapae Kehai ||","english":"Whatever is said, He Himself says."},{"punjabi":"ਆਗਿਆ ਆਵੈ ਆਗਿਆ ਜਾਇ ॥","lareedar":"ਆਗਿਆਆਵੈਆਗਿਆਜਾਇ ॥","translit":"Aagiaa Aavai Aagiaa Jaae ||","english":"By His Will we come, and by His Will we go."},{"punjabi":"ਨਾਨਕ ਜਾ ਭਾਵੈ ਤਾ ਲਏ ਸਮਾਇ ॥੬॥","lareedar":"ਨਾਨਕਜਾਭਾਵੈਤਾਲਏਸਮਾਇ ॥੬ ॥","translit":"Naanak Jaa Bhaavai Thaa Leae Samaae ||6||","english":"O Nanak, when it pleases Him, then He absorbs us into Himself. ||6||"},{"punjabi":"ਇਸ ਤੇ ਹੋਇ ਸੁ ਨਾਹੀ ਬੁਰਾ ॥","lareedar":"ਇਸਤੇਹੋਇਸੁਨਾਹੀਬੁਰਾ ॥","translit":"Eis Thae Hoe S Naahee Buraa ||","english":"If it comes from Him, it cannot be bad."},{"punjabi":"ਓਰੈ ਕਹਹੁ ਕਿਨੈ ਕਛੁ ਕਰਾ ॥","lareedar":"ਓਰੈਕਹਹੁਕਿਨੈਕਛੁਕਰਾ ॥","translit":"Ourai Kehahu Kinai Kashh Karaa ||","english":"Other than Him, who can do anything?"}]},{"index":78,"ang":294,"lines":[{"punjabi":"ਆਪਿ ਭਲਾ ਕਰਤੂਤਿ ਅਤਿ ਨੀਕੀ ॥","lareedar":"ਆਪਿਭਲਾਕਰਤੂਤਿਅਤਿਨੀਕੀ ॥","translit":"Aap Bhalaa Karathooth Ath Neekee ||","english":"He Himself is good; His actions are the very best."},{"punjabi":"ਆਪੇ ਜਾਨੈ ਅਪਨੇ ਜੀ ਕੀ ॥","lareedar":"ਆਪੇਜਾਨੈਅਪਨੇਜੀਕੀ ॥","translit":"Aapae Jaanai Apanae Jee Kee ||","english":"He Himself knows His Own Being."},{"punjabi":"ਆਪਿ ਸਾਚੁ ਧਾਰੀ ਸਭ ਸਾਚੁ ॥","lareedar":"ਆਪਿਸਾਚੁਧਾਰੀਸਭਸਾਚੁ ॥","translit":"Aap Saach Dhhaaree Sabh Saach ||","english":"He Himself is True, and all that He has established is True."},{"punjabi":"ਓਤਿ ਪੋਤਿ ਆਪਨ ਸੰਗਿ ਰਾਚੁ ॥","lareedar":"ਓਤਿਪੋਤਿਆਪਨਸੰਗਿਰਾਚੁ ॥","translit":"Outh Poth Aapan Sang Raach ||","english":"Through and through, He is blended with His creation."},{"punjabi":"ਤਾ ਕੀ ਗਤਿ ਮਿਤਿ ਕਹੀ ਨ ਜਾਇ ॥","lareedar":"ਤਾਕੀਗਤਿਮਿਤਿਕਹੀਨਜਾਇ ॥","translit":"Thaa Kee Gath Mith Kehee N Jaae ||","english":"His state and extent cannot be described."},{"punjabi":"ਦੂਸਰ ਹੋਇ ਤ ਸੋਝੀ ਪਾਇ ॥","lareedar":"ਦੂਸਰਹੋਇਤਸੋਝੀਪਾਇ ॥","translit":"Dhoosar Hoe Th Sojhee Paae ||","english":"If there were another like Him, then only he could understand Him."},{"punjabi":"ਤਿਸ ਕਾ ਕੀਆ ਸਭੁ ਪਰਵਾਨੁ ॥","lareedar":"ਤਿਸਕਾਕੀਆਸਭੁਪਰਵਾਨੁ ॥","translit":"This Kaa Keeaa Sabh Paravaan ||","english":"His actions are all approved and accepted."},{"punjabi":"ਗੁਰ ਪ੍ਰਸਾਦਿ ਨਾਨਕ ਇਹੁ ਜਾਨੁ ॥੭॥","lareedar":"ਗੁਰਪ੍ਰਸਾਦਿਨਾਨਕਇਹੁਜਾਨੁ ॥੭ ॥","translit":"Gur Prasaadh Naanak Eihu Jaan ||7||","english":"By Guru's Grace, O Nanak, this is known. ||7||"},{"punjabi":"ਜੋ ਜਾਨੈ ਤਿਸੁ ਸਦਾ ਸੁਖੁ ਹੋਇ ॥","lareedar":"ਜੋਜਾਨੈਤਿਸੁਸਦਾਸੁਖੁਹੋਇ ॥","translit":"Jo Jaanai This Sadhaa Sukh Hoe ||","english":"One who knows Him, obtains everlasting peace."},{"punjabi":"ਆਪਿ ਮਿਲਾਇ ਲਏ ਪ੍ਰਭੁ ਸੋਇ ॥","lareedar":"ਆਪਿਮਿਲਾਇਲਏਪ੍ਰਭੁਸੋਇ ॥","translit":"Aap Milaae Leae Prabh Soe ||","english":"God blends that one into Himself."},{"punjabi":"ਓਹੁ ਧਨਵੰਤੁ ਕੁਲਵੰਤੁ ਪਤਿਵੰਤੁ ॥","lareedar":"ਓਹੁਧਨਵੰਤੁਕੁਲਵੰਤੁਪਤਿਵੰਤੁ ॥","translit":"Ouhu Dhhanavanth Kulavanth Pathivanth ||","english":"He is wealth and prosperous, and of noble birth."},{"punjabi":"ਜੀਵਨ ਮੁਕਤਿ ਜਿਸੁ ਰਿਦੈ ਭਗਵੰਤੁ ॥","lareedar":"ਜੀਵਨਮੁਕਤਿਜਿਸੁਰਿਦੈਭਗਵੰਤੁ ॥","translit":"Jeevan Mukath Jis Ridhai Bhagavanth ||","english":"He is Jivan Mukta - liberated while yet alive; the Lord God abides in his heart."},{"punjabi":"ਧੰਨੁ ਧੰਨੁ ਧੰਨੁ ਜਨੁ ਆਇਆ ॥","lareedar":"ਧੰਨੁਧੰਨੁਧੰਨੁਜਨੁਆਇਆ ॥","translit":"Dhhann Dhhann Dhhann Jan Aaeiaa ||","english":"Blessed, blessed, blessed is the coming of that humble being;"},{"punjabi":"ਜਿਸੁ ਪ੍ਰਸਾਦਿ ਸਭੁ ਜਗਤੁ ਤਰਾਇਆ ॥","lareedar":"ਜਿਸੁਪ੍ਰਸਾਦਿਸਭੁਜਗਤੁਤਰਾਇਆ ॥","translit":"Jis Prasaadh Sabh Jagath Tharaaeiaa ||","english":"By his grace, the whole world is saved."},{"punjabi":"ਜਨ ਆਵਨ ਕਾ ਇਹੈ ਸੁਆਉ ॥","lareedar":"ਜਨਆਵਨਕਾਇਹੈਸੁਆਉ ॥","translit":"Jan Aavan Kaa Eihai Suaao ||","english":"This is his purpose in life;"},{"punjabi":"ਜਨ ਕੈ ਸੰਗਿ ਚਿਤਿ ਆਵੈ ਨਾਉ ॥","lareedar":"ਜਨਕੈਸੰਗਿਚਿਤਿਆਵੈਨਾਉ ॥","translit":"Jan Kai Sang Chith Aavai Naao ||","english":"In the Company of this humble servant, the Lord's Name comes to mind."},{"punjabi":"ਆਪਿ ਮੁਕਤੁ ਮੁਕਤੁ ਕਰੈ ਸੰਸਾਰੁ ॥","lareedar":"ਆਪਿਮੁਕਤੁਮੁਕਤੁਕਰੈਸੰਸਾਰੁ ॥","translit":"Aap Mukath Mukath Karai Sansaar ||","english":"He Himself is liberated, and He liberates the universe."},{"punjabi":"ਨਾਨਕ ਤਿਸੁ ਜਨ ਕਉ ਸਦਾ ਨਮਸਕਾਰੁ ॥੮॥੨੩॥","lareedar":"ਨਾਨਕਤਿਸੁਜਨਕਉਸਦਾਨਮਸਕਾਰੁ ॥੮ ॥੨੩ ॥","translit":"Naanak This Jan Ko Sadhaa Namasakaar ||8||23||","english":"O Nanak, to that humble servant, I bow in reverence forever. ||8||23||"},{"punjabi":"ਸਲੋਕੁ ॥","lareedar":"ਸਲੋਕੁ ॥","translit":"Salok ||","english":"Shalok:"},{"punjabi":"ਪੂਰਾ ਪ੍ਰਭੁ ਆਰਾਧਿਆ ਪੂਰਾ ਜਾ ਕਾ ਨਾਉ ॥","lareedar":"ਪੂਰਾਪ੍ਰਭੁਆਰਾਧਿਆਪੂਰਾਜਾਕਾਨਾਉ ॥","translit":"Pooraa Prabh Aaraadhhiaa Pooraa Jaa Kaa Naao ||","english":"I worship and adore the Perfect Lord God. Perfect is His Name."},{"punjabi":"ਨਾਨਕ ਪੂਰਾ ਪਾਇਆ ਪੂਰੇ ਕੇ ਗੁਨ ਗਾਉ ॥੧॥","lareedar":"ਨਾਨਕਪੂਰਾਪਾਇਆਪੂਰੇਕੇਗੁਨਗਾਉ ॥੧ ॥","translit":"Naanak Pooraa Paaeiaa Poorae Kae Gun Gaao ||1||","english":"O Nanak, I have obtained the Perfect One; I sing the Glorious Praises of the Perfect Lord. ||1||"},{"punjabi":"ਅਸਟਪਦੀ ॥","lareedar":"ਅਸਟਪਦੀ ॥","translit":"Asattapadhee ||","english":"Ashtapadee:"},{"punjabi":"ਪੂਰੇ ਗੁਰ ਕਾ ਸੁਨਿ ਉਪਦੇਸੁ ॥","lareedar":"ਪੂਰੇਗੁਰਕਾਸੁਨਿਉਪਦੇਸੁ ॥","translit":"Poorae Gur Kaa Sun Oupadhaes ||","english":"Listen to the Teachings of the Perfect Guru;"},{"punjabi":"ਪਾਰਬ੍ਰਹਮੁ ਨਿਕਟਿ ਕਰਿ ਪੇਖੁ ॥","lareedar":"ਪਾਰਬ੍ਰਹਮੁਨਿਕਟਿਕਰਿਪੇਖੁ ॥","translit":"Paarabreham Nikatt Kar Paekh ||","english":"See the Supreme Lord God near you."},{"punjabi":"ਸਾਸਿ ਸਾਸਿ ਸਿਮਰਹੁ ਗੋਬਿੰਦ ॥","lareedar":"ਸਾਸਿਸਾਸਿਸਿਮਰਹੁਗੋਬਿੰਦ ॥","translit":"Saas Saas Simarahu Gobindh ||","english":"With each and every breath, meditate in remembrance on the Lord of the Universe,"}]},{"index":79,"ang":295,"lines":[{"punjabi":"ਮਨ ਅੰਤਰ ਕੀ ਉਤਰੈ ਚਿੰਦ ॥","lareedar":"ਮਨਅੰਤਰਕੀਉਤਰੈਚਿੰਦ ॥","translit":"Man Anthar Kee Outharai Chindh ||","english":"And the anxiety within your mind shall depart."},{"punjabi":"ਆਸ ਅਨਿਤ ਤਿਆਗਹੁ ਤਰੰਗ ॥","lareedar":"ਆਸਅਨਿਤਤਿਆਗਹੁਤਰੰਗ ॥","translit":"Aas Anith Thiaagahu Tharang ||","english":"Abandon the waves of fleeting desire,"},{"punjabi":"ਸੰਤ ਜਨਾ ਕੀ ਧੂਰਿ ਮਨ ਮੰਗ ॥","lareedar":"ਸੰਤਜਨਾਕੀਧੂਰਿਮਨਮੰਗ ॥","translit":"Santh Janaa Kee Dhhoor Man Mang ||","english":"And pray for the dust of the feet of the Saints."},{"punjabi":"ਆਪੁ ਛੋਡਿ ਬੇਨਤੀ ਕਰਹੁ ॥","lareedar":"ਆਪੁਛੋਡਿਬੇਨਤੀਕਰਹੁ ॥","translit":"Aap Shhodd Baenathee Karahu ||","english":"Renounce your selfishness and conceit and offer your prayers."},{"punjabi":"ਸਾਧਸੰਗਿ ਅਗਨਿ ਸਾਗਰੁ ਤਰਹੁ ॥","lareedar":"ਸਾਧਸੰਗਿਅਗਨਿਸਾਗਰੁਤਰਹੁ ॥","translit":"Saadhhasang Agan Saagar Tharahu ||","english":"In the Saadh Sangat, the Company of the Holy, cross over the ocean of fire."},{"punjabi":"ਹਰਿ ਧਨ ਕੇ ਭਰਿ ਲੇਹੁ ਭੰਡਾਰ ॥","lareedar":"ਹਰਿਧਨਕੇਭਰਿਲੇਹੁਭੰਡਾਰ ॥","translit":"Har Dhhan Kae Bhar Laehu Bhanddaar ||","english":"Fill your stores with the wealth of the Lord."},{"punjabi":"ਨਾਨਕ ਗੁਰ ਪੂਰੇ ਨਮਸਕਾਰ ॥੧॥","lareedar":"ਨਾਨਕਗੁਰਪੂਰੇਨਮਸਕਾਰ ॥੧ ॥","translit":"Naanak Gur Poorae Namasakaar ||1||","english":"Nanak bows in humility and reverence to the Perfect Guru. ||1||"},{"punjabi":"ਖੇਮ ਕੁਸਲ ਸਹਜ ਆਨੰਦ ॥","lareedar":"ਖੇਮਕੁਸਲਸਹਜਆਨੰਦ ॥","translit":"Khaem Kusal Sehaj Aanandh ||","english":"Happiness, intuitive peace, poise and bliss"},{"punjabi":"ਸਾਧਸੰਗਿ ਭਜੁ ਪਰਮਾਨੰਦ ॥","lareedar":"ਸਾਧਸੰਗਿਭਜੁਪਰਮਾਨੰਦ ॥","translit":"Saadhhasang Bhaj Paramaanandh ||","english":"In the Company of the Holy, meditate on the Lord of supreme bliss."},{"punjabi":"ਨਰਕ ਨਿਵਾਰਿ ਉਧਾਰਹੁ ਜੀਉ ॥","lareedar":"ਨਰਕਨਿਵਾਰਿਉਧਾਰਹੁਜੀਉ ॥","translit":"Narak Nivaar Oudhhaarahu Jeeo ||","english":"You shall be spared from hell - save your soul!"},{"punjabi":"ਗੁਨ ਗੋਬਿੰਦ ਅੰਮ੍ਰਿਤ ਰਸੁ ਪੀਉ ॥","lareedar":"ਗੁਨਗੋਬਿੰਦਅੰਮ੍ਰਿਤਰਸੁਪੀਉ ॥","translit":"Gun Gobindh Anmrith Ras Peeo ||","english":"Drink in the ambrosial essence of the Glorious Praises of the Lord of the Universe."},{"punjabi":"ਚਿਤਿ ਚਿਤਵਹੁ ਨਾਰਾਇਣ ਏਕ ॥","lareedar":"ਚਿਤਿਚਿਤਵਹੁਨਾਰਾਇਣਏਕ ॥","translit":"Chith Chithavahu Naaraaein Eaek ||","english":"Focus your consciousness on the One, the All-pervading Lord"},{"punjabi":"ਏਕ ਰੂਪ ਜਾ ਕੇ ਰੰਗ ਅਨੇਕ ॥","lareedar":"ਏਕਰੂਪਜਾਕੇਰੰਗਅਨੇਕ ॥","translit":"Eaek Roop Jaa Kae Rang Anaek ||","english":"He has One Form, but He has many manifestations."},{"punjabi":"ਗੋਪਾਲ ਦਾਮੋਦਰ ਦੀਨ ਦਇਆਲ ॥","lareedar":"ਗੋਪਾਲਦਾਮੋਦਰਦੀਨਦਇਆਲ ॥","translit":"Gopaal Dhaamodhar Dheen Dhaeiaal ||","english":"Sustainer of the Universe, Lord of the world, Kind to the poor,"},{"punjabi":"ਦੁਖ ਭੰਜਨ ਪੂਰਨ ਕਿਰਪਾਲ ॥","lareedar":"ਦੁਖਭੰਜਨਪੂਰਨਕਿਰਪਾਲ ॥","translit":"Dhukh Bhanjan Pooran Kirapaal ||","english":"Destroyer of sorrow, perfectly Merciful."},{"punjabi":"ਸਿਮਰਿ ਸਿਮਰਿ ਨਾਮੁ ਬਾਰੰ ਬਾਰ ॥","lareedar":"ਸਿਮਰਿਸਿਮਰਿਨਾਮੁਬਾਰੰਬਾਰ ॥","translit":"Simar Simar Naam Baaran Baar ||","english":"Meditate, meditate in remembrance on the Naam, again and again."},{"punjabi":"ਨਾਨਕ ਜੀਅ ਕਾ ਇਹੈ ਅਧਾਰ ॥੨॥","lareedar":"ਨਾਨਕਜੀਅਕਾਇਹੈਅਧਾਰ ॥੨ ॥","translit":"Naanak Jeea Kaa Eihai Adhhaar ||2||","english":"O Nanak, it is the Support of the soul. ||2||"},{"punjabi":"ਉਤਮ ਸਲੋਕ ਸਾਧ ਕੇ ਬਚਨ ॥","lareedar":"ਉਤਮਸਲੋਕਸਾਧਕੇਬਚਨ ॥","translit":"Outham Salok Saadhh Kae Bachan ||","english":"The most sublime hymns are the Words of the Holy."},{"punjabi":"ਅਮੁਲੀਕ ਲਾਲ ਏਹਿ ਰਤਨ ॥","lareedar":"ਅਮੁਲੀਕਲਾਲਏਹਿਰਤਨ ॥","translit":"Amuleek Laal Eaehi Rathan ||","english":"These are priceless rubies and gems."},{"punjabi":"ਸੁਨਤ ਕਮਾਵਤ ਹੋਤ ਉਧਾਰ ॥","lareedar":"ਸੁਨਤਕਮਾਵਤਹੋਤਉਧਾਰ ॥","translit":"Sunath Kamaavath Hoth Oudhhaar ||","english":"One who listens and acts on them is saved."},{"punjabi":"ਆਪਿ ਤਰੈ ਲੋਕਹ ਨਿਸਤਾਰ ॥","lareedar":"ਆਪਿਤਰੈਲੋਕਹਨਿਸਤਾਰ ॥","translit":"Aap Tharai Lokeh Nisathaar ||","english":"He himself swims across, and saves others as well."},{"punjabi":"ਸਫਲ ਜੀਵਨੁ ਸਫਲੁ ਤਾ ਕਾ ਸੰਗੁ ॥","lareedar":"ਸਫਲਜੀਵਨੁਸਫਲੁਤਾਕਾਸੰਗੁ ॥","translit":"Safal Jeevan Safal Thaa Kaa Sang ||","english":"His life is prosperous, and his company is fruitful;"},{"punjabi":"ਜਾ ਕੈ ਮਨਿ ਲਾਗਾ ਹਰਿ ਰੰਗੁ ॥","lareedar":"ਜਾਕੈਮਨਿਲਾਗਾਹਰਿਰੰਗੁ ॥","translit":"Jaa Kai Man Laagaa Har Rang ||","english":"His mind is imbued with the love of the Lord."},{"punjabi":"ਜੈ ਜੈ ਸਬਦੁ ਅਨਾਹਦੁ ਵਾਜੈ ॥","lareedar":"ਜੈਜੈਸਬਦੁਅਨਾਹਦੁਵਾਜੈ ॥","translit":"Jai Jai Sabadh Anaahadh Vaajai ||","english":"Hail, hail to him, for whom the sound current of the Shabad vibrates."},{"punjabi":"ਸੁਨਿ ਸੁਨਿ ਅਨਦ ਕਰੇ ਪ੍ਰਭੁ ਗਾਜੈ ॥","lareedar":"ਸੁਨਿਸੁਨਿਅਨਦਕਰੇਪ੍ਰਭੁਗਾਜੈ ॥","translit":"Sun Sun Anadh Karae Prabh Gaajai ||","english":"Hearing it again and again, he is in bliss, proclaiming God's Praises."}]},{"index":80,"ang":295,"lines":[{"punjabi":"ਪ੍ਰਗਟੇ ਗੁਪਾਲ ਮਹਾਂਤ ਕੈ ਮਾਥੇ ॥","lareedar":"ਪ੍ਰਗਟੇਗੁਪਾਲਮਹਾਂਤਕੈਮਾਥੇ ॥","translit":"Pragattae Gupaal Mehaanth Kai Maathhae ||","english":"The Lord radiates from the foreheads of the Holy."},{"punjabi":"ਨਾਨਕ ਉਧਰੇ ਤਿਨ ਕੈ ਸਾਥੇ ॥੩॥","lareedar":"ਨਾਨਕਉਧਰੇਤਿਨਕੈਸਾਥੇ ॥੩ ॥","translit":"Naanak Oudhharae Thin Kai Saathhae ||3||","english":"Nanak is saved in their company. ||3||"},{"punjabi":"ਸਰਨਿ ਜੋਗੁ ਸੁਨਿ ਸਰਨੀ ਆਏ ॥","lareedar":"ਸਰਨਿਜੋਗੁਸੁਨਿਸਰਨੀਆਏ ॥","translit":"Saran Jog Sun Saranee Aaeae ||","english":"Hearing that He can give Sanctuary, I have come seeking His Sanctuary."},{"punjabi":"ਕਰਿ ਕਿਰਪਾ ਪ੍ਰਭ ਆਪ ਮਿਲਾਏ ॥","lareedar":"ਕਰਿਕਿਰਪਾਪ੍ਰਭਆਪਮਿਲਾਏ ॥","translit":"Kar Kirapaa Prabh Aap Milaaeae ||","english":"Bestowing His Mercy, God has blended me with Himself."},{"punjabi":"ਮਿਟਿ ਗਏ ਬੈਰ ਭਏ ਸਭ ਰੇਨ ॥","lareedar":"ਮਿਟਿਗਏਬੈਰਭਏਸਭਰੇਨ ॥","translit":"Mitt Geae Bair Bheae Sabh Raen ||","english":"Hatred is gone, and I have become the dust of all."},{"punjabi":"ਅੰਮ੍ਰਿਤ ਨਾਮੁ ਸਾਧਸੰਗਿ ਲੈਨ ॥","lareedar":"ਅੰਮ੍ਰਿਤਨਾਮੁਸਾਧਸੰਗਿਲੈਨ ॥","translit":"Anmrith Naam Saadhhasang Lain ||","english":"I have received the Ambrosial Naam in the Company of the Holy."},{"punjabi":"ਸੁਪ੍ਰਸੰਨ ਭਏ ਗੁਰਦੇਵ ॥","lareedar":"ਸੁਪ੍ਰਸੰਨਭਏਗੁਰਦੇਵ ॥","translit":"Suprasann Bheae Guradhaev ||","english":"The Divine Guru is perfectly pleased;"},{"punjabi":"ਪੂਰਨ ਹੋਈ ਸੇਵਕ ਕੀ ਸੇਵ ॥","lareedar":"ਪੂਰਨਹੋਈਸੇਵਕਕੀਸੇਵ ॥","translit":"Pooran Hoee Saevak Kee Saev ||","english":"The service of His servant has been rewarded."},{"punjabi":"ਆਲ ਜੰਜਾਲ ਬਿਕਾਰ ਤੇ ਰਹਤੇ ॥","lareedar":"ਆਲਜੰਜਾਲਬਿਕਾਰਤੇਰਹਤੇ ॥","translit":"Aal Janjaal Bikaar Thae Rehathae ||","english":"I have been released from worldly entanglements and corruption,"},{"punjabi":"ਰਾਮ ਨਾਮ ਸੁਨਿ ਰਸਨਾ ਕਹਤੇ ॥","lareedar":"ਰਾਮਨਾਮਸੁਨਿਰਸਨਾਕਹਤੇ ॥","translit":"Raam Naam Sun Rasanaa Kehathae ||","english":"Hearing the Lord's Name and chanting it with my tongue."},{"punjabi":"ਕਰਿ ਪ੍ਰਸਾਦੁ ਦਇਆ ਪ੍ਰਭਿ ਧਾਰੀ ॥","lareedar":"ਕਰਿਪ੍ਰਸਾਦੁਦਇਆਪ੍ਰਭਿਧਾਰੀ ॥","translit":"Kar Prasaadh Dhaeiaa Prabh Dhhaaree ||","english":"By His Grace, God has bestowed His Mercy."},{"punjabi":"ਨਾਨਕ ਨਿਬਹੀ ਖੇਪ ਹਮਾਰੀ ॥੪॥","lareedar":"ਨਾਨਕਨਿਬਹੀਖੇਪਹਮਾਰੀ ॥੪ ॥","translit":"Naanak Nibehee Khaep Hamaaree ||4||","english":"O Nanak, my merchandise has arrived save and sound. ||4||"},{"punjabi":"ਪ੍ਰਭ ਕੀ ਉਸਤਤਿ ਕਰਹੁ ਸੰਤ ਮੀਤ ॥","lareedar":"ਪ੍ਰਭਕੀਉਸਤਤਿਕਰਹੁਸੰਤਮੀਤ ॥","translit":"Prabh Kee Ousathath Karahu Santh Meeth ||","english":"Sing the Praises of God, O Saints, O friends,"},{"punjabi":"ਸਾਵਧਾਨ ਏਕਾਗਰ ਚੀਤ ॥","lareedar":"ਸਾਵਧਾਨਏਕਾਗਰਚੀਤ ॥","translit":"Saavadhhaan Eaekaagar Cheeth ||","english":"With total concentration and one-pointedness of mind."},{"punjabi":"ਸੁਖਮਨੀ ਸਹਜ ਗੋਬਿੰਦ ਗੁਨ ਨਾਮ ॥","lareedar":"ਸੁਖਮਨੀਸਹਜਗੋਬਿੰਦਗੁਨਨਾਮ ॥","translit":"Sukhamanee Sehaj Gobindh Gun Naam ||","english":"Sukhmani is the peaceful ease, the Glory of God, the Naam."},{"punjabi":"ਜਿਸੁ ਮਨਿ ਬਸੈ ਸੁ ਹੋਤ ਨਿਧਾਨ ॥","lareedar":"ਜਿਸੁਮਨਿਬਸੈਸੁਹੋਤਨਿਧਾਨ ॥","translit":"Jis Man Basai S Hoth Nidhhaan ||","english":"When it abides in the mind, one becomes wealthy."},{"punjabi":"ਸਰਬ ਇਛਾ ਤਾ ਕੀ ਪੂਰਨ ਹੋਇ ॥","lareedar":"ਸਰਬਇਛਾਤਾਕੀਪੂਰਨਹੋਇ ॥","translit":"Sarab Eishhaa Thaa Kee Pooran Hoe ||","english":"All desires are fulfilled."},{"punjabi":"ਪ੍ਰਧਾਨ ਪੁਰਖੁ ਪ੍ਰਗਟੁ ਸਭ ਲੋਇ ॥","lareedar":"ਪ੍ਰਧਾਨਪੁਰਖੁਪ੍ਰਗਟੁਸਭਲੋਇ ॥","translit":"Pradhhaan Purakh Pragatt Sabh Loe ||","english":"One becomes the most respected person, famous all over the world."},{"punjabi":"ਸਭ ਤੇ ਊਚ ਪਾਏ ਅਸਥਾਨੁ ॥","lareedar":"ਸਭਤੇਊਚਪਾਏਅਸਥਾਨੁ ॥","translit":"Sabh Thae Ooch Paaeae Asathhaan ||","english":"He obtains the highest place of all."},{"punjabi":"ਬਹੁਰਿ ਨ ਹੋਵੈ ਆਵਨ ਜਾਨੁ ॥","lareedar":"ਬਹੁਰਿਨਹੋਵੈਆਵਨਜਾਨੁ ॥","translit":"Bahur N Hovai Aavan Jaan ||","english":"He does not come and go in reincarnation any longer."},{"punjabi":"ਹਰਿ ਧਨੁ ਖਾਟਿ ਚਲੈ ਜਨੁ ਸੋਇ ॥","lareedar":"ਹਰਿਧਨੁਖਾਟਿਚਲੈਜਨੁਸੋਇ ॥","translit":"Har Dhhan Khaatt Chalai Jan Soe ||","english":"One who departs, after earning the wealth of the Lord's Name,"},{"punjabi":"ਨਾਨਕ ਜਿਸਹਿ ਪਰਾਪਤਿ ਹੋਇ ॥੫॥","lareedar":"ਨਾਨਕਜਿਸਹਿਪਰਾਪਤਿਹੋਇ ॥੫ ॥","translit":"Naanak Jisehi Paraapath Hoe ||5||","english":"O Nanak, realizes it. ||5||"},{"punjabi":"ਖੇਮ ਸਾਂਤਿ ਰਿਧਿ ਨਵ ਨਿਧਿ ॥","lareedar":"ਖੇਮਸਾਂਤਿਰਿਧਿਨਵਨਿਧਿ ॥","translit":"Khaem Saanth Ridhh Nav Nidhh ||","english":"Comfort, peace and tranquility, wealth and the nine treasures;"},{"punjabi":"ਬੁਧਿ ਗਿਆਨੁ ਸਰਬ ਤਹ ਸਿਧਿ ॥","lareedar":"ਬੁਧਿਗਿਆਨੁਸਰਬਤਹਸਿਧਿ ॥","translit":"Budhh Giaan Sarab Theh Sidhh ||","english":"Wisdom, knowledge, and all spiritual powers;"},{"punjabi":"ਬਿਦਿਆ ਤਪੁ ਜੋਗੁ ਪ੍ਰਭ ਧਿਆਨੁ ॥","lareedar":"ਬਿਦਿਆਤਪੁਜੋਗੁਪ੍ਰਭਧਿਆਨੁ ॥","translit":"Bidhiaa Thap Jog Prabh Dhhiaan ||","english":"Learning, penance, Yoga and meditation on God;"}]},{"index":81,"ang":296,"lines":[{"punjabi":"ਗਿਆਨੁ ਸ੍ਰੇਸਟ ਊਤਮ ਇਸਨਾਨੁ ॥","lareedar":"ਗਿਆਨੁਸ੍ਰੇਸਟਊਤਮਇਸਨਾਨੁ ॥","translit":"Giaan Sraesatt Ootham Eisanaan ||","english":"The most sublime wisdom and purifying baths;"},{"punjabi":"ਚਾਰਿ ਪਦਾਰਥ ਕਮਲ ਪ੍ਰਗਾਸ ॥","lareedar":"ਚਾਰਿਪਦਾਰਥਕਮਲਪ੍ਰਗਾਸ ॥","translit":"Chaar Padhaarathh Kamal Pragaas ||","english":"The four cardinal blessings, the opening of the heart-lotus;"},{"punjabi":"ਸਭ ਕੈ ਮਧਿ ਸਗਲ ਤੇ ਉਦਾਸ ॥","lareedar":"ਸਭਕੈਮਧਿਸਗਲਤੇਉਦਾਸ ॥","translit":"Sabh Kai Madhh Sagal Thae Oudhaas ||","english":"In the midst of all, and yet detached from all;"},{"punjabi":"ਸੁੰਦਰੁ ਚਤੁਰੁ ਤਤ ਕਾ ਬੇਤਾ ॥","lareedar":"ਸੁੰਦਰੁਚਤੁਰੁਤਤਕਾਬੇਤਾ ॥","translit":"Sundhar Chathur Thath Kaa Baethaa ||","english":"Beauty, intelligence, and the realization of reality;"},{"punjabi":"ਸਮਦਰਸੀ ਏਕ ਦ੍ਰਿਸਟੇਤਾ ॥","lareedar":"ਸਮਦਰਸੀਏਕਦ੍ਰਿਸਟੇਤਾ ॥","translit":"Samadharasee Eaek Dhrisattaethaa ||","english":"Hese blessings come to one who chants the Naam with his mouth,"},{"punjabi":"ਇਹ ਫਲ ਤਿਸੁ ਜਨ ਕੈ ਮੁਖਿ ਭਨੇ ॥","lareedar":"ਇਹਫਲਤਿਸੁਜਨਕੈਮੁਖਿਭਨੇ ॥","translit":"Eih Fal This Jan Kai Mukh Bhanae ||","english":"These blessings come to one who, through Guru Nanak,"},{"punjabi":"ਗੁਰ ਨਾਨਕ ਨਾਮ ਬਚਨ ਮਨਿ ਸੁਨੇ ॥੬॥","lareedar":"ਗੁਰਨਾਨਕਨਾਮਬਚਨਮਨਿਸੁਨੇ ॥੬ ॥","translit":"Gur Naanak Naam Bachan Man Sunae ||6||","english":"And hears the Word with his ears through Guru Nanak. ||6||"},{"punjabi":"ਇਹੁ ਨਿਧਾਨੁ ਜਪੈ ਮਨਿ ਕੋਇ ॥","lareedar":"ਇਹੁਨਿਧਾਨੁਜਪੈਮਨਿਕੋਇ ॥","translit":"Eihu Nidhhaan Japai Man Koe ||","english":"One who chants this treasure in his mind"},{"punjabi":"ਸਭ ਜੁਗ ਮਹਿ ਤਾ ਕੀ ਗਤਿ ਹੋਇ ॥","lareedar":"ਸਭਜੁਗਮਹਿਤਾਕੀਗਤਿਹੋਇ ॥","translit":"Sabh Jug Mehi Thaa Kee Gath Hoe ||","english":"In every age, he attains salvation."},{"punjabi":"ਗੁਣ ਗੋਬਿੰਦ ਨਾਮ ਧੁਨਿ ਬਾਣੀ ॥","lareedar":"ਗੁਣਗੋਬਿੰਦਨਾਮਧੁਨਿਬਾਣੀ ॥","translit":"Gun Gobindh Naam Dhhun Baanee ||","english":"In it is the Glory of God, the Naam, the chanting of Gurbani."},{"punjabi":"ਸਿਮ੍ਰਿਤਿ ਸਾਸਤ੍ਰ ਬੇਦ ਬਖਾਣੀ ॥","lareedar":"ਸਿਮ੍ਰਿਤਿਸਾਸਤ੍ਰਬੇਦਬਖਾਣੀ ॥","translit":"Simrith Saasathr Baedh Bakhaanee ||","english":"The Simritees, the Shaastras and the Vedas speak of it."},{"punjabi":"ਸਗਲ ਮਤਾਂਤ ਕੇਵਲ ਹਰਿ ਨਾਮ ॥","lareedar":"ਸਗਲਮਤਾਂਤਕੇਵਲਹਰਿਨਾਮ ॥","translit":"Sagal Mathaanth Kaeval Har Naam ||","english":"The essence of all religion is the Lord's Name alone."},{"punjabi":"ਗੋਬਿੰਦ ਭਗਤ ਕੈ ਮਨਿ ਬਿਸ੍ਰਾਮ ॥","lareedar":"ਗੋਬਿੰਦਭਗਤਕੈਮਨਿਬਿਸ੍ਰਾਮ ॥","translit":"Gobindh Bhagath Kai Man Bisraam ||","english":"It abides in the minds of the devotees of God."},{"punjabi":"ਕੋਟਿ ਅਪ੍ਰਾਧ ਸਾਧਸੰਗਿ ਮਿਟੈ ॥","lareedar":"ਕੋਟਿਅਪ੍ਰਾਧਸਾਧਸੰਗਿਮਿਟੈ ॥","translit":"Kott Apraadhh Saadhhasang Mittai ||","english":"Millions of sins are erased, in the Company of the Holy."},{"punjabi":"ਸੰਤ ਕ੍ਰਿਪਾ ਤੇ ਜਮ ਤੇ ਛੁਟੈ ॥","lareedar":"ਸੰਤਕ੍ਰਿਪਾਤੇਜਮਤੇਛੁਟੈ ॥","translit":"Santh Kirapaa Thae Jam Thae Shhuttai ||","english":"By the Grace of the Saint, one escapes the Messenger of Death."},{"punjabi":"ਜਾ ਕੈ ਮਸਤਕਿ ਕਰਮ ਪ੍ਰਭਿ ਪਾਏ ॥","lareedar":"ਜਾਕੈਮਸਤਕਿਕਰਮਪ੍ਰਭਿਪਾਏ ॥","translit":"Jaa Kai Masathak Karam Prabh Paaeae ||","english":"Those, who have such pre-ordained destiny on their foreheads,"},{"punjabi":"ਸਾਧ ਸਰਣਿ ਨਾਨਕ ਤੇ ਆਏ ॥੭॥","lareedar":"ਸਾਧਸਰਣਿਨਾਨਕਤੇਆਏ ॥੭ ॥","translit":"Saadhh Saran Naanak Thae Aaeae ||7||","english":"O Nanak, enter the Sanctuary of the Saints. ||7||"},{"punjabi":"ਜਿਸੁ ਮਨਿ ਬਸੈ ਸੁਨੈ ਲਾਇ ਪ੍ਰੀਤਿ ॥","lareedar":"ਜਿਸੁਮਨਿਬਸੈਸੁਨੈਲਾਇਪ੍ਰੀਤਿ ॥","translit":"Jis Man Basai Sunai Laae Preeth ||","english":"One, within whose mind it abides, and who listens to it with love"},{"punjabi":"ਤਿਸੁ ਜਨ ਆਵੈ ਹਰਿ ਪ੍ਰਭੁ ਚੀਤਿ ॥","lareedar":"ਤਿਸੁਜਨਆਵੈਹਰਿਪ੍ਰਭੁਚੀਤਿ ॥","translit":"This Jan Aavai Har Prabh Cheeth ||","english":"That humble person consciously remembers the Lord God."},{"punjabi":"ਜਨਮ ਮਰਨ ਤਾ ਕਾ ਦੂਖੁ ਨਿਵਾਰੈ ॥","lareedar":"ਜਨਮਮਰਨਤਾਕਾਦੂਖੁਨਿਵਾਰੈ ॥","translit":"Janam Maran Thaa Kaa Dhookh Nivaarai ||","english":"The pains of birth and death are removed."},{"punjabi":"ਦੁਲਭ ਦੇਹ ਤਤਕਾਲ ਉਧਾਰੈ ॥","lareedar":"ਦੁਲਭਦੇਹਤਤਕਾਲਉਧਾਰੈ ॥","translit":"Dhulabh Dhaeh Thathakaal Oudhhaarai ||","english":"The human body, so difficult to obtain, is instantly redeemed."},{"punjabi":"ਨਿਰਮਲ ਸੋਭਾ ਅੰਮ੍ਰਿਤ ਤਾ ਕੀ ਬਾਨੀ ॥","lareedar":"ਨਿਰਮਲਸੋਭਾਅੰਮ੍ਰਿਤਤਾਕੀਬਾਨੀ ॥","translit":"Niramal Sobhaa Anmrith Thaa Kee Baanee ||","english":"Spotlessly pure is his reputation, and ambrosial is his speech."},{"punjabi":"ਏਕੁ ਨਾਮੁ ਮਨ ਮਾਹਿ ਸਮਾਨੀ ॥","lareedar":"ਏਕੁਨਾਮੁਮਨਮਾਹਿਸਮਾਨੀ ॥","translit":"Eaek Naam Man Maahi Samaanee ||","english":"The One Name permeates his mind."},{"punjabi":"ਦੂਖ ਰੋਗ ਬਿਨਸੇ ਭੈ ਭਰਮ ॥","lareedar":"ਦੂਖਰੋਗਬਿਨਸੇਭੈਭਰਮ ॥","translit":"Dhookh Rog Binasae Bhai Bharam ||","english":"Sorrow, sickness, fear and doubt depart."},{"punjabi":"ਸਾਧ ਨਾਮ ਨਿਰਮਲ ਤਾ ਕੇ ਕਰਮ ॥","lareedar":"ਸਾਧਨਾਮਨਿਰਮਲਤਾਕੇਕਰਮ ॥","translit":"Saadhh Naam Niramal Thaa Kae Karam ||","english":"He is called a Holy person; his actions are immaculate and pure."}]},{"index":82,"ang":296,"lines":[{"punjabi":"ਸਭ ਤੇ ਊਚ ਤਾ ਕੀ ਸੋਭਾ ਬਨੀ ॥","lareedar":"ਸਭਤੇਊਚਤਾਕੀਸੋਭਾਬਨੀ ॥","translit":"Sabh Thae Ooch Thaa Kee Sobhaa Banee ||","english":"His glory becomes the highest of all."},{"punjabi":"ਨਾਨਕ ਇਹ ਗੁਣਿ ਨਾਮੁ ਸੁਖਮਨੀ ॥੮॥੨੪॥","lareedar":"ਨਾਨਕਇਹਗੁਣਿਨਾਮੁਸੁਖਮਨੀ ॥੮ ॥੨੪ ॥","translit":"Naanak Eih Gun Naam Sukhamanee ||8||24||","english":"O Nanak, by these Glorious Virtues, this is named Sukhmani, Peace of mind. ||8||24||"}]}]};
